window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JOB"]={"book":"JOB","editions":{"hbo-source":[[1,1,"אִ֛ישׁ הָיָ֥ה בְ⁠אֶֽרֶץ־ע֖וּץ אִיּ֣וֹב שְׁמ֑⁠וֹ וְ⁠הָיָ֣ה ׀ הָ⁠אִ֣ישׁ הַ⁠ה֗וּא תָּ֧ם וְ⁠יָשָׁ֛ר וִ⁠ירֵ֥א אֱלֹהִ֖ים וְ⁠סָ֥ר מֵ⁠רָֽע׃","ʼi֛yş̌ háyá֥h bĕ⁠ʼeֽreẕ-ʻ֖ẇẕ ʼiẏ֣wòb şĕ̌m֑⁠wò wĕ⁠háyá֣h ׀ há⁠ʼi֣yş̌ ha⁠h֗ẇʼ ţá֧̇m wĕ⁠yáşá֛̌r wi⁠yré֥ʼ ʼèlòhi֖ym wĕ⁠sá֥r mé⁠ráֽʻ׃"],[1,2,"וַ⁠יִּוָּ֥לְדוּ ל֛⁠וֹ שִׁבְעָ֥ה בָנִ֖ים וְ⁠שָׁל֥וֹשׁ בָּנֽוֹת׃","wa⁠yi̇wá֥̇lĕdẇ l֛⁠wò şǐbĕʻá֥h báni֖ym wĕ⁠şá̌l֥wòş̌ bá̇nֽwòţ׃"],[1,3,"וַ⁠יְהִ֣י מִ֠קְנֵ⁠הוּ שִֽׁבְעַ֨ת אַלְפֵי־צֹ֜אן וּ⁠שְׁלֹ֧שֶׁת אַלְפֵ֣י גְמַלִּ֗ים וַ⁠חֲמֵ֨שׁ מֵא֤וֹת צֶֽמֶד־בָּקָר֙ וַ⁠חֲמֵ֣שׁ מֵא֣וֹת אֲתוֹנ֔וֹת וַ⁠עֲבֻדָּ֖ה רַבָּ֣ה מְאֹ֑ד וַ⁠יְהִי֙ הָ⁠אִ֣ישׁ הַ⁠ה֔וּא גָּד֖וֹל מִ⁠כָּל־בְּנֵי־קֶֽדֶם׃","wa⁠yĕhi֣y mi֠qĕné⁠hẇ şǐֽbĕʻa֨ţ ʼalĕpéy-ẕò֜ʼn ẇ⁠şĕ̌lò֧şěţ ʼalĕpé֣y gĕmali̇֗ym wa⁠ẖàmé֨ş̌ méʼ֤wòţ ẕeֽmed-bá̇qár֙ wa⁠ẖàmé֣ş̌ méʼ֣wòţ ʼàţwòn֔wòţ wa⁠ʻàbudá֖̇h rabá֣̇h mĕʼò֑d wa⁠yĕhiy֙ há⁠ʼi֣yş̌ ha⁠h֔ẇʼ gá̇d֖wòl mi⁠ká̇l-bĕ̇néy-qeֽdem׃"],[1,4,"וְ⁠הָלְכ֤וּ בָנָי⁠ו֙ וְ⁠עָשׂ֣וּ מִשְׁתֶּ֔ה בֵּ֖ית אִ֣ישׁ יוֹמ֑⁠וֹ וְ⁠שָׁלְח֗וּ וְ⁠קָרְאוּ֙ לִ⁠שְׁלֹ֣שֶׁת אחיתי⁠הם לֶ⁠אֱכֹ֥ל וְ⁠לִ⁠שְׁתּ֖וֹת עִמָּ⁠הֶֽם׃","wĕ⁠hálĕk֤ẇ bánáy⁠w֙ wĕ⁠ʻáş֣̂ẇ mişĕ̌ţė֔h bé֖̇yţ ʼi֣yş̌ ywòm֑⁠wò wĕ⁠şá̌lĕẖ֗ẇ wĕ⁠qárĕʼẇ֙ li⁠şĕ̌lò֣şěţ ʼẖyţy⁠hm le⁠ʼèkò֥l wĕ⁠li⁠şĕ̌ţ֖̇wòţ ʻimá̇⁠heֽm׃"],[1,5,"וַ⁠יְהִ֡י כִּ֣י הִקִּיפֽוּ֩ יְמֵ֨י הַ⁠מִּשְׁתֶּ֜ה וַ⁠יִּשְׁלַ֧ח אִיּ֣וֹב וַֽ⁠יְקַדְּשֵׁ֗⁠ם וְ⁠הִשְׁכִּ֣ים בַּ⁠בֹּקֶר֮ וְ⁠הֶעֱלָ֣ה עֹלוֹת֮ מִסְפַּ֣ר כֻּלָּ⁠ם֒ כִּ֚י אָמַ֣ר אִיּ֔וֹב אוּלַי֙ חָטְא֣וּ בָנַ֔⁠י וּ⁠בֵרֲכ֥וּ אֱלֹהִ֖ים בִּ⁠לְבָבָ֑⁠ם כָּ֛כָה יַעֲשֶׂ֥ה אִיּ֖וֹב כָּל־הַ⁠יָּמִֽים׃פ","wa⁠yĕhi֡y ki֣̇y hiqi̇ypֽẇ֩ yĕmé֨y ha⁠mi̇şĕ̌ţė֜h wa⁠yi̇şĕ̌la֧ẖ ʼiẏ֣wòb waֽ⁠yĕqadĕ̇şé̌֗⁠m wĕ⁠hişĕ̌ki֣̇ym bȧ⁠bò̇qer֮ wĕ⁠heʻèlá֣h ʻòlwòţ֮ misĕpȧ֣r ku̇lá̇⁠m֒ ki֚̇y ʼáma֣r ʼiẏ֔wòb ʼẇlay֙ ẖátĕʼ֣ẇ bána֔⁠y ẇ⁠béràk֥ẇ ʼèlòhi֖ym bi̇⁠lĕbábá֑⁠m ká֛̇káh yaʻàşê֥h ʼiẏ֖wòb ká̇l-ha⁠yá̇miֽym׃p"],[1,6,"וַ⁠יְהִ֣י הַ⁠יּ֔וֹם וַ⁠יָּבֹ֨אוּ֙ בְּנֵ֣י הָ⁠אֱלֹהִ֔ים לְ⁠הִתְיַצֵּ֖ב עַל־יְהוָ֑ה וַ⁠יָּב֥וֹא גַֽם־הַ⁠שָּׂטָ֖ן בְּ⁠תוֹכָֽ⁠ם׃","wa⁠yĕhi֣y ha⁠ẏ֔wòm wa⁠yá̇bò֨ʼẇ֙ bĕ̇né֣y há⁠ʼèlòhi֔ym lĕ⁠hiţĕyaẕé֖̇b ʻal-yĕhwá֑h wa⁠yá̇b֥wòʼ gaֽm-ha⁠şá̇̂tá֖n bĕ̇⁠ţwòkáֽ⁠m׃"],[1,7,"וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֶל־הַ⁠שָּׂטָ֖ן מֵ⁠אַ֣יִן תָּבֹ֑א וַ⁠יַּ֨עַן הַ⁠שָּׂטָ֤ן אֶת־יְהוָה֙ וַ⁠יֹּאמַ֔ר מִ⁠שּׁ֣וּט בָּ⁠אָ֔רֶץ וּ⁠מֵֽ⁠הִתְהַלֵּ֖ךְ בָּֽ⁠הּ׃","wa⁠yò֧̇ʼmer yĕhwá֛h ʼel-ha⁠şá̇̂tá֖n mé⁠ʼa֣yin ţá̇bò֑ʼ wa⁠yȧ֨ʻan ha⁠şá̇̂tá֤n ʼeţ-yĕhwáh֙ wa⁠yò̇ʼma֔r mi⁠ş֣̇̌ẇt bá̇⁠ʼá֔reẕ ẇ⁠méֽ⁠hiţĕhalé֖̇kĕ báֽ̇⁠ḣ׃"],[1,8,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־הַ⁠שָּׂטָ֔ן הֲ⁠שַׂ֥מְתָּ לִבְּ⁠ךָ֖ עַל־עַבְדִּ֣⁠י אִיּ֑וֹב כִּ֣י אֵ֤ין כָּמֹ֨⁠הוּ֙ בָּ⁠אָ֔רֶץ אִ֣ישׁ תָּ֧ם וְ⁠יָשָׁ֛ר יְרֵ֥א אֱלֹהִ֖ים וְ⁠סָ֥ר מֵ⁠רָֽע׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-ha⁠şá̇̂tá֔n hà⁠şâ֥mĕţá̇ libĕ̇⁠ká֖ ʻal-ʻabĕdi֣̇⁠y ʼiẏ֑wòb ki֣̇y ʼé֤yn ká̇mò֨⁠hẇ֙ bá̇⁠ʼá֔reẕ ʼi֣yş̌ ţá֧̇m wĕ⁠yáşá֛̌r yĕré֥ʼ ʼèlòhi֖ym wĕ⁠sá֥r mé⁠ráֽʻ׃"],[1,9,"וַ⁠יַּ֧עַן הַ⁠שָּׂטָ֛ן אֶת־יְהוָ֖ה וַ⁠יֹּאמַ֑ר הַֽ⁠חִנָּ֔ם יָרֵ֥א אִיּ֖וֹב אֱלֹהִֽים׃","wa⁠yȧ֧ʻan ha⁠şá̇̂tá֛n ʼeţ-yĕhwá֖h wa⁠yò̇ʼma֑r haֽ⁠ẖiná̇֔m yáré֥ʼ ʼiẏ֖wòb ʼèlòhiֽym׃"],[1,10,"הֲ⁠לֹֽא־את שַׂ֣כְתָּ בַעֲד֧⁠וֹ וּ⁠בְעַד־בֵּית֛⁠וֹ וּ⁠בְעַ֥ד כָּל־אֲשֶׁר־ל֖⁠וֹ מִ⁠סָּבִ֑יב מַעֲשֵׂ֤ה יָדָי⁠ו֙ בֵּרַ֔כְתָּ וּ⁠מִקְנֵ֖⁠הוּ פָּרַ֥ץ בָּ⁠אָֽרֶץ׃","hà⁠lòֽʼ-ʼţ şâ֣kĕţá̇ baʻàd֧⁠wò ẇ⁠bĕʻad-bé̇yţ֛⁠wò ẇ⁠bĕʻa֥d ká̇l-ʼàşěr-l֖⁠wò mi⁠sá̇bi֑yb maʻàşé֤̂h yádáy⁠w֙ bé̇ra֔kĕţá̇ ẇ⁠miqĕné֖⁠hẇ pá̇ra֥ẕ bá̇⁠ʼáֽreẕ׃"],[1,11,"וְ⁠אוּלָם֙ שְֽׁלַֽח־נָ֣א יָֽדְ⁠ךָ֔ וְ⁠גַ֖ע בְּ⁠כָל־אֲשֶׁר־ל֑⁠וֹ אִם־לֹ֥א עַל־פָּנֶ֖י⁠ךָ יְבָרֲכֶֽ⁠ךָּ׃","wĕ⁠ʼẇlám֙ şĕֽ̌laֽẖ-ná֣ʼ yáֽdĕ⁠ká֔ wĕ⁠ga֖ʻ bĕ̇⁠kál-ʼàşěr-l֑⁠wò ʼim-lò֥ʼ ʻal-pá̇ne֖y⁠ká yĕbáràkeֽ⁠ká̇׃"],[1,12,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־הַ⁠שָּׂטָ֗ן הִנֵּ֤ה כָל־אֲשֶׁר־ל⁠וֹ֙ בְּ⁠יָדֶ֔⁠ךָ רַ֣ק אֵלָ֔י⁠ו אַל־תִּשְׁלַ֖ח יָדֶ֑⁠ךָ וַ⁠יֵּצֵא֙ הַ⁠שָּׂטָ֔ן מֵ⁠עִ֖ם פְּנֵ֥י יְהוָֽה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-ha⁠şá̇̂tá֗n hiné֤̇h kál-ʼàşěr-l⁠wò֙ bĕ̇⁠yáde֔⁠ká ra֣q ʼélá֔y⁠w ʼal-ţi̇şĕ̌la֖ẖ yáde֑⁠ká wa⁠yé̇ẕéʼ֙ ha⁠şá̇̂tá֔n mé⁠ʻi֖m pĕ̇né֥y yĕhwáֽh׃"],[1,13,"וַ⁠יְהִ֖י הַ⁠יּ֑וֹם וּ⁠בָנָ֨י⁠ו וּ⁠בְנֹתָ֤י⁠ו אֹֽכְלִים֙ וְ⁠שֹׁתִ֣ים יַ֔יִן בְּ⁠בֵ֖ית אֲחִי⁠הֶ֥ם הַ⁠בְּכֽוֹר׃","wa⁠yĕhi֖y ha⁠ẏ֑wòm ẇ⁠báná֨y⁠w ẇ⁠bĕnòţá֤y⁠w ʼòֽkĕliym֙ wĕ⁠şò̌ţi֣ym ya֔yin bĕ̇⁠bé֖yţ ʼàẖiy⁠he֥m ha⁠bĕ̇kֽwòr׃"],[1,14,"וּ⁠מַלְאָ֛ךְ בָּ֥א אֶל־אִיּ֖וֹב וַ⁠יֹּאמַ֑ר הַ⁠בָּקָר֙ הָי֣וּ חֹֽרְשׁ֔וֹת וְ⁠הָ⁠אֲתֹנ֖וֹת רֹע֥וֹת עַל־יְדֵי⁠הֶֽם׃","ẇ⁠malĕʼá֛kĕ bá֥̇ʼ ʼel-ʼiẏ֖wòb wa⁠yò̇ʼma֑r ha⁠bá̇qár֙ háy֣ẇ ẖòֽrĕş̌֔wòţ wĕ⁠há⁠ʼàţòn֖wòţ ròʻ֥wòţ ʻal-yĕdéy⁠heֽm׃"],[1,15,"וַ⁠תִּפֹּ֤ל שְׁבָא֙ וַ⁠תִּקָּחֵ֔⁠ם וְ⁠אֶת־הַ⁠נְּעָרִ֖ים הִכּ֣וּ לְ⁠פִי־חָ֑רֶב וָֽ⁠אִמָּ֨לְטָ֧⁠ה רַק־אֲנִ֛י לְ⁠בַדִּ֖⁠י לְ⁠הַגִּ֥יד לָֽ⁠ךְ׃","wa⁠ţi̇pò֤̇l şĕ̌báʼ֙ wa⁠ţi̇qá̇ẖé֔⁠m wĕ⁠ʼeţ-ha⁠nĕ̇ʻári֖ym hik֣̇ẇ lĕ⁠piy-ẖá֑reb wáֽ⁠ʼimá̇֨lĕtá֧⁠h raq-ʼàni֛y lĕ⁠badi֖̇⁠y lĕ⁠hagi֥̇yd láֽ⁠kĕ׃"],[1,16,"ע֣וֹד ׀ זֶ֣ה מְדַבֵּ֗ר וְ⁠זֶה֮ בָּ֣א וַ⁠יֹּאמַר֒ אֵ֣שׁ אֱלֹהִ֗ים נָֽפְלָה֙ מִן־הַ⁠שָּׁמַ֔יִם וַ⁠תִּבְעַ֥ר בַּ⁠צֹּ֛אן וּ⁠בַ⁠נְּעָרִ֖ים וַ⁠תֹּאכְלֵ֑⁠ם וָ⁠אִמָּ֨לְטָ֧⁠ה רַק־אֲנִ֛י לְ⁠בַדִּ֖⁠י לְ⁠הַגִּ֥יד לָֽ⁠ךְ׃","ʻ֣wòd ׀ ze֣h mĕdabé̇֗r wĕ⁠zeh֮ bá֣̇ʼ wa⁠yò̇ʼmar֒ ʼé֣ş̌ ʼèlòhi֗ym náֽpĕláh֙ min-ha⁠şá̇̌ma֔yim wa⁠ţi̇bĕʻa֥r bȧ⁠ẕò֛̇ʼn ẇ⁠ba⁠nĕ̇ʻári֖ym wa⁠ţò̇ʼkĕlé֑⁠m wá⁠ʼimá̇֨lĕtá֧⁠h raq-ʼàni֛y lĕ⁠badi֖̇⁠y lĕ⁠hagi֥̇yd láֽ⁠kĕ׃"],[1,17,"ע֣וֹד ׀ זֶ֣ה מְדַבֵּ֗ר וְ⁠זֶה֮ בָּ֣א וַ⁠יֹּאמַר֒ כַּשְׂדִּ֞ים שָׂ֣מוּ ׀ שְׁלֹשָׁ֣ה רָאשִׁ֗ים וַֽ⁠יִּפְשְׁט֤וּ עַל־הַ⁠גְּמַלִּים֙ וַ⁠יִּקָּח֔וּ⁠ם וְ⁠אֶת־הַ⁠נְּעָרִ֖ים הִכּ֣וּ לְ⁠פִי־חָ֑רֶב וָ⁠אִמָּ֨לְטָ֧⁠ה רַק־אֲנִ֛י לְ⁠בַדִּ֖⁠י לְ⁠הַגִּ֥יד לָֽ⁠ךְ׃","ʻ֣wòd ׀ ze֣h mĕdabé̇֗r wĕ⁠zeh֮ bá֣̇ʼ wa⁠yò̇ʼmar֒ kȧşĕ̂di̇֞ym şá֣̂mẇ ׀ şĕ̌lòşá֣̌h ráʼşǐ֗ym waֽ⁠yi̇pĕşĕ̌t֤ẇ ʻal-ha⁠gĕ̇mali̇ym֙ wa⁠yi̇qá̇ẖ֔ẇ⁠m wĕ⁠ʼeţ-ha⁠nĕ̇ʻári֖ym hik֣̇ẇ lĕ⁠piy-ẖá֑reb wá⁠ʼimá̇֨lĕtá֧⁠h raq-ʼàni֛y lĕ⁠badi֖̇⁠y lĕ⁠hagi֥̇yd láֽ⁠kĕ׃"],[1,18,"עַ֚ד זֶ֣ה מְדַבֵּ֔ר וְ⁠זֶ֖ה בָּ֣א וַ⁠יֹּאמַ֑ר בָּנֶ֨י⁠ךָ וּ⁠בְנוֹתֶ֤י⁠ךָ אֹֽכְלִים֙ וְ⁠שֹׁתִ֣ים יַ֔יִן בְּ⁠בֵ֖ית אֲחִי⁠הֶ֥ם הַ⁠בְּכֽוֹר׃","ʻa֚d ze֣h mĕdabé̇֔r wĕ⁠ze֖h bá֣̇ʼ wa⁠yò̇ʼma֑r bá̇ne֨y⁠ká ẇ⁠bĕnwòţe֤y⁠ká ʼòֽkĕliym֙ wĕ⁠şò̌ţi֣ym ya֔yin bĕ̇⁠bé֖yţ ʼàẖiy⁠he֥m ha⁠bĕ̇kֽwòr׃"],[1,19,"וְ⁠הִנֵּה֩ ר֨וּחַ גְּדוֹלָ֜ה בָּ֣אָה ׀ מֵ⁠עֵ֣בֶר הַ⁠מִּדְבָּ֗ר וַ⁠יִּגַּע֙ בְּ⁠אַרְבַּע֙ פִּנּ֣וֹת הַ⁠בַּ֔יִת וַ⁠יִּפֹּ֥ל עַל־הַ⁠נְּעָרִ֖ים וַ⁠יָּמ֑וּתוּ וָ⁠אִמָּ֨לְטָ֧⁠ה רַק־אֲנִ֛י לְ⁠בַדִּ֖⁠י לְ⁠הַגִּ֥יד לָֽ⁠ךְ׃","wĕ⁠hiné̇h֩ r֨ẇẖa gĕ̇dwòlá֜h bá֣̇ʼáh ׀ mé⁠ʻé֣ber ha⁠mi̇dĕbá̇֗r wa⁠yi̇gȧʻ֙ bĕ̇⁠ʼarĕbȧʻ֙ pi̇ṅ֣wòţ ha⁠bȧ֔yiţ wa⁠yi̇pò֥̇l ʻal-ha⁠nĕ̇ʻári֖ym wa⁠yá̇m֑ẇţẇ wá⁠ʼimá̇֨lĕtá֧⁠h raq-ʼàni֛y lĕ⁠badi֖̇⁠y lĕ⁠hagi֥̇yd láֽ⁠kĕ׃"],[1,20,"וַ⁠יָּ֤קָם אִיּוֹב֙ וַ⁠יִּקְרַ֣ע אֶת־מְעִל֔⁠וֹ וַ⁠יָּ֖גָז אֶת־רֹאשׁ֑⁠וֹ וַ⁠יִּפֹּ֥ל אַ֖רְצָ⁠ה וַ⁠יִּשְׁתָּֽחוּ׃","wa⁠yá֤̇qám ʼiẏwòb֙ wa⁠yi̇qĕra֣ʻ ʼeţ-mĕʻil֔⁠wò wa⁠yá֖̇gáz ʼeţ-ròʼş֑̌⁠wò wa⁠yi̇pò֥̇l ʼa֖rĕẕá⁠h wa⁠yi̇şĕ̌ţáֽ̇ẖẇ׃"],[1,21,"וַ⁠יֹּאמֶר֩ עָרֹ֨ם יצתי מִ⁠בֶּ֣טֶן אִמִּ֗⁠י וְ⁠עָרֹם֙ אָשׁ֣וּב שָׁ֔מָ⁠ה יְהוָ֣ה נָתַ֔ן וַ⁠יהוָ֖ה לָקָ֑ח יְהִ֛י שֵׁ֥ם יְהוָ֖ה מְבֹרָֽךְ׃","wa⁠yò̇ʼmer֩ ʻárò֨m yẕţy mi⁠bė֣ten ʼimi̇֗⁠y wĕ⁠ʻáròm֙ ʼáş֣̌ẇb şá̌֔má⁠h yĕhwá֣h náţa֔n wa⁠yhwá֖h láqá֑ẖ yĕhi֛y şé֥̌m yĕhwá֖h mĕbòráֽkĕ׃"],[1,22,"בְּ⁠כָל־זֹ֖את לֹא־חָטָ֣א אִיּ֑וֹב וְ⁠לֹא־נָתַ֥ן תִּפְלָ֖ה לֵ⁠אלֹהִֽים׃פ","bĕ̇⁠kál-zò֖ʼţ lòʼ-ẖátá֣ʼ ʼiẏ֑wòb wĕ⁠lòʼ-náţa֥n ţi̇pĕlá֖h lé⁠ʼlòhiֽym׃p"],[2,1,"וַ⁠יְהִ֣י הַ⁠יּ֔וֹם וַ⁠יָּבֹ֨אוּ֙ בְּנֵ֣י הָֽ⁠אֱלֹהִ֔ים לְ⁠הִתְיַצֵּ֖ב עַל־יְהוָ֑ה וַ⁠יָּב֤וֹא גַֽם־הַ⁠שָּׂטָן֙ בְּ⁠תֹכָ֔⁠ם לְ⁠הִתְיַצֵּ֖ב עַל־יְהוָֽה׃","wa⁠yĕhi֣y ha⁠ẏ֔wòm wa⁠yá̇bò֨ʼẇ֙ bĕ̇né֣y háֽ⁠ʼèlòhi֔ym lĕ⁠hiţĕyaẕé֖̇b ʻal-yĕhwá֑h wa⁠yá̇b֤wòʼ gaֽm-ha⁠şá̇̂tán֙ bĕ̇⁠ţòká֔⁠m lĕ⁠hiţĕyaẕé֖̇b ʻal-yĕhwáֽh׃"],[2,2,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־הַ⁠שָּׂטָ֔ן אֵ֥י מִ⁠זֶּ֖ה תָּבֹ֑א וַ⁠יַּ֨עַן הַ⁠שָּׂטָ֤ן אֶת־יְהוָה֙ וַ⁠יֹּאמַ֔ר מִ⁠שֻּׁ֣ט בָּ⁠אָ֔רֶץ וּ⁠מֵ⁠הִתְהַלֵּ֖ךְ בָּֽ⁠הּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-ha⁠şá̇̂tá֔n ʼé֥y mi⁠zė֖h ţá̇bò֑ʼ wa⁠yȧ֨ʻan ha⁠şá̇̂tá֤n ʼeţ-yĕhwáh֙ wa⁠yò̇ʼma֔r mi⁠şu֣̇̌t bá̇⁠ʼá֔reẕ ẇ⁠mé⁠hiţĕhalé֖̇kĕ báֽ̇⁠ḣ׃"],[2,3,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־הַ⁠שָּׂטָ֗ן הֲ⁠שַׂ֣מְתָּ לִבְּ⁠ךָ֮ אֶל־עַבְדִּ֣⁠י אִיּוֹב֒ כִּי֩ אֵ֨ין כָּמֹ֜⁠הוּ בָּ⁠אָ֗רֶץ אִ֣ישׁ תָּ֧ם וְ⁠יָשָׁ֛ר יְרֵ֥א אֱלֹהִ֖ים וְ⁠סָ֣ר מֵ⁠רָ֑ע וְ⁠עֹדֶ֨⁠נּוּ֙ מַחֲזִ֣יק בְּ⁠תֻמָּת֔⁠וֹ וַ⁠תְּסִיתֵ֥⁠נִי ב֖⁠וֹ לְ⁠בַלְּע֥⁠וֹ חִנָּֽם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-ha⁠şá̇̂tá֗n hà⁠şâ֣mĕţá̇ libĕ̇⁠ká֮ ʼel-ʻabĕdi֣̇⁠y ʼiẏwòb֒ ki̇y֩ ʼé֨yn ká̇mò֜⁠hẇ bá̇⁠ʼá֗reẕ ʼi֣yş̌ ţá֧̇m wĕ⁠yáşá֛̌r yĕré֥ʼ ʼèlòhi֖ym wĕ⁠sá֣r mé⁠rá֑ʻ wĕ⁠ʻòde֨⁠ṅẇ֙ maẖàzi֣yq bĕ̇⁠ţumá̇ţ֔⁠wò wa⁠ţĕ̇siyţé֥⁠niy b֖⁠wò lĕ⁠balĕ̇ʻ֥⁠wò ẖináֽ̇m׃"],[2,4,"וַ⁠יַּ֧עַן הַ⁠שָּׂטָ֛ן אֶת־יְהוָ֖ה וַ⁠יֹּאמַ֑ר ע֣וֹר בְּעַד־ע֗וֹר וְ⁠כֹל֙ אֲשֶׁ֣ר לָ⁠אִ֔ישׁ יִתֵּ֖ן בְּעַ֥ד נַפְשֽׁ⁠וֹ׃","wa⁠yȧ֧ʻan ha⁠şá̇̂tá֛n ʼeţ-yĕhwá֖h wa⁠yò̇ʼma֑r ʻ֣wòr bĕ̇ʻad-ʻ֗wòr wĕ⁠kòl֙ ʼàşě֣r lá⁠ʼi֔yş̌ yiţé֖̇n bĕ̇ʻa֥d napĕşֽ̌⁠wò׃"],[2,5,"אוּלָם֙ שְֽׁלַֽח־נָ֣א יָֽדְ⁠ךָ֔ וְ⁠גַ֥ע אֶל־עַצְמ֖⁠וֹ וְ⁠אֶל־בְּשָׂר֑⁠וֹ אִם־לֹ֥א אֶל־פָּנֶ֖י⁠ךָ יְבָרֲכֶֽ⁠ךָּ׃","ʼẇlám֙ şĕֽ̌laֽẖ-ná֣ʼ yáֽdĕ⁠ká֔ wĕ⁠ga֥ʻ ʼel-ʻaẕĕm֖⁠wò wĕ⁠ʼel-bĕ̇şá̂r֑⁠wò ʼim-lò֥ʼ ʼel-pá̇ne֖y⁠ká yĕbáràkeֽ⁠ká̇׃"],[2,6,"וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֶל־הַ⁠שָּׂטָ֖ן הִנּ֣⁠וֹ בְ⁠יָדֶ֑⁠ךָ אַ֖ךְ אֶת־נַפְשׁ֥⁠וֹ שְׁמֹֽר׃","wa⁠yò֧̇ʼmer yĕhwá֛h ʼel-ha⁠şá̇̂tá֖n hiṅ֣⁠wò bĕ⁠yáde֑⁠ká ʼa֖kĕ ʼeţ-napĕş֥̌⁠wò şĕ̌mòֽr׃"],[2,7,"וַ⁠יֵּצֵא֙ הַ⁠שָּׂטָ֔ן מֵ⁠אֵ֖ת פְּנֵ֣י יְהוָ֑ה וַ⁠יַּ֤ךְ אֶת־אִיּוֹב֙ בִּ⁠שְׁחִ֣ין רָ֔ע מִ⁠כַּ֥ף רַגְל֖⁠וֹ עד קָדְקֳדֽ⁠וֹ׃","wa⁠yé̇ẕéʼ֙ ha⁠şá̇̂tá֔n mé⁠ʼé֖ţ pĕ̇né֣y yĕhwá֑h wa⁠yȧ֤kĕ ʼeţ-ʼiẏwòb֙ bi̇⁠şĕ̌ẖi֣yn rá֔ʻ mi⁠kȧ֥p ragĕl֖⁠wò ʻd qádĕqodֽ⁠wò׃"],[2,8,"וַ⁠יִּֽקַּֽח־ל֣⁠וֹ חֶ֔רֶשׂ לְ⁠הִתְגָּרֵ֖ד בּ֑⁠וֹ וְ⁠ה֖וּא יֹשֵׁ֥ב בְּ⁠תוֹךְ־הָ⁠אֵֽפֶר׃","wa⁠yiֽ̇qȧֽẖ-l֣⁠wò ẖe֔reş̂ lĕ⁠hiţĕgá̇ré֖d ḃ֑⁠wò wĕ⁠h֖ẇʼ yòşé֥̌b bĕ̇⁠ţwòkĕ-há⁠ʼéֽper׃"],[2,9,"וַ⁠תֹּ֤אמֶר ל⁠וֹ֙ אִשְׁתּ֔⁠וֹ עֹדְ⁠ךָ֖ מַחֲזִ֣יק בְּ⁠תֻמָּתֶ֑⁠ךָ בָּרֵ֥ךְ אֱלֹהִ֖ים וָ⁠מֻֽת׃","wa⁠ţò֤̇ʼmer l⁠wò֙ ʼişĕ̌ţ̇֔⁠wò ʻòdĕ⁠ká֖ maẖàzi֣yq bĕ̇⁠ţumá̇ţe֑⁠ká bá̇ré֥kĕ ʼèlòhi֖ym wá⁠muֽţ׃"],[2,10,"וַ⁠יֹּ֣אמֶר אֵלֶ֗י⁠הָ כְּ⁠דַבֵּ֞ר אַחַ֤ת הַ⁠נְּבָלוֹת֙ תְּדַבֵּ֔רִי גַּ֣ם אֶת־הַ⁠טּ֗וֹב נְקַבֵּל֙ מֵ⁠אֵ֣ת הָ⁠אֱלֹהִ֔ים וְ⁠אֶת־הָ⁠רָ֖ע לֹ֣א נְקַבֵּ֑ל בְּ⁠כָל־זֹ֛את לֹא־חָטָ֥א אִיּ֖וֹב בִּ⁠שְׂפָתָֽי⁠ו׃פ","wa⁠yò֣̇ʼmer ʼéle֗y⁠há kĕ̇⁠dabé̇֞r ʼaẖa֤ţ ha⁠nĕ̇bálwòţ֙ ţĕ̇dabé̇֔riy gȧ֣m ʼeţ-ha⁠ṫ֗wòb nĕqabé̇l֙ mé⁠ʼé֣ţ há⁠ʼèlòhi֔ym wĕ⁠ʼeţ-há⁠rá֖ʻ lò֣ʼ nĕqabé֑̇l bĕ̇⁠kál-zò֛ʼţ lòʼ-ẖátá֥ʼ ʼiẏ֖wòb bi̇⁠şĕ̂páţáֽy⁠w׃p"],[2,11,"וַֽ⁠יִּשְׁמְע֞וּ שְׁלֹ֣שֶׁת ׀ רֵעֵ֣י אִיּ֗וֹב אֵ֣ת כָּל־הָ⁠רָעָ֣ה הַ⁠זֹּאת֮ הַ⁠בָּ֣אָה עָלָי⁠ו֒ וַ⁠יָּבֹ֨אוּ֙ אִ֣ישׁ מִ⁠מְּקֹמ֔⁠וֹ אֱלִיפַ֤ז הַ⁠תֵּימָנִי֙ וּ⁠בִלְדַּ֣ד הַ⁠שּׁוּחִ֔י וְ⁠צוֹפַ֖ר הַ⁠נַּֽעֲמָתִ֑י וַ⁠יִּוָּעֲד֣וּ יַחְדָּ֔ו לָ⁠ב֥וֹא לָ⁠נֽוּד־ל֖⁠וֹ וּֽ⁠לְ⁠נַחֲמֽ⁠וֹ׃","waֽ⁠yi̇şĕ̌mĕʻ֞ẇ şĕ̌lò֣şěţ ׀ réʻé֣y ʼiẏ֗wòb ʼé֣ţ ká̇l-há⁠ráʻá֣h ha⁠zò̇ʼţ֮ ha⁠bá֣̇ʼáh ʻáláy⁠w֒ wa⁠yá̇bò֨ʼẇ֙ ʼi֣yş̌ mi⁠mĕ̇qòm֔⁠wò ʼèliypa֤z ha⁠ţé̇ymániy֙ ẇ⁠bilĕdȧ֣d ha⁠ş̇̌ẇẖi֔y wĕ⁠ẕwòpa֖r ha⁠nȧֽʻàmáţi֑y wa⁠yi̇wá̇ʻàd֣ẇ yaẖĕdá̇֔w lá⁠b֥wòʼ lá⁠nֽẇd-l֖⁠wò ẇֽ⁠lĕ⁠naẖàmֽ⁠wò׃"],[2,12,"וַ⁠יִּשְׂא֨וּ אֶת־עֵינֵי⁠הֶ֤ם מֵ⁠רָחוֹק֙ וְ⁠לֹ֣א הִכִּירֻ֔⁠הוּ וַ⁠יִּשְׂא֥וּ קוֹלָ֖⁠ם וַ⁠יִּבְכּ֑וּ וַֽ⁠יִּקְרְעוּ֙ אִ֣ישׁ מְעִל֔⁠וֹ וַ⁠יִּזְרְק֥וּ עָפָ֛ר עַל־רָאשֵׁי⁠הֶ֖ם הַ⁠שָּׁמָֽיְמָ⁠ה׃","wa⁠yi̇şĕ̂ʼ֨ẇ ʼeţ-ʻéynéy⁠he֤m mé⁠ráẖwòq֙ wĕ⁠lò֣ʼ hiki̇yru֔⁠hẇ wa⁠yi̇şĕ̂ʼ֥ẇ qwòlá֖⁠m wa⁠yi̇bĕk֑̇ẇ waֽ⁠yi̇qĕrĕʻẇ֙ ʼi֣yş̌ mĕʻil֔⁠wò wa⁠yi̇zĕrĕq֥ẇ ʻápá֛r ʻal-ráʼşé̌y⁠he֖m ha⁠şá̇̌máֽyĕmá⁠h׃"],[2,13,"וַ⁠יֵּשְׁב֤וּ אִתּ⁠וֹ֙ לָ⁠אָ֔רֶץ שִׁבְעַ֥ת יָמִ֖ים וְ⁠שִׁבְעַ֣ת לֵיל֑וֹת וְ⁠אֵין־דֹּבֵ֤ר אֵלָי⁠ו֙ דָּבָ֔ר כִּ֣י רָא֔וּ כִּֽי־גָדַ֥ל הַ⁠כְּאֵ֖ב מְאֹֽד׃","wa⁠yé̇şĕ̌b֤ẇ ʼiţ̇⁠wò֙ lá⁠ʼá֔reẕ şǐbĕʻa֥ţ yámi֖ym wĕ⁠şǐbĕʻa֣ţ léyl֑wòţ wĕ⁠ʼéyn-dò̇bé֤r ʼéláy⁠w֙ dá̇bá֔r ki֣̇y ráʼ֔ẇ kiֽ̇y-gáda֥l ha⁠kĕ̇ʼé֖b mĕʼòֽd׃"],[3,1,"אַחֲרֵי־כֵ֗ן פָּתַ֤ח אִיּוֹב֙ אֶת־פִּ֔י⁠הוּ וַ⁠יְקַלֵּ֖ל אֶת־יוֹמֽ⁠וֹ׃פ","ʼaẖàréy-ké֗n pá̇ţa֤ẖ ʼiẏwòb֙ ʼeţ-pi̇֔y⁠hẇ wa⁠yĕqalé֖̇l ʼeţ-ywòmֽ⁠wò׃p"],[3,2,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[3,3,"יֹ֣אבַד י֭וֹם אִוָּ֣לֶד בּ֑⁠וֹ וְ⁠הַ⁠לַּ֥יְלָה אָ֝מַ֗ר הֹ֣רָה גָֽבֶר׃","yò֣ʼbad y֭wòm ʼiwá֣̇led ḃ֑⁠wò wĕ⁠ha⁠lȧ֥yĕláh ʼá֝ma֗r hò֣ráh gáֽber׃"],[3,4,"הַ⁠יּ֥וֹם הַ⁠ה֗וּא יְֽהִ֫י חֹ֥שֶׁךְ אַֽל־יִדְרְשֵׁ֣⁠הוּ אֱל֣וֹהַּ מִ⁠מָּ֑עַל וְ⁠אַל־תּוֹפַ֖ע עָלָ֣י⁠ו נְהָרָֽה׃","ha⁠ẏ֥wòm ha⁠h֗ẇʼ yĕֽhi֫y ẖò֥şěkĕ ʼaֽl-yidĕrĕşé֣̌⁠hẇ ʼèl֣wòhȧ mi⁠má֑̇ʻal wĕ⁠ʼal-ţ̇wòpa֖ʻ ʻálá֣y⁠w nĕháráֽh׃"],[3,5,"יִגְאָלֻ֡⁠הוּ חֹ֣שֶׁךְ וְ֭⁠צַלְמָוֶת תִּשְׁכָּן־עָלָ֣י⁠ו עֲנָנָ֑ה יְ֝בַעֲתֻ֗⁠הוּ כִּֽמְרִ֥ירֵי יֽוֹם׃","yigĕʼálu֡⁠hẇ ẖò֣şěkĕ wĕ֭⁠ẕalĕmáweţ ţi̇şĕ̌ká̇n-ʻálá֣y⁠w ʻànáná֑h yĕ֝baʻàţu֗⁠hẇ kiֽ̇mĕri֥yréy yֽwòm׃"],[3,6,"הַ⁠לַּ֥יְלָה הַ⁠הוּא֮ יִקָּחֵ֪⁠ה֫וּ אֹ֥פֶל אַל־יִ֭חַדְּ בִּ⁠ימֵ֣י שָׁנָ֑ה בְּ⁠מִסְפַּ֥ר יְ֝רָחִ֗ים אַל־יָבֹֽא׃","ha⁠lȧ֥yĕláh ha⁠hẇʼ֮ yiqá̇ẖé֪⁠h֫ẇ ʼò֥pel ʼal-yi֭ẖadĕ̇ bi̇⁠ymé֣y şá̌ná֑h bĕ̇⁠misĕpȧ֥r yĕ֝ráẖi֗ym ʼal-yábòֽʼ׃"],[3,7,"הִנֵּ֤ה הַ⁠לַּ֣יְלָה הַ֭⁠הוּא יְהִ֣י גַלְמ֑וּד אַל־תָּבֹ֖א רְנָנָ֣ה בֽ⁠וֹ׃","hiné֤̇h ha⁠lȧ֣yĕláh ha֭⁠hẇʼ yĕhi֣y galĕm֑ẇd ʼal-ţá̇bò֖ʼ rĕnáná֣h bֽ⁠wò׃"],[3,8,"יִקְּבֻ֥⁠הוּ אֹרְרֵי־י֑וֹם הָ֝⁠עֲתִידִ֗ים עֹרֵ֥ר לִוְיָתָֽן׃","yiqĕ̇bu֥⁠hẇ ʼòrĕréy-y֑wòm há֝⁠ʻàţiydi֗ym ʻòré֥r liwĕyáţáֽn׃"],[3,9,"יֶחְשְׁכוּ֮ כּוֹכְבֵ֪י נִ֫שְׁפּ֥⁠וֹ יְקַו־לְ⁠א֥וֹר וָ⁠אַ֑יִן וְ⁠אַל־יִ֝רְאֶ֗ה בְּ⁠עַפְעַפֵּי־שָֽׁחַר׃","yeẖĕşĕ̌kẇ֮ k̇wòkĕbé֪y ni֫şĕ̌ṗ֥⁠wò yĕqaw-lĕ⁠ʼ֥wòr wá⁠ʼa֑yin wĕ⁠ʼal-yi֝rĕʼe֗h bĕ̇⁠ʻapĕʻapé̇y-şáֽ̌ẖar׃"],[3,10,"כִּ֤י לֹ֣א סָ֭גַר דַּלְתֵ֣י בִטְנִ֑⁠י וַ⁠יַּסְתֵּ֥ר עָ֝מָ֗ל מֵ⁠עֵינָֽ⁠י׃","ki֤̇y lò֣ʼ sá֭gar dȧlĕţé֣y bitĕni֑⁠y wa⁠yȧsĕţé֥̇r ʻá֝má֗l mé⁠ʻéynáֽ⁠y׃"],[3,11,"לָ֤⁠מָּה לֹּ֣א מֵ⁠רֶ֣חֶם אָמ֑וּת מִ⁠בֶּ֖טֶן יָצָ֣אתִי וְ⁠אֶגְוָֽע׃","lá֤⁠má̇h lò֣̇ʼ mé⁠re֣ẖem ʼám֑ẇţ mi⁠bė֖ten yáẕá֣ʼţiy wĕ⁠ʼegĕwáֽʻ׃"],[3,12,"מַ֭דּוּעַ קִדְּמ֣וּ⁠נִי בִרְכָּ֑יִם וּ⁠מַה־שָּׁ֝דַ֗יִם כִּ֣י אִינָֽק׃","ma֭ḋẇʻa qidĕ̇m֣ẇ⁠niy birĕká֑̇yim ẇ⁠mah-şá̇̌֝da֗yim ki֣̇y ʼiynáֽq׃"],[3,13,"כִּֽי־עַ֭תָּה שָׁכַ֣בְתִּי וְ⁠אֶשְׁק֑וֹט יָ֝שַׁ֗נְתִּי אָ֤ז ׀ יָנ֬וּחַֽ לִֽ⁠י׃","kiֽ̇y-ʻa֭ţá̇h şá̌ka֣bĕţi̇y wĕ⁠ʼeşĕ̌q֑wòt yá֝şǎ֗nĕţi̇y ʼá֤z ׀ yán֬ẇẖaֽ liֽ⁠y׃"],[3,14,"עִם־מְ֭לָכִים וְ⁠יֹ֣עֲצֵי אָ֑רֶץ הַ⁠בֹּנִ֖ים חֳרָב֣וֹת לָֽ⁠מוֹ׃","ʻim-mĕ֭lákiym wĕ⁠yò֣ʻàẕéy ʼá֑reẕ ha⁠bò̇ni֖ym ẖoráb֣wòţ láֽ⁠mwò׃"],[3,15,"א֣וֹ עִם־שָׂ֭רִים זָהָ֣ב לָ⁠הֶ֑ם הַֽ⁠מְמַלְאִ֖ים בָּתֵּי⁠הֶ֣ם כָּֽסֶף׃","ʼ֣wò ʻim-şá֭̂riym záhá֣b lá⁠he֑m haֽ⁠mĕmalĕʼi֖ym bá̇ţé̇y⁠he֣m káֽ̇sep׃"],[3,16,"א֤וֹ כְ⁠נֵ֣פֶל טָ֭מוּן לֹ֣א אֶהְיֶ֑ה כְּ֝⁠עֹלְלִ֗ים לֹא־רָ֥אוּ אֽוֹר׃","ʼ֤wò kĕ⁠né֣pel tá֭mẇn lò֣ʼ ʼehĕye֑h kĕ̇֝⁠ʻòlĕli֗ym lòʼ-rá֥ʼẇ ʼֽwòr׃"],[3,17,"שָׁ֣ם רְ֭שָׁעִים חָ֣דְלוּ רֹ֑גֶז וְ⁠שָׁ֥ם יָ֝נ֗וּחוּ יְגִ֣יעֵי כֹֽחַ׃","şá֣̌m rĕ֭şá̌ʻiym ẖá֣dĕlẇ rò֑gez wĕ⁠şá֥̌m yá֝n֗ẇẖẇ yĕgi֣yʻéy kòֽẖa׃"],[3,18,"יַ֭חַד אֲסִירִ֣ים שַׁאֲנָ֑נוּ לֹ֥א שָׁ֝מְע֗וּ ק֣וֹל נֹגֵֽשׂ׃","ya֭ẖad ʼàsiyri֣ym şǎʼàná֑nẇ lò֥ʼ şá̌֝mĕʻ֗ẇ q֣wòl nògéֽş̂׃"],[3,19,"קָטֹ֣ן וְ֭⁠גָדוֹל שָׁ֣ם ה֑וּא וְ֝⁠עֶ֗בֶד חָפְשִׁ֥י מֵ⁠אֲדֹנָֽי⁠ו׃","qátò֣n wĕ֭⁠gádwòl şá֣̌m h֑ẇʼ wĕ֝⁠ʻe֗bed ẖápĕşǐ֥y mé⁠ʼàdònáֽy⁠w׃"],[3,20,"לָ֤⁠מָּה יִתֵּ֣ן לְ⁠עָמֵ֣ל א֑וֹר וְ֝⁠חַיִּ֗ים לְ⁠מָ֣רֵי נָֽפֶשׁ׃","lá֤⁠má̇h yiţé֣̇n lĕ⁠ʻámé֣l ʼ֑wòr wĕ֝⁠ẖayi̇֗ym lĕ⁠má֣réy náֽpeş̌׃"],[3,21,"הַֽ⁠מְחַכִּ֣ים לַ⁠מָּ֣וֶת וְ⁠אֵינֶ֑⁠נּוּ וַֽ֝⁠יַּחְפְּרֻ֗⁠הוּ מִ⁠מַּטְמוֹנִֽים׃","haֽ⁠mĕẖaki֣̇ym la⁠má֣̇weţ wĕ⁠ʼéyne֑⁠ṅẇ waֽ֝⁠yȧẖĕpĕ̇ru֗⁠hẇ mi⁠mȧtĕmwòniֽym׃"],[3,22,"הַ⁠שְּׂמֵחִ֥ים אֱלֵי־גִ֑יל יָ֝שִׂ֗ישׂוּ כִּ֣י יִמְצְאוּ־קָֽבֶר׃","ha⁠şĕ̇̂méẖi֥ym ʼèléy-gi֑yl yá֝şî֗yş̂ẇ ki֣̇y yimĕẕĕʼẇ-qáֽber׃"],[3,23,"לְ֭⁠גֶבֶר אֲשֶׁר־דַּרְכּ֣⁠וֹ נִסְתָּ֑רָה וַ⁠יָּ֖סֶךְ אֱל֣וֹהַּ בַּעֲדֽ⁠וֹ׃","lĕ֭⁠geber ʼàşěr-dȧrĕk֣̇⁠wò nisĕţá֑̇ráh wa⁠yá֖̇sekĕ ʼèl֣wòhȧ bȧʻàdֽ⁠wò׃"],[3,24,"כִּֽי־לִ⁠פְנֵ֣י לַ֭חְמִ⁠י אַנְחָתִ֣⁠י תָבֹ֑א וַֽ⁠יִּתְּכ֥וּ כַ֝⁠מַּ֗יִם שַׁאֲגֹתָֽ⁠י׃","kiֽ̇y-li⁠pĕné֣y la֭ẖĕmi⁠y ʼanĕẖáţi֣⁠y ţábò֑ʼ waֽ⁠yi̇ţĕ̇k֥ẇ ka֝⁠mȧ֗yim şǎʼàgòţáֽ⁠y׃"],[3,25,"כִּ֤י פַ֣חַד פָּ֭חַדְתִּי וַ⁠יֶּאֱתָיֵ֑⁠נִי וַ⁠אֲשֶׁ֥ר יָ֝גֹ֗רְתִּי יָ֣בֹא לִֽ⁠י׃","ki֤̇y pa֣ẖad pá֭̇ẖadĕţi̇y wa⁠yėʼèţáyé֑⁠niy wa⁠ʼàşě֥r yá֝gò֗rĕţi̇y yá֣bòʼ liֽ⁠y׃"],[3,26,"לֹ֤א שָׁלַ֨וְתִּי ׀ וְ⁠לֹ֖א שָׁקַ֥טְתִּי וְֽ⁠לֹא־נָ֗חְתִּי וַ⁠יָּ֥בֹא רֹֽגֶז׃פ","lò֤ʼ şá̌la֨wĕţi̇y ׀ wĕ⁠lò֖ʼ şá̌qa֥tĕţi̇y wĕֽ⁠lòʼ-ná֗ẖĕţi̇y wa⁠yá֥̇bòʼ ròֽgez׃p"],[4,1,"וַ֭⁠יַּעַן אֱלִיפַ֥ז הַֽ⁠תֵּימָנִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan ʼèliypa֥z haֽ⁠ţé̇ymáni֗y wa⁠yò̇ʼmaֽr׃"],[4,2,"הֲ⁠נִסָּ֬ה דָבָ֣ר אֵלֶ֣י⁠ךָ תִּלְאֶ֑ה וַ⁠עְצֹ֥ר בְּ֝⁠מִלִּ֗ין מִ֣י יוּכָֽל׃","hà⁠nisá̇֬h dábá֣r ʼéle֣y⁠ká ţi̇lĕʼe֑h wa⁠ʻĕẕò֥r bĕ̇֝⁠mili̇֗yn mi֣y yẇkáֽl׃"],[4,3,"הִ֭נֵּה יִסַּ֣רְתָּ רַבִּ֑ים וְ⁠יָדַ֖יִם רָפ֣וֹת תְּחַזֵּֽק׃","hi֭né̇h yisȧ֣rĕţá̇ rabi֑̇ym wĕ⁠yáda֖yim ráp֣wòţ ţĕ̇ẖazéֽ̇q׃"],[4,4,"כּ֭וֹשֵׁל יְקִימ֣וּ⁠ן מִלֶּ֑י⁠ךָ וּ⁠בִרְכַּ֖יִם כֹּרְע֣וֹת תְּאַמֵּֽץ׃","k֭̇wòşé̌l yĕqiym֣ẇ⁠n milė֑y⁠ká ẇ⁠birĕkȧ֖yim kò̇rĕʻ֣wòţ ţĕ̇ʼaméֽ̇ẕ׃"],[4,5,"כִּ֤י עַתָּ֨ה ׀ תָּב֣וֹא אֵלֶ֣י⁠ךָ וַ⁠תֵּ֑לֶא תִּגַּ֥ע עָ֝דֶ֗י⁠ךָ וַ⁠תִּבָּהֵֽל׃","ki֤̇y ʻaţá̇֨h ׀ ţá̇b֣wòʼ ʼéle֣y⁠ká wa⁠ţé֑̇leʼ ţi̇gȧ֥ʻ ʻá֝de֗y⁠ká wa⁠ţi̇bá̇héֽl׃"],[4,6,"הֲ⁠לֹ֣א יִ֭רְאָתְ⁠ךָ כִּסְלָתֶ֑⁠ךָ תִּ֝קְוָתְ⁠ךָ֗ וְ⁠תֹ֣ם דְּרָכֶֽי⁠ךָ׃","hà⁠lò֣ʼ yi֭rĕʼáţĕ⁠ká ki̇sĕláţe֑⁠ká ţi̇֝qĕwáţĕ⁠ká֗ wĕ⁠ţò֣m dĕ̇rákeֽy⁠ká׃"],[4,7,"זְכָר־נָ֗א מִ֤י ה֣וּא נָקִ֣י אָבָ֑ד וְ֝⁠אֵיפֹ֗ה יְשָׁרִ֥ים נִכְחָֽדוּ׃","zĕkár-ná֗ʼ mi֤y h֣ẇʼ náqi֣y ʼábá֑d wĕ֝⁠ʼéypò֗h yĕşá̌ri֥ym nikĕẖáֽdẇ׃"],[4,8,"כַּ⁠אֲשֶׁ֣ר רָ֭אִיתִי חֹ֣רְשֵׁי אָ֑וֶן וְ⁠זֹרְעֵ֖י עָמָ֣ל יִקְצְרֻֽ⁠הוּ׃","kȧ⁠ʼàşě֣r rá֭ʼiyţiy ẖò֣rĕşé̌y ʼá֑wen wĕ⁠zòrĕʻé֖y ʻámá֣l yiqĕẕĕruֽ⁠hẇ׃"],[4,9,"מִ⁠נִּשְׁמַ֣ת אֱל֣וֹהַ יֹאבֵ֑דוּ וּ⁠מֵ⁠ר֖וּחַ אַפּ֣⁠וֹ יִכְלֽוּ׃","mi⁠ni̇şĕ̌ma֣ţ ʼèl֣wòha yòʼbé֑dẇ ẇ⁠mé⁠r֖ẇẖa ʼaṗ֣⁠wò yikĕlֽẇ׃"],[4,10,"שַׁאֲגַ֣ת אַ֭רְיֵה וְ⁠ק֣וֹל שָׁ֑חַל וְ⁠שִׁנֵּ֖י כְפִירִ֣ים נִתָּֽעוּ׃","şǎʼàga֣ţ ʼa֭rĕyéh wĕ⁠q֣wòl şá֑̌ẖal wĕ⁠şǐné֖̇y kĕpiyri֣ym niţáֽ̇ʻẇ׃"],[4,11,"לַ֭יִשׁ אֹבֵ֣ד מִ⁠בְּלִי־טָ֑רֶף וּ⁠בְנֵ֥י לָ֝בִ֗יא יִתְפָּרָֽדוּ׃","la֭yiş̌ ʼòbé֣d mi⁠bĕ̇liy-tá֑rep ẇ⁠bĕné֥y lá֝bi֗yʼ yiţĕpá̇ráֽdẇ׃"],[4,12,"וְ֭⁠אֵלַ⁠י דָּבָ֣ר יְגֻנָּ֑ב וַ⁠תִּקַּ֥ח אָ֝זְנִ֗⁠י שֵׁ֣מֶץ מֶֽנְ⁠הֽוּ׃","wĕ֭⁠ʼéla⁠y dá̇bá֣r yĕguná֑̇b wa⁠ţi̇qȧ֥ẖ ʼá֝zĕni֗⁠y şé֣̌meẕ mֽenĕ⁠hֽẇ׃"],[4,13,"בִּ֭⁠שְׂעִפִּים מֵ⁠חֶזְיֹנ֣וֹת לָ֑יְלָה בִּ⁠נְפֹ֥ל תַּ֝רְדֵּמָ֗ה עַל־אֲנָשִֽׁים׃","bi֭̇⁠şĕ̂ʻipi̇ym mé⁠ẖezĕyòn֣wòţ lá֑yĕláh bi̇⁠nĕpò֥l ţȧ֝rĕdé̇má֗h ʻal-ʼànáşǐֽym׃"],[4,14,"פַּ֣חַד קְ֭רָאַ⁠נִי וּ⁠רְעָדָ֑ה וְ⁠רֹ֖ב עַצְמוֹתַ֣⁠י הִפְחִֽיד׃","pȧ֣ẖad qĕ֭ráʼa⁠niy ẇ⁠rĕʻádá֑h wĕ⁠rò֖b ʻaẕĕmwòţa֣⁠y hipĕẖiֽyd׃"],[4,15,"וְ֭⁠רוּחַ עַל־פָּנַ֣⁠י יַחֲלֹ֑ף תְּ֝סַמֵּ֗ר שַֽׂעֲרַ֥ת בְּשָׂרִֽ⁠י׃","wĕ֭⁠rẇẖa ʻal-pá̇na֣⁠y yaẖàlò֑p ţĕ̇֝samé̇֗r şâֽʻàra֥ţ bĕ̇şá̂riֽ⁠y׃"],[4,16,"יַעֲמֹ֤ד ׀ וְֽ⁠לֹא־אַכִּ֬יר מַרְאֵ֗⁠הוּ תְּ֭מוּנָה לְ⁠נֶ֣גֶד עֵינָ֑⁠י דְּמָמָ֖ה וָ⁠ק֣וֹל אֶשְׁמָֽע׃","yaʻàmò֤d ׀ wĕֽ⁠lòʼ-ʼaki̇֬yr marĕʼé֗⁠hẇ ţĕ֭̇mẇnáh lĕ⁠ne֣ged ʻéyná֑⁠y dĕ̇mámá֖h wá⁠q֣wòl ʼeşĕ̌máֽʻ׃"],[4,17,"הַֽ֭⁠אֱנוֹשׁ מֵ⁠אֱל֣וֹהַ יִצְדָּ֑ק אִ֥ם מֵ֝⁠עֹשֵׂ֗⁠הוּ יִטְהַר־גָּֽבֶר׃","haֽ֭⁠ʼènwòş̌ mé⁠ʼèl֣wòha yiẕĕdá֑̇q ʼi֥m mé֝⁠ʻòşé̂֗⁠hẇ yitĕhar-gáֽ̇ber׃"],[4,18,"הֵ֣ן בַּ֭⁠עֲבָדָי⁠ו לֹ֣א יַאֲמִ֑ין וּ֝⁠בְ⁠מַלְאָכָ֗י⁠ו יָשִׂ֥ים תָּהֳלָֽה׃","hé֣n bȧ֭⁠ʻàbádáy⁠w lò֣ʼ yaʼàmi֑yn ẇ֝⁠bĕ⁠malĕʼáká֗y⁠w yáşî֥ym ţá̇holáֽh׃"],[4,19,"אַ֤ף ׀ שֹׁכְנֵ֬י בָֽתֵּי־חֹ֗מֶר אֲשֶׁר־בֶּ⁠עָפָ֥ר יְסוֹדָ֑⁠ם יְ֝דַכְּא֗וּ⁠ם לִ⁠פְנֵי־עָֽשׁ׃","ʼa֤p ׀ şò̌kĕné֬y báֽţé̇y-ẖò֗mer ʼàşěr-bė⁠ʻápá֥r yĕswòdá֑⁠m yĕ֝dakĕ̇ʼ֗ẇ⁠m li⁠pĕnéy-ʻáֽş̌׃"],[4,20,"מִ⁠בֹּ֣קֶר לָ⁠עֶ֣רֶב יֻכַּ֑תּוּ מִ⁠בְּלִ֥י מֵ֝שִׂ֗ים לָ⁠נֶ֥צַח יֹאבֵֽדוּ׃","mi⁠bò֣̇qer lá⁠ʻe֣reb yukȧ֑ţ̇ẇ mi⁠bĕ̇li֥y mé֝şî֗ym lá⁠ne֥ẕaẖ yòʼbéֽdẇ׃"],[4,21,"הֲ⁠לֹא־נִסַּ֣ע יִתְרָ֣⁠ם בָּ֑⁠ם יָ֝מ֗וּתוּ וְ⁠לֹ֣א בְ⁠חָכְמָֽה׃","hà⁠lòʼ-nisȧ֣ʻ yiţĕrá֣⁠m bá֑̇⁠m yá֝m֗ẇţẇ wĕ⁠lò֣ʼ bĕ⁠ẖákĕmáֽh׃"],[5,1,"קְֽרָא־נָ֭א הֲ⁠יֵ֣שׁ עוֹנֶ֑⁠ךָּ וְ⁠אֶל־מִ֖י מִ⁠קְּדֹשִׁ֣ים תִּפְנֶֽה׃","qĕֽráʼ-ná֭ʼ hà⁠yé֣ş̌ ʻwòne֑⁠ká̇ wĕ⁠ʼel-mi֖y mi⁠qĕ̇dòşǐ֣ym ţi̇pĕneֽh׃"],[5,2,"כִּֽי־לֶֽ֭⁠אֱוִיל יַהֲרָג־כָּ֑עַשׂ וּ֝⁠פֹתֶ֗ה תָּמִ֥ית קִנְאָֽה׃","kiֽ̇y-leֽ֭⁠ʼèwiyl yahàrág-ká֑̇ʻaş̂ ẇ֝⁠pòţe֗h ţá̇mi֥yţ qinĕʼáֽh׃"],[5,3,"אֲֽנִי־רָ֭אִיתִי אֱוִ֣יל מַשְׁרִ֑ישׁ וָ⁠אֶקּ֖וֹב נָוֵ֣⁠הוּ פִתְאֹֽם׃","ʼàֽniy-rá֭ʼiyţiy ʼèwi֣yl maşĕ̌ri֑yş̌ wá⁠ʼeq֖̇wòb náwé֣⁠hẇ piţĕʼòֽm׃"],[5,4,"יִרְחֲק֣וּ בָנָ֣י⁠ו מִ⁠יֶּ֑שַׁע וְ⁠יִֽדַּכְּא֥וּ בַ֝⁠שַּׁ֗עַר וְ⁠אֵ֣ין מַצִּֽיל׃","yirĕẖàq֣ẇ báná֣y⁠w mi⁠yė֑şǎʻ wĕ⁠yiֽdȧkĕ̇ʼ֥ẇ ba֝⁠şȧ̌֗ʻar wĕ⁠ʼé֣yn maẕiֽ̇yl׃"],[5,5,"אֲשֶׁ֤ר קְצִיר֨⁠וֹ ׀ רָ֘עֵ֤ב יֹאכֵ֗ל וְ⁠אֶֽל־מִ⁠צִּנִּ֥ים יִקָּחֵ֑⁠הוּ וְ⁠שָׁאַ֖ף צַמִּ֣ים חֵילָֽ⁠ם׃","ʼàşě֤r qĕẕiyr֨⁠wò ׀ rá֘ʻé֤b yòʼké֗l wĕ⁠ʼeֽl-mi⁠ẕi̇ni֥̇ym yiqá̇ẖé֑⁠hẇ wĕ⁠şá̌ʼa֖p ẕami֣̇ym ẖéyláֽ⁠m׃"],[5,6,"כִּ֤י ׀ לֹא־יֵצֵ֣א מֵ⁠עָפָ֣ר אָ֑וֶן וּ֝⁠מֵ⁠אֲדָמָ֗ה לֹא־יִצְמַ֥ח עָמָֽל׃","ki֤̇y ׀ lòʼ-yéẕé֣ʼ mé⁠ʻápá֣r ʼá֑wen ẇ֝⁠mé⁠ʼàdámá֗h lòʼ-yiẕĕma֥ẖ ʻámáֽl׃"],[5,7,"כִּֽי־אָ֭דָם לְ⁠עָמָ֣ל יוּלָּ֑ד וּ⁠בְנֵי־רֶ֝֗שֶׁף יַגְבִּ֥יהוּ עֽוּף׃","kiֽ̇y-ʼá֭dám lĕ⁠ʻámá֣l yẇlá֑̇d ẇ⁠bĕnéy-re֝֗şěp yagĕbi֥̇yhẇ ʻֽẇp׃"],[5,8,"אוּלָ֗ם אֲ֭נִי אֶדְרֹ֣שׁ אֶל־אֵ֑ל וְ⁠אֶל־אֱ֝לֹהִ֗ים אָשִׂ֥ים דִּבְרָתִֽ⁠י׃","ʼẇlá֗m ʼà֭niy ʼedĕrò֣ş̌ ʼel-ʼé֑l wĕ⁠ʼel-ʼè֝lòhi֗ym ʼáşî֥ym di̇bĕráţiֽ⁠y׃"],[5,9,"עֹשֶׂ֣ה גְ֭דֹלוֹת וְ⁠אֵ֣ין חֵ֑קֶר נִ֝פְלָא֗וֹת עַד־אֵ֥ין מִסְפָּֽר׃","ʻòşê֣h gĕ֭dòlwòţ wĕ⁠ʼé֣yn ẖé֑qer ni֝pĕláʼ֗wòţ ʻad-ʼé֥yn misĕpáֽ̇r׃"],[5,10,"הַ⁠נֹּתֵ֣ן מָ֭טָר עַל־פְּנֵי־אָ֑רֶץ וְ⁠שֹׁ֥לֵֽחַ מַ֝יִם עַל־פְּנֵ֥י חוּצֽוֹת׃","ha⁠nò̇ţé֣n má֭tár ʻal-pĕ̇néy-ʼá֑reẕ wĕ⁠şò֥̌léֽẖa ma֝yim ʻal-pĕ̇né֥y ẖẇẕֽwòţ׃"],[5,11,"לָ⁠שׂ֣וּם שְׁפָלִ֣ים לְ⁠מָר֑וֹם וְ֝⁠קֹדְרִ֗ים שָׂ֣גְבוּ יֶֽשַׁע׃","lá⁠ş֣̂ẇm şĕ̌páli֣ym lĕ⁠már֑wòm wĕ֝⁠qòdĕri֗ym şá֣̂gĕbẇ yeֽşǎʻ׃"],[5,12,"מֵ֭פֵר מַחְשְׁב֣וֹת עֲרוּמִ֑ים וְֽ⁠לֹא־תַעֲשֶׂ֥ינָה יְ֝דֵי⁠הֶ֗ם תּוּשִׁיָּֽה׃","mé֭pér maẖĕşĕ̌b֣wòţ ʻàrẇmi֑ym wĕֽ⁠lòʼ-ţaʻàşê֥ynáh yĕ֝déy⁠he֗m ţ̇ẇşǐyáֽ̇h׃"],[5,13,"לֹכֵ֣ד חֲכָמִ֣ים בְּ⁠עָרְמָ֑⁠ם וַ⁠עֲצַ֖ת נִפְתָּלִ֣ים נִמְהָֽרָה׃","lòké֣d ẖàkámi֣ym bĕ̇⁠ʻárĕmá֑⁠m wa⁠ʻàẕa֖ţ nipĕţá̇li֣ym nimĕháֽráh׃"],[5,14,"יוֹמָ֥ם יְפַגְּשׁוּ־חֹ֑שֶׁךְ וְ֝⁠כַ⁠לַּ֗יְלָה יְֽמַשְׁשׁ֥וּ בַֽ⁠צָּהֳרָֽיִם׃","ywòmá֥m yĕpagĕ̇ş̌ẇ-ẖò֑şěkĕ wĕ֝⁠ka⁠lȧ֗yĕláh yĕֽmaşĕ̌ş֥̌ẇ baֽ⁠ẕá̇horáֽyim׃"],[5,15,"וַ⁠יֹּ֣שַׁע מֵ֭⁠חֶרֶב מִ⁠פִּי⁠הֶ֑ם וּ⁠מִ⁠יַּ֖ד חָזָ֣ק אֶבְיֽוֹן׃","wa⁠yò֣̇şǎʻ mé֭⁠ẖereb mi⁠pi̇y⁠he֑m ẇ⁠mi⁠yȧ֖d ẖázá֣q ʼebĕyֽwòn׃"],[5,16,"וַ⁠תְּהִ֣י לַ⁠דַּ֣ל תִּקְוָ֑ה וְ֝⁠עֹלָ֗תָ⁠ה קָ֣פְצָה פִּֽי⁠הָ׃","wa⁠ţĕ̇hi֣y la⁠dȧ֣l ţi̇qĕwá֑h wĕ֝⁠ʻòlá֗ţá⁠h qá֣pĕẕáh piֽ̇y⁠há׃"],[5,17,"הִנֵּ֤ה אַשְׁרֵ֣י אֱ֭נוֹשׁ יוֹכִחֶ֣⁠נּֽוּ אֱל֑וֹהַּ וּ⁠מוּסַ֥ר שַׁ֝דַּ֗י אַל־תִּמְאָֽס׃","hiné֤̇h ʼaşĕ̌ré֣y ʼè֭nwòş̌ ywòkiẖe֣⁠ṅֽẇ ʼèl֑wòhȧ ẇ⁠mẇsa֥r şǎ֝dȧ֗y ʼal-ţi̇mĕʼáֽs׃"],[5,18,"כִּ֤י ה֣וּא יַכְאִ֣יב וְ⁠יֶחְבָּ֑שׁ יִ֝מְחַ֗ץ ו⁠יד⁠ו תִּרְפֶּֽינָה׃","ki֤̇y h֣ẇʼ yakĕʼi֣yb wĕ⁠yeẖĕbá֑̇ş̌ yi֝mĕẖa֗ẕ w⁠yd⁠w ţi̇rĕpėֽynáh׃"],[5,19,"בְּ⁠שֵׁ֣שׁ צָ֭רוֹת יַצִּילֶ֑⁠ךָּ וּ⁠בְ⁠שֶׁ֓בַע ׀ לֹא־יִגַּ֖ע בְּ⁠ךָ֣ רָֽע׃","bĕ̇⁠şé֣̌ş̌ ẕá֭rwòţ yaẕi̇yle֑⁠ká̇ ẇ⁠bĕ⁠şě֓baʻ ׀ lòʼ-yigȧ֖ʻ bĕ̇⁠ká֣ ráֽʻ׃"],[5,20,"בְּ֭⁠רָעָב פָּֽדְ⁠ךָ֣ מִ⁠מָּ֑וֶת וּ֝⁠בְ⁠מִלְחָמָ֗ה מִ֣⁠ידֵי חָֽרֶב׃","bĕ֭̇⁠ráʻáb páֽ̇dĕ⁠ká֣ mi⁠má֑̇weţ ẇ֝⁠bĕ⁠milĕẖámá֗h mi֣⁠ydéy ẖáֽreb׃"],[5,21,"בְּ⁠שׁ֣וֹט לָ֭שׁוֹן תֵּחָבֵ֑א וְֽ⁠לֹא־תִירָ֥א מִ֝⁠שֹּׁ֗ד כִּ֣י יָבֽוֹא׃","bĕ̇⁠ş֣̌wòt lá֭ş̌wòn ţé̇ẖábé֑ʼ wĕֽ⁠lòʼ-ţiyrá֥ʼ mi֝⁠şò̇̌֗d ki֣̇y yábֽwòʼ׃"],[5,22,"לְ⁠שֹׁ֣ד וּ⁠לְ⁠כָפָ֣ן תִּשְׂחָ֑ק וּֽ⁠מֵ⁠חַיַּ֥ת הָ֝⁠אָ֗רֶץ אַל־תִּירָֽא׃","lĕ⁠şò֣̌d ẇ⁠lĕ⁠kápá֣n ţi̇şĕ̂ẖá֑q ẇֽ⁠mé⁠ẖayȧ֥ţ há֝⁠ʼá֗reẕ ʼal-ţi̇yráֽʼ׃"],[5,23,"כִּ֤י עִם־אַבְנֵ֣י הַ⁠שָּׂדֶ֣ה בְרִיתֶ֑⁠ךָ וְ⁠חַיַּ֥ת הַ֝⁠שָּׂדֶ֗ה הָשְׁלְמָה־לָֽ⁠ךְ׃","ki֤̇y ʻim-ʼabĕné֣y ha⁠şá̇̂de֣h bĕriyţe֑⁠ká wĕ⁠ẖayȧ֥ţ ha֝⁠şá̇̂de֗h háşĕ̌lĕmáh-láֽ⁠kĕ׃"],[5,24,"וְֽ֭⁠יָדַעְתָּ כִּי־שָׁל֣וֹם אָהֳלֶ֑⁠ךָ וּֽ⁠פָקַדְתָּ֥ נָ֝וְ⁠ךָ וְ⁠לֹ֣א תֶחֱטָֽא׃","wĕֽ֭⁠yádaʻĕţá̇ ki̇y-şá̌l֣wòm ʼáhole֑⁠ká ẇֽ⁠páqadĕţá֥̇ ná֝wĕ⁠ká wĕ⁠lò֣ʼ ţeẖètáֽʼ׃"],[5,25,"וְֽ֭⁠יָדַעְתָּ כִּי־רַ֣ב זַרְעֶ֑⁠ךָ וְ֝⁠צֶאֱצָאֶ֗י⁠ךָ כְּ⁠עֵ֣שֶׂב הָ⁠אָֽרֶץ׃","wĕֽ֭⁠yádaʻĕţá̇ ki̇y-ra֣b zarĕʻe֑⁠ká wĕ֝⁠ẕeʼèẕáʼe֗y⁠ká kĕ̇⁠ʻé֣şêb há⁠ʼáֽreẕ׃"],[5,26,"תָּב֣וֹא בְ⁠כֶ֣לַח אֱלֵי־קָ֑בֶר כַּ⁠עֲל֖וֹת גָּדִ֣ישׁ בְּ⁠עִתּֽ⁠וֹ׃","ţá̇b֣wòʼ bĕ⁠ke֣laẖ ʼèléy-qá֑ber kȧ⁠ʻàl֖wòţ gá̇di֣yş̌ bĕ̇⁠ʻiţֽ̇⁠wò׃"],[5,27,"הִנֵּה־זֹ֭את חֲקַרְנ֥וּ⁠הָ כֶּֽן־הִ֑יא שְׁ֝מָעֶ֗⁠נָּה וְ⁠אַתָּ֥ה דַֽע־לָֽ⁠ךְ׃פ","hiné̇h-zò֭ʼţ ẖàqarĕn֥ẇ⁠há kėֽn-hi֑yʼ şĕ̌֝máʻe֗⁠ná̇h wĕ⁠ʼaţá֥̇h daֽʻ-láֽ⁠kĕ׃p"],[6,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[6,2,"ל֗וּ שָׁק֣וֹל יִשָּׁקֵ֣ל כַּעְשִׂ֑⁠י ו⁠הית⁠י בְּֽ⁠מֹאזְנַ֥יִם יִשְׂאוּ־יָֽחַד׃","l֗ẇ şá̌q֣wòl yişá̇̌qé֣l kȧʻĕşî֑⁠y w⁠hyţ⁠y bĕֽ̇⁠mòʼzĕna֥yim yişĕ̂ʼẇ-yáֽẖad׃"],[6,3,"כִּֽי־עַתָּ֗ה מֵ⁠ח֣וֹל יַמִּ֣ים יִכְבָּ֑ד עַל־כֵּ֝֗ן דְּבָרַ֥⁠י לָֽעוּ׃","kiֽ̇y-ʻaţá̇֗h mé⁠ẖ֣wòl yami֣̇ym yikĕbá֑̇d ʻal-ké̇֝֗n dĕ̇bára֥⁠y láֽʻẇ׃"],[6,4,"כִּ֤י חִצֵּ֪י שַׁדַּ֡י עִמָּדִ֗⁠י אֲשֶׁ֣ר חֲ֭מָתָ⁠ם שֹׁתָ֣ה רוּחִ֑⁠י בִּעוּתֵ֖י אֱל֣וֹהַּ יַֽעַרְכֽוּ⁠נִי׃","ki֤̇y ẖiẕé֪̇y şǎdȧ֡y ʻimá̇di֗⁠y ʼàşě֣r ẖà֭máţá⁠m şò̌ţá֣h rẇẖi֑⁠y bi̇ʻẇţé֖y ʼèl֣wòhȧ yaֽʻarĕkֽẇ⁠niy׃"],[6,5,"הֲ⁠יִֽנְהַק־פֶּ֥רֶא עֲלֵי־דֶ֑שֶׁא אִ֥ם יִגְעֶה־שּׁ֝֗וֹר עַל־בְּלִילֽ⁠וֹ׃","hà⁠yiֽnĕhaq-pė֥reʼ ʻàléy-de֑şěʼ ʼi֥m yigĕʻeh-ş̇̌֝֗wòr ʻal-bĕ̇liylֽ⁠wò׃"],[6,6,"הֲ⁠יֵאָכֵ֣ל תָּ֭פֵל מִ⁠בְּלִי־מֶ֑לַח אִם־יֶשׁ־טַ֝֗עַם בְּ⁠רִ֣יר חַלָּמֽוּת׃","hà⁠yéʼáké֣l ţá֭̇pél mi⁠bĕ̇liy-me֑laẖ ʼim-yeş̌-ta֝֗ʻam bĕ̇⁠ri֣yr ẖalá̇mֽẇţ׃"],[6,7,"מֵאֲנָ֣ה לִ⁠נְגּ֣וֹעַ נַפְשִׁ֑⁠י הֵ֝֗מָּה כִּ⁠דְוֵ֥י לַחְמִֽ⁠י׃","méʼàná֣h li⁠nĕġ֣wòʻa napĕşǐ֑⁠y hé֝֗má̇h ki̇⁠dĕwé֥y laẖĕmiֽ⁠y׃"],[6,8,"מִֽי־יִ֭תֵּן תָּב֣וֹא שֶֽׁאֱלָתִ֑⁠י וְ֝⁠תִקְוָתִ֗⁠י יִתֵּ֥ן אֱלֽוֹהַּ׃","miֽy-yi֭ţé̇n ţá̇b֣wòʼ şěֽʼèláţi֑⁠y wĕ֝⁠ţiqĕwáţi֗⁠y yiţé֥̇n ʼèlֽwòhȧ׃"],[6,9,"וְ⁠יֹאֵ֣ל אֱ֭לוֹהַּ וִֽ⁠ידַכְּאֵ֑⁠נִי יַתֵּ֥ר יָ֝ד֗⁠וֹ וִֽ⁠יבַצְּעֵֽ⁠נִי׃","wĕ⁠yòʼé֣l ʼè֭lwòhȧ wiֽ⁠ydakĕ̇ʼé֑⁠niy yaţé֥̇r yá֝d֗⁠wò wiֽ⁠ybaẕĕ̇ʻéֽ⁠niy׃"],[6,10,"וּ֥⁠תְהִי ע֨וֹד ׀ נֶ֘חָ֤מָתִ֗⁠י וַ⁠אֲסַלְּדָ֣ה בְ֭⁠חִילָה לֹ֣א יַחְמ֑וֹל כִּי־לֹ֥א כִ֝חַ֗דְתִּי אִמְרֵ֥י קָדֽוֹשׁ׃","ẇ֥⁠ţĕhiy ʻ֨wòd ׀ ne֘ẖá֤máţi֗⁠y wa⁠ʼàsalĕ̇dá֣h bĕ֭⁠ẖiyláh lò֣ʼ yaẖĕm֑wòl ki̇y-lò֥ʼ ki֝ẖa֗dĕţi̇y ʼimĕré֥y qádֽwòş̌׃"],[6,11,"מַה־כֹּחִ֥⁠י כִֽי־אֲיַחֵ֑ל וּ⁠מַה־קִּ֝צִּ֗⁠י כִּֽי־אַאֲרִ֥יךְ נַפְשִֽׁ⁠י׃","mah-kò̇ẖi֥⁠y kiֽy-ʼàyaẖé֑l ẇ⁠mah-qi̇֝ẕi̇֗⁠y kiֽ̇y-ʼaʼàri֥ykĕ napĕşǐֽ⁠y׃"],[6,12,"אִם־כֹּ֣חַ אֲבָנִ֣ים כֹּחִ֑⁠י אִֽם־בְּשָׂרִ֥⁠י נָחֽוּשׁ׃","ʼim-kò֣̇ẖa ʼàbáni֣ym kò̇ẖi֑⁠y ʼiֽm-bĕ̇şá̂ri֥⁠y náẖֽẇş̌׃"],[6,13,"הַ⁠אִ֬ם אֵ֣ין עֶזְרָתִ֣⁠י בִ֑⁠י וְ֝⁠תֻשִׁיָּ֗ה נִדְּחָ֥ה מִמֶּֽ⁠נִּי׃","ha⁠ʼi֬m ʼé֣yn ʻezĕráţi֣⁠y bi֑⁠y wĕ֝⁠ţuşǐyá̇֗h nidĕ̇ẖá֥h mimėֽ⁠ni̇y׃"],[6,14,"לַ⁠מָּ֣ס מֵרֵעֵ֣⁠הוּ חָ֑סֶד וְ⁠יִרְאַ֖ת שַׁדַּ֣י יַעֲזֽוֹב׃","la⁠má֣̇s méréʻé֣⁠hẇ ẖá֑sed wĕ⁠yirĕʼa֖ţ şǎdȧ֣y yaʻàzֽwòb׃"],[6,15,"אַ֭חַ⁠י בָּגְד֣וּ כְמוֹ־נָ֑חַל כַּ⁠אֲפִ֖יק נְחָלִ֣ים יַעֲבֹֽרוּ׃","ʼa֭ẖa⁠y bá̇gĕd֣ẇ kĕmwò-ná֑ẖal kȧ⁠ʼàpi֖yq nĕẖáli֣ym yaʻàbòֽrẇ׃"],[6,16,"הַ⁠קֹּדְרִ֥ים מִנִּי־קָ֑רַח עָ֝לֵ֗י⁠מוֹ יִתְעַלֶּם־שָֽׁלֶג׃","ha⁠qò̇dĕri֥ym mini̇y-qá֑raẖ ʻá֝lé֗y⁠mwò yiţĕʻalėm-şáֽ̌leg׃"],[6,17,"בְּ֭⁠עֵת יְזֹרְב֣וּ נִצְמָ֑תוּ בְּ֝⁠חֻמּ֗⁠וֹ נִדְעֲכ֥וּ מִ⁠מְּקוֹמָֽ⁠ם׃","bĕ֭̇⁠ʻéţ yĕzòrĕb֣ẇ niẕĕmá֑ţẇ bĕ̇֝⁠ẖuṁ֗⁠wò nidĕʻàk֥ẇ mi⁠mĕ̇qwòmáֽ⁠m׃"],[6,18,"יִ֭לָּ֣פְתוּ אָרְח֣וֹת דַּרְכָּ֑⁠ם יַעֲל֖וּ בַ⁠תֹּ֣הוּ וְ⁠יֹאבֵֽדוּ׃","yi֭lá֣̇pĕţẇ ʼárĕẖ֣wòţ dȧrĕká֑̇⁠m yaʻàl֖ẇ ba⁠ţò֣̇hẇ wĕ⁠yòʼbéֽdẇ׃"],[6,19,"הִ֭בִּיטוּ אָרְח֣וֹת תֵּמָ֑א הֲלִיכֹ֥ת שְׁ֝בָ֗א קִוּוּ־לָֽ⁠מוֹ׃","hi֭bi̇ytẇ ʼárĕẖ֣wòţ ţé̇má֑ʼ hàliykò֥ţ şĕ̌֝bá֗ʼ qiẇẇ-láֽ⁠mwò׃"],[6,20,"בֹּ֥שׁוּ כִּֽי־בָטָ֑ח בָּ֥אוּ עָ֝דֶ֗י⁠הָ וַ⁠יֶּחְפָּֽרוּ׃","bò֥̇ş̌ẇ kiֽ̇y-bátá֑ẖ bá֥̇ʼẇ ʻá֝de֗y⁠há wa⁠yėẖĕpáֽ̇rẇ׃"],[6,21,"כִּֽי־עַ֭תָּה הֱיִ֣יתֶם לא תִּֽרְא֥וּ חֲ֝תַ֗ת וַ⁠תִּירָֽאוּ׃","kiֽ̇y-ʻa֭ţá̇h hèyi֣yţem lʼ ţiֽ̇rĕʼ֥ẇ ẖà֝ţa֗ţ wa⁠ţi̇yráֽʼẇ׃"],[6,22,"הֲֽ⁠כִי־אָ֭מַרְתִּי הָ֣בוּ לִ֑⁠י וּ֝⁠מִ⁠כֹּחֲ⁠כֶ֗ם שִׁחֲד֥וּ בַעֲדִֽ⁠י׃","hàֽ⁠kiy-ʼá֭marĕţi̇y há֣bẇ li֑⁠y ẇ֝⁠mi⁠kò̇ẖà⁠ke֗m şǐẖàd֥ẇ baʻàdiֽ⁠y׃"],[6,23,"וּ⁠מַלְּט֥וּ⁠נִי מִ⁠יַּד־צָ֑ר וּ⁠מִ⁠יַּ֖ד עָרִיצִ֣ים תִּפְדּֽוּ⁠נִי׃","ẇ⁠malĕ̇t֥ẇ⁠niy mi⁠yȧd-ẕá֑r ẇ⁠mi⁠yȧ֖d ʻáriyẕi֣ym ţi̇pĕḋֽẇ⁠niy׃"],[6,24,"ה֭וֹרוּ⁠נִי וַ⁠אֲנִ֣י אַחֲרִ֑ישׁ וּ⁠מַה־שָּׁ֝גִ֗יתִי הָבִ֥ינוּ לִֽ⁠י׃","h֭wòrẇ⁠niy wa⁠ʼàni֣y ʼaẖàri֑yş̌ ẇ⁠mah-şá̇̌֝gi֗yţiy hábi֥ynẇ liֽ⁠y׃"],[6,25,"מַה־נִּמְרְצ֥וּ אִמְרֵי־יֹ֑שֶׁר וּ⁠מַה־יּוֹכִ֖יחַ הוֹכֵ֣חַ מִ⁠כֶּֽם׃","mah-ni̇mĕrĕẕ֥ẇ ʼimĕréy-yò֑şěr ẇ⁠mah-ẏwòki֖yẖa hwòké֣ẖa mi⁠kėֽm׃"],[6,26,"הַ⁠לְ⁠הוֹכַ֣ח מִלִּ֣ים תַּחְשֹׁ֑בוּ וּ֝⁠לְ⁠ר֗וּחַ אִמְרֵ֥י נֹאָֽשׁ׃","ha⁠lĕ⁠hwòka֣ẖ mili֣̇ym ţȧẖĕşò֑̌bẇ ẇ֝⁠lĕ⁠r֗ẇẖa ʼimĕré֥y nòʼáֽş̌׃"],[6,27,"אַף־עַל־יָת֥וֹם תַּפִּ֑ילוּ וְ֝⁠תִכְר֗וּ עַל־רֵֽיעֲ⁠כֶֽם׃","ʼap-ʻal-yáţ֥wòm ţȧpi֑̇ylẇ wĕ֝⁠ţikĕr֗ẇ ʻal-réֽyʻà⁠keֽm׃"],[6,28,"וְ֭⁠עַתָּה הוֹאִ֣ילוּ פְנוּ־בִ֑⁠י וְ⁠עַל־פְּ֝נֵי⁠כֶ֗ם אִם־אֲכַזֵּֽב׃","wĕ֭⁠ʻaţá̇h hwòʼi֣ylẇ pĕnẇ-bi֑⁠y wĕ⁠ʻal-pĕ̇֝néy⁠ke֗m ʼim-ʼàkazéֽ̇b׃"],[6,29,"שֻֽׁבוּ־נָ֭א אַל־תְּהִ֣י עַוְלָ֑ה ו⁠שבי ע֝וֹד צִדְקִ⁠י־בָֽ⁠הּ׃","şǔֽbẇ-ná֭ʼ ʼal-ţĕ̇hi֣y ʻawĕlá֑h w⁠şby ʻ֝wòd ẕidĕqi⁠y-báֽ⁠ḣ׃"],[6,30,"הֲ⁠יֵשׁ־בִּ⁠לְשׁוֹנִ֥⁠י עַוְלָ֑ה אִם־חִ֝כִּ֗⁠י לֹא־יָבִ֥ין הַוּֽוֹת׃","hà⁠yéş̌-bi̇⁠lĕş̌wòni֥⁠y ʻawĕlá֑h ʼim-ẖi֝ki̇֗⁠y lòʼ-yábi֥yn haẇֽwòţ׃"],[7,1,"הֲ⁠לֹא־צָבָ֣א לֶ⁠אֱנ֣וֹשׁ על־אָ֑רֶץ וְ⁠כִ⁠ימֵ֖י שָׂכִ֣יר יָמָֽי⁠ו׃","hà⁠lòʼ-ẕábá֣ʼ le⁠ʼèn֣wòş̌ ʻl-ʼá֑reẕ wĕ⁠ki⁠ymé֖y şá̂ki֣yr yámáֽy⁠w׃"],[7,2,"כְּ⁠עֶ֥בֶד יִשְׁאַף־צֵ֑ל וּ֝⁠כְ⁠שָׂכִ֗יר יְקַוֶּ֥ה פָעֳלֽ⁠וֹ׃","kĕ̇⁠ʻe֥bed yişĕ̌ʼap-ẕé֑l ẇ֝⁠kĕ⁠şá̂ki֗yr yĕqawė֥h páʻolֽ⁠wò׃"],[7,3,"כֵּ֤ן הָנְחַ֣לְתִּי לִ֭⁠י יַרְחֵי־שָׁ֑וְא וְ⁠לֵיל֥וֹת עָ֝מָ֗ל מִנּוּ־לִֽ⁠י׃","ké֤̇n hánĕẖa֣lĕţi̇y li֭⁠y yarĕẖéy-şá֑̌wĕʼ wĕ⁠léyl֥wòţ ʻá֝má֗l miṅẇ-liֽ⁠y׃"],[7,4,"אִם־שָׁכַ֗בְתִּי וְ⁠אָמַ֗רְתִּי מָתַ֣י אָ֭קוּם וּ⁠מִדַּד־עָ֑רֶב וְ⁠שָׂבַ֖עְתִּי נְדֻדִ֣ים עֲדֵי־נָֽשֶׁף׃","ʼim-şá̌ka֗bĕţi̇y wĕ⁠ʼáma֗rĕţi̇y máţa֣y ʼá֭qẇm ẇ⁠midȧd-ʻá֑reb wĕ⁠şá̂ba֖ʻĕţi̇y nĕdudi֣ym ʻàdéy-náֽşěp׃"],[7,5,"לָ֘בַ֤שׁ בְּשָׂרִ֣⁠י רִ֭מָּה ו⁠גיש עָפָ֑ר עוֹרִ֥⁠י רָ֝גַ֗ע וַ⁠יִּמָּאֵֽס׃","lá֘ba֤ş̌ bĕ̇şá̂ri֣⁠y ri֭má̇h w⁠gyş ʻápá֑r ʻwòri֥⁠y rá֝ga֗ʻ wa⁠yi̇má̇ʼéֽs׃"],[7,6,"יָמַ֣⁠י קַ֭לּוּ מִנִּי־אָ֑רֶג וַ֝⁠יִּכְל֗וּ בְּ⁠אֶ֣פֶס תִּקְוָֽה׃","yáma֣⁠y qa֭l̇ẇ mini̇y-ʼá֑reg wa֝⁠yi̇kĕl֗ẇ bĕ̇⁠ʼe֣pes ţi̇qĕwáֽh׃"],[7,7,"זְ֭כֹר כִּי־ר֣וּחַ חַיָּ֑⁠י לֹא־תָשׁ֥וּב עֵ֝ינִ֗⁠י לִ⁠רְא֥וֹת טֽוֹב׃","zĕ֭kòr ki̇y-r֣ẇẖa ẖayá֑̇⁠y lòʼ-ţáş֥̌ẇb ʻé֝yni֗⁠y li⁠rĕʼ֥wòţ tֽwòb׃"],[7,8,"לֹֽא־תְ֭שׁוּרֵ⁠נִי עֵ֣ין רֹ֑אִי עֵינֶ֖י⁠ךָ בִּ֣⁠י וְ⁠אֵינֶֽ⁠נִּי׃","lòֽʼ-ţĕ֭ş̌ẇré⁠niy ʻé֣yn rò֑ʼiy ʻéyne֖y⁠ká bi֣̇⁠y wĕ⁠ʼéyneֽ⁠ni̇y׃"],[7,9,"כָּלָ֣ה עָ֭נָן וַ⁠יֵּלַ֑ךְ כֵּ֥ן יוֹרֵ֥ד שְׁ֝א֗וֹל לֹ֣א יַעֲלֶֽה׃","ká̇lá֣h ʻá֭nán wa⁠yé̇la֑kĕ ké֥̇n ywòré֥d şĕ̌֝ʼ֗wòl lò֣ʼ yaʻàlֽeh׃"],[7,10,"לֹא־יָשׁ֣וּב ע֣וֹד לְ⁠בֵית֑⁠וֹ וְ⁠לֹא־יַכִּירֶ֖⁠נּוּ ע֣וֹד מְקֹמֽ⁠וֹ׃","lòʼ-yáş֣̌ẇb ʻ֣wòd lĕ⁠béyţ֑⁠wò wĕ⁠lòʼ-yaki̇yre֖⁠ṅẇ ʻ֣wòd mĕqòmֽ⁠wò׃"],[7,11,"גַּם־אֲנִי֮ לֹ֤א אֶחֱשָׂ֫ךְ פִּ֥⁠י אֲֽ֭דַבְּרָה בְּ⁠צַ֣ר רוּחִ֑⁠י אָ֝שִׂ֗יחָה בְּ⁠מַ֣ר נַפְשִֽׁ⁠י׃","gȧm-ʼàniy֮ lò֤ʼ ʼeẖèşá̂֫kĕ pi֥̇⁠y ʼàֽ֭dabĕ̇ráh bĕ̇⁠ẕa֣r rẇẖi֑⁠y ʼá֝şî֗yẖáh bĕ̇⁠ma֣r napĕşǐֽ⁠y׃"],[7,12,"הֲֽ⁠יָם־אָ֭נִי אִם־תַּנִּ֑ין כִּֽי־תָשִׂ֖ים עָלַ֣⁠י מִשְׁמָֽר׃","hàֽ⁠yám-ʼá֭niy ʼim-ţȧni֑̇yn kiֽ̇y-ţáşî֖ym ʻála֣⁠y mişĕ̌máֽr׃"],[7,13,"כִּֽי־אָ֭מַרְתִּי תְּנַחֲמֵ֣⁠נִי עַרְשִׂ֑⁠י יִשָּׂ֥א בְ֝⁠שִׂיחִ֗⁠י מִשְׁכָּבִֽ⁠י׃","kiֽ̇y-ʼá֭marĕţi̇y ţĕ̇naẖàmé֣⁠niy ʻarĕşî֑⁠y yişá֥̇̂ʼ bĕ֝⁠şîyẖi֗⁠y mişĕ̌ká̇biֽ⁠y׃"],[7,14,"וְ⁠חִתַּתַּ֥⁠נִי בַ⁠חֲלֹמ֑וֹת וּֽ⁠מֵ⁠חֶזְיֹנ֥וֹת תְּבַעֲתַֽ⁠נִּי׃","wĕ⁠ẖiţȧţȧ֥⁠niy ba⁠ẖàlòm֑wòţ ẇֽ⁠mé⁠ẖezĕyòn֥wòţ ţĕ̇baʻàţaֽ⁠ni̇y׃"],[7,15,"וַ⁠תִּבְחַ֣ר מַחֲנָ֣ק נַפְשִׁ֑⁠י מָ֝֗וֶת מֵֽ⁠עַצְמוֹתָֽ⁠י׃","wa⁠ţi̇bĕẖa֣r maẖàná֣q napĕşǐ֑⁠y má֝֗weţ méֽ⁠ʻaẕĕmwòţáֽ⁠y׃"],[7,16,"מָ֭אַסְתִּי לֹא־לְ⁠עֹלָ֣ם אֶֽחְיֶ֑ה חֲדַ֥ל מִ֝מֶּ֗⁠נִּי כִּי־הֶ֥בֶל יָמָֽ⁠י׃","má֭ʼasĕţi̇y lòʼ-lĕ⁠ʻòlá֣m ʼeֽẖĕye֑h ẖàda֥l mi֝mė֗⁠ni̇y ki̇y-he֥bel yámáֽ⁠y׃"],[7,17,"מָֽה־אֱ֭נוֹשׁ כִּ֣י תְגַדְּלֶ֑⁠נּוּ וְ⁠כִי־תָשִׁ֖ית אֵלָ֣י⁠ו לִבֶּֽ⁠ךָ׃","máֽh-ʼè֭nwòş̌ ki֣̇y ţĕgadĕ̇le֑⁠ṅẇ wĕ⁠kiy-ţáşǐ֖yţ ʼélá֣y⁠w libėֽ⁠ká׃"],[7,18,"וַ⁠תִּפְקְדֶ֥⁠נּוּ לִ⁠בְקָרִ֑ים לִ֝⁠רְגָעִ֗ים תִּבְחָנֶֽ⁠נּוּ׃","wa⁠ţi̇pĕqĕde֥⁠ṅẇ li⁠bĕqári֑ym li֝⁠rĕgáʻi֗ym ţi̇bĕẖáneֽ⁠ṅẇ׃"],[7,19,"כַּ֭⁠מָּה לֹא־תִשְׁעֶ֣ה מִמֶּ֑⁠נִּי לֹֽא־תַ֝רְפֵּ֗⁠נִי עַד־בִּלְעִ֥⁠י רֻקִּֽ⁠י׃","kȧ֭⁠má̇h lòʼ-ţişĕ̌ʻe֣h mimė֑⁠ni̇y lòֽʼ-ţa֝rĕpé̇֗⁠niy ʻad-bi̇lĕʻi֥⁠y ruqiֽ̇⁠y׃"],[7,20,"חָטָ֡אתִי מָ֤ה אֶפְעַ֨ל ׀ לָ⁠ךְ֮ נֹצֵ֪ר הָ⁠אָ֫דָ֥ם לָ֤⁠מָה שַׂמְתַּ֣⁠נִי לְ⁠מִפְגָּ֣ע לָ֑⁠ךְ וָ⁠אֶהְיֶ֖ה עָלַ֣⁠י לְ⁠מַשָּֽׂא׃","ẖátá֡ʼţiy má֤h ʼepĕʻa֨l ׀ lá⁠kĕ֮ nòẕé֪r há⁠ʼá֫dá֥m lá֤⁠máh şâmĕţȧ֣⁠niy lĕ⁠mipĕgá֣̇ʻ lá֑⁠kĕ wá⁠ʼehĕye֖h ʻála֣⁠y lĕ⁠maşáֽ̇̂ʼ׃"],[7,21,"וּ⁠מֶ֤ה ׀ לֹא־תִשָּׂ֣א פִשְׁעִ⁠י֮ וְ⁠תַעֲבִ֪יר אֶת־עֲוֺ֫נִ֥⁠י כִּֽי־עַ֭תָּה לֶ⁠עָפָ֣ר אֶשְׁכָּ֑ב וְ⁠שִׁ֖חֲרְתַּ֣⁠נִי וְ⁠אֵינֶֽ⁠נִּי׃פ","ẇ⁠me֤h ׀ lòʼ-ţişá֣̇̂ʼ pişĕ̌ʻi⁠y֮ wĕ⁠ţaʻàbi֪yr ʼeţ-ʻàwֺ֫ni֥⁠y kiֽ̇y-ʻa֭ţá̇h le⁠ʻápá֣r ʼeşĕ̌ká֑̇b wĕ⁠şǐ֖ẖàrĕţȧ֣⁠niy wĕ⁠ʼéyneֽ⁠ni̇y׃p"],[8,1,"וַ֭⁠יַּעַן בִּלְדַּ֥ד הַ⁠שּׁוּחִ֗י וַ⁠יֹאמַֽר׃","wa֭⁠yȧʻan bi̇lĕdȧ֥d ha⁠ş̇̌ẇẖi֗y wa⁠yòʼmaֽr׃"],[8,2,"עַד־אָ֥ן תְּמַלֶּל־אֵ֑לֶּה וְ⁠ר֥וּחַ כַּ֝בִּיר אִמְרֵי־פִֽי⁠ךָ׃","ʻad-ʼá֥n ţĕ̇malėl-ʼé֑lėh wĕ⁠r֥ẇẖa kȧ֝bi̇yr ʼimĕréy-piֽy⁠ká׃"],[8,3,"הַ֭⁠אֵל יְעַוֵּ֣ת מִשְׁפָּ֑ט וְ⁠אִם־שַׁ֝דַּ֗י יְעַוֵּֽת־צֶֽדֶק׃","ha֭⁠ʼél yĕʻawé֣̇ţ mişĕ̌pá֑̇t wĕ⁠ʼim-şǎ֝dȧ֗y yĕʻawéֽ̇ţ-ẕeֽdeq׃"],[8,4,"אִם־בָּנֶ֥י⁠ךָ חָֽטְאוּ־ל֑⁠וֹ וַֽ֝⁠יְשַׁלְּחֵ֗⁠ם בְּ⁠יַד־פִּשְׁעָֽ⁠ם׃","ʼim-bá̇ne֥y⁠ká ẖáֽtĕʼẇ-l֑⁠wò waֽ֝⁠yĕşǎlĕ̇ẖé֗⁠m bĕ̇⁠yad-pi̇şĕ̌ʻáֽ⁠m׃"],[8,5,"אִם־אַ֭תָּה תְּשַׁחֵ֣ר אֶל־אֵ֑ל וְ⁠אֶל־שַׁ֝דַּ֗י תִּתְחַנָּֽן׃","ʼim-ʼa֭ţá̇h ţĕ̇şǎẖé֣r ʼel-ʼé֑l wĕ⁠ʼel-şǎ֝dȧ֗y ţi̇ţĕẖanáֽ̇n׃"],[8,6,"אִם־זַ֥ךְ וְ⁠יָשָׁ֗ר אָ֥תָּה כִּי־עַ֭תָּה יָעִ֣יר עָלֶ֑י⁠ךָ וְ֝⁠שִׁלַּ֗ם נְוַ֣ת צִדְקֶֽ⁠ךָ׃","ʼim-za֥kĕ wĕ⁠yáşá̌֗r ʼá֥ţá̇h ki̇y-ʻa֭ţá̇h yáʻi֣yr ʻále֑y⁠ká wĕ֝⁠şǐlȧ֗m nĕwa֣ţ ẕidĕqeֽ⁠ká׃"],[8,7,"וְ⁠הָיָ֣ה רֵאשִׁיתְ⁠ךָ֣ מִצְעָ֑ר וְ֝⁠אַחֲרִיתְ⁠ךָ֗ יִשְׂגֶּ֥ה מְאֹֽד׃","wĕ⁠háyá֣h réʼşǐyţĕ⁠ká֣ miẕĕʻá֑r wĕ֝⁠ʼaẖàriyţĕ⁠ká֗ yişĕ̂gė֥h mĕʼòֽd׃"],[8,8,"כִּֽי־שְׁאַל־נָ֭א לְ⁠דֹ֣ר רִישׁ֑וֹן וְ֝⁠כוֹנֵ֗ן לְ⁠חֵ֣קֶר אֲבוֹתָֽ⁠ם׃","kiֽ̇y-şĕ̌ʼal-ná֭ʼ lĕ⁠dò֣r riyş֑̌wòn wĕ֝⁠kwòné֗n lĕ⁠ẖé֣qer ʼàbwòţáֽ⁠m׃"],[8,9,"כִּֽי־תְמ֣וֹל אֲ֭נַחְנוּ וְ⁠לֹ֣א נֵדָ֑ע כִּ֤י צֵ֖ל יָמֵ֣י⁠נוּ עֲלֵי־אָֽרֶץ׃","kiֽ̇y-ţĕm֣wòl ʼà֭naẖĕnẇ wĕ⁠lò֣ʼ nédá֑ʻ ki֤̇y ẕé֖l yámé֣y⁠nẇ ʻàléy-ʼáֽreẕ׃"],[8,10,"הֲ⁠לֹא־הֵ֣ם י֭וֹרוּ⁠ךָ יֹ֣אמְרוּ לָ֑⁠ךְ וּ֝⁠מִ⁠לִּבָּ֗⁠ם יוֹצִ֥אוּ מִלִּֽים׃","hà⁠lòʼ-hé֣m y֭wòrẇ⁠ká yò֣ʼmĕrẇ lá֑⁠kĕ ẇ֝⁠mi⁠li̇bá̇֗⁠m ywòẕi֥ʼẇ miliֽ̇ym׃"],[8,11,"הֲ⁠יִֽגְאֶה־גֹּ֭מֶא בְּ⁠לֹ֣א בִצָּ֑ה יִשְׂגֶּה־אָ֥חוּ בְלִי־מָֽיִם׃","hà⁠yiֽgĕʼeh-gò֭̇meʼ bĕ̇⁠lò֣ʼ biẕá֑̇h yişĕ̂gėh-ʼá֥ẖẇ bĕliy-máֽyim׃"],[8,12,"עֹדֶ֣⁠נּוּ בְ֭⁠אִבּ⁠וֹ לֹ֣א יִקָּטֵ֑ף וְ⁠לִ⁠פְנֵ֖י כָל־חָצִ֣יר יִיבָֽשׁ׃","ʻòde֣⁠ṅẇ bĕ֭⁠ʼiḃ⁠wò lò֣ʼ yiqá̇té֑p wĕ⁠li⁠pĕné֖y kál-ẖáẕi֣yr yiybáֽş̌׃"],[8,13,"כֵּ֗ן אָ֭רְחוֹת כָּל־שֹׁ֣כְחֵי אֵ֑ל וְ⁠תִקְוַ֖ת חָנֵ֣ף תֹּאבֵֽד׃","ké̇֗n ʼá֭rĕẖwòţ ká̇l-şò֣̌kĕẖéy ʼé֑l wĕ⁠ţiqĕwa֖ţ ẖáné֣p ţò̇ʼbéֽd׃"],[8,14,"אֲשֶׁר־יָק֥וֹט כִּסְל֑⁠וֹ וּ⁠בֵ֥ית עַ֝כָּבִ֗ישׁ מִבְטַחֽ⁠וֹ׃","ʼàşěr-yáq֥wòt ki̇sĕl֑⁠wò ẇ⁠bé֥yţ ʻa֝ká̇bi֗yş̌ mibĕtaẖֽ⁠wò׃"],[8,15,"יִשָּׁעֵ֣ן עַל־בֵּ֭ית⁠וֹ וְ⁠לֹ֣א יַעֲמֹ֑ד יַחֲזִ֥יק בּ֝֗⁠וֹ וְ⁠לֹ֣א יָקֽוּם׃","yişá̇̌ʻé֣n ʻal-bé֭̇yţ⁠wò wĕ⁠lò֣ʼ yaʻàmò֑d yaẖàzi֥yq ḃ֝֗⁠wò wĕ⁠lò֣ʼ yáqֽẇm׃"],[8,16,"רָטֹ֣ב ה֭וּא לִ⁠פְנֵי־שָׁ֑מֶשׁ וְ⁠עַ֥ל גַּ֝נָּת֗⁠וֹ יֹֽנַקְתּ֥⁠וֹ תֵצֵֽא׃","rátò֣b h֭ẇʼ li⁠pĕnéy-şá֑̌meş̌ wĕ⁠ʻa֥l gȧ֝ná̇ţ֗⁠wò yòֽnaqĕţ֥̇⁠wò ţéẕéֽʼ׃"],[8,17,"עַל־גַּ֭ל שָֽׁרָשָׁ֣י⁠ו יְסֻבָּ֑כוּ בֵּ֖ית אֲבָנִ֣ים יֶחֱזֶֽה׃","ʻal-gȧ֭l şáֽ̌ráşá֣̌y⁠w yĕsubá֑̇kẇ bé֖̇yţ ʼàbáni֣ym yeẖèzeֽh׃"],[8,18,"אִם־יְבַלְּעֶ֥⁠נּוּ מִ⁠מְּקוֹמ֑⁠וֹ וְ⁠כִ֥חֶשׁ בּ֝֗⁠וֹ לֹ֣א רְאִיתִֽי⁠ךָ׃","ʼim-yĕbalĕ̇ʻe֥⁠ṅẇ mi⁠mĕ̇qwòm֑⁠wò wĕ⁠ki֥ẖeş̌ ḃ֝֗⁠wò lò֣ʼ rĕʼiyţiֽy⁠ká׃"],[8,19,"הֶן־ה֭וּא מְשׂ֣וֹשׂ דַּרְכּ֑⁠וֹ וּ֝⁠מֵ⁠עָפָ֗ר אַחֵ֥ר יִצְמָֽחוּ׃","hen-h֭ẇʼ mĕş֣̂wòş̂ dȧrĕk֑̇⁠wò ẇ֝⁠mé⁠ʻápá֗r ʼaẖé֥r yiẕĕmáֽẖẇ׃"],[8,20,"הֶן־אֵ֭ל לֹ֣א יִמְאַס־תָּ֑ם וְ⁠לֹֽא־יַ֝חֲזִ֗יק בְּ⁠יַד־מְרֵעִֽים׃","hen-ʼé֭l lò֣ʼ yimĕʼas-ţá֑̇m wĕ⁠lòֽʼ-ya֝ẖàzi֗yq bĕ̇⁠yad-mĕréʻiֽym׃"],[8,21,"עַד־יְמַלֵּ֣ה שְׂח֣וֹק פִּ֑י⁠ךָ וּ⁠שְׂפָתֶ֥י⁠ךָ תְרוּעָֽה׃","ʻad-yĕmalé֣̇h şĕ̂ẖ֣wòq pi֑̇y⁠ká ẇ⁠şĕ̂páţe֥y⁠ká ţĕrẇʻáֽh׃"],[8,22,"שֹׂנְאֶ֥י⁠ךָ יִלְבְּשׁוּ־בֹ֑שֶׁת וְ⁠אֹ֖הֶל רְשָׁעִ֣ים אֵינֶֽ⁠נּוּ׃פ","şò̂nĕʼe֥y⁠ká yilĕbĕ̇ş̌ẇ-bò֑şěţ wĕ⁠ʼò֖hel rĕşá̌ʻi֣ym ʼéyneֽ⁠ṅẇ׃p"],[9,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[9,2,"אָ֭מְנָם יָדַ֣עְתִּי כִי־כֵ֑ן וּ⁠מַה־יִּצְדַּ֖ק אֱנ֣וֹשׁ עִם־אֵֽל׃","ʼá֭mĕnám yáda֣ʻĕţi̇y kiy-ké֑n ẇ⁠mah-yi̇ẕĕdȧ֖q ʼèn֣wòş̌ ʻim-ʼéֽl׃"],[9,3,"אִם־יַ֭חְפֹּץ לָ⁠רִ֣יב עִמּ֑⁠וֹ לֹֽא־יַ֝עֲנֶ֗⁠נּוּ אַחַ֥ת מִנִּי־אָֽלֶף׃","ʼim-ya֭ẖĕpò̇ẕ lá⁠ri֣yb ʻiṁ֑⁠wò lòֽʼ-ya֝ʻàne֗⁠ṅẇ ʼaẖa֥ţ mini̇y-ʼáֽlep׃"],[9,4,"חֲכַ֣ם לֵ֭בָב וְ⁠אַמִּ֣יץ כֹּ֑חַ מִֽי־הִקְשָׁ֥ה אֵ֝לָ֗י⁠ו וַ⁠יִּשְׁלָֽם׃","ẖàka֣m lé֭báb wĕ⁠ʼami֣̇yẕ kò֑̇ẖa miֽy-hiqĕşá֥̌h ʼé֝lá֗y⁠w wa⁠yi̇şĕ̌láֽm׃"],[9,5,"הַ⁠מַּעְתִּ֣יק הָ֭רִים וְ⁠לֹ֣א יָדָ֑עוּ אֲשֶׁ֖ר הֲפָכָ֣⁠ם בְּ⁠אַפּֽ⁠וֹ׃","ha⁠mȧʻĕţi֣̇yq há֭riym wĕ⁠lò֣ʼ yádá֑ʻẇ ʼàşě֖r hàpáká֣⁠m bĕ̇⁠ʼaṗֽ⁠wò׃"],[9,6,"הַ⁠מַּרְגִּ֣יז אֶ֭רֶץ מִ⁠מְּקוֹמָ֑⁠הּ וְ֝⁠עַמּוּדֶ֗י⁠הָ יִתְפַלָּצֽוּ⁠ן׃","ha⁠mȧrĕgi֣̇yz ʼe֭reẕ mi⁠mĕ̇qwòmá֑⁠ḣ wĕ֝⁠ʻaṁẇde֗y⁠há yiţĕpalá̇ẕֽẇ⁠n׃"],[9,7,"הָ⁠אֹמֵ֣ר לַ֭⁠חֶרֶס וְ⁠לֹ֣א יִזְרָ֑ח וּ⁠בְעַ֖ד כּוֹכָבִ֣ים יַחְתֹּֽם׃","há⁠ʼòmé֣r la֭⁠ẖeres wĕ⁠lò֣ʼ yizĕrá֑ẖ ẇ⁠bĕʻa֖d k̇wòkábi֣ym yaẖĕţòֽ̇m׃"],[9,8,"נֹטֶ֣ה שָׁמַ֣יִם לְ⁠בַדּ֑⁠וֹ וְ֝⁠דוֹרֵ֗ךְ עַל־בָּ֥מֳתֵי יָֽם׃","nòte֣h şá̌ma֣yim lĕ⁠baḋ֑⁠wò wĕ֝⁠dwòré֗kĕ ʻal-bá֥̇moţéy yáֽm׃"],[9,9,"עֹֽשֶׂה־עָ֭שׁ כְּסִ֥יל וְ⁠כִימָ֗ה וְ⁠חַדְרֵ֥י תֵמָֽן׃","ʻòֽşêh-ʻá֭ş̌ kĕ̇si֥yl wĕ⁠kiymá֗h wĕ⁠ẖadĕré֥y ţémáֽn׃"],[9,10,"עֹשֶׂ֣ה גְ֭דֹלוֹת עַד־אֵ֣ין חֵ֑קֶר וְ⁠נִפְלָא֗וֹת עַד־אֵ֥ין מִסְפָּֽר׃","ʻòşê֣h gĕ֭dòlwòţ ʻad-ʼé֣yn ẖé֑qer wĕ⁠nipĕláʼ֗wòţ ʻad-ʼé֥yn misĕpáֽ̇r׃"],[9,11,"הֵ֤ן יַעֲבֹ֣ר עָ֭לַ⁠י וְ⁠לֹ֣א אֶרְאֶ֑ה וְ֝⁠יַחֲלֹ֗ף וְֽ⁠לֹא־אָבִ֥ין לֽ⁠וֹ׃","hé֤n yaʻàbò֣r ʻá֭la⁠y wĕ⁠lò֣ʼ ʼerĕʼe֑h wĕ֝⁠yaẖàlò֗p wĕֽ⁠lòʼ-ʼábi֥yn lֽ⁠wò׃"],[9,12,"הֵ֣ן יַ֭חְתֹּף מִ֣י יְשִׁיבֶ֑⁠נּוּ מִֽי־יֹאמַ֥ר אֵ֝לָ֗י⁠ו מַֽה־תַּעֲשֶֽׂה׃","hé֣n ya֭ẖĕţò̇p mi֣y yĕşǐybe֑⁠ṅẇ miֽy-yòʼma֥r ʼé֝lá֗y⁠w maֽh-ţȧʻàşêֽh׃"],[9,13,"אֱ֭לוֹהַּ לֹא־יָשִׁ֣יב אַפּ֑⁠וֹ תחת⁠ו שָׁ֝חֲח֗וּ עֹ֣זְרֵי רָֽהַב׃","ʼè֭lwòhȧ lòʼ-yáşǐ֣yb ʼaṗ֑⁠wò ţẖţ⁠w şá̌֝ẖàẖ֗ẇ ʻò֣zĕréy ráֽhab׃"],[9,14,"אַ֭ף כִּֽי־אָנֹכִ֣י אֶֽעֱנֶ֑⁠נּוּ אֶבְחֲרָ֖ה דְבָרַ֣⁠י עִמּֽ⁠וֹ׃","ʼa֭p kiֽ̇y-ʼánòki֣y ʼeֽʻène֑⁠ṅẇ ʼebĕẖàrá֖h dĕbára֣⁠y ʻiṁֽ⁠wò׃"],[9,15,"אֲשֶׁ֣ר אִם־צָ֭דַקְתִּי לֹ֣א אֶעֱנֶ֑ה לִ֝⁠מְשֹׁפְטִ֗⁠י אֶתְחַנָּֽן׃","ʼàşě֣r ʼim-ẕá֭daqĕţi̇y lò֣ʼ ʼeʻène֑h li֝⁠mĕşò̌pĕti֗⁠y ʼeţĕẖanáֽ̇n׃"],[9,16,"אִם־קָרָ֥אתִי וַֽ⁠יַּעֲנֵ֑⁠נִי לֹֽא־אַ֝אֲמִ֗ין כִּֽי־יַאֲזִ֥ין קוֹלִֽ⁠י׃","ʼim-qárá֥ʼţiy waֽ⁠yȧʻàné֑⁠niy lòֽʼ-ʼa֝ʼàmi֗yn kiֽ̇y-yaʼàzi֥yn qwòliֽ⁠y׃"],[9,17,"אֲשֶׁר־בִּ⁠שְׂעָרָ֥ה יְשׁוּפֵ֑⁠נִי וְ⁠הִרְבָּ֖ה פְצָעַ֣⁠י חִנָּֽם׃","ʼàşěr-bi̇⁠şĕ̂ʻárá֥h yĕş̌ẇpé֑⁠niy wĕ⁠hirĕbá֖̇h pĕẕáʻa֣⁠y ẖináֽ̇m׃"],[9,18,"לֹֽא־יִ֭תְּנֵ⁠נִי הָשֵׁ֣ב רוּחִ֑⁠י כִּ֥י יַ֝שְׂבִּעַ֗⁠נִי מַמְּרֹרִֽים׃","lòֽʼ-yi֭ţĕ̇né⁠niy háşé֣̌b rẇẖi֑⁠y ki֥̇y ya֝şĕ̂bi̇ʻa֗⁠niy mamĕ̇ròriֽym׃"],[9,19,"אִם־לְ⁠כֹ֣חַ אַמִּ֣יץ הִנֵּ֑ה וְ⁠אִם־לְ֝⁠מִשְׁפָּ֗ט מִ֣י יוֹעִידֵֽ⁠נִי׃","ʼim-lĕ⁠kò֣ẖa ʼami֣̇yẕ hiné֑̇h wĕ⁠ʼim-lĕ֝⁠mişĕ̌pá̇֗t mi֣y ywòʻiydéֽ⁠niy׃"],[9,20,"אִם־אֶ֭צְדָּק פִּ֣⁠י יַרְשִׁיעֵ֑⁠נִי תָּֽם־אָ֝֗נִי וַֽ⁠יַּעְקְשֵֽׁ⁠נִי׃","ʼim-ʼe֭ẕĕdá̇q pi֣̇⁠y yarĕşǐyʻé֑⁠niy ţáֽ̇m-ʼá֝֗niy waֽ⁠yȧʻĕqĕşéֽ̌⁠niy׃"],[9,21,"תָּֽם־אָ֭נִי לֹֽא־אֵדַ֥ע נַפְשִׁ֗⁠י אֶמְאַ֥ס חַיָּֽ⁠י׃","ţáֽ̇m-ʼá֭niy lòֽʼ-ʼéda֥ʻ napĕşǐ֗⁠y ʼemĕʼa֥s ẖayáֽ̇⁠y׃"],[9,22,"אַחַ֗ת הִ֥יא עַל־כֵּ֥ן אָמַ֑רְתִּי תָּ֥ם וְ֝⁠רָשָׁ֗ע ה֣וּא מְכַלֶּֽה׃","ʼaẖa֗ţ hi֥yʼ ʻal-ké֥̇n ʼáma֑rĕţi̇y ţá֥̇m wĕ֝⁠ráşá̌֗ʻ h֣ẇʼ mĕkalėֽh׃"],[9,23,"אִם־שׁ֭וֹט יָמִ֣ית פִּתְאֹ֑ם לְ⁠מַסַּ֖ת נְקִיִּ֣ם יִלְעָֽג׃","ʼim-ş֭̌wòt yámi֣yţ pi̇ţĕʼò֑m lĕ⁠masȧ֖ţ nĕqiyi֣̇m yilĕʻáֽg׃"],[9,24,"אֶ֤רֶץ ׀ נִתְּנָ֬ה בְֽ⁠יַד־רָשָׁ֗ע פְּנֵֽי־שֹׁפְטֶ֥י⁠הָ יְכַסֶּ֑ה אִם־לֹ֖א אֵפ֣וֹא מִי־הֽוּא׃","ʼe֤reẕ ׀ niţĕ̇ná֬h bĕֽ⁠yad-ráşá̌֗ʻ pĕ̇néֽy-şò̌pĕte֥y⁠há yĕkasė֑h ʼim-lò֖ʼ ʼép֣wòʼ miy-hֽẇʼ׃"],[9,25,"וְ⁠יָמַ֣⁠י קַ֭לּוּ מִנִּי־רָ֑ץ בָּֽ֝רְח֗וּ לֹא־רָא֥וּ טוֹבָֽה׃","wĕ⁠yáma֣⁠y qa֭l̇ẇ mini̇y-rá֑ẕ báֽ̇֝rĕẖ֗ẇ lòʼ-ráʼ֥ẇ twòbáֽh׃"],[9,26,"חָ֭לְפוּ עִם־אֳנִיּ֣וֹת אֵבֶ֑ה כְּ֝⁠נֶ֗שֶׁר יָט֥וּשׂ עֲלֵי־אֹֽכֶל׃","ẖá֭lĕpẇ ʻim-ʼoniẏ֣wòţ ʼébe֑h kĕ̇֝⁠ne֗şěr yát֥ẇş̂ ʻàléy-ʼòֽkel׃"],[9,27,"אִם־אָ֭מְרִ⁠י אֶשְׁכְּחָ֣ה שִׂיחִ֑⁠י אֶעֶזְבָ֖ה פָנַ֣⁠י וְ⁠אַבְלִֽיגָה׃","ʼim-ʼá֭mĕri⁠y ʼeşĕ̌kĕ̇ẖá֣h şîyẖi֑⁠y ʼeʻezĕbá֖h pána֣⁠y wĕ⁠ʼabĕliֽygáh׃"],[9,28,"יָגֹ֥רְתִּי כָל־עַצְּבֹתָ֑⁠י יָ֝דַ֗עְתִּי כִּי־לֹ֥א תְנַקֵּֽ⁠נִי׃","yágò֥rĕţi̇y kál-ʻaẕĕ̇bòţá֑⁠y yá֝da֗ʻĕţi̇y ki̇y-lò֥ʼ ţĕnaqéֽ̇⁠niy׃"],[9,29,"אָנֹכִ֥י אֶרְשָׁ֑ע לָ⁠מָּה־זֶּ֝֗ה הֶ֣בֶל אִיגָֽע׃","ʼánòki֥y ʼerĕşá֑̌ʻ lá⁠má̇h-zė֝֗h he֣bel ʼiygáֽʻ׃"],[9,30,"אִם־הִתְרָחַ֥צְתִּי במו־שָׁ֑לֶג וַ֝⁠הֲזִכּ֗וֹתִי בְּ⁠בֹ֣ר כַּפָּֽ⁠י׃","ʼim-hiţĕráẖa֥ẕĕţi̇y bmw-şá֑̌leg wa֝⁠hàzik̇֗wòţiy bĕ̇⁠bò֣r kȧpáֽ̇⁠y׃"],[9,31,"אָ֭ז בַּ⁠שַּׁ֣חַת תִּטְבְּלֵ֑⁠נִי וְ֝⁠תִֽעֲב֗וּ⁠נִי שַׂלְמוֹתָֽ⁠י׃","ʼá֭z bȧ⁠şȧ֣̌ẖaţ ţi̇tĕbĕ̇lé֑⁠niy wĕ֝⁠ţiֽʻàb֗ẇ⁠niy şâlĕmwòţáֽ⁠y׃"],[9,32,"כִּי־לֹא־אִ֣ישׁ כָּמֹ֣⁠נִי אֶֽעֱנֶ֑⁠נּוּ נָב֥וֹא יַ֝חְדָּ֗ו בַּ⁠מִּשְׁפָּֽט׃","ki̇y-lòʼ-ʼi֣yş̌ ká̇mò֣⁠niy ʼeֽʻène֑⁠ṅẇ náb֥wòʼ ya֝ẖĕdá̇֗w bȧ⁠mi̇şĕ̌páֽ̇t׃"],[9,33,"לֹ֣א יֵשׁ־בֵּינֵ֣י⁠נוּ מוֹכִ֑יחַ יָשֵׁ֖ת יָד֣⁠וֹ עַל־שְׁנֵֽי⁠נוּ׃","lò֣ʼ yéş̌-bé̇yné֣y⁠nẇ mwòki֑yẖa yáşé֖̌ţ yád֣⁠wò ʻal-şĕ̌néֽy⁠nẇ׃"],[9,34,"יָסֵ֣ר מֵ⁠עָלַ֣⁠י שִׁבְט֑⁠וֹ וְ֝⁠אֵמָת֗⁠וֹ אַֽל־תְּבַעֲתַֽ⁠נִּי׃","yásé֣r mé⁠ʻála֣⁠y şǐbĕt֑⁠wò wĕ֝⁠ʼémáţ֗⁠wò ʼaֽl-ţĕ̇baʻàţaֽ⁠ni̇y׃"],[9,35,"אַֽ֭דַבְּרָה וְ⁠לֹ֣א אִירָאֶ֑⁠נּוּ כִּ֥י לֹא־כֵ֥ן אָ֝נֹכִ֗י עִמָּדִֽ⁠י׃","ʼaֽ֭dabĕ̇ráh wĕ⁠lò֣ʼ ʼiyráʼe֑⁠ṅẇ ki֥̇y lòʼ-ké֥n ʼá֝nòki֗y ʻimá̇diֽ⁠y׃"],[10,1,"נָֽקְטָ֥ה נַפְשִׁ֗⁠י בְּ⁠חַ֫יָּ֥⁠י אֶֽעֶזְבָ֣ה עָלַ֣⁠י שִׂיחִ֑⁠י אֲ֝דַבְּרָה֗ בְּ⁠מַ֣ר נַפְשִֽׁ⁠י׃","náֽqĕtá֥h napĕşǐ֗⁠y bĕ̇⁠ẖa֫yá֥̇⁠y ʼeֽʻezĕbá֣h ʻála֣⁠y şîyẖi֑⁠y ʼà֝dabĕ̇ráh֗ bĕ̇⁠ma֣r napĕşǐֽ⁠y׃"],[10,2,"אֹמַ֣ר אֶל־אֱ֭לוֹהַּ אַל־תַּרְשִׁיעֵ֑⁠נִי הֽ֝וֹדִיעֵ֗⁠נִי עַ֣ל מַה־תְּרִיבֵֽ⁠נִי׃","ʼòma֣r ʼel-ʼè֭lwòhȧ ʼal-ţȧrĕşǐyʻé֑⁠niy hֽ֝wòdiyʻé֗⁠niy ʻa֣l mah-ţĕ̇riybéֽ⁠niy׃"],[10,3,"הֲ⁠ט֤וֹב לְ⁠ךָ֨ ׀ כִּֽי־תַעֲשֹׁ֗ק כִּֽי־תִ֭מְאַס יְגִ֣יעַ כַּפֶּ֑י⁠ךָ וְ⁠עַל־עֲצַ֖ת רְשָׁעִ֣ים הוֹפָֽעְתָּ׃","hà⁠t֤wòb lĕ⁠ká֨ ׀ kiֽ̇y-ţaʻàşò̌֗q kiֽ̇y-ţi֭mĕʼas yĕgi֣yʻa kȧpė֑y⁠ká wĕ⁠ʻal-ʻàẕa֖ţ rĕşá̌ʻi֣ym hwòpáֽʻĕţá̇׃"],[10,4,"הַ⁠עֵינֵ֣י בָשָׂ֣ר לָ֑⁠ךְ אִם־כִּ⁠רְא֖וֹת אֱנ֣וֹשׁ תִּרְאֶֽה׃","ha⁠ʻéyné֣y báşá֣̂r lá֑⁠kĕ ʼim-ki̇⁠rĕʼ֖wòţ ʼèn֣wòş̌ ţi̇rĕʼeֽh׃"],[10,5,"הֲ⁠כִ⁠ימֵ֣י אֱנ֣וֹשׁ יָמֶ֑י⁠ךָ אִם־שְׁ֝נוֹתֶ֗י⁠ךָ כִּ֣⁠ימֵי גָֽבֶר׃","hà⁠ki⁠ymé֣y ʼèn֣wòş̌ yáme֑y⁠ká ʼim-şĕ̌֝nwòţe֗y⁠ká ki֣̇⁠yméy gáֽber׃"],[10,6,"כִּֽי־תְבַקֵּ֥שׁ לַ⁠עֲוֺנִ֑⁠י וּ֭⁠לְ⁠חַטָּאתִ֥⁠י תִדְרֽוֹשׁ׃","kiֽ̇y-ţĕbaqé֥̇ş̌ la⁠ʻàwֺni֑⁠y ẇ֭⁠lĕ⁠ẖatá̇ʼţi֥⁠y ţidĕrֽwòş̌׃"],[10,7,"עַֽל־דַּ֭עְתְּ⁠ךָ כִּי־לֹ֣א אֶרְשָׁ֑ע וְ⁠אֵ֖ין מִ⁠יָּדְ⁠ךָ֣ מַצִּֽיל׃","ʻaֽl-dȧ֭ʻĕţĕ̇⁠ká ki̇y-lò֣ʼ ʼerĕşá֑̌ʻ wĕ⁠ʼé֖yn mi⁠yá̇dĕ⁠ká֣ maẕiֽ̇yl׃"],[10,8,"יָדֶ֣י⁠ךָ עִ֭צְּבוּ⁠נִי וַֽ⁠יַּעֲשׂ֑וּ⁠נִי יַ֥חַד סָ֝בִ֗יב וַֽ⁠תְּבַלְּעֵֽ⁠נִי׃","yáde֣y⁠ká ʻi֭ẕĕ̇bẇ⁠niy waֽ⁠yȧʻàş֑̂ẇ⁠niy ya֥ẖad sá֝bi֗yb waֽ⁠ţĕ̇balĕ̇ʻéֽ⁠niy׃"],[10,9,"זְכָר־נָ֭א כִּי־כַ⁠חֹ֣מֶר עֲשִׂיתָ֑⁠נִי וְֽ⁠אֶל־עָפָ֥ר תְּשִׁיבֵֽ⁠נִי׃","zĕkár-ná֭ʼ ki̇y-ka⁠ẖò֣mer ʻàşîyţá֑⁠niy wĕֽ⁠ʼel-ʻápá֥r ţĕ̇şǐybéֽ⁠niy׃"],[10,10,"הֲ⁠לֹ֣א כֶ֭⁠חָלָב תַּתִּיכֵ֑⁠נִי וְ֝⁠כַ⁠גְּבִנָּ֗ה תַּקְפִּיאֵֽ⁠נִי׃","hà⁠lò֣ʼ ke֭⁠ẖáláb ţȧţi̇yké֑⁠niy wĕ֝⁠ka⁠gĕ̇biná̇֗h ţȧqĕpi̇yʼéֽ⁠niy׃"],[10,11,"ע֣וֹר וּ֭⁠בָשָׂר תַּלְבִּישֵׁ֑⁠נִי וּֽ⁠בַ⁠עֲצָמ֥וֹת וְ֝⁠גִידִ֗ים תְּסֹכְכֵֽ⁠נִי׃","ʻ֣wòr ẇ֭⁠báşá̂r ţȧlĕbi̇yşé֑̌⁠niy ẇֽ⁠ba⁠ʻàẕám֥wòţ wĕ֝⁠giydi֗ym ţĕ̇sòkĕkéֽ⁠niy׃"],[10,12,"חַיִּ֣ים וָ֭⁠חֶסֶד עָשִׂ֣יתָ עִמָּדִ֑⁠י וּ֝⁠פְקֻדָּתְ⁠ךָ֗ שָֽׁמְרָ֥ה רוּחִֽ⁠י׃","ẖayi֣̇ym wá֭⁠ẖesed ʻáşî֣yţá ʻimá̇di֑⁠y ẇ֝⁠pĕqudá̇ţĕ⁠ká֗ şáֽ̌mĕrá֥h rẇẖiֽ⁠y׃"],[10,13,"וְ֭⁠אֵלֶּה צָפַ֣נְתָּ בִ⁠לְבָבֶ֑⁠ךָ יָ֝דַ֗עְתִּי כִּי־זֹ֥את עִמָּֽ⁠ךְ׃","wĕ֭⁠ʼélėh ẕápa֣nĕţá̇ bi⁠lĕbábe֑⁠ká yá֝da֗ʻĕţi̇y ki̇y-zò֥ʼţ ʻimáֽ̇⁠kĕ׃"],[10,14,"אִם־חָטָ֥אתִי וּ⁠שְׁמַרְתָּ֑⁠נִי וּ֝⁠מֵ⁠עֲוֺנִ֗⁠י לֹ֣א תְנַקֵּֽ⁠נִי׃","ʼim-ẖátá֥ʼţiy ẇ⁠şĕ̌marĕţá֑̇⁠niy ẇ֝⁠mé⁠ʻàwֺni֗⁠y lò֣ʼ ţĕnaqéֽ̇⁠niy׃"],[10,15,"אִם־רָשַׁ֡עְתִּי אַלְלַ֬י לִ֗⁠י וְ֭⁠צָדַקְתִּי לֹא־אֶשָּׂ֣א רֹאשִׁ֑⁠י שְׂבַ֥ע קָ֝ל֗וֹן וּ⁠רְאֵ֥ה עָנְיִֽ⁠י׃","ʼim-ráşǎ֡ʻĕţi̇y ʼalĕla֬y li֗⁠y wĕ֭⁠ẕádaqĕţi̇y lòʼ-ʼeşá֣̇̂ʼ ròʼşǐ֑⁠y şĕ̂ba֥ʻ qá֝l֗wòn ẇ⁠rĕʼé֥h ʻánĕyֽi⁠y׃"],[10,16,"וְ֭⁠יִגְאֶה כַּ⁠שַּׁ֣חַל תְּצוּדֵ֑⁠נִי וְ֝⁠תָשֹׁ֗ב תִּתְפַּלָּא־בִֽ⁠י׃","wĕ֭⁠yigĕʼeh kȧ⁠şȧ֣̌ẖal ţĕ̇ẕẇdé֑⁠niy wĕ֝⁠ţáşò̌֗b ţi̇ţĕpȧlá̇ʼ-biֽ⁠y׃"],[10,17,"תְּחַדֵּ֬שׁ עֵדֶ֨י⁠ךָ ׀ נֶגְדִּ֗⁠י וְ⁠תֶ֣רֶב כַּֽ֭עַשְׂ⁠ךָ עִמָּדִ֑⁠י חֲלִיפ֖וֹת וְ⁠צָבָ֣א עִמִּֽ⁠י׃","ţĕ̇ẖadé̇֬ş̌ ʻéde֨y⁠ká ׀ negĕdi̇֗⁠y wĕ⁠ţe֣reb kȧֽ֭ʻaşĕ̂⁠ká ʻimá̇di֑⁠y ẖàliyp֖wòţ wĕ⁠ẕábá֣ʼ ʻimiֽ̇⁠y׃"],[10,18,"וְ⁠לָ֣⁠מָּה מֵ֭⁠רֶחֶם הֹצֵאתָ֑⁠נִי אֶ֝גְוַ֗ע וְ⁠עַ֣יִן לֹא־תִרְאֵֽ⁠נִי׃","wĕ⁠lá֣⁠má̇h mé֭⁠reẖem hòẕéʼţá֑⁠niy ʼe֝gĕwa֗ʻ wĕ⁠ʻa֣yin lòʼ-ţirĕʼéֽ⁠niy׃"],[10,19,"כַּ⁠אֲשֶׁ֣ר לֹא־הָיִ֣יתִי אֶהְיֶ֑ה מִ֝⁠בֶּ֗טֶן לַ⁠קֶּ֥בֶר אוּבָֽל׃","kȧ⁠ʼàşě֣r lòʼ-háyi֣yţiy ʼehĕye֑h mi֝⁠bė֗ten la⁠qė֥ber ʼẇbáֽl׃"],[10,20,"הֲ⁠לֹא־מְעַ֣ט יָמַ֣⁠י יחדל ישית מִ֝מֶּ֗⁠נִּי וְ⁠אַבְלִ֥יגָה מְּעָֽט׃","hà⁠lòʼ-mĕʻa֣t yáma֣⁠y yẖdl yşyţ mi֝mė֗⁠ni̇y wĕ⁠ʼabĕli֥ygáh mĕ̇ʻáֽt׃"],[10,21,"בְּ⁠טֶ֣רֶם אֵ֭לֵךְ וְ⁠לֹ֣א אָשׁ֑וּב אֶל־אֶ֖רֶץ חֹ֣שֶׁךְ וְ⁠צַלְמָֽוֶת׃","bĕ̇⁠te֣rem ʼé֭lékĕ wĕ⁠lò֣ʼ ʼáş֑̌ẇb ʼel-ʼe֖reẕ ẖò֣şěkĕ wĕ⁠ẕalĕmáֽweţ׃"],[10,22,"אֶ֤רֶץ עֵיפָ֨תָ⁠ה ׀ כְּמ֥וֹ אֹ֗פֶל צַ֭לְמָוֶת וְ⁠לֹ֥א סְדָרִ֗ים וַ⁠תֹּ֥פַע כְּמוֹ־אֹֽפֶל׃פ","ʼe֤reẕ ʻéypá֨ţá⁠h ׀ kĕ̇m֥wò ʼò֗pel ẕa֭lĕmáweţ wĕ⁠lò֥ʼ sĕdári֗ym wa⁠ţò֥̇paʻ kĕ̇mwò-ʼòֽpel׃p"],[11,1,"וַ֭⁠יַּעַן צֹפַ֥ר הַֽ⁠נַּעֲמָתִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan ẕòpa֥r haֽ⁠nȧʻàmáţi֗y wa⁠yò̇ʼmaֽr׃"],[11,2,"הֲ⁠רֹ֣ב דְּ֭בָרִים לֹ֣א יֵעָנֶ֑ה וְ⁠אִם־אִ֖ישׁ שְׂפָתַ֣יִם יִצְדָּֽק׃","hà⁠rò֣b dĕ֭̇báriym lò֣ʼ yéʻáne֑h wĕ⁠ʼim-ʼi֖yş̌ şĕ̂páţa֣yim yiẕĕdáֽ̇q׃"],[11,3,"בַּ֭דֶּי⁠ךָ מְתִ֣ים יַחֲרִ֑ישׁו וַ֝⁠תִּלְעַ֗ג וְ⁠אֵ֣ין מַכְלִֽם׃","bȧ֭dėy⁠ká mĕţi֣ym yaẖàri֑yş̌w wa֝⁠ţi̇lĕʻa֗g wĕ⁠ʼé֣yn makĕliֽm׃"],[11,4,"וַ֭⁠תֹּאמֶר זַ֣ךְ לִקְחִ֑⁠י וּ֝⁠בַ֗ר הָיִ֥יתִי בְ⁠עֵינֶֽי⁠ךָ׃","wa֭⁠ţò̇ʼmer za֣kĕ liqĕẖi֑⁠y ẇ֝⁠ba֗r háyi֥yţiy bĕ⁠ʻéyneֽy⁠ká׃"],[11,5,"וְֽ⁠אוּלָ֗ם מִֽי־יִתֵּ֣ן אֱל֣וֹהַּ דַּבֵּ֑ר וְ⁠יִפְתַּ֖ח שְׂפָתָ֣י⁠ו עִמָּֽ⁠ךְ׃","wĕֽ⁠ʼẇlá֗m miֽy-yiţé֣̇n ʼèl֣wòhȧ dȧbé֑̇r wĕ⁠yipĕţȧ֖ẖ şĕ̂páţá֣y⁠w ʻimáֽ̇⁠kĕ׃"],[11,6,"וְ⁠יַגֶּד־לְ⁠ךָ֨ ׀ תַּֽעֲלֻמ֣וֹת חָכְמָה֮ כִּֽי־כִפְלַ֪יִם לְֽ⁠ת֫וּשִׁיָּ֥ה וְ⁠דַ֡ע כִּֽי־יַשֶּׁ֥ה לְ⁠ךָ֥ אֱ֝ל֗וֹהַ מֵ⁠עֲוֺנֶֽ⁠ךָ׃","wĕ⁠yagėd-lĕ⁠ká֨ ׀ ţȧֽʻàlum֣wòţ ẖákĕmáh֮ kiֽ̇y-kipĕla֪yim lĕֽ⁠ţ֫ẇşǐyá֥̇h wĕ⁠da֡ʻ kiֽ̇y-yaşė֥̌h lĕ⁠ká֥ ʼè֝l֗wòha mé⁠ʻàwֺneֽ⁠ká׃"],[11,7,"הַ⁠חֵ֣קֶר אֱל֣וֹהַ תִּמְצָ֑א אִ֤ם עַד־תַּכְלִ֖ית שַׁדַּ֣י תִּמְצָֽא׃","ha⁠ẖé֣qer ʼèl֣wòha ţi̇mĕẕá֑ʼ ʼi֤m ʻad-ţȧkĕli֖yţ şǎdȧ֣y ţi̇mĕẕáֽʼ׃"],[11,8,"גָּבְהֵ֣י שָׁ֭מַיִם מַה־תִּפְעָ֑ל עֲמֻקָּ֥ה מִ֝⁠שְּׁא֗וֹל מַה־תֵּדָֽע׃","gá̇bĕhé֣y şá֭̌mayim mah-ţi̇pĕʻá֑l ʻàmuqá֥̇h mi֝⁠şĕ̇̌ʼ֗wòl mah-ţé̇dáֽʻ׃"],[11,9,"אֲרֻכָּ֣ה מֵ⁠אֶ֣רֶץ מִדָּ֑⁠הּ וּ֝⁠רְחָבָ֗ה מִנִּי־יָֽם׃","ʼàruká֣̇h mé⁠ʼe֣reẕ midá֑̇⁠ḣ ẇ֝⁠rĕẖábá֗h mini̇y-yáֽm׃"],[11,10,"אִם־יַחֲלֹ֥ף וְ⁠יַסְגִּ֑יר וְ֝⁠יַקְהִ֗יל וּ⁠מִ֣י יְשִׁיבֶֽ⁠נּוּ׃","ʼim-yaẖàlò֥p wĕ⁠yasĕgi֑̇yr wĕ֝⁠yaqĕhi֗yl ẇ⁠mi֣y yĕşǐybeֽ⁠ṅẇ׃"],[11,11,"כִּי־ה֭וּא יָדַ֣ע מְתֵי־שָׁ֑וְא וַ⁠יַּרְא־אָ֝֗וֶן וְ⁠לֹ֣א יִתְבּוֹנָֽן׃","ki̇y-h֭ẇʼ yáda֣ʻ mĕţéy-şá֑̌wĕʼ wa⁠yȧrĕʼ-ʼá֝֗wen wĕ⁠lò֣ʼ yiţĕḃwònáֽn׃"],[11,12,"וְ⁠אִ֣ישׁ נָ֭בוּב יִלָּבֵ֑ב וְ⁠עַ֥יִר פֶּ֝֗רֶא אָדָ֥ם יִוָּלֵֽד׃","wĕ⁠ʼi֣yş̌ ná֭bẇb yilá̇bé֑b wĕ⁠ʻa֥yir pė֝֗reʼ ʼádá֥m yiwá̇léֽd׃"],[11,13,"אִם־אַ֭תָּ֗ה הֲכִינ֣וֹתָ לִבֶּ֑⁠ךָ וּ⁠פָרַשְׂתָּ֖ אֵלָ֣י⁠ו כַּפֶּֽ⁠ךָ׃","ʼim-ʼa֭ţá̇֗h hàkiyn֣wòţá libė֑⁠ká ẇ⁠páraşĕ̂ţá֖̇ ʼélá֣y⁠w kȧpėֽ⁠ká׃"],[11,14,"אִם־אָ֣וֶן בְּ֭⁠יָדְ⁠ךָ הַרְחִיקֵ֑⁠הוּ וְ⁠אַל־תַּשְׁכֵּ֖ן בְּ⁠אֹהָלֶ֣י⁠ךָ עַוְלָֽה׃","ʼim-ʼá֣wen bĕ֭̇⁠yádĕ⁠ká harĕẖiyqé֑⁠hẇ wĕ⁠ʼal-ţȧşĕ̌ké֖̇n bĕ̇⁠ʼòhále֣y⁠ká ʻawĕláֽh׃"],[11,15,"כִּי־אָ֤ז ׀ תִּשָּׂ֣א פָנֶ֣י⁠ךָ מִ⁠מּ֑וּם וְ⁠הָיִ֥יתָ מֻ֝צָ֗ק וְ⁠לֹ֣א תִירָֽא׃","ki̇y-ʼá֤z ׀ ţi̇şá֣̇̂ʼ páne֣y⁠ká mi⁠ṁ֑ẇm wĕ⁠háyi֥yţá mu֝ẕá֗q wĕ⁠lò֣ʼ ţiyráֽʼ׃"],[11,16,"כִּי־אַ֭תָּה עָמָ֣ל תִּשְׁכָּ֑ח כְּ⁠מַ֖יִם עָבְר֣וּ תִזְכֹּֽר׃","ki̇y-ʼa֭ţá̇h ʻámá֣l ţi̇şĕ̌ká֑̇ẖ kĕ̇⁠ma֖yim ʻábĕr֣ẇ ţizĕkòֽ̇r׃"],[11,17,"וּֽ֭⁠מִ⁠צָּהֳרַיִם יָק֣וּם חָ֑לֶד תָּ֝עֻ֗פָ⁠ה כַּ⁠בֹּ֥קֶר תִּהְיֶֽה׃","ẇֽ֭⁠mi⁠ẕá̇horayim yáq֣ẇm ẖá֑led ţá̇֝ʻu֗pá⁠h kȧ⁠bò֥̇qer ţi̇hĕyeֽh׃"],[11,18,"וּֽ֭⁠בָטַחְתָּ כִּי־יֵ֣שׁ תִּקְוָ֑ה וְ֝⁠חָפַרְתָּ֗ לָ⁠בֶ֥טַח תִּשְׁכָּֽב׃","ẇֽ֭⁠bátaẖĕţá̇ ki̇y-yé֣ş̌ ţi̇qĕwá֑h wĕ֝⁠ẖáparĕţá̇֗ lá⁠be֥taẖ ţi̇şĕ̌káֽ̇b׃"],[11,19,"וְֽ֭⁠רָבַצְתָּ וְ⁠אֵ֣ין מַחֲרִ֑יד וְ⁠חִלּ֖וּ פָנֶ֣י⁠ךָ רַבִּֽים׃","wĕֽ֭⁠rábaẕĕţá̇ wĕ⁠ʼé֣yn maẖàri֑yd wĕ⁠ẖil֖̇ẇ páne֣y⁠ká rabiֽ̇ym׃"],[11,20,"וְ⁠עֵינֵ֥י רְשָׁעִ֗ים תִּ֫כְלֶ֥ינָה וּ֭⁠מָנוֹס אָבַ֣ד מִנְ⁠הֶ֑ם וְ֝⁠תִקְוָתָ֗⁠ם מַֽפַּח־נָֽפֶשׁ׃פ","wĕ⁠ʻéyné֥y rĕşá̌ʻi֗ym ţi̇֫kĕle֥ynáh ẇ֭⁠mánwòs ʼába֣d minĕ⁠he֑m wĕ֝⁠ţiqĕwáţá֗⁠m maֽpȧẖ-náֽpeş̌׃p"],[12,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[12,2,"אָ֭מְנָם כִּ֣י אַתֶּם־עָ֑ם וְ֝⁠עִמָּ⁠כֶ֗ם תָּמ֥וּת חָכְמָֽה׃","ʼá֭mĕnám ki֣̇y ʼaţėm-ʻá֑m wĕ֝⁠ʻimá̇⁠ke֗m ţá̇m֥ẇţ ẖákĕmáֽh׃"],[12,3,"גַּם־לִ֤⁠י לֵבָ֨ב ׀ כְּֽמוֹ⁠כֶ֗ם לֹא־נֹפֵ֣ל אָנֹכִ֣י מִ⁠כֶּ֑ם וְ⁠אֶת־מִי־אֵ֥ין כְּמוֹ־אֵֽלֶּה׃","gȧm-li֤⁠y lébá֨b ׀ kĕֽ̇mwò⁠ke֗m lòʼ-nòpé֣l ʼánòki֣y mi⁠kė֑m wĕ⁠ʼeţ-miy-ʼé֥yn kĕ̇mwò-ʼéֽlėh׃"],[12,4,"שְׂחֹ֤ק לְ⁠רֵעֵ֨⁠הוּ ׀ אֶֽהְיֶ֗ה קֹרֵ֣א לֶ֭⁠אֱלוֹהַּ וַֽ⁠יַּעֲנֵ֑⁠הוּ שְׂ֝ח֗וֹק צַדִּ֥יק תָּמִֽים׃","şĕ̂ẖò֤q lĕ⁠réʻé֨⁠hẇ ׀ ʼeֽhĕye֗h qòré֣ʼ le֭⁠ʼèlwòhȧ waֽ⁠yȧʻàné֑⁠hẇ şĕ̂֝ẖ֗wòq ẕadi֥̇yq ţá̇miֽym׃"],[12,5,"לַ⁠פִּ֣יד בּ֭וּז לְ⁠עַשְׁתּ֣וּת שַׁאֲנָ֑ן נָ֝כ֗וֹן לְ⁠מ֣וֹעֲדֵי רָֽגֶל׃","la⁠pi֣̇yd ḃ֭ẇz lĕ⁠ʻaşĕ̌ţ֣̇ẇţ şǎʼàná֑n ná֝k֗wòn lĕ⁠m֣wòʻàdéy ráֽgel׃"],[12,6,"יִשְׁלָ֤יוּ אֹֽהָלִ֨ים ׀ לְ⁠שֹׁ֥דְדִ֗ים וּֽ֭⁠בַטֻּחוֹת לְ⁠מַרְגִּ֣יזֵי אֵ֑ל לַ⁠אֲשֶׁ֤ר הֵבִ֖יא אֱל֣וֹהַּ בְּ⁠יָדֽ⁠וֹ׃","yişĕ̌lá֤yẇ ʼòֽháli֨ym ׀ lĕ⁠şò֥̌dĕdi֗ym ẇֽ֭⁠batu̇ẖwòţ lĕ⁠marĕgi֣̇yzéy ʼé֑l la⁠ʼàşě֤r hébi֖yʼ ʼèl֣wòhȧ bĕ̇⁠yádֽ⁠wò׃"],[12,7,"וְֽ⁠אוּלָ֗ם שְׁאַל־נָ֣א בְהֵמ֣וֹת וְ⁠תֹרֶ֑⁠ךָּ וְ⁠ע֥וֹף הַ֝⁠שָּׁמַ֗יִם וְ⁠יַגֶּד־לָֽ⁠ךְ׃","wĕֽ⁠ʼẇlá֗m şĕ̌ʼal-ná֣ʼ bĕhém֣wòţ wĕ⁠ţòre֑⁠ká̇ wĕ⁠ʻ֥wòp ha֝⁠şá̇̌ma֗yim wĕ⁠yagėd-láֽ⁠kĕ׃"],[12,8,"א֤וֹ שִׂ֣יחַ לָ⁠אָ֣רֶץ וְ⁠תֹרֶ֑⁠ךָּ וִֽ⁠יסַפְּר֥וּ לְ֝⁠ךָ֗ דְּגֵ֣י הַ⁠יָּֽם׃","ʼ֤wò şî֣yẖa lá⁠ʼá֣reẕ wĕ⁠ţòre֑⁠ká̇ wiֽ⁠ysapĕ̇r֥ẇ lĕ֝⁠ká֗ dĕ̇gé֣y ha⁠yáֽ̇m׃"],[12,9,"מִ֭י לֹא־יָדַ֣ע בְּ⁠כָל־אֵ֑לֶּה כִּ֥י יַד־יְ֝הוָה עָ֣שְׂתָה זֹּֽאת׃","mi֭y lòʼ-yáda֣ʻ bĕ̇⁠kál-ʼé֑lėh ki֥̇y yad-yĕ֝hwáh ʻá֣şĕ̂ţáh zòֽ̇ʼţ׃"],[12,10,"אֲשֶׁ֣ר בְּ֭⁠יָד⁠וֹ נֶ֣פֶשׁ כָּל־חָ֑י וְ֝⁠ר֗וּחַ כָּל־בְּשַׂר־אִֽישׁ׃","ʼàşě֣r bĕ֭̇⁠yád⁠wò ne֣peş̌ ká̇l-ẖá֑y wĕ֝⁠r֗ẇẖa ká̇l-bĕ̇şâr-ʼiֽyş̌׃"],[12,11,"הֲ⁠לֹא־אֹ֭זֶן מִלִּ֣ין תִּבְחָ֑ן וְ֝⁠חֵ֗ךְ אֹ֣כֶל יִטְעַם־לֽ⁠וֹ׃","hà⁠lòʼ-ʼò֭zen mili֣̇yn ţi̇bĕẖá֑n wĕ֝⁠ẖé֗kĕ ʼò֣kel yitĕʻam-lֽ⁠wò׃"],[12,12,"בִּֽ⁠ישִׁישִׁ֥ים חָכְמָ֑ה וְ⁠אֹ֖רֶךְ יָמִ֣ים תְּבוּנָֽה׃","biֽ̇⁠yşǐyşǐ֥ym ẖákĕmá֑h wĕ⁠ʼò֖rekĕ yámi֣ym ţĕ̇bẇnáֽh׃"],[12,13,"עִ֭מּ⁠וֹ חָכְמָ֣ה וּ⁠גְבוּרָ֑ה ל֝֗⁠וֹ עֵצָ֥ה וּ⁠תְבוּנָֽה׃","ʻi֭ṁ⁠wò ẖákĕmá֣h ẇ⁠gĕbẇrá֑h l֝֗⁠wò ʻéẕá֥h ẇ⁠ţĕbẇnáֽh׃"],[12,14,"הֵ֣ן יַ֭הֲרוֹס וְ⁠לֹ֣א יִבָּנֶ֑ה יִסְגֹּ֥ר עַל־אִ֝֗ישׁ וְ⁠לֹ֣א יִפָּתֵֽחַ׃","hé֣n ya֭hàrwòs wĕ⁠lò֣ʼ yibá̇ne֑h yisĕgò֥̇r ʻal-ʼi֝֗yş̌ wĕ⁠lò֣ʼ yipá̇ţéֽẖa׃"],[12,15,"הֵ֤ן יַעְצֹ֣ר בַּ⁠מַּ֣יִם וְ⁠יִבָ֑שׁוּ וִֽ֝⁠ישַׁלְּחֵ֗⁠ם וְ⁠יַ֖הַפְכוּ אָֽרֶץ׃","hé֤n yaʻĕẕò֣r bȧ⁠mȧ֣yim wĕ⁠yibá֑ş̌ẇ wiֽ֝⁠yşǎlĕ̇ẖé֗⁠m wĕ⁠ya֖hapĕkẇ ʼáֽreẕ׃"],[12,16,"עִ֭מּ⁠וֹ עֹ֣ז וְ⁠תֽוּשִׁיָּ֑ה ל֝֗⁠וֹ שֹׁגֵ֥ג וּ⁠מַשְׁגֶּֽה׃","ʻi֭ṁ⁠wò ʻò֣z wĕ⁠ţֽẇşǐyá֑̇h l֝֗⁠wò şò̌gé֥g ẇ⁠maşĕ̌gėֽh׃"],[12,17,"מוֹלִ֣יךְ יוֹעֲצִ֣ים שׁוֹלָ֑ל וְֽ⁠שֹׁפְטִ֥ים יְהוֹלֵֽל׃","mwòli֣ykĕ ywòʻàẕi֣ym ş̌wòlá֑l wĕֽ⁠şò̌pĕti֥ym yĕhwòléֽl׃"],[12,18,"מוּסַ֣ר מְלָכִ֣ים פִּתֵּ֑חַ וַ⁠יֶּאְסֹ֥ר אֵ֝ז֗וֹר בְּ⁠מָתְנֵי⁠הֶֽם׃","mẇsa֣r mĕláki֣ym pi̇ţé֑̇ẖa wa⁠yėʼĕsò֥r ʼé֝z֗wòr bĕ̇⁠máţĕnéy⁠heֽm׃"],[12,19,"מוֹלִ֣יךְ כֹּהֲנִ֣ים שׁוֹלָ֑ל וְ⁠אֵֽתָנִ֣ים יְסַלֵּֽף׃","mwòli֣ykĕ kò̇hàni֣ym ş̌wòlá֑l wĕ⁠ʼéֽţáni֣ym yĕsaléֽ̇p׃"],[12,20,"מֵסִ֣יר שָׂ֭פָה לְ⁠נֶאֱמָנִ֑ים וְ⁠טַ֖עַם זְקֵנִ֣ים יִקָּֽח׃","mési֣yr şá֭̂páh lĕ⁠neʼèmáni֑ym wĕ⁠ta֖ʻam zĕqéni֣ym yiqáֽ̇ẖ׃"],[12,21,"שׁוֹפֵ֣ךְ בּ֭וּז עַל־נְדִיבִ֑ים וּ⁠מְזִ֖יחַ אֲפִיקִ֣ים רִפָּֽה׃","ş̌wòpé֣kĕ ḃ֭ẇz ʻal-nĕdiybi֑ym ẇ⁠mĕzi֖yẖa ʼàpiyqi֣ym ripáֽ̇h׃"],[12,22,"מְגַלֶּ֣ה עֲ֭מֻקוֹת מִנִּי־חֹ֑שֶׁךְ וַ⁠יֹּצֵ֖א לָ⁠א֣וֹר צַלְמָֽוֶת׃","mĕgalė֣h ʻà֭muqwòţ mini̇y-ẖò֑şěkĕ wa⁠yò̇ẕé֖ʼ lá⁠ʼ֣wòr ẕalĕmáֽweţ׃"],[12,23,"מַשְׂגִּ֣יא לַ֭⁠גּוֹיִם וַֽ⁠יְאַבְּדֵ֑⁠ם שֹׁטֵ֥חַ לַ֝⁠גּוֹיִ֗ם וַ⁠יַּנְחֵֽ⁠ם׃","maşĕ̂gi֣̇yʼ la֭⁠ġwòyim waֽ⁠yĕʼabĕ̇dé֑⁠m şò̌té֥ẖa la֝⁠ġwòyi֗m wa⁠yȧnĕẖéֽ⁠m׃"],[12,24,"מֵסִ֗יר לֵ֭ב רָאשֵׁ֣י עַם־הָ⁠אָ֑רֶץ וַ֝⁠יַּתְעֵ֗⁠ם בְּ⁠תֹ֣הוּ לֹא־דָֽרֶךְ׃","mési֗yr lé֭b ráʼşé֣̌y ʻam-há⁠ʼá֑reẕ wa֝⁠yȧţĕʻé֗⁠m bĕ̇⁠ţò֣hẇ lòʼ-dáֽrekĕ׃"],[12,25,"יְמַֽשְׁשׁוּ־חֹ֥שֶׁךְ וְ⁠לֹא־א֑וֹר וַ֝⁠יַּתְעֵ֗⁠ם כַּ⁠שִּׁכּֽוֹר׃","yĕmaֽşĕ̌ş̌ẇ-ẖò֥şěkĕ wĕ⁠lòʼ-ʼ֑wòr wa֝⁠yȧţĕʻé֗⁠m kȧ⁠şi̇̌kֽ̇wòr׃"],[13,1,"הֶן־כֹּ֭ל רָאֲתָ֣ה עֵינִ֑⁠י שָֽׁמְעָ֥ה אָ֝זְנִ֗⁠י וַ⁠תָּ֥בֶן לָֽ⁠הּ׃","hen-kò֭̇l ráʼàţá֣h ʻéyni֑⁠y şáֽ̌mĕʻá֥h ʼá֝zĕni֗⁠y wa⁠ţá֥̇ben láֽ⁠ḣ׃"],[13,2,"כְּֽ֭⁠דַעְתְּ⁠כֶם יָדַ֣עְתִּי גַם־אָ֑נִי לֹא־נֹפֵ֖ל אָנֹכִ֣י מִ⁠כֶּֽם׃","kĕֽ֭̇⁠daʻĕţĕ̇⁠kem yáda֣ʻĕţi̇y gam-ʼá֑niy lòʼ-nòpé֖l ʼánòki֣y mi⁠kėֽm׃"],[13,3,"אוּלָ֗ם אֲ֭נִי אֶל־שַׁדַּ֣י אֲדַבֵּ֑ר וְ⁠הוֹכֵ֖חַ אֶל־אֵ֣ל אֶחְפָּֽץ׃","ʼẇlá֗m ʼà֭niy ʼel-şǎdȧ֣y ʼàdabé֑̇r wĕ⁠hwòké֖ẖa ʼel-ʼé֣l ʼeẖĕpáֽ̇ẕ׃"],[13,4,"וְֽ⁠אוּלָ֗ם אַתֶּ֥ם טֹֽפְלֵי־שָׁ֑קֶר רֹפְאֵ֖י אֱלִ֣ל כֻּלְּ⁠כֶֽם׃","wĕֽ⁠ʼẇlá֗m ʼaţė֥m tòֽpĕléy-şá֑̌qer ròpĕʼé֖y ʼèli֣l ku̇lĕ̇⁠keֽm׃"],[13,5,"מִֽי־יִ֭תֵּן הַחֲרֵ֣שׁ תַּחֲרִישׁ֑וּ⁠ן וּ⁠תְהִ֖י לָ⁠כֶ֣ם לְ⁠חָכְמָֽה׃","miֽy-yi֭ţé̇n haẖàré֣ş̌ ţȧẖàriyş֑̌ẇ⁠n ẇ⁠ţĕhi֖y lá⁠ke֣m lĕ⁠ẖákĕmáֽh׃"],[13,6,"שִׁמְעוּ־נָ֥א תוֹכַחְתִּ֑⁠י וְ⁠רִב֖וֹת שְׂפָתַ֣⁠י הַקְשִֽׁיבוּ׃","şǐmĕʻẇ-ná֥ʼ ţwòkaẖĕţi֑̇⁠y wĕ⁠rib֖wòţ şĕ̂páţa֣⁠y haqĕşǐֽybẇ׃"],[13,7,"הַ֭⁠לְ⁠אֵל תְּדַבְּר֣וּ עַוְלָ֑ה וְ֝⁠ל֗⁠וֹ תְּֽדַבְּר֥וּ רְמִיָּֽה׃","ha֭⁠lĕ⁠ʼél ţĕ̇dabĕ̇r֣ẇ ʻawĕlá֑h wĕ֝⁠l֗⁠wò ţĕֽ̇dabĕ̇r֥ẇ rĕmiyáֽ̇h׃"],[13,8,"הֲ⁠פָנָ֥י⁠ו תִּשָּׂא֑וּ⁠ן אִם־לָ⁠אֵ֥ל תְּרִיבֽוּ⁠ן׃","hà⁠páná֥y⁠w ţi̇şá̇̂ʼ֑ẇ⁠n ʼim-lá⁠ʼé֥l ţĕ̇riybֽẇ⁠n׃"],[13,9,"הֲ֭⁠טוֹב כִּֽי־יַחְקֹ֣ר אֶתְ⁠כֶ֑ם אִם־כְּ⁠הָתֵ֥ל בֶּ֝⁠אֱנ֗וֹשׁ תְּהָתֵ֥לּוּ בֽ⁠וֹ׃","hà֭⁠twòb kiֽ̇y-yaẖĕqò֣r ʼeţĕ⁠ke֑m ʼim-kĕ̇⁠háţé֥l bė֝⁠ʼèn֗wòş̌ ţĕ̇háţé֥l̇ẇ bֽ⁠wò׃"],[13,10,"הוֹכֵ֣חַ יוֹכִ֣יחַ אֶתְ⁠כֶ֑ם אִם־בַּ֝⁠סֵּ֗תֶר פָּנִ֥ים תִּשָּׂאֽוּ⁠ן׃","hwòké֣ẖa ywòki֣yẖa ʼeţĕ⁠ke֑m ʼim-bȧ֝⁠sé̇֗ţer pá̇ni֥ym ţi̇şá̇̂ʼֽẇ⁠n׃"],[13,11,"הֲ⁠לֹ֣א שְׂ֭אֵת⁠וֹ תְּבַעֵ֣ת אֶתְ⁠כֶ֑ם וּ֝⁠פַחְדּ֗⁠וֹ יִפֹּ֥ל עֲלֵי⁠כֶֽם׃","hà⁠lò֣ʼ şĕ֭̂ʼéţ⁠wò ţĕ̇baʻé֣ţ ʼeţĕ⁠ke֑m ẇ֝⁠paẖĕḋ֗⁠wò yipò֥̇l ʻàléy⁠keֽm׃"],[13,12,"זִֽ֭כְרֹנֵי⁠כֶם מִשְׁלֵי־אֵ֑פֶר לְ⁠גַבֵּי־חֹ֝֗מֶר גַּבֵּי⁠כֶֽם׃","ziֽ֭kĕrònéy⁠kem mişĕ̌léy-ʼé֑per lĕ⁠gabé̇y-ẖò֝֗mer gȧbé̇y⁠keֽm׃"],[13,13,"הַחֲרִ֣ישׁוּ מִ֭מֶּ⁠נִּי וַ⁠אֲדַבְּרָה־אָ֑נִי וְ⁠יַעֲבֹ֖ר עָלַ֣⁠י מָֽה׃","haẖàri֣yş̌ẇ mi֭mė⁠ni̇y wa⁠ʼàdabĕ̇ráh-ʼá֑niy wĕ⁠yaʻàbò֖r ʻála֣⁠y máֽh׃"],[13,14,"עַל־מָ֤ה ׀ אֶשָּׂ֣א בְשָׂרִ֣⁠י בְ⁠שִׁנָּ֑⁠י וְ֝⁠נַפְשִׁ֗⁠י אָשִׂ֥ים בְּ⁠כַפִּֽ⁠י׃","ʻal-má֤h ׀ ʼeşá֣̇̂ʼ bĕşá̂ri֣⁠y bĕ⁠şǐná֑̇⁠y wĕ֝⁠napĕşǐ֗⁠y ʼáşî֥ym bĕ̇⁠kapiֽ̇⁠y׃"],[13,15,"הֵ֣ן יִ֭קְטְלֵ⁠נִי לא אֲיַחֵ֑ל אַךְ־דְּ֝רָכַ֗⁠י אֶל־פָּנָ֥י⁠ו אוֹכִֽיחַ׃","hé֣n yi֭qĕtĕlé⁠niy lʼ ʼàyaẖé֑l ʼakĕ-dĕ̇֝ráka֗⁠y ʼel-pá̇ná֥y⁠w ʼwòkiֽyẖa׃"],[13,16,"גַּם־הוּא־לִ֥⁠י לִֽ⁠ישׁוּעָ֑ה כִּי־לֹ֥א לְ֝⁠פָנָ֗י⁠ו חָנֵ֥ף יָבֽוֹא׃","gȧm-hẇʼ-li֥⁠y liֽ⁠yş̌ẇʻá֑h ki̇y-lò֥ʼ lĕ֝⁠páná֗y⁠w ẖáné֥p yábֽwòʼ׃"],[13,17,"שִׁמְע֣וּ שָׁ֭מוֹעַ מִלָּתִ֑⁠י וְ֝⁠אַֽחֲוָתִ֗⁠י בְּ⁠אָזְנֵי⁠כֶֽם׃","şǐmĕʻ֣ẇ şá֭̌mwòʻa milá̇ţi֑⁠y wĕ֝⁠ʼֽaẖàwáţi֗⁠y bĕ̇⁠ʼázĕnéy⁠keֽm׃"],[13,18,"הִנֵּה־נָ֭א עָרַ֣כְתִּי מִשְׁפָּ֑ט יָ֝דַ֗עְתִּי כִּֽי־אֲנִ֥י אֶצְדָּֽק׃","hiné̇h-ná֭ʼ ʻára֣kĕţi̇y mişĕ̌pá֑̇t yá֝da֗ʻĕţi̇y kiֽ̇y-ʼàni֥y ʼeẕĕdáֽ̇q׃"],[13,19,"מִי־ה֭וּא יָרִ֣יב עִמָּדִ֑⁠י כִּֽי־עַתָּ֖ה אַחֲרִ֣ישׁ וְ⁠אֶגְוָֽע׃","miy-h֭ẇʼ yári֣yb ʻimá̇di֑⁠y kiֽ̇y-ʻaţá֖̇h ʼaẖàri֣yş̌ wĕ⁠ʼegĕwáֽʻ׃"],[13,20,"אַךְ־שְׁ֭תַּיִם אַל־תַּ֣עַשׂ עִמָּדִ֑⁠י אָ֥ז מִ֝⁠פָּנֶ֗י⁠ךָ לֹ֣א אֶסָּתֵֽר׃","ʼakĕ-şĕ֭̌ţȧyim ʼal-ţȧ֣ʻaş̂ ʻimá̇di֑⁠y ʼá֥z mi֝⁠pá̇ne֗y⁠ká lò֣ʼ ʼesá̇ţéֽr׃"],[13,21,"כַּ֭פְּ⁠ךָ מֵ⁠עָלַ֣⁠י הַרְחַ֑ק וְ֝⁠אֵ֥מָתְ⁠ךָ֗ אַֽל־תְּבַעֲתַֽ⁠נִּי׃","kȧ֭pĕ̇⁠ká mé⁠ʻála֣⁠y harĕẖa֑q wĕ֝⁠ʼé֥máţĕ⁠ká֗ ʼaֽl-ţĕ̇baʻàţaֽ⁠ni̇y׃"],[13,22,"וּ֭⁠קְרָא וְ⁠אָנֹכִ֣י אֶֽעֱנֶ֑ה אֽוֹ־אֲ֝דַבֵּ֗ר וַ⁠הֲשִׁיבֵֽ⁠נִי׃","ẇ֭⁠qĕráʼ wĕ⁠ʼánòki֣y ʼeֽʻène֑h ʼֽwò-ʼà֝dabé̇֗r wa⁠hàşǐybéֽ⁠niy׃"],[13,23,"כַּ⁠מָּ֣ה לִ֭⁠י עֲוֺנ֣וֹת וְ⁠חַטָּא֑וֹת פִּֽשְׁעִ֥⁠י וְ֝⁠חַטָּאתִ֗⁠י הֹדִיעֵֽ⁠נִי׃","kȧ⁠má֣̇h li֭⁠y ʻàwֺn֣wòţ wĕ⁠ẖatá̇ʼ֑wòţ piֽ̇şĕ̌ʻi֥⁠y wĕ֝⁠ẖatá̇ʼţi֗⁠y hòdiyʻéֽ⁠niy׃"],[13,24,"לָֽ⁠מָּה־פָנֶ֥י⁠ךָ תַסְתִּ֑יר וְ⁠תַחְשְׁבֵ֖⁠נִי לְ⁠אוֹיֵ֣ב לָֽ⁠ךְ׃","láֽ⁠má̇h-páne֥y⁠ká ţasĕţi֑̇yr wĕ⁠ţaẖĕşĕ̌bé֖⁠niy lĕ⁠ʼwòyé֣b láֽ⁠kĕ׃"],[13,25,"הֶ⁠עָלֶ֣ה נִדָּ֣ף תַּעֲר֑וֹץ וְ⁠אֶת־קַ֖שׁ יָבֵ֣שׁ תִּרְדֹּֽף׃","he⁠ʻále֣h nidá֣̇p ţȧʻàr֑wòẕ wĕ⁠ʼeţ-qa֖ş̌ yábé֣ş̌ ţi̇rĕdòֽ̇p׃"],[13,26,"כִּֽי־תִכְתֹּ֣ב עָלַ֣⁠י מְרֹר֑וֹת וְ֝⁠תוֹרִישֵׁ֗⁠נִי עֲוֺנ֥וֹת נְעוּרָֽ⁠י׃","kiֽ̇y-ţikĕţò֣̇b ʻála֣⁠y mĕròr֑wòţ wĕ֝⁠ţwòriyşé̌֗⁠niy ʻàwֺn֥wòţ nĕʻẇráֽ⁠y׃"],[13,27,"וְ⁠תָ֘שֵׂ֤ם בַּ⁠סַּ֨ד ׀ רַגְלַ֗⁠י וְ⁠תִשְׁמ֥וֹר כָּל־אָרְחוֹתָ֑⁠י עַל־שָׁרְשֵׁ֥י רַ֝גְלַ֗⁠י תִּתְחַקֶּֽה׃","wĕ⁠ţá֘şé֤̂m bȧ⁠sȧ֨d ׀ ragĕla֗⁠y wĕ⁠ţişĕ̌m֥wòr ká̇l-ʼárĕẖwòţá֑⁠y ʻal-şá̌rĕşé֥̌y ra֝gĕla֗⁠y ţi̇ţĕẖaqėֽh׃"],[13,28,"וְ֭⁠הוּא כְּ⁠רָקָ֣ב יִבְלֶ֑ה כְּ֝⁠בֶ֗גֶד אֲכָ֣ל⁠וֹ עָֽשׁ׃","wĕ֭⁠hẇʼ kĕ̇⁠ráqá֣b yibĕle֑h kĕ̇֝⁠be֗ged ʼàká֣l⁠wò ʻáֽş̌׃"],[14,1,"אָ֭דָם יְל֣וּד אִשָּׁ֑ה קְצַ֥ר יָ֝מִ֗ים וּֽ⁠שְׂבַֽע־רֹֽגֶז׃","ʼá֭dám yĕl֣ẇd ʼişá֑̇̌h qĕẕa֥r yá֝mi֗ym ẇֽ⁠şĕ̂baֽʻ-ròֽgez׃"],[14,2,"כְּ⁠צִ֣יץ יָ֭צָא וַ⁠יִּמָּ֑ל וַ⁠יִּבְרַ֥ח כַּ֝⁠צֵּ֗ל וְ⁠לֹ֣א יַעֲמֽוֹד׃","kĕ̇⁠ẕi֣yẕ yá֭ẕáʼ wa⁠yi̇má֑̇l wa⁠yi̇bĕra֥ẖ kȧ֝⁠ẕé̇֗l wĕ⁠lò֣ʼ yaʻàmֽwòd׃"],[14,3,"אַף־עַל־זֶ֭ה פָּקַ֣חְתָּ עֵינֶ֑⁠ךָ וְ⁠אֹ֘תִ֤⁠י תָבִ֖יא בְ⁠מִשְׁפָּ֣ט עִמָּֽ⁠ךְ׃","ʼap-ʻal-ze֭h pá̇qa֣ẖĕţá̇ ʻéyne֑⁠ká wĕ⁠ʼò֘ţi֤⁠y ţábi֖yʼ bĕ⁠mişĕ̌pá֣̇t ʻimáֽ̇⁠kĕ׃"],[14,4,"מִֽי־יִתֵּ֣ן טָ֭הוֹר מִ⁠טָּמֵ֗א לֹ֣א אֶחָֽד׃","miֽy-yiţé֣̇n tá֭hwòr mi⁠tá̇mé֗ʼ lò֣ʼ ʼeẖáֽd׃"],[14,5,"אִ֥ם חֲרוּצִ֨ים ׀ יָמָ֗י⁠ו מִֽסְפַּר־חֳדָשָׁ֥י⁠ו אִתָּ֑⁠ךְ חק⁠ו עָ֝שִׂ֗יתָ וְ⁠לֹ֣א יַעֲבֽוֹר׃","ʼi֥m ẖàrẇẕi֨ym ׀ yámá֗y⁠w miֽsĕpȧr-ẖodáşá֥̌y⁠w ʼiţá֑̇⁠kĕ ẖq⁠w ʻá֝şî֗yţá wĕ⁠lò֣ʼ yaʻàbֽwòr׃"],[14,6,"שְׁעֵ֣ה מֵ⁠עָלָ֣י⁠ו וְ⁠יֶחְדָּ֑ל עַד־יִ֝רְצֶ֗ה כְּ⁠שָׂכִ֥יר יוֹמֽ⁠וֹ׃","şĕ̌ʻé֣h mé⁠ʻálá֣y⁠w wĕ⁠yeẖĕdá֑̇l ʻad-yi֝rĕẕe֗h kĕ̇⁠şá̂ki֥yr ywòmֽ⁠wò׃"],[14,7,"כִּ֤י יֵ֥שׁ לָ⁠עֵ֗ץ תִּ֫קְוָ֥ה אִֽם־יִ֭כָּרֵת וְ⁠ע֣וֹד יַחֲלִ֑יף וְ֝⁠יֹֽנַקְתּ֗⁠וֹ לֹ֣א תֶחְדָּֽל׃","ki֤̇y yé֥ş̌ lá⁠ʻé֗ẕ ţi̇֫qĕwá֥h ʼiֽm-yi֭ká̇réţ wĕ⁠ʻ֣wòd yaẖàli֑yp wĕ֝⁠yòֽnaqĕţ̇֗⁠wò lò֣ʼ ţeẖĕdáֽ̇l׃"],[14,8,"אִם־יַזְקִ֣ין בָּ⁠אָ֣רֶץ שָׁרְשׁ֑⁠וֹ וּ֝⁠בֶ⁠עָפָ֗ר יָמ֥וּת גִּזְעֽ⁠וֹ׃","ʼim-yazĕqi֣yn bá̇⁠ʼá֣reẕ şá̌rĕş֑̌⁠wò ẇ֝⁠be⁠ʻápá֗r yám֥ẇţ gi̇zĕʻֽ⁠wò׃"],[14,9,"מֵ⁠רֵ֣יחַ מַ֣יִם יַפְרִ֑חַ וְ⁠עָשָׂ֖ה קָצִ֣יר כְּמוֹ־נָֽטַע׃","mé⁠ré֣yẖa ma֣yim yapĕri֑ẖa wĕ⁠ʻáşá֖̂h qáẕi֣yr kĕ̇mwò-náֽtaʻ׃"],[14,10,"וְ⁠גֶ֣בֶר יָ֭מוּת וַֽ⁠יֶּחֱלָ֑שׁ וַ⁠יִּגְוַ֖ע אָדָ֣ם וְ⁠אַיּֽ⁠וֹ׃","wĕ⁠ge֣ber yá֭mẇţ waֽ⁠yėẖèlá֑ş̌ wa⁠yi̇gĕwa֖ʻ ʼádá֣m wĕ⁠ʼaẏֽ⁠wò׃"],[14,11,"אָֽזְלוּ־מַ֭יִם מִנִּי־יָ֑ם וְ֝⁠נָהָ֗ר יֶחֱרַ֥ב וְ⁠יָבֵֽשׁ׃","ʼáֽzĕlẇ-ma֭yim mini̇y-yá֑m wĕ֝⁠náhá֗r yeẖèra֥b wĕ⁠yábéֽş̌׃"],[14,12,"וְ⁠אִ֥ישׁ שָׁכַ֗ב וְֽ⁠לֹא־יָ֫ק֥וּם עַד־בִּלְתִּ֣י שָׁ֭מַיִם לֹ֣א יָקִ֑יצוּ וְ⁠לֹֽא־יֵ֝עֹ֗רוּ מִ⁠שְּׁנָתָֽ⁠ם׃","wĕ⁠ʼi֥yş̌ şá̌ka֗b wĕֽ⁠lòʼ-yá֫q֥ẇm ʻad-bi̇lĕţi֣̇y şá֭̌mayim lò֣ʼ yáqi֑yẕẇ wĕ⁠lòֽʼ-yé֝ʻò֗rẇ mi⁠şĕ̇̌náţáֽ⁠m׃"],[14,13,"מִ֤י יִתֵּ֨ן ׀ בִּ⁠שְׁא֬וֹל תַּצְפִּנֵ֗⁠נִי תַּ֭סְתִּירֵ⁠נִי עַד־שׁ֣וּב אַפֶּ֑⁠ךָ תָּ֤שִׁ֥ית לִ֖⁠י חֹ֣ק וְ⁠תִזְכְּרֵֽ⁠נִי׃","mi֤y yiţé̇֨n ׀ bi̇⁠şĕ̌ʼ֬wòl ţȧẕĕpi̇né֗⁠niy ţȧ֭sĕţi̇yré⁠niy ʻad-ş֣̌ẇb ʼapė֑⁠ká ţá֤̇şǐ֥yţ li֖⁠y ẖò֣q wĕ⁠ţizĕkĕ̇réֽ⁠niy׃"],[14,14,"אִם־יָמ֥וּת גֶּ֗בֶר הֲ⁠יִ֫חְיֶ֥ה כָּל־יְמֵ֣י צְבָאִ֣⁠י אֲיַחֵ֑ל עַד־בּ֝֗וֹא חֲלִיפָתִֽ⁠י׃","ʼim-yám֥ẇţ gė֗ber hà⁠yi֫ẖĕye֥h ká̇l-yĕmé֣y ẕĕbáʼi֣⁠y ʼàyaẖé֑l ʻad-ḃ֝֗wòʼ ẖàliypáţiֽ⁠y׃"],[14,15,"תִּ֭קְרָא וְ⁠אָנֹכִ֣י אֶֽעֱנֶ֑⁠ךָּ לְֽ⁠מַעֲשֵׂ֖ה יָדֶ֣י⁠ךָ תִכְסֹֽף׃","ţi֭̇qĕráʼ wĕ⁠ʼánòki֣y ʼeֽʻène֑⁠ká̇ lĕֽ⁠maʻàşé֖̂h yáde֣y⁠ká ţikĕsòֽp׃"],[14,16,"כִּֽי־עַ֭תָּה צְעָדַ֣⁠י תִּסְפּ֑וֹר לֹֽא־תִ֝שְׁמ֗וֹר עַל־חַטָּאתִֽ⁠י׃","kiֽ̇y-ʻa֭ţá̇h ẕĕʻáda֣⁠y ţi̇sĕṗ֑wòr lòֽʼ-ţi֝şĕ̌m֗wòr ʻal-ẖatá̇ʼţiֽ⁠y׃"],[14,17,"חָתֻ֣ם בִּ⁠צְר֣וֹר פִּשְׁעִ֑⁠י וַ֝⁠תִּטְפֹּ֗ל עַל־עֲוֺנִֽ⁠י׃","ẖáţu֣m bi̇⁠ẕĕr֣wòr pi̇şĕ̌ʻi֑⁠y wa֝⁠ţi̇tĕpò̇֗l ʻal-ʻàwֺniֽ⁠y׃"],[14,18,"וְ֭⁠אוּלָם הַר־נוֹפֵ֣ל יִבּ֑וֹל וְ֝⁠צ֗וּר יֶעְתַּ֥ק מִ⁠מְּקֹמֽ⁠וֹ׃","wĕ֭⁠ʼẇlám har-nwòpé֣l yiḃ֑wòl wĕ֝⁠ẕ֗ẇr yeʻĕţȧ֥q mi⁠mĕ̇qòmֽ⁠wò׃"],[14,19,"אֲבָנִ֤ים ׀ שָׁ֥חֲקוּ מַ֗יִם תִּשְׁטֹֽף־סְפִיחֶ֥י⁠הָ עֲפַר־אָ֑רֶץ וְ⁠תִקְוַ֖ת אֱנ֣וֹשׁ הֶאֱבַֽדְתָּ׃","ʼàbáni֤ym ׀ şá֥̌ẖàqẇ ma֗yim ţi̇şĕ̌tòֽp-sĕpiyẖe֥y⁠há ʻàpar-ʼá֑reẕ wĕ⁠ţiqĕwa֖ţ ʼèn֣wòş̌ heʼèbaֽdĕţá̇׃"],[14,20,"תִּתְקְפֵ֣⁠הוּ לָ֭⁠נֶצַח וַֽ⁠יַּהֲלֹ֑ךְ מְשַׁנֶּ֥ה פָ֝נָ֗י⁠ו וַֽ⁠תְּשַׁלְּחֵֽ⁠הוּ׃","ţi̇ţĕqĕpé֣⁠hẇ lá֭⁠neẕaẖ waֽ⁠yȧhàlò֑kĕ mĕşǎnė֥h pá֝ná֗y⁠w waֽ⁠ţĕ̇şǎlĕ̇ẖéֽ⁠hẇ׃"],[14,21,"יִכְבְּד֣וּ בָ֭נָי⁠ו וְ⁠לֹ֣א יֵדָ֑ע וְ֝⁠יִצְעֲר֗וּ וְֽ⁠לֹא־יָבִ֥ין לָֽ⁠מוֹ׃","yikĕbĕ̇d֣ẇ bá֭náy⁠w wĕ⁠lò֣ʼ yédá֑ʻ wĕ֝⁠yiẕĕʻàr֗ẇ wĕֽ⁠lòʼ-yábi֥yn láֽ⁠mwò׃"],[14,22,"אַךְ־בְּ֭שָׂר⁠וֹ עָלָ֣י⁠ו יִכְאָ֑ב וְ֝⁠נַפְשׁ֗⁠וֹ עָלָ֥י⁠ו תֶּאֱבָֽל׃פ","ʼakĕ-bĕ֭̇şá̂r⁠wò ʻálá֣y⁠w yikĕʼá֑b wĕ֝⁠napĕş̌֗⁠wò ʻálá֥y⁠w ţėʼèbáֽl׃p"],[15,1,"וַ֭⁠יַּעַן אֱלִיפַ֥ז הַֽ⁠תֵּימָנִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan ʼèliypa֥z haֽ⁠ţé̇ymáni֗y wa⁠yò̇ʼmaֽr׃"],[15,2,"הֶֽ⁠חָכָ֗ם יַעֲנֶ֥ה דַֽעַת־ר֑וּחַ וִֽ⁠ימַלֵּ֖א קָדִ֣ים בִּטְנֽ⁠וֹ׃","heֽ⁠ẖáká֗m yaʻàne֥h daֽʻaţ-r֑ẇẖa wiֽ⁠ymalé֖̇ʼ qádi֣ym bi̇tĕnֽ⁠wò׃"],[15,3,"הוֹכֵ֣חַ בְּ֭⁠דָבָר לֹ֣א יִסְכּ֑וֹן וּ֝⁠מִלִּ֗ים לֹא־יוֹעִ֥יל בָּֽ⁠ם׃","hwòké֣ẖa bĕ֭̇⁠dábár lò֣ʼ yisĕk֑̇wòn ẇ֝⁠mili̇֗ym lòʼ-ywòʻi֥yl báֽ̇⁠m׃"],[15,4,"אַף־אַ֭תָּה תָּפֵ֣ר יִרְאָ֑ה וְ⁠תִגְרַ֥ע שִׂ֝יחָ֗ה לִ⁠פְנֵי־אֵֽל׃","ʼap-ʼa֭ţá̇h ţá̇pé֣r yirĕʼá֑h wĕ⁠ţigĕra֥ʻ şî֝yẖá֗h li⁠pĕnéy-ʼéֽl׃"],[15,5,"כִּ֤י יְאַלֵּ֣ף עֲוֺנְ⁠ךָ֣ פִ֑י⁠ךָ וְ֝⁠תִבְחַ֗ר לְשׁ֣וֹן עֲרוּמִֽים׃","ki֤̇y yĕʼalé֣̇p ʻàwֺnĕ⁠ká֣ pi֑y⁠ká wĕ֝⁠ţibĕẖa֗r lĕş֣̌wòn ʻàrẇmiֽym׃"],[15,6,"יַרְשִֽׁיעֲ⁠ךָ֣ פִ֣י⁠ךָ וְ⁠לֹא־אָ֑נִי וּ֝⁠שְׂפָתֶ֗י⁠ךָ יַעֲנוּ־בָֽ⁠ךְ׃","yarĕşǐֽyʻà⁠ká֣ pi֣y⁠ká wĕ⁠lòʼ-ʼá֑niy ẇ֝⁠şĕ̂páţe֗y⁠ká yaʻànẇ-báֽ⁠kĕ׃"],[15,7,"הֲ⁠רִאישׁ֣וֹן אָ֭דָם תִּוָּלֵ֑ד וְ⁠לִ⁠פְנֵ֖י גְבָע֣וֹת חוֹלָֽלְתָּ׃","hà⁠riʼyş֣̌wòn ʼá֭dám ţi̇wá̇lé֑d wĕ⁠li⁠pĕné֖y gĕbáʻ֣wòţ ẖwòláֽlĕţá̇׃"],[15,8,"הַ⁠בְ⁠ס֣וֹד אֱל֣וֹהַ תִּשְׁמָ֑ע וְ⁠תִגְרַ֖ע אֵלֶ֣י⁠ךָ חָכְמָֽה׃","ha⁠bĕ⁠s֣wòd ʼèl֣wòha ţi̇şĕ̌má֑ʻ wĕ⁠ţigĕra֖ʻ ʼéle֣y⁠ká ẖákĕmáֽh׃"],[15,9,"מַה־יָּ֭דַעְתָּ וְ⁠לֹ֣א נֵדָ֑ע תָּ֝בִ֗ין וְֽ⁠לֹא־עִמָּ֥⁠נוּ הֽוּא׃","mah-yá֭̇daʻĕţá̇ wĕ⁠lò֣ʼ nédá֑ʻ ţá̇֝bi֗yn wĕֽ⁠lòʼ-ʻimá֥̇⁠nẇ hֽẇʼ׃"],[15,10,"גַּם־שָׂ֣ב גַּם־יָשִׁ֣ישׁ בָּ֑⁠נוּ כַּבִּ֖יר מֵ⁠אָבִ֣י⁠ךָ יָמִֽים׃","gȧm-şá֣̂b gȧm-yáşǐ֣yş̌ bá֑̇⁠nẇ kȧbi֖̇yr mé⁠ʼábi֣y⁠ká yámiֽym׃"],[15,11,"הַ⁠מְעַ֣ט מִ֭מְּ⁠ךָ תַּנְחֻמ֣וֹת אֵ֑ל וְ֝⁠דָבָ֗ר לָ⁠אַ֥ט עִמָּֽ⁠ךְ׃","ha⁠mĕʻa֣t mi֭mĕ̇⁠ká ţȧnĕẖum֣wòţ ʼé֑l wĕ֝⁠dábá֗r lá⁠ʼa֥t ʻimáֽ̇⁠kĕ׃"],[15,12,"מַה־יִּקָּחֲ⁠ךָ֥ לִבֶּ֑⁠ךָ וּֽ⁠מַה־יִּרְזְמ֥וּ⁠ן עֵינֶֽי⁠ךָ׃","mah-yi̇qá̇ẖà⁠ká֥ libė֑⁠ká ẇֽ⁠mah-yi̇rĕzĕm֥ẇ⁠n ʻéyneֽy⁠ká׃"],[15,13,"כִּֽי־תָשִׁ֣יב אֶל־אֵ֣ל רוּחֶ֑⁠ךָ וְ⁠הֹצֵ֖אתָ מִ⁠פִּ֣י⁠ךָ מִלִּֽין׃","kiֽ̇y-ţáşǐ֣yb ʼel-ʼé֣l rẇẖe֑⁠ká wĕ⁠hòẕé֖ʼţá mi⁠pi֣̇y⁠ká miliֽ̇yn׃"],[15,14,"מָֽה־אֱנ֥וֹשׁ כִּֽי־יִזְכֶּ֑ה וְ⁠כִֽי־יִ֝צְדַּ֗ק יְל֣וּד אִשָּֽׁה׃","máֽh-ʼèn֥wòş̌ kiֽ̇y-yizĕkė֑h wĕ⁠kiֽy-yi֝ẕĕdȧ֗q yĕl֣ẇd ʼişáֽ̇̌h׃"],[15,15,"הֵ֣ן ב⁠קדש⁠ו לֹ֣א יַאֲמִ֑ין וְ֝⁠שָׁמַ֗יִם לֹא־זַכּ֥וּ בְ⁠עֵינָֽי⁠ו׃","hé֣n b⁠qdş⁠w lò֣ʼ yaʼàmi֑yn wĕ֝⁠şá̌ma֗yim lòʼ-zak֥̇ẇ bĕ⁠ʻéynáֽy⁠w׃"],[15,16,"אַ֭ף כִּֽי־נִתְעָ֥ב וְֽ⁠נֶאֱלָ֑ח אִישׁ־שֹׁתֶ֖ה כַ⁠מַּ֣יִם עַוְלָֽה׃","ʼa֭p kiֽ̇y-niţĕʻá֥b wĕֽ⁠neʼèlá֑ẖ ʼiyş̌-şò̌ţe֖h ka⁠mȧ֣yim ʻawĕláֽh׃"],[15,17,"אֲחַוְ⁠ךָ֥ שְֽׁמַֽע־לִ֑⁠י וְ⁠זֶֽה־חָ֝זִ֗יתִי וַ⁠אֲסַפֵּֽרָה׃","ʼàẖawĕ⁠ká֥ şĕֽ̌maֽʻ-li֑⁠y wĕ⁠zeֽh-ẖá֝zi֗yţiy wa⁠ʼàsapéֽ̇ráh׃"],[15,18,"אֲשֶׁר־חֲכָמִ֥ים יַגִּ֑ידוּ וְ⁠לֹ֥א כִֽ֝חֲד֗וּ מֵ⁠אֲבוֹתָֽ⁠ם׃","ʼàşěr-ẖàkámi֥ym yagi֑̇ydẇ wĕ⁠lò֥ʼ kiֽ֝ẖàd֗ẇ mé⁠ʼàbwòţáֽ⁠m׃"],[15,19,"לָ⁠הֶ֣ם לְ֭⁠בַדָּ⁠ם נִתְּנָ֣ה הָ⁠אָ֑רֶץ וְ⁠לֹא־עָ֖בַר זָ֣ר בְּ⁠תוֹכָֽ⁠ם׃","lá⁠he֣m lĕ֭⁠badá̇⁠m niţĕ̇ná֣h há⁠ʼá֑reẕ wĕ⁠lòʼ-ʻá֖bar zá֣r bĕ̇⁠ţwòkáֽ⁠m׃"],[15,20,"כָּל־יְמֵ֣י רָ֭שָׁע ה֣וּא מִתְחוֹלֵ֑ל וּ⁠מִסְפַּ֥ר שָׁ֝נִ֗ים נִצְפְּנ֥וּ לֶ⁠עָרִֽיץ׃","ká̇l-yĕmé֣y rá֭şá̌ʻ h֣ẇʼ miţĕẖwòlé֑l ẇ⁠misĕpȧ֥r şá̌֝ni֗ym niẕĕpĕ̇n֥ẇ le⁠ʻáriֽyẕ׃"],[15,21,"קוֹל־פְּחָדִ֥ים בְּ⁠אָזְנָ֑י⁠ו בַּ֝⁠שָּׁל֗וֹם שׁוֹדֵ֥ד יְבוֹאֶֽ⁠נּוּ׃","qwòl-pĕ̇ẖádi֥ym bĕ̇⁠ʼázĕná֑y⁠w bȧ֝⁠şá̇̌l֗wòm ş̌wòdé֥d yĕbwòʼeֽ⁠ṅẇ׃"],[15,22,"לֹא־יַאֲמִ֣ין שׁ֭וּב מִנִּי־חֹ֑שֶׁךְ ו⁠צפו ה֣וּא אֱלֵי־חָֽרֶב׃","lòʼ-yaʼàmi֣yn ş֭̌ẇb mini̇y-ẖò֑şěkĕ w⁠ẕpw h֣ẇʼ ʼèléy-ẖáֽreb׃"],[15,23,"נֹ֘דֵ֤ד ה֣וּא לַ⁠לֶּ֣חֶם אַיֵּ֑ה יָדַ֓ע ׀ כִּֽי־נָכ֖וֹן בְּ⁠יָד֣⁠וֹ יֽוֹם־חֹֽשֶׁךְ׃","nò֘dé֤d h֣ẇʼ la⁠lė֣ẖem ʼayé֑̇h yáda֓ʻ ׀ kiֽ̇y-nák֖wòn bĕ̇⁠yád֣⁠wò yֽwòm-ẖòֽşěkĕ׃"],[15,24,"יְֽ֭בַעֲתֻ⁠הוּ צַ֣ר וּ⁠מְצוּקָ֑ה תִּ֝תְקְפֵ֗⁠הוּ כְּ⁠מֶ֤לֶךְ ׀ עָתִ֬יד לַ⁠כִּידֽוֹר׃","yĕֽ֭baʻàţu⁠hẇ ẕa֣r ẇ⁠mĕẕẇqá֑h ţi̇֝ţĕqĕpé֗⁠hẇ kĕ̇⁠me֤lekĕ ׀ ʻáţi֬yd la⁠ki̇ydֽwòr׃"],[15,25,"כִּֽי־נָטָ֣ה אֶל־אֵ֣ל יָד֑⁠וֹ וְ⁠אֶל־שַׁ֝דַּ֗י יִתְגַּבָּֽר׃","kiֽ̇y-nátá֣h ʼel-ʼé֣l yád֑⁠wò wĕ⁠ʼel-şǎ֝dȧ֗y yiţĕgȧbáֽ̇r׃"],[15,26,"יָר֣וּץ אֵלָ֣י⁠ו בְּ⁠צַוָּ֑אר בַּ֝⁠עֲבִ֗י גַּבֵּ֥י מָֽגִנָּֽי⁠ו׃","yár֣ẇẕ ʼélá֣y⁠w bĕ̇⁠ẕawá֑̇ʼr bȧ֝⁠ʻàbi֗y gȧbé֥̇y máֽgináֽ̇y⁠w׃"],[15,27,"כִּֽי־כִסָּ֣ה פָנָ֣י⁠ו בְּ⁠חֶלְבּ֑⁠וֹ וַ⁠יַּ֖עַשׂ פִּימָ֣ה עֲלֵי־כָֽסֶל׃","kiֽ̇y-kisá֣̇h páná֣y⁠w bĕ̇⁠ẖelĕḃ֑⁠wò wa⁠yȧ֖ʻaş̂ pi̇ymá֣h ʻàléy-káֽsel׃"],[15,28,"וַ⁠יִּשְׁכּ֤וֹן ׀ עָ֘רִ֤ים נִכְחָד֗וֹת בָּ֭תִּים לֹא־יֵ֣שְׁבוּ לָ֑⁠מוֹ אֲשֶׁ֖ר הִתְעַתְּד֣וּ לְ⁠גַלִּֽים׃","wa⁠yi̇şĕ̌k֤̇wòn ׀ ʻá֘ri֤ym nikĕẖád֗wòţ bá֭̇ţi̇ym lòʼ-yé֣şĕ̌bẇ lá֑⁠mwò ʼàşě֖r hiţĕʻaţĕ̇d֣ẇ lĕ⁠galiֽ̇ym׃"],[15,29,"לֹֽא־יֶ֭עְשַׁר וְ⁠לֹא־יָק֣וּם חֵיל֑⁠וֹ וְ⁠לֹֽא־יִטֶּ֖ה לָ⁠אָ֣רֶץ מִנְלָֽ⁠ם׃","lòֽʼ-ye֭ʻĕşǎr wĕ⁠lòʼ-yáq֣ẇm ẖéyl֑⁠wò wĕ⁠lòֽʼ-yitė֖h lá⁠ʼá֣reẕ minĕláֽ⁠m׃"],[15,30,"לֹֽא־יָס֨וּר ׀ מִנִּי־חֹ֗שֶׁךְ יֹֽ֭נַקְתּ⁠וֹ תְּיַבֵּ֣שׁ שַׁלְהָ֑בֶת וְ֝⁠יָס֗וּר בְּ⁠ר֣וּחַ פִּֽי⁠ו׃","lòֽʼ-yás֨ẇr ׀ mini̇y-ẖò֗şěkĕ yòֽ֭naqĕţ̇⁠wò ţĕ̇yabé֣̇ş̌ şǎlĕhá֑beţ wĕ֝⁠yás֗ẇr bĕ̇⁠r֣ẇẖa piֽ̇y⁠w׃"],[15,31,"אַל־יַאֲמֵ֣ן ב⁠שו נִתְעָ֑ה כִּי־שָׁ֝֗וְא תִּהְיֶ֥ה תְמוּרָתֽ⁠וֹ׃","ʼal-yaʼàmé֣n b⁠şw niţĕʻá֑h ki̇y-şá̌֝֗wĕʼ ţi̇hĕye֥h ţĕmẇráţֽ⁠wò׃"],[15,32,"בְּֽ⁠לֹא־י֭וֹמ⁠וֹ תִּמָּלֵ֑א וְ֝⁠כִפָּת֗⁠וֹ לֹ֣א רַעֲנָֽנָה׃","bĕֽ̇⁠lòʼ-y֭wòm⁠wò ţi̇má̇lé֑ʼ wĕ֝⁠kipá̇ţ֗⁠wò lò֣ʼ raʻànáֽnáh׃"],[15,33,"יַחְמֹ֣ס כַּ⁠גֶּ֣פֶן בִּסְר֑⁠וֹ וְ⁠יַשְׁלֵ֥ךְ כַּ֝⁠זַּ֗יִת נִצָּתֽ⁠וֹ׃","yaẖĕmò֣s kȧ⁠gė֣pen bi̇sĕr֑⁠wò wĕ⁠yaşĕ̌lé֥kĕ kȧ֝⁠zȧ֗yiţ niẕá̇ţֽ⁠wò׃"],[15,34,"כִּֽי־עֲדַ֣ת חָנֵ֣ף גַּלְמ֑וּד וְ֝⁠אֵ֗שׁ אָכְלָ֥ה אָֽהֳלֵי־שֹֽׁחַד׃","kiֽ̇y-ʻàda֣ţ ẖáné֣p gȧlĕm֑ẇd wĕ֝⁠ʼé֗ş̌ ʼákĕlá֥h ʼáֽholéy-şòֽ̌ẖad׃"],[15,35,"הָרֹ֣ה עָ֭מָל וְ⁠יָ֣לֹד אָ֑וֶן וּ֝⁠בִטְנָ֗⁠ם תָּכִ֥ין מִרְמָֽה׃ס","hárò֣h ʻá֭mál wĕ⁠yá֣lòd ʼá֑wen ẇ֝⁠bitĕná֗⁠m ţá̇ki֥yn mirĕmáֽh׃s"],[16,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[16,2,"שָׁמַ֣עְתִּי כְ⁠אֵ֣לֶּה רַבּ֑וֹת מְנַחֲמֵ֖י עָמָ֣ל כֻּלְּ⁠כֶֽם׃","şá̌ma֣ʻĕţi̇y kĕ⁠ʼé֣lėh raḃ֑wòţ mĕnaẖàmé֖y ʻámá֣l ku̇lĕ̇⁠keֽm׃"],[16,3,"הֲ⁠קֵ֥ץ לְ⁠דִבְרֵי־ר֑וּחַ א֥וֹ מַה־יַּ֝מְרִֽיצְ⁠ךָ֗ כִּ֣י תַעֲנֶֽה׃","hà⁠qé֥ẕ lĕ⁠dibĕréy-r֑ẇẖa ʼ֥wò mah-yȧ֝mĕriֽyẕĕ⁠ká֗ ki֣̇y ţaʻàneֽh׃"],[16,4,"גַּ֤ם ׀ אָנֹכִי֮ כָּ⁠כֶ֪ם אֲדַ֫בֵּ֥רָה ל֤וּ־יֵ֪שׁ נַפְשְׁ⁠כֶ֡ם תַּ֤חַת נַפְשִׁ֗⁠י אַחְבִּ֣ירָה עֲלֵי⁠כֶ֣ם בְּ⁠מִלִּ֑ים וְ⁠אָנִ֥יעָה עֲ֝לֵי⁠כֶ֗ם בְּמ֣וֹ רֹאשִֽׁ⁠י׃","gȧ֤m ׀ ʼánòkiy֮ ká̇⁠ke֪m ʼàda֫bé֥̇ráh l֤ẇ-yé֪ş̌ napĕşĕ̌⁠ke֡m ţȧ֤ẖaţ napĕşǐ֗⁠y ʼaẖĕbi֣̇yráh ʻàléy⁠ke֣m bĕ̇⁠mili֑̇ym wĕ⁠ʼáni֥yʻáh ʻà֝léy⁠ke֗m bĕ̇m֣wò ròʼşǐֽ⁠y׃"],[16,5,"אֲאַמִּצְ⁠כֶ֥ם בְּמוֹ־פִ֑⁠י וְ⁠נִ֖יד שְׂפָתַ֣⁠י יַחְשֹֽׂךְ׃","ʼàʼami̇ẕĕ⁠ke֥m bĕ̇mwò-pi֑⁠y wĕ⁠ni֖yd şĕ̂páţa֣⁠y yaẖĕşòֽ̂kĕ׃"],[16,6,"אִֽם־אֲ֭דַבְּרָה לֹא־יֵחָשֵׂ֣ךְ כְּאֵבִ֑⁠י וְ֝⁠אַחְדְּלָ֗ה מַה־מִ⁠נִּ֥י יַהֲלֹֽךְ׃","ʼiֽm-ʼà֭dabĕ̇ráh lòʼ-yéẖáşé֣̂kĕ kĕ̇ʼébi֑⁠y wĕ֝⁠ʼaẖĕdĕ̇lá֗h mah-mi⁠ni֥̇y yahàlòֽkĕ׃"],[16,7,"אַךְ־עַתָּ֥ה הֶלְאָ֑⁠נִי הֲ֝שִׁמּ֗וֹתָ כָּל־עֲדָתִֽ⁠י׃","ʼakĕ-ʻaţá֥̇h helĕʼá֑⁠niy hà֝şǐṁ֗wòţá ká̇l-ʻàdáţiֽ⁠y׃"],[16,8,"וַֽ֭⁠תִּקְמְטֵ⁠נִי לְ⁠עֵ֣ד הָיָ֑ה וַ⁠יָּ֥קָם בִּ֥⁠י כַ֝חֲשִׁ֗⁠י בְּ⁠פָנַ֥⁠י יַעֲנֶֽה׃","waֽ֭⁠ţi̇qĕmĕté⁠niy lĕ⁠ʻé֣d háyá֑h wa⁠yá֥̇qám bi֥̇⁠y ka֝ẖàşǐ֗⁠y bĕ̇⁠pána֥⁠y yaʻàneֽh׃"],[16,9,"אַפּ֤⁠וֹ טָרַ֨ף ׀ וַֽ⁠יִּשְׂטְמֵ֗⁠נִי חָרַ֣ק עָלַ֣⁠י בְּ⁠שִׁנָּ֑י⁠ו צָרִ֓⁠י ׀ יִלְט֖וֹשׁ עֵינָ֣י⁠ו לִֽ⁠י׃","ʼaṗ֤⁠wò tára֨p ׀ waֽ⁠yi̇şĕ̂tĕmé֗⁠niy ẖára֣q ʻála֣⁠y bĕ̇⁠şǐná֑̇y⁠w ẕári֓⁠y ׀ yilĕt֖wòş̌ ʻéyná֣y⁠w liֽ⁠y׃"],[16,10,"פָּעֲר֬וּ עָלַ֨⁠י ׀ בְּ⁠פִי⁠הֶ֗ם בְּ֭⁠חֶרְפָּה הִכּ֣וּ לְחָיָ֑⁠י יַ֝֗חַד עָלַ֥⁠י יִתְמַלָּאֽוּ⁠ן׃","pá̇ʻàr֬ẇ ʻála֨⁠y ׀ bĕ̇⁠piy⁠he֗m bĕ֭̇⁠ẖerĕpá̇h hik֣̇ẇ lĕẖáyá֑⁠y ya֝֗ẖad ʻála֥⁠y yiţĕmalá̇ʼֽẇ⁠n׃"],[16,11,"יַסְגִּירֵ֣⁠נִי אֵ֭ל אֶ֣ל עֲוִ֑יל וְ⁠עַל־יְדֵ֖י רְשָׁעִ֣ים יִרְטֵֽ⁠נִי׃","yasĕgi̇yré֣⁠niy ʼé֭l ʼe֣l ʻàwi֑yl wĕ⁠ʻal-yĕdé֖y rĕşá̌ʻi֣ym yirĕtéֽ⁠niy׃"],[16,12,"שָׁ֘לֵ֤ו הָיִ֨יתִי ׀ וַֽ⁠יְפַרְפְּרֵ֗⁠נִי וְ⁠אָחַ֣ז בְּ֭⁠עָרְפִּ⁠י וַֽ⁠יְפַצְפְּצֵ֑⁠נִי וַ⁠יְקִימֵ֥⁠נִי ל֝֗⁠וֹ לְ⁠מַטָּרָֽה׃","şá̌֘lé֤w háyi֨yţiy ׀ waֽ⁠yĕparĕpĕ̇ré֗⁠niy wĕ⁠ʼáẖa֣z bĕ֭̇⁠ʻárĕpi̇⁠y waֽ⁠yĕpaẕĕpĕ̇ẕé֑⁠niy wa⁠yĕqiymé֥⁠niy l֝֗⁠wò lĕ⁠matá̇ráֽh׃"],[16,13,"יָ֘סֹ֤בּוּ עָלַ֨⁠י ׀ רַבָּ֗י⁠ו יְפַלַּ֣ח כִּ֭לְיוֹתַ⁠י וְ⁠לֹ֣א יַחְמ֑וֹל יִשְׁפֹּ֥ךְ לָ֝⁠אָ֗רֶץ מְרֵרָֽתִ⁠י׃","yá֘sò֤ḃẇ ʻála֨⁠y ׀ rabá̇֗y⁠w yĕpalȧ֣ẖ ki֭̇lĕywòţa⁠y wĕ⁠lò֣ʼ yaẖĕm֑wòl yişĕ̌pò֥̇kĕ lá֝⁠ʼá֗reẕ mĕréráֽţi⁠y׃"],[16,14,"יִפְרְצֵ֣⁠נִי פֶ֭רֶץ עַל־פְּנֵי־פָ֑רֶץ יָרֻ֖ץ עָלַ֣⁠י כְּ⁠גִבּֽוֹר׃","yipĕrĕẕé֣⁠niy pe֭reẕ ʻal-pĕ̇néy-pá֑reẕ yáru֖ẕ ʻála֣⁠y kĕ̇⁠giḃֽwòr׃"],[16,15,"שַׂ֣ק תָּ֭פַרְתִּי עֲלֵ֣י גִלְדִּ֑⁠י וְ⁠עֹלַ֖לְתִּי בֶ⁠עָפָ֣ר קַרְנִֽ⁠י׃","şâ֣q ţá֭̇parĕţi̇y ʻàlé֣y gilĕdi֑̇⁠y wĕ⁠ʻòla֖lĕţi̇y be⁠ʻápá֣r qarĕniֽ⁠y׃"],[16,16,"פָּנַ֣⁠י חמרמרה מִנִּי־בֶ֑כִי וְ⁠עַ֖ל עַפְעַפַּ֣⁠י צַלְמָֽוֶת׃","pá̇na֣⁠y ẖmrmrh mini̇y-be֑kiy wĕ⁠ʻa֖l ʻapĕʻapȧ֣⁠y ẕalĕmáֽweţ׃"],[16,17,"עַ֭ל לֹא־חָמָ֣ס בְּ⁠כַפָּ֑⁠י וּֽ⁠תְפִלָּתִ֥⁠י זַכָּֽה׃","ʻa֭l lòʼ-ẖámá֣s bĕ̇⁠kapá֑̇⁠y ẇֽ⁠ţĕpilá̇ţi֥⁠y zakáֽ̇h׃"],[16,18,"אֶ֭רֶץ אַל־תְּכַסִּ֣י דָמִ֑⁠י וְֽ⁠אַל־יְהִ֥י מָ֝ק֗וֹם לְ⁠זַעֲקָתִֽ⁠י׃","ʼe֭reẕ ʼal-ţĕ̇kasi֣̇y dámi֑⁠y wĕֽ⁠ʼal-yĕhi֥y má֝q֗wòm lĕ⁠zaʻàqáţiֽ⁠y׃"],[16,19,"גַּם־עַ֭תָּה הִנֵּה־בַ⁠שָּׁמַ֣יִם עֵדִ֑⁠י וְ֝⁠שָׂהֲדִ֗⁠י בַּ⁠מְּרוֹמִֽים׃","gȧm-ʻa֭ţá̇h hiné̇h-ba⁠şá̇̌ma֣yim ʻédi֑⁠y wĕ֝⁠şá̂hàdi֗⁠y bȧ⁠mĕ̇rwòmiֽym׃"],[16,20,"מְלִיצַ֥⁠י רֵעָ֑⁠י אֶל־אֱ֝ל֗וֹהַ דָּלְפָ֥ה עֵינִֽ⁠י׃","mĕliyẕa֥⁠y réʻá֑⁠y ʼel-ʼè֝l֗wòha dá̇lĕpá֥h ʻéyniֽ⁠y׃"],[16,21,"וְ⁠יוֹכַ֣ח לְ⁠גֶ֣בֶר עִם־אֱל֑וֹהַּ וּֽ⁠בֶן־אָדָ֥ם לְ⁠רֵעֵֽ⁠הוּ׃","wĕ⁠ywòka֣ẖ lĕ⁠ge֣ber ʻim-ʼèl֑wòhȧ ẇֽ⁠ben-ʼádá֥m lĕ⁠réʻéֽ⁠hẇ׃"],[16,22,"כִּֽי־שְׁנ֣וֹת מִסְפָּ֣ר יֶאֱתָ֑יוּ וְ⁠אֹ֖רַח לֹא־אָשׁ֣וּב אֶהֱלֹֽךְ׃","kiֽ̇y-şĕ̌n֣wòţ misĕpá֣̇r yeʼèţá֑yẇ wĕ⁠ʼò֖raẖ lòʼ-ʼáş֣̌ẇb ʼehèlòֽkĕ׃"],[17,1,"רוּחִ֣⁠י חֻ֭בָּלָה יָמַ֥⁠י נִזְעָ֗כוּ קְבָרִ֥ים לִֽ⁠י׃","rẇẖi֣⁠y ẖu֭bá̇láh yáma֥⁠y nizĕʻá֗kẇ qĕbári֥ym liֽ⁠y׃"],[17,2,"אִם־לֹ֣א הֲ֭תֻלִים עִמָּדִ֑⁠י וּ֝⁠בְ⁠הַמְּרוֹתָ֗⁠ם תָּלַ֥ן עֵינִֽ⁠י׃","ʼim-lò֣ʼ hà֭ţuliym ʻimá̇di֑⁠y ẇ֝⁠bĕ⁠hamĕ̇rwòţá֗⁠m ţá̇la֥n ʻéyniֽ⁠y׃"],[17,3,"שִֽׂימָ⁠ה־נָּ֭א עָרְבֵ֣⁠נִי עִמָּ֑⁠ךְ מִֽי ה֝֗וּא לְ⁠יָדִ֥⁠י יִתָּקֵֽעַ׃","şîֽymá⁠h-ná֭̇ʼ ʻárĕbé֣⁠niy ʻimá֑̇⁠kĕ miֽy h֝֗ẇʼ lĕ⁠yádi֥⁠y yiţá̇qéֽʻa׃"],[17,4,"כִּֽי־לִ֭בָּ⁠ם צָפַ֣נְתָּ מִּ⁠שָּׂ֑כֶל עַל־כֵּ֝֗ן לֹ֣א תְרֹמֵֽם׃","kiֽ̇y-li֭bá̇⁠m ẕápa֣nĕţá̇ mi̇⁠şá֑̇̂kel ʻal-ké̇֝֗n lò֣ʼ ţĕròméֽm׃"],[17,5,"לְ֭⁠חֵלֶק יַגִּ֣יד רֵעִ֑ים וְ⁠עֵינֵ֖י בָנָ֣י⁠ו תִּכְלֶֽנָה׃","lĕ֭⁠ẖéleq yagi֣̇yd réʻi֑ym wĕ⁠ʻéyné֖y báná֣y⁠w ţi̇kĕleֽnáh׃"],[17,6,"וְֽ֭⁠הִצִּגַ⁠נִי לִ⁠מְשֹׁ֣ל עַמִּ֑ים וְ⁠תֹ֖פֶת לְ⁠פָנִ֣ים אֶֽהְיֶֽה׃","wĕֽ֭⁠hiẕi̇ga⁠niy li⁠mĕşò֣̌l ʻami֑̇ym wĕ⁠ţò֖peţ lĕ⁠páni֣ym ʼeֽhĕyeֽh׃"],[17,7,"וַ⁠תֵּ֣כַהּ מִ⁠כַּ֣עַשׂ עֵינִ֑⁠י וִֽ⁠יצֻרַ֖⁠י כַּ⁠צֵּ֣ל כֻּלָּֽ⁠ם׃","wa⁠ţé֣̇kaḣ mi⁠kȧ֣ʻaş̂ ʻéyni֑⁠y wiֽ⁠yẕura֖⁠y kȧ⁠ẕé֣̇l ku̇láֽ̇⁠m׃"],[17,8,"יָשֹׁ֣מּוּ יְשָׁרִ֣ים עַל־זֹ֑את וְ֝⁠נָקִ֗י עַל־חָנֵ֥ף יִתְעֹרָֽר׃","yáşò֣̌ṁẇ yĕşá̌ri֣ym ʻal-zò֑ʼţ wĕ֝⁠náqi֗y ʻal-ẖáné֥p yiţĕʻòráֽr׃"],[17,9,"וְ⁠יֹאחֵ֣ז צַדִּ֣יק דַּרְכּ֑⁠וֹ וּֽ⁠טֳהָר־יָ֝דַ֗יִם יֹסִ֥יף אֹֽמֶץ׃","wĕ⁠yòʼẖé֣z ẕadi֣̇yq dȧrĕk֑̇⁠wò ẇֽ⁠tohár-yá֝da֗yim yòsi֥yp ʼòֽmeẕ׃"],[17,10,"וְֽ⁠אוּלָ֗ם כֻּלָּ֣⁠ם תָּ֭שֻׁבוּ וּ⁠בֹ֣אוּ נָ֑א וְ⁠לֹֽא־אֶמְצָ֖א בָ⁠כֶ֣ם חָכָֽם׃","wĕֽ⁠ʼẇlá֗m ku̇lá֣̇⁠m ţá֭̇şǔbẇ ẇ⁠bò֣ʼẇ ná֑ʼ wĕ⁠lòֽʼ-ʼemĕẕá֖ʼ bá⁠ke֣m ẖákáֽm׃"],[17,11,"יָמַ֣⁠י עָ֭בְרוּ זִמֹּתַ֣⁠י נִתְּק֑וּ מ֖וֹרָשֵׁ֣י לְבָבִֽ⁠י׃","yáma֣⁠y ʻá֭bĕrẇ zimò̇ţa֣⁠y niţĕ̇q֑ẇ m֖wòráşé֣̌y lĕbábiֽ⁠y׃"],[17,12,"לַ֭יְלָה לְ⁠י֣וֹם יָשִׂ֑ימוּ א֝֗וֹר קָר֥וֹב מִ⁠פְּנֵי־חֹֽשֶׁךְ׃","la֭yĕláh lĕ⁠y֣wòm yáşî֑ymẇ ʼ֝֗wòr qár֥wòb mi⁠pĕ̇néy-ẖòֽşěkĕ׃"],[17,13,"אִם־אֲ֭קַוֶּה שְׁא֣וֹל בֵּיתִ֑⁠י בַּ֝⁠חֹ֗שֶׁךְ רִפַּ֥דְתִּי יְצוּעָֽ⁠י׃","ʼim-ʼà֭qawėh şĕ̌ʼ֣wòl bé̇yţi֑⁠y bȧ֝⁠ẖò֗şěkĕ ripȧ֥dĕţi̇y yĕẕẇʻáֽ⁠y׃"],[17,14,"לַ⁠שַּׁ֣חַת קָ֭רָאתִי אָ֣בִ⁠י אָ֑תָּה אִמִּ֥⁠י וַ֝⁠אֲחֹתִ֗⁠י לָֽ⁠רִמָּֽה׃","la⁠şȧ֣̌ẖaţ qá֭ráʼţiy ʼá֣bi⁠y ʼá֑ţá̇h ʼimi֥̇⁠y wa֝⁠ʼàẖòţi֗⁠y láֽ⁠rimáֽ̇h׃"],[17,15,"וְ֭⁠אַיֵּה אֵפ֣וֹ תִקְוָתִ֑⁠י וְ֝⁠תִקְוָתִ֗⁠י מִ֣י יְשׁוּרֶֽ⁠נָּה׃","wĕ֭⁠ʼayé̇h ʼép֣wò ţiqĕwáţi֑⁠y wĕ֝⁠ţiqĕwáţi֗⁠y mi֣y yĕş̌ẇreֽ⁠ná̇h׃"],[17,16,"בַּדֵּ֣י שְׁאֹ֣ל תֵּרַ֑דְנָה אִם־יַ֖חַד עַל־עָפָ֣ר נָֽחַת׃ס","bȧdé֣̇y şĕ̌ʼò֣l ţé̇ra֑dĕnáh ʼim-ya֖ẖad ʻal-ʻápá֣r náֽẖaţ׃s"],[18,1,"וַ֭⁠יַּעַן בִּלְדַּ֥ד הַ⁠שֻּׁחִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan bi̇lĕdȧ֥d ha⁠şu̇̌ẖi֗y wa⁠yò̇ʼmaֽr׃"],[18,2,"עַד־אָ֤נָה ׀ תְּשִׂימ֣וּ⁠ן קִנְצֵ֣י לְ⁠מִלִּ֑ין תָּ֝בִ֗ינוּ וְ⁠אַחַ֥ר נְדַבֵּֽר׃","ʻad-ʼá֤náh ׀ ţĕ̇şîym֣ẇ⁠n qinĕẕé֣y lĕ⁠mili֑̇yn ţá̇֝bi֗ynẇ wĕ⁠ʼaẖa֥r nĕdabéֽ̇r׃"],[18,3,"מַ֭דּוּעַ נֶחְשַׁ֣בְנוּ כַ⁠בְּהֵמָ֑ה נִ֝טְמִ֗ינוּ בְּ⁠עֵינֵי⁠כֶֽם׃","ma֭ḋẇʻa neẖĕşǎ֣bĕnẇ ka⁠bĕ̇hémá֑h ni֝tĕmi֗ynẇ bĕ̇⁠ʻéynéy⁠keֽm׃"],[18,4,"טֹֽרֵ֥ף נַפְשׁ֗⁠וֹ בְּ⁠אַ֫פּ֥⁠וֹ הַ֭⁠לְמַעַנְ⁠ךָ תֵּעָ֣זַב אָ֑רֶץ וְ⁠יֶעְתַּק־צ֝֗וּר מִ⁠מְּקֹמֽ⁠וֹ׃","tòֽré֥p napĕş̌֗⁠wò bĕ̇⁠ʼa֫ṗ֥⁠wò ha֭⁠lĕmaʻanĕ⁠ká ţé̇ʻá֣zab ʼá֑reẕ wĕ⁠yeʻĕţȧq-ẕ֝֗ẇr mi⁠mĕ̇qòmֽ⁠wò׃"],[18,5,"גַּ֤ם א֣וֹר רְשָׁעִ֣ים יִדְעָ֑ךְ וְ⁠לֹֽא־יִ֝גַּ֗הּ שְׁבִ֣יב אִשּֽׁ⁠וֹ׃","gȧ֤m ʼ֣wòr rĕşá̌ʻi֣ym yidĕʻá֑kĕ wĕ⁠lòֽʼ-yi֝gȧ֗ḣ şĕ̌bi֣yb ʼişֽ̇̌⁠wò׃"],[18,6,"א֭וֹר חָשַׁ֣ךְ בְּ⁠אָהֳל֑⁠וֹ וְ֝⁠נֵר֗⁠וֹ עָלָ֥י⁠ו יִדְעָֽךְ׃","ʼ֭wòr ẖáşǎ֣kĕ bĕ̇⁠ʼáhol֑⁠wò wĕ֝⁠nér֗⁠wò ʻálá֥y⁠w yidĕʻáֽkĕ׃"],[18,7,"יֵֽ֭צְרוּ צַעֲדֵ֣י אוֹנ֑⁠וֹ וְֽ⁠תַשְׁלִיכֵ֥⁠הוּ עֲצָתֽ⁠וֹ׃","yéֽ֭ẕĕrẇ ẕaʻàdé֣y ʼwòn֑⁠wò wĕֽ⁠ţaşĕ̌liyké֥⁠hẇ ʻàẕáţֽ⁠wò׃"],[18,8,"כִּֽי־שֻׁלַּ֣ח בְּ⁠רֶ֣שֶׁת בְּ⁠רַגְלָ֑י⁠ו וְ⁠עַל־שְׂ֝בָכָ֗ה יִתְהַלָּֽךְ׃","kiֽ̇y-şǔlȧ֣ẖ bĕ̇⁠re֣şěţ bĕ̇⁠ragĕlá֑y⁠w wĕ⁠ʻal-şĕ̂֝báká֗h yiţĕhaláֽ̇kĕ׃"],[18,9,"יֹאחֵ֣ז בְּ⁠עָקֵ֣ב פָּ֑ח יַחֲזֵ֖ק עָלָ֣י⁠ו צַמִּֽים׃","yòʼẖé֣z bĕ̇⁠ʻáqé֣b pá֑̇ẖ yaẖàzé֖q ʻálá֣y⁠w ẕamiֽ̇ym׃"],[18,10,"טָמ֣וּן בָּ⁠אָ֣רֶץ חַבְל֑⁠וֹ וּ֝⁠מַלְכֻּדְתּ֗⁠וֹ עֲלֵ֣י נָתִֽיב׃","tám֣ẇn bá̇⁠ʼá֣reẕ ẖabĕl֑⁠wò ẇ֝⁠malĕku̇dĕţ̇֗⁠wò ʻàlé֣y náţiֽyb׃"],[18,11,"סָ֭בִיב בִּֽעֲתֻ֣⁠הוּ בַלָּה֑וֹת וֶ⁠הֱפִיצֻ֥⁠הוּ לְ⁠רַגְלָֽי⁠ו׃","sá֭biyb biֽ̇ʻàţu֣⁠hẇ balá̇h֑wòţ we⁠hèpiyẕu֥⁠hẇ lĕ⁠ragĕláֽy⁠w׃"],[18,12,"יְהִי־רָעֵ֥ב אֹנ֑⁠וֹ וְ֝⁠אֵ֗יד נָכ֥וֹן לְ⁠צַלְעֽ⁠וֹ׃","yĕhiy-ráʻé֥b ʼòn֑⁠wò wĕ֝⁠ʼé֗yd nák֥wòn lĕ⁠ẕalĕʻֽ⁠wò׃"],[18,13,"יֹ֭אכַל בַּדֵּ֣י עוֹר֑⁠וֹ יֹאכַ֥ל בַּ֝דָּ֗י⁠ו בְּכ֣וֹר מָֽוֶת׃","yò֭ʼkal bȧdé֣̇y ʻwòr֑⁠wò yòʼka֥l bȧ֝dá̇֗y⁠w bĕ̇k֣wòr máֽweţ׃"],[18,14,"יִנָּתֵ֣ק מֵ֭⁠אָהֳל⁠וֹ מִבְטַח֑⁠וֹ וְ֝⁠תַצְעִדֵ֗⁠הוּ לְ⁠מֶ֣לֶךְ בַּלָּהֽוֹת׃","yiná̇ţé֣q mé֭⁠ʼáhol⁠wò mibĕtaẖ֑⁠wò wĕ֝⁠ţaẕĕʻidé֗⁠hẇ lĕ⁠me֣lekĕ bȧlá̇hֽwòţ׃"],[18,15,"תִּשְׁכּ֣וֹן בְּ֭⁠אָהֳל⁠וֹ מִ⁠בְּלִי־ל֑⁠וֹ יְזֹרֶ֖ה עַל־נָוֵ֣⁠הוּ גָפְרִֽית׃","ţi̇şĕ̌k֣̇wòn bĕ֭̇⁠ʼáhol⁠wò mi⁠bĕ̇liy-l֑⁠wò yĕzòre֖h ʻal-náwé֣⁠hẇ gápĕriֽyţ׃"],[18,16,"מִ֭⁠תַּחַת שָֽׁרָשָׁ֣י⁠ו יִבָ֑שׁוּ וּ֝⁠מִ⁠מַּ֗עַל יִמַּ֥ל קְצִירֽ⁠וֹ׃","mi֭⁠ţȧẖaţ şáֽ̌ráşá֣̌y⁠w yibá֑ş̌ẇ ẇ֝⁠mi⁠mȧ֗ʻal yimȧ֥l qĕẕiyrֽ⁠wò׃"],[18,17,"זִֽכְר⁠וֹ־אָ֭בַד מִנִּי־אָ֑רֶץ וְ⁠לֹא־שֵׁ֥ם ל֝֗⁠וֹ עַל־פְּנֵי־חֽוּץ׃","ziֽkĕr⁠wò-ʼá֭bad mini̇y-ʼá֑reẕ wĕ⁠lòʼ-şé֥̌m l֝֗⁠wò ʻal-pĕ̇néy-ẖֽẇẕ׃"],[18,18,"יֶ֭הְדְּפֻ⁠הוּ מֵ⁠א֣וֹר אֶל־חֹ֑שֶׁךְ וּֽ⁠מִ⁠תֵּבֵ֥ל יְנִדֻּֽ⁠הוּ׃","ye֭hĕdĕ̇pu⁠hẇ mé⁠ʼ֣wòr ʼel-ẖò֑şěkĕ ẇֽ⁠mi⁠ţé̇bé֥l yĕniduֽ̇⁠hẇ׃"],[18,19,"לֹ֘א נִ֤ין ל֣⁠וֹ וְ⁠לֹא־נֶ֣כֶד בְּ⁠עַמּ֑⁠וֹ וְ⁠אֵ֥ין שָׂ֝רִ֗יד בִּ⁠מְגוּרָֽי⁠ו׃","lò֘ʼ ni֤yn l֣⁠wò wĕ⁠lòʼ-ne֣ked bĕ̇⁠ʻaṁ֑⁠wò wĕ⁠ʼé֥yn şá̂֝ri֗yd bi̇⁠mĕgẇráֽy⁠w׃"],[18,20,"עַל־י֭וֹמ⁠וֹ נָשַׁ֣מּוּ אַחֲרֹנִ֑ים וְ֝⁠קַדְמֹנִ֗ים אָ֣חֲזוּ שָֽׂעַר׃","ʻal-y֭wòm⁠wò náşǎ֣ṁẇ ʼaẖàròni֑ym wĕ֝⁠qadĕmòni֗ym ʼá֣ẖàzẇ şáֽ̂ʻar׃"],[18,21,"אַךְ־אֵ֭לֶּה מִשְׁכְּנ֣וֹת עַוָּ֑ל וְ֝⁠זֶ֗ה מְק֣וֹם לֹא־יָדַֽע־אֵֽל׃ס","ʼakĕ-ʼé֭lėh mişĕ̌kĕ̇n֣wòţ ʻawá֑̇l wĕ֝⁠ze֗h mĕq֣wòm lòʼ-yádaֽʻ-ʼéֽl׃s"],[19,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[19,2,"עַד־אָ֭נָה תּוֹגְי֣וּ⁠ן נַפְשִׁ֑⁠י וּֽ⁠תְדַכְּאוּ⁠נַ֥נִי בְ⁠מִלִּֽים׃","ʻad-ʼá֭náh ţ̇wògĕy֣ẇ⁠n napĕşǐ֑⁠y ẇֽ⁠ţĕdakĕ̇ʼẇ⁠na֥niy bĕ⁠miliֽ̇ym׃"],[19,3,"זֶ֤ה עֶ֣שֶׂר פְּ֭עָמִים תַּכְלִימ֑וּ⁠נִי לֹֽא־תֵ֝בֹ֗שׁוּ תַּהְכְּרוּ־לִֽ⁠י׃","ze֤h ʻe֣şêr pĕ֭̇ʻámiym ţȧkĕliym֑ẇ⁠niy lòֽʼ-ţé֝bò֗ş̌ẇ ţȧhĕkĕ̇rẇ-liֽ⁠y׃"],[19,4,"וְ⁠אַף־אָמְנָ֥ם שָׁגִ֑יתִי אִ֝תִּ֗⁠י תָּלִ֥ין מְשׁוּגָתִֽ⁠י׃","wĕ⁠ʼap-ʼámĕná֥m şá̌gi֑yţiy ʼi֝ţi̇֗⁠y ţá̇li֥yn mĕş̌ẇgáţiֽ⁠y׃"],[19,5,"אִם־אָ֭מְנָם עָלַ֣⁠י תַּגְדִּ֑ילוּ וְ⁠תוֹכִ֥יחוּ עָ֝לַ֗⁠י חֶרְפָּתִּֽ⁠י׃","ʼim-ʼá֭mĕnám ʻála֣⁠y ţȧgĕdi֑̇ylẇ wĕ⁠ţwòki֥yẖẇ ʻá֝la֗⁠y ẖerĕpá̇ţiֽ̇⁠y׃"],[19,6,"דְּֽעוּ־אֵ֭פוֹ כִּי־אֱל֣וֹהַּ עִוְּתָ֑⁠נִי וּ֝⁠מְצוּד֗⁠וֹ עָלַ֥⁠י הִקִּֽיף׃","dĕֽ̇ʻẇ-ʼé֭pwò ki̇y-ʼèl֣wòhȧ ʻiwĕ̇ţá֑⁠niy ẇ֝⁠mĕẕẇd֗⁠wò ʻála֥⁠y hiqiֽ̇yp׃"],[19,7,"הֵ֤ן אֶצְעַ֣ק חָ֭מָס וְ⁠לֹ֣א אֵעָנֶ֑ה אֲ֝שַׁוַּ֗ע וְ⁠אֵ֣ין מִשְׁפָּֽט׃","hé֤n ʼeẕĕʻa֣q ẖá֭más wĕ⁠lò֣ʼ ʼéʻáne֑h ʼà֝şǎwȧ֗ʻ wĕ⁠ʼé֣yn mişĕ̌páֽ̇t׃"],[19,8,"אָרְחִ֣⁠י גָ֭דַר וְ⁠לֹ֣א אֶעֱב֑וֹר וְ⁠עַ֥ל נְ֝תִיבוֹתַ֗⁠י חֹ֣שֶׁךְ יָשִֽׂים׃","ʼárĕẖi֣⁠y gá֭dar wĕ⁠lò֣ʼ ʼeʻèb֑wòr wĕ⁠ʻa֥l nĕ֝ţiybwòţa֗⁠y ẖò֣şěkĕ yáşîֽym׃"],[19,9,"כְּ֭בוֹדִ⁠י מֵ⁠עָלַ֣⁠י הִפְשִׁ֑יט וַ֝⁠יָּ֗סַר עֲטֶ֣רֶת רֹאשִֽׁ⁠י׃","kĕ֭̇bwòdi⁠y mé⁠ʻála֣⁠y hipĕşǐ֑yt wa֝⁠yá̇֗sar ʻàte֣reţ ròʼşǐֽ⁠y׃"],[19,10,"יִתְּצֵ֣⁠נִי סָ֭בִיב וָ⁠אֵלַ֑ךְ וַ⁠יַּסַּ֥ע כָּ֝⁠עֵ֗ץ תִּקְוָתִֽ⁠י׃","yiţĕ̇ẕé֣⁠niy sá֭biyb wá⁠ʼéla֑kĕ wa⁠yȧsȧ֥ʻ ká̇֝⁠ʻé֗ẕ ţi̇qĕwáţiֽ⁠y׃"],[19,11,"וַ⁠יַּ֣חַר עָלַ֣⁠י אַפּ֑⁠וֹ וַ⁠יַּחְשְׁבֵ֖⁠נִי ל֣⁠וֹ כְ⁠צָרָֽי⁠ו׃","wa⁠yȧ֣ẖar ʻála֣⁠y ʼaṗ֑⁠wò wa⁠yȧẖĕşĕ̌bé֖⁠niy l֣⁠wò kĕ⁠ẕáráֽy⁠w׃"],[19,12,"יַ֤חַד ׀ יָ֘בֹ֤אוּ גְדוּדָ֗י⁠ו וַ⁠יָּסֹ֣לּוּ עָלַ֣⁠י דַּרְכָּ֑⁠ם וַ⁠יַּחֲנ֖וּ סָבִ֣יב לְ⁠אָהֳלִֽ⁠י׃","ya֤ẖad ׀ yá֘bò֤ʼẇ gĕdẇdá֗y⁠w wa⁠yá̇sò֣l̇ẇ ʻála֣⁠y dȧrĕká֑̇⁠m wa⁠yȧẖàn֖ẇ sábi֣yb lĕ⁠ʼáholiֽ⁠y׃"],[19,13,"אַ֭חַ⁠י מֵ⁠עָלַ֣⁠י הִרְחִ֑יק וְ֝⁠יֹדְעַ֗⁠י אַךְ־זָ֥רוּ מִמֶּֽ⁠נִּי׃","ʼa֭ẖa⁠y mé⁠ʻála֣⁠y hirĕẖi֑yq wĕ֝⁠yòdĕʻa֗⁠y ʼakĕ-zá֥rẇ mimėֽ⁠ni̇y׃"],[19,14,"חָדְל֥וּ קְרוֹבָ֑⁠י וּֽ⁠מְיֻדָּעַ֥⁠י שְׁכֵחֽוּ⁠נִי׃","ẖádĕl֥ẇ qĕrwòbá֑⁠y ẇֽ⁠mĕyudá̇ʻa֥⁠y şĕ̌kéẖֽẇ⁠niy׃"],[19,15,"גָּ֘רֵ֤י בֵיתִ֣⁠י וְ֭⁠אַמְהֹתַ⁠י לְ⁠זָ֣ר תַּחְשְׁבֻ֑⁠נִי נָ֝כְרִ֗י הָיִ֥יתִי בְ⁠עֵינֵי⁠הֶֽם׃","gá̇֘ré֤y béyţi֣⁠y wĕ֭⁠ʼamĕhòţa⁠y lĕ⁠zá֣r ţȧẖĕşĕ̌bu֑⁠niy ná֝kĕri֗y háyi֥yţiy bĕ⁠ʻéynéy⁠heֽm׃"],[19,16,"לְ⁠עַבְדִּ֣⁠י קָ֭רָאתִי וְ⁠לֹ֣א יַעֲנֶ֑ה בְּמוֹ־פִ֝֗⁠י אֶתְחַנֶּן־לֽ⁠וֹ׃","lĕ⁠ʻabĕdi֣̇⁠y qá֭ráʼţiy wĕ⁠lò֣ʼ yaʻàne֑h bĕ̇mwò-pi֝֗⁠y ʼeţĕẖanėn-lֽ⁠wò׃"],[19,17,"ר֭וּחִֽ⁠י זָ֣רָה לְ⁠אִשְׁתִּ֑⁠י וְ֝⁠חַנֹּתִ֗י לִ⁠בְנֵ֥י בִטְנִֽ⁠י׃","r֭ẇẖiֽ⁠y zá֣ráh lĕ⁠ʼişĕ̌ţi֑̇⁠y wĕ֝⁠ẖanò̇ţi֗y li⁠bĕné֥y bitĕniֽ⁠y׃"],[19,18,"גַּם־עֲ֭וִילִים מָ֣אֲסוּ בִ֑⁠י אָ֝ק֗וּמָה וַ⁠יְדַבְּרוּ־בִֽ⁠י׃","gȧm-ʻà֭wiyliym má֣ʼàsẇ bi֑⁠y ʼá֝q֗ẇmáh wa⁠yĕdabĕ̇rẇ-biֽ⁠y׃"],[19,19,"תִּֽ֭עֲבוּ⁠נִי כָּל־מְתֵ֣י סוֹדִ֑⁠י וְ⁠זֶֽה־אָ֝הַ֗בְתִּי נֶהְפְּכוּ־בִֽ⁠י׃","ţiֽ֭̇ʻàbẇ⁠niy ká̇l-mĕţé֣y swòdi֑⁠y wĕ⁠zeֽh-ʼá֝ha֗bĕţi̇y nehĕpĕ̇kẇ-biֽ⁠y׃"],[19,20,"בְּ⁠עוֹרִ֣⁠י וּ֭⁠בִ⁠בְשָׂרִ⁠י דָּבְקָ֣ה עַצְמִ֑⁠י וָ֝⁠אֶתְמַלְּטָ֗⁠ה בְּ⁠ע֣וֹר שִׁנָּֽ⁠י׃","bĕ̇⁠ʻwòri֣⁠y ẇ֭⁠bi⁠bĕşá̂ri⁠y dá̇bĕqá֣h ʻaẕĕmi֑⁠y wá֝⁠ʼeţĕmalĕ̇tá֗⁠h bĕ̇⁠ʻ֣wòr şǐnáֽ̇⁠y׃"],[19,21,"חָנֻּ֬⁠נִי חָנֻּ֣⁠נִי אַתֶּ֣ם רֵעָ֑⁠י כִּ֥י יַד־אֱ֝ל֗וֹהַּ נָ֣גְעָה בִּֽ⁠י׃","ẖánu̇֬⁠niy ẖánu֣̇⁠niy ʼaţė֣m réʻá֑⁠y ki֥̇y yad-ʼè֝l֗wòhȧ ná֣gĕʻáh biֽ̇⁠y׃"],[19,22,"לָ֭⁠מָּה תִּרְדְּפֻ֣⁠נִי כְמוֹ־אֵ֑ל וּ֝⁠מִ⁠בְּשָׂרִ֗⁠י לֹ֣א תִשְׂבָּֽעוּ׃","lá֭⁠má̇h ţi̇rĕdĕ̇pu֣⁠niy kĕmwò-ʼé֑l ẇ֝⁠mi⁠bĕ̇şá̂ri֗⁠y lò֣ʼ ţişĕ̂báֽ̇ʻẇ׃"],[19,23,"מִֽי־יִתֵּ֣ן אֵ֭פוֹ וְ⁠יִכָּתְב֣וּ⁠ן מִלָּ֑⁠י מִֽי־יִתֵּ֖ן בַּ⁠סֵּ֣פֶר וְ⁠יֻחָֽקוּ׃","miֽy-yiţé֣̇n ʼé֭pwò wĕ⁠yiká̇ţĕb֣ẇ⁠n milá֑̇⁠y miֽy-yiţé֖̇n bȧ⁠sé֣̇per wĕ⁠yuẖáֽqẇ׃"],[19,24,"בְּ⁠עֵט־בַּרְזֶ֥ל וְ⁠עֹפָ֑רֶת לָ֝⁠עַ֗ד בַּ⁠צּ֥וּר יֵחָצְבֽוּ⁠ן׃","bĕ̇⁠ʻét-bȧrĕze֥l wĕ⁠ʻòpá֑reţ lá֝⁠ʻa֗d bȧ⁠ẕ֥̇ẇr yéẖáẕĕbֽẇ⁠n׃"],[19,25,"וַ⁠אֲנִ֣י יָ֭דַעְתִּי גֹּ֣אֲלִ⁠י חָ֑י וְ֝⁠אַחֲר֗וֹן עַל־עָפָ֥ר יָקֽוּם׃","wa⁠ʼàni֣y yá֭daʻĕţi̇y gò֣̇ʼàli⁠y ẖá֑y wĕ֝⁠ʼaẖàr֗wòn ʻal-ʻápá֥r yáqֽẇm׃"],[19,26,"וְ⁠אַחַ֣ר ע֭וֹרִֽ⁠י נִקְּפוּ־זֹ֑את וּ֝⁠מִ⁠בְּשָׂרִ֗⁠י אֶֽחֱזֶ֥ה אֱלֽוֹהַּ׃","wĕ⁠ʼaẖa֣r ʻ֭wòriֽ⁠y niqĕ̇pẇ-zò֑ʼţ ẇ֝⁠mi⁠bĕ̇şá̂ri֗⁠y ʼeֽẖèze֥h ʼèlֽwòhȧ׃"],[19,27,"אֲשֶׁ֤ר אֲנִ֨י ׀ אֶֽחֱזֶה־לִּ֗⁠י וְ⁠עֵינַ֣⁠י רָא֣וּ וְ⁠לֹא־זָ֑ר כָּל֖וּ כִלְיֹתַ֣⁠י בְּ⁠חֵקִֽ⁠י׃","ʼàşě֤r ʼàni֨y ׀ ʼeֽẖèzeh-li̇֗⁠y wĕ⁠ʻéyna֣⁠y ráʼ֣ẇ wĕ⁠lòʼ-zá֑r ká̇l֖ẇ kilĕyòţa֣⁠y bĕ̇⁠ẖéqiֽ⁠y׃"],[19,28,"כִּ֣י תֹ֭אמְרוּ מַה־נִּרְדָּף־ל֑⁠וֹ וְ⁠שֹׁ֥רֶשׁ דָּ֝בָ֗ר נִמְצָא־בִֽ⁠י׃","ki֣̇y ţò֭ʼmĕrẇ mah-ni̇rĕdá̇p-l֑⁠wò wĕ⁠şò֥̌reş̌ dá̇֝bá֗r nimĕẕáʼ-biֽ⁠y׃"],[19,29,"גּ֤וּרוּ לָ⁠כֶ֨ם ׀ מִ⁠פְּנֵי־חֶ֗רֶב כִּֽי־חֵ֭מָה עֲוֺנ֣וֹת חָ֑רֶב לְמַ֖עַן תֵּדְע֣וּ⁠ן ש⁠דין׃ס","ġ֤ẇrẇ lá⁠ke֨m ׀ mi⁠pĕ̇néy-ẖe֗reb kiֽ̇y-ẖé֭máh ʻàwֺn֣wòţ ẖá֑reb lĕma֖ʻan ţé̇dĕʻ֣ẇ⁠n ş⁠dyn׃s"],[20,1,"וַ֭⁠יַּעַן צֹפַ֥ר הַ⁠נַּֽעֲמָתִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan ẕòpa֥r ha⁠nȧֽʻàmáţi֗y wa⁠yò̇ʼmaֽr׃"],[20,2,"לָ֭⁠כֵן שְׂעִפַּ֣⁠י יְשִׁיב֑וּ⁠נִי וּ֝⁠בַ⁠עֲב֗וּר ח֣וּשִׁ⁠י בִֽ⁠י׃","lá֭⁠kén şĕ̂ʻipȧ֣⁠y yĕşǐyb֑ẇ⁠niy ẇ֝⁠ba⁠ʻàb֗ẇr ẖ֣ẇşǐ⁠y biֽ⁠y׃"],[20,3,"מוּסַ֣ר כְּלִמָּתִ֣⁠י אֶשְׁמָ֑ע וְ֝⁠ר֗וּחַ מִֽ⁠בִּינָתִ֥⁠י יַעֲנֵֽ⁠נִי׃","mẇsa֣r kĕ̇limá̇ţi֣⁠y ʼeşĕ̌má֑ʻ wĕ֝⁠r֗ẇẖa miֽ⁠bi̇ynáţi֥⁠y yaʻànéֽ⁠niy׃"],[20,4,"הֲ⁠זֹ֣את יָ֭דַעְתָּ מִנִּי־עַ֑ד מִנִּ֤י שִׂ֖ים אָדָ֣ם עֲלֵי־אָֽרֶץ׃","hà⁠zò֣ʼţ yá֭daʻĕţá̇ mini̇y-ʻa֑d mini֤̇y şî֖ym ʼádá֣m ʻàléy-ʼáֽreẕ׃"],[20,5,"כִּ֤י רִנְנַ֣ת רְ֭שָׁעִים מִ⁠קָּר֑וֹב וְ⁠שִׂמְחַ֖ת חָנֵ֣ף עֲדֵי־רָֽגַע׃","ki֤̇y rinĕna֣ţ rĕ֭şá̌ʻiym mi⁠qá̇r֑wòb wĕ⁠şîmĕẖa֖ţ ẖáné֣p ʻàdéy-ráֽgaʻ׃"],[20,6,"אִם־יַעֲלֶ֣ה לַ⁠שָּׁמַ֣יִם שִׂיא֑⁠וֹ וְ֝⁠רֹאשׁ֗⁠וֹ לָ⁠עָ֥ב יַגִּֽיעַ׃","ʼim-yaʻàle֣h la⁠şá̇̌ma֣yim şîyʼ֑⁠wò wĕ֝⁠ròʼş̌֗⁠wò lá⁠ʻá֥b yagiֽ̇yʻa׃"],[20,7,"כְּֽ֭⁠גֶלֲל⁠וֹ לָ⁠נֶ֣צַח יֹאבֵ֑ד רֹ֝אָ֗י⁠ו יֹאמְר֥וּ אַיּֽ⁠וֹ׃","kĕֽ֭̇⁠gelàl⁠wò lá⁠ne֣ẕaẖ yòʼbé֑d rò֝ʼá֗y⁠w yòʼmĕr֥ẇ ʼaẏֽ⁠wò׃"],[20,8,"כַּ⁠חֲל֣וֹם יָ֭עוּף וְ⁠לֹ֣א יִמְצָא֑וּ⁠הוּ וְ֝⁠יֻדַּ֗ד כְּ⁠חֶזְי֥וֹן לָֽיְלָה׃","kȧ⁠ẖàl֣wòm yá֭ʻẇp wĕ⁠lò֣ʼ yimĕẕáʼ֑ẇ⁠hẇ wĕ֝⁠yudȧ֗d kĕ̇⁠ẖezĕy֥wòn láֽyĕláh׃"],[20,9,"עַ֣יִן שְׁ֭זָפַתּ⁠וּ וְ⁠לֹ֣א תוֹסִ֑יף וְ⁠לֹא־ע֝֗וֹד תְּשׁוּרֶ֥⁠נּוּ מְקוֹמֽ⁠וֹ׃","ʻa֣yin şĕ֭̌zápaţ̇⁠ẇ wĕ⁠lò֣ʼ ţwòsi֑yp wĕ⁠lòʼ-ʻ֝֗wòd ţĕ̇ş̌ẇre֥⁠ṅẇ mĕqwòmֽ⁠wò׃"],[20,10,"בָּ֭נָי⁠ו יְרַצּ֣וּ דַלִּ֑ים וְ֝⁠יָדָ֗י⁠ו תָּשֵׁ֥בְנָה אוֹנֽ⁠וֹ׃","bá֭̇náy⁠w yĕraẕ֣̇ẇ dali֑̇ym wĕ֝⁠yádá֗y⁠w ţá̇şé֥̌bĕnáh ʼwònֽ⁠wò׃"],[20,11,"עַ֭צְמוֹתָי⁠ו מָלְא֣וּ עלומ⁠ו וְ֝⁠עִמּ֗⁠וֹ עַל־עָפָ֥ר תִּשְׁכָּֽב׃","ʻa֭ẕĕmwòţáy⁠w málĕʼ֣ẇ ʻlwm⁠w wĕ֝⁠ʻiṁ֗⁠wò ʻal-ʻápá֥r ţi̇şĕ̌káֽ̇b׃"],[20,12,"אִם־תַּמְתִּ֣יק בְּ⁠פִ֣י⁠ו רָעָ֑ה יַ֝כְחִידֶ֗⁠נָּה תַּ֣חַת לְשׁוֹנֽ⁠וֹ׃","ʼim-ţȧmĕţi֣̇yq bĕ̇⁠pi֣y⁠w ráʻá֑h ya֝kĕẖiyde֗⁠ná̇h ţȧ֣ẖaţ lĕş̌wònֽ⁠wò׃"],[20,13,"יַחְמֹ֣ל עָ֭לֶי⁠הָ וְ⁠לֹ֣א יַֽעַזְבֶ֑⁠נָּה וְ֝⁠יִמְנָעֶ֗⁠נָּה בְּ⁠ת֣וֹךְ חִכּֽ⁠וֹ׃","yaẖĕmò֣l ʻá֭ley⁠há wĕ⁠lò֣ʼ yaֽʻazĕbe֑⁠ná̇h wĕ֝⁠yimĕnáʻe֗⁠ná̇h bĕ̇⁠ţ֣wòkĕ ẖikֽ̇⁠wò׃"],[20,14,"לַ֭חְמ⁠וֹ בְּ⁠מֵעָ֣י⁠ו נֶהְפָּ֑ךְ מְרוֹרַ֖ת פְּתָנִ֣ים בְּ⁠קִרְבּֽ⁠וֹ׃","la֭ẖĕm⁠wò bĕ̇⁠méʻá֣y⁠w nehĕpá֑̇kĕ mĕrwòra֖ţ pĕ̇ţáni֣ym bĕ̇⁠qirĕḃֽ⁠wò׃"],[20,15,"חַ֣יִל בָּ֭לַע וַ⁠יְקִאֶ֑⁠נּוּ מִ֝⁠בִּטְנ֗⁠וֹ יוֹרִשֶׁ֥⁠נּוּ אֵֽל׃","ẖa֣yil bá֭̇laʻ wa⁠yĕqiʼe֑⁠ṅẇ mi֝⁠bi̇tĕn֗⁠wò ywòrişě֥⁠ṅẇ ʼéֽl׃"],[20,16,"רֹאשׁ־פְּתָנִ֥ים יִינָ֑ק תַּֽ֝הַרְגֵ֗⁠הוּ לְשׁ֣וֹן אֶפְעֶֽה׃","ròʼş̌-pĕ̇ţáni֥ym yiyná֑q ţȧֽ֝harĕgé֗⁠hẇ lĕş֣̌wòn ʼepĕʻeֽh׃"],[20,17,"אַל־יֵ֥רֶא בִ⁠פְלַגּ֑וֹת נַהֲרֵ֥י נַ֝חֲלֵ֗י דְּבַ֣שׁ וְ⁠חֶמְאָֽה׃","ʼal-yé֥reʼ bi⁠pĕlaġ֑wòţ nahàré֥y na֝ẖàlé֗y dĕ̇ba֣ş̌ wĕ⁠ẖemĕʼáֽh׃"],[20,18,"מֵשִׁ֣יב יָ֭גָע וְ⁠לֹ֣א יִבְלָ֑ע כְּ⁠חֵ֥יל תְּ֝מוּרָת֗⁠וֹ וְ⁠לֹ֣א יַעֲלֹֽס׃","méşǐ֣yb yá֭gáʻ wĕ⁠lò֣ʼ yibĕlá֑ʻ kĕ̇⁠ẖé֥yl ţĕ̇֝mẇráţ֗⁠wò wĕ⁠lò֣ʼ yaʻàlòֽs׃"],[20,19,"כִּֽי־רִ֭צַּץ עָזַ֣ב דַּלִּ֑ים בַּ֥יִת גָּ֝זַ֗ל וְ⁠לֹ֣א יִבֶנֵֽ⁠הוּ׃","kiֽ̇y-ri֭ẕȧẕ ʻáza֣b dȧli֑̇ym bȧ֥yiţ gá̇֝za֗l wĕ⁠lò֣ʼ yibenéֽ⁠hẇ׃"],[20,20,"כִּ֤י ׀ לֹא־יָדַ֣ע שָׁלֵ֣ו בְּ⁠בִטְנ֑⁠וֹ בַּ֝⁠חֲמוּד֗⁠וֹ לֹ֣א יְמַלֵּֽט׃","ki֤̇y ׀ lòʼ-yáda֣ʻ şá̌lé֣w bĕ̇⁠bitĕn֑⁠wò bȧ֝⁠ẖàmẇd֗⁠wò lò֣ʼ yĕmaléֽ̇t׃"],[20,21,"אֵין־שָׂרִ֥יד לְ⁠אָכְל֑⁠וֹ עַל־כֵּ֝֗ן לֹא־יָחִ֥יל טוּבֽ⁠וֹ׃","ʼéyn-şá̂ri֥yd lĕ⁠ʼákĕl֑⁠wò ʻal-ké̇֝֗n lòʼ-yáẖi֥yl tẇbֽ⁠wò׃"],[20,22,"בִּ⁠מְלֹ֣אות שִׂ֭פְק⁠וֹ יֵ֣צֶר ל֑⁠וֹ כָּל־יַ֖ד עָמֵ֣ל תְּבוֹאֶֽ⁠נּוּ׃","bi̇⁠mĕlò֣ʼwţ şî֭pĕq⁠wò yé֣ẕer l֑⁠wò ká̇l-ya֖d ʻámé֣l ţĕ̇bwòʼeֽ⁠ṅẇ׃"],[20,23,"יְהִ֤י ׀ לְ⁠מַלֵּ֬א בִטְנ֗⁠וֹ יְֽשַׁלַּח־בּ֭⁠וֹ חֲר֣וֹן אַפּ֑⁠וֹ וְ⁠יַמְטֵ֥ר עָ֝לֵ֗י⁠מוֹ בִּ⁠לְחוּמֽ⁠וֹ׃","yĕhi֤y ׀ lĕ⁠malé̇֬ʼ bitĕn֗⁠wò yĕֽşǎlȧẖ-ḃ֭⁠wò ẖàr֣wòn ʼaṗ֑⁠wò wĕ⁠yamĕté֥r ʻá֝lé֗y⁠mwò bi̇⁠lĕẖẇmֽ⁠wò׃"],[20,24,"יִ֭בְרַח מִ⁠נֵּ֣שֶׁק בַּרְזֶ֑ל תַּ֝חְלְפֵ֗⁠הוּ קֶ֣שֶׁת נְחוּשָֽׁה׃","yi֭bĕraẖ mi⁠né֣̇şěq bȧrĕze֑l ţȧ֝ẖĕlĕpé֗⁠hẇ qe֣şěţ nĕẖẇşáֽ̌h׃"],[20,25,"שָׁלַף֮ וַ⁠יֵּצֵ֪א מִ⁠גֵּ֫וָ֥ה וּ֭⁠בָרָק מִֽ⁠מְּרֹרָת֥⁠וֹ יַהֲלֹ֗ךְ עָלָ֥י⁠ו אֵמִֽים׃","şá̌lap֮ wa⁠yé̇ẕé֪ʼ mi⁠gé̇֫wá֥h ẇ֭⁠báráq miֽ⁠mĕ̇ròráţ֥⁠wò yahàlò֗kĕ ʻálá֥y⁠w ʼémiֽym׃"],[20,26,"כָּל־חֹשֶׁךְ֮ טָמ֪וּן לִ⁠צְפּ֫וּנָ֥י⁠ו תְּ֭אָכְלֵ⁠הוּ אֵ֣שׁ לֹֽא־נֻפָּ֑ח יֵ֖רַע שָׂרִ֣יד בְּ⁠אָהֳלֽ⁠וֹ׃","ká̇l-ẖòşěkĕ֮ tám֪ẇn li⁠ẕĕṗ֫ẇná֥y⁠w ţĕ֭̇ʼákĕlé⁠hẇ ʼé֣ş̌ lòֽʼ-nupá֑̇ẖ yé֖raʻ şá̂ri֣yd bĕ̇⁠ʼáholֽ⁠wò׃"],[20,27,"יְגַלּ֣וּ שָׁמַ֣יִם עֲוֺנ֑⁠וֹ וְ֝⁠אֶ֗רֶץ מִתְקוֹמָ֘מָ֥ה לֽ⁠וֹ׃","yĕgal֣̇ẇ şá̌ma֣yim ʻàwֺn֑⁠wò wĕ֝⁠ʼe֗reẕ miţĕqwòmá֘má֥h lֽ⁠wò׃"],[20,28,"יִ֭גֶל יְב֣וּל בֵּית֑⁠וֹ נִ֝גָּר֗וֹת בְּ⁠י֣וֹם אַפּֽ⁠וֹ׃","yi֭gel yĕb֣ẇl bé̇yţ֑⁠wò ni֝gá̇r֗wòţ bĕ̇⁠y֣wòm ʼaṗֽ⁠wò׃"],[20,29,"זֶ֤ה ׀ חֵֽלֶק־אָדָ֣ם רָ֭שָׁע מֵ⁠אֱלֹהִ֑ים וְ⁠נַחֲלַ֖ת אִמְר֣⁠וֹ מֵ⁠אֵֽל׃פ","ze֤h ׀ ẖéֽleq-ʼádá֣m rá֭şá̌ʻ mé⁠ʼèlòhi֑ym wĕ⁠naẖàla֖ţ ʼimĕr֣⁠wò mé⁠ʼéֽl׃p"],[21,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[21,2,"שִׁמְע֣וּ שָׁ֭מוֹעַ מִלָּתִ֑⁠י וּ⁠תְהִי־זֹ֝֗את תַּנְח֥וּמֹֽתֵי⁠כֶֽם׃","şǐmĕʻ֣ẇ şá֭̌mwòʻa milá̇ţi֑⁠y ẇ⁠ţĕhiy-zò֝֗ʼţ ţȧnĕẖ֥ẇmòֽţéy⁠keֽm׃"],[21,3,"שָׂ֭אוּ⁠נִי וְ⁠אָנֹכִ֣י אֲדַבֵּ֑ר וְ⁠אַחַ֖ר דַּבְּרִ֣⁠י תַלְעִֽיג׃","şá֭̂ʼẇ⁠niy wĕ⁠ʼánòki֣y ʼàdabé֑̇r wĕ⁠ʼaẖa֖r dȧbĕ̇ri֣⁠y ţalĕʻiֽyg׃"],[21,4,"הֶ֭⁠אָנֹכִי לְ⁠אָדָ֣ם שִׂיחִ֑⁠י וְ⁠אִם־מַ֝דּ֗וּעַ לֹא־תִקְצַ֥ר רוּחִֽ⁠י׃","he֭⁠ʼánòkiy lĕ⁠ʼádá֣m şîyẖi֑⁠y wĕ⁠ʼim-ma֝ḋ֗ẇʻa lòʼ-ţiqĕẕa֥r rẇẖiֽ⁠y׃"],[21,5,"פְּנוּ־אֵלַ֥⁠י וְ⁠הָשַׁ֑מּוּ וְ⁠שִׂ֖ימוּ יָ֣ד עַל־פֶּֽה׃","pĕ̇nẇ-ʼéla֥⁠y wĕ⁠háşǎ֑ṁẇ wĕ⁠şî֖ymẇ yá֣d ʻal-pėֽh׃"],[21,6,"וְ⁠אִם־זָכַ֥רְתִּי וְ⁠נִבְהָ֑לְתִּי וְ⁠אָחַ֥ז בְּ֝שָׂרִ֗⁠י פַּלָּצֽוּת׃","wĕ⁠ʼim-záka֥rĕţi̇y wĕ⁠nibĕhá֑lĕţi̇y wĕ⁠ʼáẖa֥z bĕ̇֝şá̂ri֗⁠y pȧlá̇ẕֽẇţ׃"],[21,7,"מַדּ֣וּעַ רְשָׁעִ֣ים יִחְי֑וּ עָ֝תְק֗וּ גַּם־גָּ֥בְרוּ חָֽיִל׃","maḋ֣ẇʻa rĕşá̌ʻi֣ym yiẖĕy֑ẇ ʻá֝ţĕq֗ẇ gȧm-gá֥̇bĕrẇ ẖáֽyil׃"],[21,8,"זַרְעָ֤⁠ם נָכ֣וֹן לִ⁠פְנֵי⁠הֶ֣ם עִמָּ֑⁠ם וְ֝⁠צֶאֱצָאֵי⁠הֶ֗ם לְ⁠עֵינֵי⁠הֶֽם׃","zarĕʻá֤⁠m nák֣wòn li⁠pĕnéy⁠he֣m ʻimá֑̇⁠m wĕ֝⁠ẕeʼèẕáʼéy⁠he֗m lĕ⁠ʻéynéy⁠heֽm׃"],[21,9,"בָּתֵּי⁠הֶ֣ם שָׁל֣וֹם מִ⁠פָּ֑חַד וְ⁠לֹ֤א שֵׁ֖בֶט אֱל֣וֹהַּ עֲלֵי⁠הֶֽם׃","bá̇ţé̇y⁠he֣m şá̌l֣wòm mi⁠pá֑̇ẖad wĕ⁠lò֤ʼ şé֖̌bet ʼèl֣wòhȧ ʻàléy⁠heֽm׃"],[21,10,"שׁוֹר֣⁠וֹ עִ֭בַּר וְ⁠לֹ֣א יַגְעִ֑ל תְּפַלֵּ֥ט פָּ֝רָת֗⁠וֹ וְ⁠לֹ֣א תְשַׁכֵּֽל׃","ş̌wòr֣⁠wò ʻi֭bȧr wĕ⁠lò֣ʼ yagĕʻi֑l ţĕ̇palé֥̇t pá̇֝ráţ֗⁠wò wĕ⁠lò֣ʼ ţĕşǎkéֽ̇l׃"],[21,11,"יְשַׁלְּח֣וּ כַ֭⁠צֹּאן עֲוִילֵי⁠הֶ֑ם וְ֝⁠יַלְדֵי⁠הֶ֗ם יְרַקֵּדֽוּ⁠ן׃","yĕşǎlĕ̇ẖ֣ẇ ka֭⁠ẕò̇ʼn ʻàwiyléy⁠he֑m wĕ֝⁠yalĕdéy⁠he֗m yĕraqé̇dֽẇ⁠n׃"],[21,12,"יִ֭שְׂאוּ כְּ⁠תֹ֣ף וְ⁠כִנּ֑וֹר וְ֝⁠יִשְׂמְח֗וּ לְ⁠ק֣וֹל עוּגָֽב׃","yi֭şĕ̂ʼẇ kĕ̇⁠ţò֣p wĕ⁠kiṅ֑wòr wĕ֝⁠yişĕ̂mĕẖ֗ẇ lĕ⁠q֣wòl ʻẇgáֽb׃"],[21,13,"יבלו בַ⁠טּ֣וֹב יְמֵי⁠הֶ֑ם וּ֝⁠בְ⁠רֶ֗גַע שְׁא֣וֹל יֵחָֽתּוּ׃","yblw ba⁠ṫ֣wòb yĕméy⁠he֑m ẇ֝⁠bĕ⁠re֗gaʻ şĕ̌ʼ֣wòl yéẖáֽţ̇ẇ׃"],[21,14,"וַ⁠יֹּאמְר֣וּ לָ֭⁠אֵל ס֣וּר מִמֶּ֑⁠נּוּ וְ⁠דַ֥עַת דְּ֝רָכֶ֗י⁠ךָ לֹ֣א חָפָֽצְנוּ׃","wa⁠yò̇ʼmĕr֣ẇ lá֭⁠ʼél s֣ẇr mimė֑⁠ṅẇ wĕ⁠da֥ʻaţ dĕ̇֝ráke֗y⁠ká lò֣ʼ ẖápáֽẕĕnẇ׃"],[21,15,"מַה־שַׁדַּ֥י כִּֽי־נַֽעַבְדֶ֑⁠נּוּ וּ⁠מַה־נּ֝וֹעִ֗יל כִּ֣י נִפְגַּע־בּֽ⁠וֹ׃","mah-şǎdȧ֥y kiֽ̇y-naֽʻabĕde֑⁠ṅẇ ẇ⁠mah-ṅ֝wòʻi֗yl ki֣̇y nipĕgȧʻ-ḃֽ⁠wò׃"],[21,16,"הֵ֤ן לֹ֣א בְ⁠יָדָ֣⁠ם טוּבָ֑⁠ם עֲצַ֥ת רְ֝שָׁעִ֗ים רָ֣חֲקָה מֶֽ⁠נִּי׃","hé֤n lò֣ʼ bĕ⁠yádá֣⁠m tẇbá֑⁠m ʻàẕa֥ţ rĕ֝şá̌ʻi֗ym rá֣ẖàqáh meֽ⁠ni̇y׃"],[21,17,"כַּ⁠מָּ֤ה ׀ נֵר־רְשָׁ֘עִ֤ים יִדְעָ֗ךְ וְ⁠יָבֹ֣א עָלֵ֣י⁠מוֹ אֵידָ֑⁠ם חֲ֝בָלִ֗ים יְחַלֵּ֥ק בְּ⁠אַפּֽ⁠וֹ׃","kȧ⁠má֤̇h ׀ nér-rĕşá̌֘ʻi֤ym yidĕʻá֗kĕ wĕ⁠yábò֣ʼ ʻálé֣y⁠mwò ʼéydá֑⁠m ẖà֝báli֗ym yĕẖalé֥̇q bĕ̇⁠ʼaṗֽ⁠wò׃"],[21,18,"יִהְי֗וּ כְּ⁠תֶ֥בֶן לִ⁠פְנֵי־ר֑וּחַ וּ֝⁠כְ⁠מֹ֗ץ גְּנָבַ֥תּ⁠וּ סוּפָֽה׃","yihĕy֗ẇ kĕ̇⁠ţe֥ben li⁠pĕnéy-r֑ẇẖa ẇ֝⁠kĕ⁠mò֗ẕ gĕ̇nába֥ţ̇⁠ẇ sẇpáֽh׃"],[21,19,"אֱל֗וֹהַּ יִצְפֹּן־לְ⁠בָנָ֥י⁠ו אוֹנ֑⁠וֹ יְשַׁלֵּ֖ם אֵלָ֣י⁠ו וְ⁠יֵדָֽע׃","ʼèl֗wòhȧ yiẕĕpò̇n-lĕ⁠báná֥y⁠w ʼwòn֑⁠wò yĕşǎlé֖̇m ʼélá֣y⁠w wĕ⁠yédáֽʻ׃"],[21,20,"יִרְא֣וּ עינ⁠ו כִּיד֑⁠וֹ וּ⁠מֵ⁠חֲמַ֖ת שַׁדַּ֣י יִשְׁתֶּֽה׃","yirĕʼ֣ẇ ʻyn⁠w ki̇yd֑⁠wò ẇ⁠mé⁠ẖàma֖ţ şǎdȧ֣y yişĕ̌ţėֽh׃"],[21,21,"כִּ֤י מַה־חֶפְצ֣⁠וֹ בְּ⁠בֵית֣⁠וֹ אַחֲרָ֑י⁠ו וּ⁠מִסְפַּ֖ר חֳדָשָׁ֣י⁠ו חֻצָּֽצוּ׃","ki֤̇y mah-ẖepĕẕ֣⁠wò bĕ̇⁠béyţ֣⁠wò ʼaẖàrá֑y⁠w ẇ⁠misĕpȧ֖r ẖodáşá֣̌y⁠w ẖuẕáֽ̇ẕẇ׃"],[21,22,"הַ⁠לְ⁠אֵ֥ל יְלַמֶּד־דָּ֑עַת וְ֝⁠ה֗וּא רָמִ֥ים יִשְׁפּֽוֹט׃","ha⁠lĕ⁠ʼé֥l yĕlamėd-dá֑̇ʻaţ wĕ֝⁠h֗ẇʼ rámi֥ym yişĕ̌ṗֽwòt׃"],[21,23,"זֶ֗ה יָ֭מוּת בְּ⁠עֶ֣צֶם תֻּמּ֑⁠וֹ כֻּ֝לּ֗⁠וֹ שַׁלְאֲנַ֥ן וְ⁠שָׁלֵֽיו׃","ze֗h yá֭mẇţ bĕ̇⁠ʻe֣ẕem ţu̇ṁ֑⁠wò ku̇֝l̇֗⁠wò şǎlĕʼàna֥n wĕ⁠şá̌léֽyw׃"],[21,24,"עֲ֭טִינָי⁠ו מָלְא֣וּ חָלָ֑ב וּ⁠מֹ֖חַ עַצְמוֹתָ֣י⁠ו יְשֻׁקֶּֽה׃","ʻà֭tiynáy⁠w málĕʼ֣ẇ ẖálá֑b ẇ⁠mò֖ẖa ʻaẕĕmwòţá֣y⁠w yĕşǔqėֽh׃"],[21,25,"וְ⁠זֶ֗ה יָ֭מוּת בְּ⁠נֶ֣פֶשׁ מָרָ֑ה וְ⁠לֹֽא־אָ֝כַ֗ל בַּ⁠טּוֹבָֽה׃","wĕ⁠ze֗h yá֭mẇţ bĕ̇⁠ne֣peş̌ márá֑h wĕ⁠lòֽʼ-ʼá֝ka֗l bȧ⁠ṫwòbáֽh׃"],[21,26,"יַ֭חַד עַל־עָפָ֣ר יִשְׁכָּ֑בוּ וְ֝⁠רִמָּ֗ה תְּכַסֶּ֥ה עֲלֵי⁠הֶֽם׃","ya֭ẖad ʻal-ʻápá֣r yişĕ̌ká֑̇bẇ wĕ֝⁠rimá̇֗h ţĕ̇kasė֥h ʻàléy⁠heֽm׃"],[21,27,"הֵ֣ן יָ֭דַעְתִּי מַחְשְׁבֽוֹתֵי⁠כֶ֑ם וּ֝⁠מְזִמּ֗וֹת עָלַ֥⁠י תַּחְמֹֽסוּ׃","hé֣n yá֭daʻĕţi̇y maẖĕşĕ̌bֽwòţéy⁠ke֑m ẇ֝⁠mĕziṁ֗wòţ ʻála֥⁠y ţȧẖĕmòֽsẇ׃"],[21,28,"כִּ֤י תֹֽאמְר֗וּ אַיֵּ֥ה בֵית־נָדִ֑יב וְ֝⁠אַיֵּ֗ה אֹ֤הֶל ׀ מִשְׁכְּנ֬וֹת רְשָׁעִֽים׃","ki֤̇y ţòֽʼmĕr֗ẇ ʼayé֥̇h béyţ-nádi֑yb wĕ֝⁠ʼayé̇֗h ʼò֤hel ׀ mişĕ̌kĕ̇n֬wòţ rĕşá̌ʻiֽym׃"],[21,29,"הֲ⁠לֹ֣א שְׁ֭אֶלְתֶּם ע֣וֹבְרֵי דָ֑רֶךְ וְ֝⁠אֹתֹתָ֗⁠ם לֹ֣א תְנַכֵּֽרוּ׃","hà⁠lò֣ʼ şĕ֭̌ʼelĕţėm ʻ֣wòbĕréy dá֑rekĕ wĕ֝⁠ʼòţòţá֗⁠m lò֣ʼ ţĕnakéֽ̇rẇ׃"],[21,30,"כִּ֤י לְ⁠י֣וֹם אֵ֭יד יֵחָ֣שֶׂךְ רָ֑ע לְ⁠י֖וֹם עֲבָר֣וֹת יוּבָֽלוּ׃","ki֤̇y lĕ⁠y֣wòm ʼé֭yd yéẖá֣şêkĕ rá֑ʻ lĕ⁠y֖wòm ʻàbár֣wòţ yẇbáֽlẇ׃"],[21,31,"מִֽי־יַגִּ֣יד עַל־פָּנָ֣י⁠ו דַּרְכּ֑⁠וֹ וְ⁠הֽוּא־עָ֝שָׂ֗ה מִ֣י יְשַׁלֶּם־לֽ⁠וֹ׃","miֽy-yagi֣̇yd ʻal-pá̇ná֣y⁠w dȧrĕk֑̇⁠wò wĕ⁠hֽẇʼ-ʻá֝şá̂֗h mi֣y yĕşǎlėm-lֽ⁠wò׃"],[21,32,"וְ֭⁠הוּא לִ⁠קְבָר֣וֹת יוּבָ֑ל וְֽ⁠עַל־גָּדִ֥ישׁ יִשְׁקֽוֹד׃","wĕ֭⁠hẇʼ li⁠qĕbár֣wòţ yẇbá֑l wĕֽ⁠ʻal-gá̇di֥yş̌ yişĕ̌qֽwòd׃"],[21,33,"מָֽתְקוּ־ל֗⁠וֹ רִגְבֵ֫י נָ֥חַל וְ֭⁠אַחֲרָי⁠ו כָּל־אָדָ֣ם יִמְשׁ֑וֹךְ וּ֝⁠לְ⁠פָנָ֗י⁠ו אֵ֣ין מִסְפָּֽר׃","máֽţĕqẇ-l֗⁠wò rigĕbé֫y ná֥ẖal wĕ֭⁠ʼaẖàráy⁠w ká̇l-ʼádá֣m yimĕş֑̌wòkĕ ẇ֝⁠lĕ⁠páná֗y⁠w ʼé֣yn misĕpáֽ̇r׃"],[21,34,"וְ֭⁠אֵיךְ תְּנַחֲמ֣וּ⁠נִי הָ֑בֶל וּ֝⁠תְשֽׁוּבֹתֵי⁠כֶ֗ם נִשְׁאַר־מָֽעַל׃ס","wĕ֭⁠ʼéykĕ ţĕ̇naẖàm֣ẇ⁠niy há֑bel ẇ֝⁠ţĕşֽ̌ẇbòţéy⁠ke֗m nişĕ̌ʼar-máֽʻal׃s"],[22,1,"וַ֭⁠יַּעַן אֱלִיפַ֥ז הַֽ⁠תֵּמָנִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan ʼèliypa֥z haֽ⁠ţé̇máni֗y wa⁠yò̇ʼmaֽr׃"],[22,2,"הַ⁠לְ⁠אֵ֥ל יִסְכָּן־גָּ֑בֶר כִּֽי־יִסְכֹּ֖ן עָלֵ֣י⁠מוֹ מַשְׂכִּֽיל׃","ha⁠lĕ⁠ʼé֥l yisĕká̇n-gá֑̇ber kiֽ̇y-yisĕkò֖̇n ʻálé֣y⁠mwò maşĕ̂kiֽ̇yl׃"],[22,3,"הַ⁠חֵ֣פֶץ לְ֭⁠שַׁדַּי כִּ֣י תִצְדָּ֑ק וְ⁠אִם־בֶּ֝֗צַע כִּֽי־תַתֵּ֥ם דְּרָכֶֽי⁠ךָ׃","ha⁠ẖé֣peẕ lĕ֭⁠şǎdȧy ki֣̇y ţiẕĕdá֑̇q wĕ⁠ʼim-bė֝֗ẕaʻ kiֽ̇y-ţaţé֥̇m dĕ̇rákeֽy⁠ká׃"],[22,4,"הֲֽ֭⁠מִ⁠יִּרְאָ֣תְ⁠ךָ יֹכִיחֶ֑⁠ךָ יָב֥וֹא עִ֝מְּ⁠ךָ֗ בַּ⁠מִּשְׁפָּֽט׃","hàֽ֭⁠mi⁠yi̇rĕʼá֣ţĕ⁠ká yòkiyẖe֑⁠ká yáb֥wòʼ ʻi֝mĕ̇⁠ká֗ bȧ⁠mi̇şĕ̌páֽ̇t׃"],[22,5,"הֲ⁠לֹ֣א רָעָֽתְ⁠ךָ֣ רַבָּ֑ה וְ⁠אֵֽין־קֵ֝֗ץ לַ⁠עֲוֺנֹתֶֽי⁠ךָ׃","hà⁠lò֣ʼ ráʻáֽţĕ⁠ká֣ rabá֑̇h wĕ⁠ʼéֽyn-qé֝֗ẕ la⁠ʻàwֺnòţeֽy⁠ká׃"],[22,6,"כִּֽי־תַחְבֹּ֣ל אַחֶ֣י⁠ךָ חִנָּ֑ם וּ⁠בִגְדֵ֖י עֲרוּמִּ֣ים תַּפְשִֽׁיט׃","kiֽ̇y-ţaẖĕbò֣̇l ʼaẖe֣y⁠ká ẖiná֑̇m ẇ⁠bigĕdé֖y ʻàrẇmi֣̇ym ţȧpĕşǐֽyt׃"],[22,7,"לֹא־מַ֭יִם עָיֵ֣ף תַּשְׁקֶ֑ה וּ֝⁠מֵ⁠רָעֵ֗ב תִּֽמְנַֽע־לָֽחֶם׃","lòʼ-ma֭yim ʻáyé֣p ţȧşĕ̌qe֑h ẇ֝⁠mé⁠ráʻé֗b ţiֽ̇mĕnaֽʻ-láֽẖem׃"],[22,8,"וְ⁠אִ֣ישׁ זְ֭רוֹעַ ל֣⁠וֹ הָ⁠אָ֑רֶץ וּ⁠נְשׂ֥וּא פָ֝נִ֗ים יֵ֣שֶׁב בָּֽ⁠הּ׃","wĕ⁠ʼi֣yş̌ zĕ֭rwòʻa l֣⁠wò há⁠ʼá֑reẕ ẇ⁠nĕş֥̂ẇʼ pá֝ni֗ym yé֣şěb báֽ̇⁠ḣ׃"],[22,9,"אַ֭לְמָנוֹת שִׁלַּ֣חְתָּ רֵיקָ֑ם וּ⁠זְרֹע֖וֹת יְתֹמִ֣ים יְדֻכָּֽא׃","ʼa֭lĕmánwòţ şǐlȧ֣ẖĕţá̇ réyqá֑m ẇ⁠zĕròʻ֖wòţ yĕţòmi֣ym yĕdukáֽ̇ʼ׃"],[22,10,"עַל־כֵּ֭ן סְבִיבוֹתֶ֣י⁠ךָ פַחִ֑ים וִֽ֝⁠יבַהֶלְ⁠ךָ פַּ֣חַד פִּתְאֹֽם׃","ʻal-ké֭̇n sĕbiybwòţe֣y⁠ká paẖi֑ym wiֽ֝⁠ybahelĕ⁠ká pȧ֣ẖad pi̇ţĕʼòֽm׃"],[22,11,"אוֹ־חֹ֥שֶׁךְ לֹֽא־תִרְאֶ֑ה וְֽ⁠שִׁפְעַת־מַ֥יִם תְּכַסֶּֽ⁠ךָּ׃","ʼwò-ẖò֥şěkĕ lòֽʼ-ţirĕʼe֑h wĕֽ⁠şǐpĕʻaţ-ma֥yim ţĕ̇kasėֽ⁠ká̇׃"],[22,12,"הֲֽ⁠לֹא־אֱ֭לוֹהַּ גֹּ֣בַהּ שָׁמָ֑יִם וּ⁠רְאֵ֤ה רֹ֖אשׁ כּוֹכָבִ֣ים כִּי־רָֽמּוּ׃","hàֽ⁠lòʼ-ʼè֭lwòhȧ gò֣̇baḣ şá̌má֑yim ẇ⁠rĕʼé֤h rò֖ʼş̌ k̇wòkábi֣ym ki̇y-ráֽṁẇ׃"],[22,13,"וְֽ֭⁠אָמַרְתָּ מַה־יָּ֣דַֽע אֵ֑ל הַ⁠בְעַ֖ד עֲרָפֶ֣ל יִשְׁפּֽוֹט׃","wĕֽ֭⁠ʼámarĕţá̇ mah-yá֣̇daֽʻ ʼé֑l ha⁠bĕʻa֖d ʻàrápe֣l yişĕ̌ṗֽwòt׃"],[22,14,"עָבִ֣ים סֵֽתֶר־ל֭⁠וֹ וְ⁠לֹ֣א יִרְאֶ֑ה וְ⁠ח֥וּג שָׁ֝מַ֗יִם יִתְהַלָּֽךְ׃","ʻábi֣ym séֽţer-l֭⁠wò wĕ⁠lò֣ʼ yirĕʼe֑h wĕ⁠ẖ֥ẇg şá̌֝ma֗yim yiţĕhaláֽ̇kĕ׃"],[22,15,"הַ⁠אֹ֣רַח עוֹלָ֣ם תִּשְׁמֹ֑ר אֲשֶׁ֖ר דָּרְכ֣וּ מְתֵי־אָֽוֶן׃","ha⁠ʼò֣raẖ ʻwòlá֣m ţi̇şĕ̌mò֑r ʼàşě֖r dá̇rĕk֣ẇ mĕţéy-ʼáֽwen׃"],[22,16,"אֲשֶֽׁר־קֻמְּט֥וּ וְ⁠לֹא־עֵ֑ת נָ֝הָ֗ר יוּצַ֥ק יְסוֹדָֽ⁠ם׃","ʼàşěֽr-qumĕ̇t֥ẇ wĕ⁠lòʼ-ʻé֑ţ ná֝há֗r yẇẕa֥q yĕswòdáֽ⁠m׃"],[22,17,"הָ⁠אֹמְרִ֣ים לָ֭⁠אֵל ס֣וּר מִמֶּ֑⁠נּוּ וּ⁠מַה־יִּפְעַ֖ל שַׁדַּ֣י לָֽ⁠מוֹ׃","há⁠ʼòmĕri֣ym lá֭⁠ʼél s֣ẇr mimė֑⁠ṅẇ ẇ⁠mah-yi̇pĕʻa֖l şǎdȧ֣y láֽ⁠mwò׃"],[22,18,"וְ⁠ה֤וּא מִלֵּ֣א בָתֵּי⁠הֶ֣ם ט֑וֹב וַ⁠עֲצַ֥ת רְ֝שָׁעִ֗ים רָ֣חֲקָה מֶֽ⁠נִּי׃","wĕ⁠h֤ẇʼ milé֣̇ʼ báţé̇y⁠he֣m t֑wòb wa⁠ʻàẕa֥ţ rĕ֝şá̌ʻi֗ym rá֣ẖàqáh meֽ⁠ni̇y׃"],[22,19,"יִרְא֣וּ צַדִּיקִ֣ים וְ⁠יִשְׂמָ֑חוּ וְ֝⁠נָקִ֗י יִלְעַג־לָֽ⁠מוֹ׃","yirĕʼ֣ẇ ẕadi̇yqi֣ym wĕ⁠yişĕ̂má֑ẖẇ wĕ֝⁠náqi֗y yilĕʻag-láֽ⁠mwò׃"],[22,20,"אִם־לֹ֣א נִכְחַ֣ד קִימָ֑⁠נוּ וְ֝⁠יִתְרָ֗⁠ם אָ֣כְלָה אֵֽשׁ׃","ʼim-lò֣ʼ nikĕẖa֣d qiymá֑⁠nẇ wĕ֝⁠yiţĕrá֗⁠m ʼá֣kĕláh ʼéֽş̌׃"],[22,21,"הַסְכֶּן־נָ֣א עִמּ֑⁠וֹ וּ⁠שְׁלם בָּ֝⁠הֶ֗ם תְּֽבוֹאַתְ⁠ךָ֥ טוֹבָֽה׃","hasĕkėn-ná֣ʼ ʻiṁ֑⁠wò ẇ⁠şĕ̌lm bá̇֝⁠he֗m ţĕֽ̇bwòʼaţĕ⁠ká֥ twòbáֽh׃"],[22,22,"קַח־נָ֣א מִ⁠פִּ֣י⁠ו תּוֹרָ֑ה וְ⁠שִׂ֥ים אֲ֝מָרָ֗י⁠ו בִּ⁠לְבָבֶֽ⁠ךָ׃","qaẖ-ná֣ʼ mi⁠pi֣̇y⁠w ţ̇wòrá֑h wĕ⁠şî֥ym ʼà֝márá֗y⁠w bi̇⁠lĕbábeֽ⁠ká׃"],[22,23,"אִם־תָּשׁ֣וּב עַד־שַׁ֭דַּי תִּבָּנֶ֑ה תַּרְחִ֥יק עַ֝וְלָ֗ה מֵ⁠אָהֳלֶֽ⁠ךָ׃","ʼim-ţá̇ş֣̌ẇb ʻad-şǎ֭dȧy ţi̇bá̇ne֑h ţȧrĕẖi֥yq ʻa֝wĕlá֗h mé⁠ʼáholeֽ⁠ká׃"],[22,24,"וְ⁠שִׁית־עַל־עָפָ֥ר בָּ֑צֶר וּ⁠בְ⁠צ֖וּר נְחָלִ֣ים אוֹפִֽיר׃","wĕ⁠şǐyţ-ʻal-ʻápá֥r bá֑̇ẕer ẇ⁠bĕ⁠ẕ֖ẇr nĕẖáli֣ym ʼwòpiֽyr׃"],[22,25,"וְ⁠הָיָ֣ה שַׁדַּ֣י בְּצָרֶ֑י⁠ךָ וְ⁠כֶ֖סֶף תּוֹעָפ֣וֹת לָֽ⁠ךְ׃","wĕ⁠háyá֣h şǎdȧ֣y bĕ̇ẕáre֑y⁠ká wĕ⁠ke֖sep ţ̇wòʻáp֣wòţ láֽ⁠kĕ׃"],[22,26,"כִּי־אָ֭ז עַל־שַׁדַּ֣י תִּתְעַנָּ֑ג וְ⁠תִשָּׂ֖א אֶל־אֱל֣וֹהַּ פָּנֶֽי⁠ךָ׃","ki̇y-ʼá֭z ʻal-şǎdȧ֣y ţi̇ţĕʻaná֑̇g wĕ⁠ţişá֖̇̂ʼ ʼel-ʼèl֣wòhȧ pá̇neֽy⁠ká׃"],[22,27,"תַּעְתִּ֣יר אֵ֭לָי⁠ו וְ⁠יִשְׁמָעֶ֑⁠ךָּ וּ⁠נְדָרֶ֥י⁠ךָ תְשַׁלֵּֽם׃","ţȧʻĕţi֣̇yr ʼé֭láy⁠w wĕ⁠yişĕ̌máʻe֑⁠ká̇ ẇ⁠nĕdáre֥y⁠ká ţĕşǎléֽ̇m׃"],[22,28,"וְֽ⁠תִגְזַר־א֭וֹמֶר וְ⁠יָ֣קָם לָ֑⁠ךְ וְ⁠עַל־דְּ֝רָכֶ֗י⁠ךָ נָ֣גַֽהּ אֽוֹר׃","wĕֽ⁠ţigĕzar-ʼ֭wòmer wĕ⁠yá֣qám lá֑⁠kĕ wĕ⁠ʻal-dĕ̇֝ráke֗y⁠ká ná֣gaֽḣ ʼֽwòr׃"],[22,29,"כִּֽי־הִ֭שְׁפִּילוּ וַ⁠תֹּ֣אמֶר גֵּוָ֑ה וְ⁠שַׁ֖ח עֵינַ֣יִם יוֹשִֽׁעַ׃","kiֽ̇y-hi֭şĕ̌pi̇ylẇ wa⁠ţò֣̇ʼmer gé̇wá֑h wĕ⁠şǎ֖ẖ ʻéyna֣yim ywòşǐֽʻa׃"],[22,30,"יְֽמַלֵּ֥ט אִֽי־נָקִ֑י וְ֝⁠נִמְלַ֗ט בְּ⁠בֹ֣ר כַּפֶּֽי⁠ךָ׃פ","yֽĕmalé֥̇t ʼiֽy-náqi֑y wĕ֝⁠nimĕla֗t bĕ̇⁠bò֣r kȧpėֽy⁠ká׃p"],[23,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[23,2,"גַּם־הַ֭⁠יּוֹם מְרִ֣י שִׂחִ֑⁠י יָ֝דִ֗⁠י כָּבְדָ֥ה עַל־אַנְחָתִֽ⁠י׃","gȧm-ha֭⁠ẏwòm mĕri֣y şîẖi֑⁠y yá֝di֗⁠y ká̇bĕdá֥h ʻal-ʼanĕẖáţiֽ⁠y׃"],[23,3,"מִֽי־יִתֵּ֣ן יָ֭דַעְתִּי וְ⁠אֶמְצָאֵ֑⁠הוּ אָ֝ב֗וֹא עַד־תְּכוּנָתֽ⁠וֹ׃","miֽy-yiţé֣̇n yá֭daʻĕţi̇y wĕ⁠ʼemĕẕáʼé֑⁠hẇ ʼá֝b֗wòʼ ʻad-ţĕ̇kẇnáţֽ⁠wò׃"],[23,4,"אֶעֶרְכָ֣ה לְ⁠פָנָ֣י⁠ו מִשְׁפָּ֑ט וּ֝⁠פִ֗⁠י אֲמַלֵּ֥א תוֹכָחֽוֹת׃","ʼeʻerĕká֣h lĕ⁠páná֣y⁠w mişĕ̌pá֑̇t ẇ֝⁠pi֗⁠y ʼàmalé֥̇ʼ ţwòkáẖֽwòţ׃"],[23,5,"אֵ֭דְעָה מִלִּ֣ים יַעֲנֵ֑⁠נִי וְ֝⁠אָבִ֗ינָה מַה־יֹּ֥אמַר לִֽ⁠י׃","ʼé֭dĕʻáh mili֣̇ym yaʻàné֑⁠niy wĕ֝⁠ʼábi֗ynáh mah-yò֥̇ʼmar liֽ⁠y׃"],[23,6,"הַ⁠בְּ⁠רָב־כֹּ֭חַ יָרִ֣יב עִמָּדִ֑⁠י לֹ֥א אַךְ־ה֝֗וּא יָשִׂ֥ם בִּֽ⁠י׃","ha⁠bĕ̇⁠ráb-kò֭̇ẖa yári֣yb ʻimá̇di֑⁠y lò֥ʼ ʼakĕ-h֝֗ẇʼ yáşî֥m biֽ̇⁠y׃"],[23,7,"שָׁ֗ם יָ֭שָׁר נוֹכָ֣ח עִמּ֑⁠וֹ וַ⁠אֲפַלְּטָ֥ה לָ֝⁠נֶ֗צַח מִ⁠שֹּׁפְטִֽ⁠י׃","şá̌֗m yá֭şá̌r nwòká֣ẖ ʻiṁ֑⁠wò wa⁠ʼàpalĕ̇tá֥h lá֝⁠ne֗ẕaẖ mi⁠şò̇̌pĕtiֽ⁠y׃"],[23,8,"הֵ֤ן קֶ֣דֶם אֶהֱלֹ֣ךְ וְ⁠אֵינֶ֑⁠נּוּ וְ֝⁠אָח֗וֹר וְֽ⁠לֹא־אָבִ֥ין לֽ⁠וֹ׃","hé֤n qe֣dem ʼehèlò֣kĕ wĕ⁠ʼéyne֑⁠ṅẇ wĕ֝⁠ʼáẖ֗wòr wĕֽ⁠lòʼ-ʼábi֥yn lֽ⁠wò׃"],[23,9,"שְׂמֹ֣אול בַּ⁠עֲשֹׂת֣⁠וֹ וְ⁠לֹא־אָ֑חַז יַעְטֹ֥ף יָ֝מִ֗ין וְ⁠לֹ֣א אֶרְאֶֽה׃","şĕ̂mò֣ʼwl bȧ⁠ʻàşò̂ţ֣⁠wò wĕ⁠lòʼ-ʼá֑ẖaz yaʻĕtò֥p yá֝mi֗yn wĕ⁠lò֣ʼ ʼerĕʼeֽh׃"],[23,10,"כִּֽי־יָ֭דַע דֶּ֣רֶךְ עִמָּדִ֑⁠י בְּ֝חָנַ֗⁠נִי כַּ⁠זָּהָ֥ב אֵצֵֽא׃","kiֽ̇y-yá֭daʻ dė֣rekĕ ʻimá̇di֑⁠y bĕ̇֝ẖána֗⁠niy kȧ⁠zá̇há֥b ʼéẕéֽʼ׃"],[23,11,"בַּ֭⁠אֲשֻׁר⁠וֹ אָחֲזָ֣ה רַגְלִ֑⁠י דַּרְכּ֖⁠וֹ שָׁמַ֣רְתִּי וְ⁠לֹא־אָֽט׃","bȧ֭⁠ʼàşǔr⁠wò ʼáẖàzá֣h ragĕli֑⁠y dȧrĕk֖̇⁠wò şá̌ma֣rĕţi̇y wĕ⁠lòʼ-ʼáֽt׃"],[23,12,"מִצְוַ֣ת שְׂ֭פָתָי⁠ו וְ⁠לֹ֣א אָמִ֑ישׁ מֵ֝⁠חֻקִּ֗⁠י צָפַ֥נְתִּי אִמְרֵי־פִֽי⁠ו׃","miẕĕwa֣ţ şĕ֭̂páţáy⁠w wĕ⁠lò֣ʼ ʼámi֑yş̌ mé֝⁠ẖuqi̇֗⁠y ẕápa֥nĕţi̇y ʼimĕréy-piֽy⁠w׃"],[23,13,"וְ⁠ה֣וּא בְ֭⁠אֶחָד וּ⁠מִ֣י יְשִׁיבֶ֑⁠נּוּ וְ⁠נַפְשׁ֖⁠וֹ אִוְּתָ֣ה וַ⁠יָּֽעַשׂ׃","wĕ⁠h֣ẇʼ bĕ֭⁠ʼeẖád ẇ⁠mi֣y yĕşǐybe֑⁠ṅẇ wĕ⁠napĕş֖̌⁠wò ʼiwĕ̇ţá֣h wa⁠yáֽ̇ʻaş̂׃"],[23,14,"כִּ֭י יַשְׁלִ֣ים חֻקִּ֑⁠י וְ⁠כָ⁠הֵ֖נָּה רַבּ֣וֹת עִמּֽ⁠וֹ׃","ki֭̇y yaşĕ̌li֣ym ẖuqi֑̇⁠y wĕ⁠ká⁠hé֖ná̇h raḃ֣wòţ ʻiṁֽ⁠wò׃"],[23,15,"עַל־כֵּ֭ן מִ⁠פָּנָ֣י⁠ו אֶבָּהֵ֑ל אֶ֝תְבּוֹנֵ֗ן וְ⁠אֶפְחַ֥ד מִמֶּֽ⁠נּוּ׃","ʻal-ké֭̇n mi⁠pá̇ná֣y⁠w ʼebá̇hé֑l ʼe֝ţĕḃwòné֗n wĕ⁠ʼepĕẖa֥d mimėֽ⁠ṅẇ׃"],[23,16,"וְ֭⁠אֵל הֵרַ֣ךְ לִבִּ֑⁠י וְ֝⁠שַׁדַּ֗י הִבְהִילָֽ⁠נִי׃","wĕ֭⁠ʼél héra֣kĕ libi֑̇⁠y wĕ֝⁠şǎdȧ֗y hibĕhiyláֽ⁠niy׃"],[23,17,"כִּֽי־לֹ֣א נִ֭צְמַתִּי מִ⁠פְּנֵי־חֹ֑שֶׁךְ וּ֝⁠מִ⁠פָּנַ֗⁠י כִּסָּה־אֹֽפֶל׃","kiֽ̇y-lò֣ʼ ni֭ẕĕmaţi̇y mi⁠pĕ̇néy-ẖò֑şěkĕ ẇ֝⁠mi⁠pá̇na֗⁠y ki̇sá̇h-ʼòֽpel׃"],[24,1,"מַדּ֗וּעַ מִ֭⁠שַּׁדַּי לֹא־נִצְפְּנ֣וּ עִתִּ֑ים ו⁠ידע⁠ו לֹא־חָ֥זוּ יָמָֽי⁠ו׃","maḋ֗ẇʻa mi֭⁠şȧ̌dȧy lòʼ-niẕĕpĕ̇n֣ẇ ʻiţi֑̇ym w⁠ydʻ⁠w lòʼ-ẖá֥zẇ yámáֽy⁠w׃"],[24,2,"גְּבֻל֥וֹת יַשִּׂ֑יגוּ עֵ֥דֶר גָּ֝זְל֗וּ וַ⁠יִּרְעֽוּ׃","gĕ̇bul֥wòţ yaşi֑̇̂ygẇ ʻé֥der gá̇֝zĕl֗ẇ wa⁠yi̇rĕʻֽẇ׃"],[24,3,"חֲמ֣וֹר יְתוֹמִ֣ים יִנְהָ֑גוּ יַ֝חְבְּל֗וּ שׁ֣וֹר אַלְמָנָֽה׃","ẖàm֣wòr yĕţwòmi֣ym yinĕhá֑gẇ ya֝ẖĕbĕ̇l֗ẇ ş֣̌wòr ʼalĕmánáֽh׃"],[24,4,"יַטּ֣וּ אֶבְיוֹנִ֣ים מִ⁠דָּ֑רֶךְ יַ֥חַד חֻ֝בְּא֗וּ עֲנִיֵּי־אָֽרֶץ׃","yaṫ֣ẇ ʼebĕywòni֣ym mi⁠dá֑̇rekĕ ya֥ẖad ẖu֝bĕ̇ʼ֗ẇ ʻàniyé̇y-ʼáֽreẕ׃"],[24,5,"הֵ֤ן פְּרָאִ֨ים ׀ בַּֽ⁠מִּדְבָּ֗ר יָצְא֣וּ בְּ֭⁠פָעֳלָ⁠ם מְשַׁחֲרֵ֣י לַ⁠טָּ֑רֶף עֲרָבָ֥ה ל֥⁠וֹ לֶ֝֗חֶם לַ⁠נְּעָרִֽים׃","hé֤n pĕ̇ráʼi֨ym ׀ bȧֽ⁠mi̇dĕbá̇֗r yáẕĕʼ֣ẇ bĕ֭̇⁠páʻolá⁠m mĕşǎẖàré֣y la⁠tá֑̇rep ʻàrábá֥h l֥⁠wò le֝֗ẖem la⁠nĕ̇ʻáriֽym׃"],[24,6,"בַּ֭⁠שָּׂדֶה בְּלִיל֣⁠וֹ יקצירו וְ⁠כֶ֖רֶם רָשָׁ֣ע יְלַקֵּֽשׁוּ׃","bȧ֭⁠şá̇̂deh bĕ̇liyl֣⁠wò yqẕyrw wĕ⁠ke֖rem ráşá֣̌ʻ yĕlaqéֽ̇ş̌ẇ׃"],[24,7,"עָר֣וֹם יָ֭לִינוּ מִ⁠בְּלִ֣י לְב֑וּשׁ וְ⁠אֵ֥ין כְּ֝ס֗וּת בַּ⁠קָּרָֽה׃","ʻár֣wòm yá֭liynẇ mi⁠bĕ̇li֣y lĕb֑ẇş̌ wĕ⁠ʼé֥yn kĕ̇֝s֗ẇţ bȧ⁠qá̇ráֽh׃"],[24,8,"מִ⁠זֶּ֣רֶם הָרִ֣ים יִרְטָ֑בוּ וּֽ⁠מִ⁠בְּלִ֥י מַ֝חְסֶ֗ה חִבְּקוּ־צֽוּר׃","mi⁠zė֣rem hári֣ym yirĕtá֑bẇ ẇֽ⁠mi⁠bĕ̇li֥y ma֝ẖĕse֗h ẖibĕ̇qẇ-ẕֽẇr׃"],[24,9,"יִ֭גְזְלוּ מִ⁠שֹּׁ֣ד יָת֑וֹם וְֽ⁠עַל־עָנִ֥י יַחְבֹּֽלוּ׃","yi֭gĕzĕlẇ mi⁠şò֣̇̌d yáţ֑wòm wĕֽ⁠ʻal-ʻáni֥y yaẖĕbòֽ̇lẇ׃"],[24,10,"עָר֣וֹם הִ֭לְּכוּ בְּלִ֣י לְב֑וּשׁ וּ֝⁠רְעֵבִ֗ים נָ֣שְׂאוּ עֹֽמֶר׃","ʻár֣wòm hi֭lĕ̇kẇ bĕ̇li֣y lĕb֑ẇş̌ ẇ֝⁠rĕʻébi֗ym ná֣şĕ̂ʼẇ ʻòֽmer׃"],[24,11,"בֵּין־שׁוּרֹתָ֥⁠ם יַצְהִ֑ירוּ יְקָבִ֥ים דָּ֝רְכ֗וּ וַ⁠יִּצְמָֽאוּ׃","bé̇yn-ş̌ẇròţá֥⁠m yaẕĕhi֑yrẇ yĕqábi֥ym dá̇֝rĕk֗ẇ wa⁠yi̇ẕĕmáֽʼẇ׃"],[24,12,"מֵ֘⁠עִ֤יר מְתִ֨ים ׀ יִנְאָ֗קוּ וְ⁠נֶֽפֶשׁ־חֲלָלִ֥ים תְּשַׁוֵּ֑עַ וֶ֝⁠אֱל֗וֹהַּ לֹא־יָשִׂ֥ים תִּפְלָֽה׃","mé֘⁠ʻi֤yr mĕţi֨ym ׀ yinĕʼá֗qẇ wĕ⁠neֽpeş̌-ẖàláli֥ym ţĕ̇şǎwé֑̇ʻa we֝⁠ʼèl֗wòhȧ lòʼ-yáşî֥ym ţi̇pĕláֽh׃"],[24,13,"הֵ֤מָּה ׀ הָיוּ֮ בְּֽ⁠מֹרְדֵ֫י־א֥וֹר לֹֽא־הִכִּ֥ירוּ דְרָכָ֑י⁠ו וְ⁠לֹ֥א יָ֝שְׁב֗וּ בִּ⁠נְתִיבֹתָֽי⁠ו׃","hé֤má̇h ׀ háyẇ֮ bĕֽ̇⁠mòrĕdé֫y-ʼ֥wòr lòֽʼ-hiki֥̇yrẇ dĕráká֑y⁠w wĕ⁠lò֥ʼ yá֝şĕ̌b֗ẇ bi̇⁠nĕţiybòţáֽy⁠w׃"],[24,14,"לָ⁠א֡וֹר יָ֘ק֤וּם רוֹצֵ֗חַ יִֽקְטָל־עָנִ֥י וְ⁠אֶבְי֑וֹן וּ֝⁠בַ⁠לַּ֗יְלָה יְהִ֣י כַ⁠גַּנָּֽב׃","lá⁠ʼ֡wòr yá֘q֤ẇm rwòẕé֗ẖa yiֽqĕtál-ʻáni֥y wĕ⁠ʼebĕy֑wòn ẇ֝⁠ba⁠lȧ֗yĕláh yĕhi֣y ka⁠gȧnáֽ̇b׃"],[24,15,"וְ⁠עֵ֤ין נֹאֵ֨ף ׀ שָׁ֤מְרָֽה נֶ֣שֶׁף לֵ֭⁠אמֹר לֹא־תְשׁוּרֵ֣⁠נִי עָ֑יִן וְ⁠סֵ֖תֶר פָּנִ֣ים יָשִֽׂים׃","wĕ⁠ʻé֤yn nòʼé֨p ׀ şá֤̌mĕráֽh ne֣şěp lé֭⁠ʼmòr lòʼ-ţĕş̌ẇré֣⁠niy ʻá֑yin wĕ⁠sé֖ţer pá̇ni֣ym yáşîֽym׃"],[24,16,"חָתַ֥ר בַּ⁠חֹ֗שֶׁךְ בָּ֫תִּ֥ים יוֹמָ֥ם חִתְּמוּ־לָ֗⁠מוֹ לֹא־יָ֥דְעוּ אֽוֹר׃","ẖáţa֥r bȧ⁠ẖò֗şěkĕ bá̇֫ţi֥̇ym ywòmá֥m ẖiţĕ̇mẇ-lá֗⁠mwò lòʼ-yá֥dĕʻẇ ʼֽwòr׃"],[24,17,"כִּ֤י יַחְדָּ֨ו ׀ בֹּ֣קֶר לָ֣⁠מוֹ צַלְמָ֑וֶת כִּֽי־יַ֝כִּ֗יר בַּלְה֥וֹת צַלְמָֽוֶת׃","ki֤̇y yaẖĕdá̇֨w ׀ bò֣̇qer lá֣⁠mwò ẕalĕmá֑weţ kiֽ̇y-ya֝ki̇֗yr bȧlĕh֥wòţ ẕalĕmáֽweţ׃"],[24,18,"קַֽל־ה֤וּא ׀ עַל־פְּנֵי־מַ֗יִם תְּקֻלַּ֣ל חֶלְקָתָ֣⁠ם בָּ⁠אָ֑רֶץ לֹֽא־יִ֝פְנֶה דֶּ֣רֶךְ כְּרָמִֽים׃","qaֽl-h֤ẇʼ ׀ ʻal-pĕ̇néy-ma֗yim ţĕ̇qulȧ֣l ẖelĕqáţá֣⁠m bá̇⁠ʼá֑reẕ lòֽʼ-yi֝pĕneh dė֣rekĕ kĕ̇rámiֽym׃"],[24,19,"צִיָּ֤ה גַם־חֹ֗ם יִגְזְל֥וּ מֵֽימֵי־שֶׁ֗לֶג שְׁא֣וֹל חָטָֽאוּ׃","ẕiyá֤̇h gam-ẖò֗m yigĕzĕl֥ẇ méֽyméy-şě֗leg şĕ̌ʼ֣wòl ẖátáֽʼẇ׃"],[24,20,"יִשְׁכָּ֘חֵ֤⁠הוּ רֶ֨חֶם ׀ מְתָ֘ק֤⁠וֹ רִמָּ֗ה ע֥וֹד לֹֽא־יִזָּכֵ֑ר וַ⁠תִּשָּׁבֵ֖ר כָּ⁠עֵ֣ץ עַוְלָֽה׃","yişĕ̌ká̇֘ẖé֤⁠hẇ re֨ẖem ׀ mĕţá֘q֤⁠wò rimá̇֗h ʻ֥wòd lòֽʼ-yizá̇ké֑r wa⁠ţi̇şá̇̌bé֖r ká̇⁠ʻé֣ẕ ʻawĕláֽh׃"],[24,21,"רֹעֶ֣ה עֲ֭קָרָה לֹ֣א תֵלֵ֑ד וְ֝⁠אַלְמָנָ֗ה לֹ֣א יְיֵטִֽיב׃","ròʻe֣h ʻà֭qáráh lò֣ʼ ţélé֑d wĕ֝⁠ʼalĕmáná֗h lò֣ʼ yĕyétiֽyb׃"],[24,22,"וּ⁠מָשַׁ֣ךְ אַבִּירִ֣ים בְּ⁠כֹח֑⁠וֹ יָ֝ק֗וּם וְֽ⁠לֹא־יַאֲמִ֥ין בַּֽ⁠חַיִּֽין׃","ẇ⁠máşǎ֣kĕ ʼabi̇yri֣ym bĕ̇⁠kòẖ֑⁠wò yá֝q֗ẇm wĕֽ⁠lòʼ-yaʼàmi֥yn bȧֽ⁠ẖayiֽ̇yn׃"],[24,23,"יִתֶּן־ל֣⁠וֹ לָ֭⁠בֶטַח וְ⁠יִשָּׁעֵ֑ן וְ֝⁠עֵינֵ֗י⁠הוּ עַל־דַּרְכֵי⁠הֶֽם׃","yiţėn-l֣⁠wò lá֭⁠betaẖ wĕ⁠yişá̇̌ʻé֑n wĕ֝⁠ʻéyné֗y⁠hẇ ʻal-dȧrĕkéy⁠heֽm׃"],[24,24,"ר֤וֹמּוּ מְּעַ֨ט ׀ וְֽ⁠אֵינֶ֗⁠נּוּ וְֽ⁠הֻמְּכ֗וּ כַּ⁠כֹּ֥ל יִקָּפְצ֑וּ⁠ן וּ⁠כְ⁠רֹ֖אשׁ שִׁבֹּ֣לֶת יִמָּֽלוּ׃","r֤wòṁẇ mĕ̇ʻa֨t ׀ wĕֽ⁠ʼéyne֗⁠ṅẇ wĕֽ⁠humĕ̇k֗ẇ kȧ⁠kò֥̇l yiqá̇pĕẕ֑ẇ⁠n ẇ⁠kĕ⁠rò֖ʼş̌ şǐbò֣̇leţ yimáֽ̇lẇ׃"],[24,25,"וְ⁠אִם־לֹ֣א אֵ֭פוֹ מִ֣י יַכְזִיבֵ֑⁠נִי וְ⁠יָשֵׂ֥ם לְ֝⁠אַ֗ל מִלָּתִֽ⁠י׃ס","wĕ⁠ʼim-lò֣ʼ ʼé֭pwò mi֣y yakĕziybé֑⁠niy wĕ⁠yáşé֥̂m lĕ֝⁠ʼa֗l milá̇ţiֽ⁠y׃s"],[25,1,"וַ֭⁠יַּעַן בִּלְדַּ֥ד הַ⁠שֻּׁחִ֗י וַ⁠יֹּאמַֽר׃","wa֭⁠yȧʻan bi̇lĕdȧ֥d ha⁠şu̇̌ẖi֗y wa⁠yò̇ʼmaֽr׃"],[25,2,"הַמְשֵׁ֣ל וָ⁠פַ֣חַד עִמּ֑⁠וֹ עֹשֶׂ֥ה שָׁ֝ל֗וֹם בִּ⁠מְרוֹמָֽי⁠ו׃","hamĕşé֣̌l wá⁠pa֣ẖad ʻiṁ֑⁠wò ʻòşê֥h şá̌֝l֗wòm bi̇⁠mĕrwòmáֽy⁠w׃"],[25,3,"הֲ⁠יֵ֣שׁ מִ֭סְפָּר לִ⁠גְדוּדָ֑י⁠ו וְ⁠עַל־מִ֝֗י לֹא־יָק֥וּם אוֹרֵֽ⁠הוּ׃","hà⁠yé֣ş̌ mi֭sĕpá̇r li⁠gĕdẇdá֑y⁠w wĕ⁠ʻal-mi֝֗y lòʼ-yáq֥ẇm ʼwòréֽ⁠hẇ׃"],[25,4,"וּ⁠מַה־יִּצְדַּ֣ק אֱנ֣וֹשׁ עִם־אֵ֑ל וּ⁠מַה־יִּ֝זְכֶּ֗ה יְל֣וּד אִשָּֽׁה׃","ẇ⁠mah-yi̇ẕĕdȧ֣q ʼèn֣wòş̌ ʻim-ʼé֑l ẇ⁠mah-yi̇֝zĕkė֗h yĕl֣ẇd ʼişáֽ̇̌h׃"],[25,5,"הֵ֣ן עַד־יָ֭רֵחַ וְ⁠לֹ֣א יַאֲהִ֑יל וְ֝⁠כוֹכָבִ֗ים לֹא־זַכּ֥וּ בְ⁠עֵינָֽי⁠ו׃","hé֣n ʻad-yá֭réẖa wĕ⁠lò֣ʼ yaʼàhi֑yl wĕ֝⁠kwòkábi֗ym lòʼ-zak֥̇ẇ bĕ⁠ʻéynáֽy⁠w׃"],[25,6,"אַ֭ף כִּֽי־אֱנ֣וֹשׁ רִמָּ֑ה וּ⁠בֶן־אָ֝דָ֗ם תּוֹלֵעָֽה׃פ","ʼa֭p kiֽ̇y-ʼèn֣wòş̌ rimá֑̇h ẇ⁠ben-ʼá֝dá֗m ţ̇wòléʻáֽh׃p"],[26,1,"וַ⁠יַּ֥עַן אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[26,2,"מֶה־עָזַ֥רְתָּ לְ⁠לֹא־כֹ֑חַ ה֝וֹשַׁ֗עְתָּ זְר֣וֹעַ לֹא־עֹֽז׃","meh-ʻáza֥rĕţá̇ lĕ⁠lòʼ-kò֑ẖa h֝wòşǎ֗ʻĕţá̇ zĕr֣wòʻa lòʼ-ʻòֽz׃"],[26,3,"מַה־יָּ֭עַצְתָּ לְ⁠לֹ֣א חָכְמָ֑ה וְ֝⁠תוּשִׁיָּ֗ה לָ⁠רֹ֥ב הוֹדָֽעְתָּ׃","mah-yá֭̇ʻaẕĕţá̇ lĕ⁠lò֣ʼ ẖákĕmá֑h wĕ֝⁠ţẇşǐyá̇֗h lá⁠rò֥b hwòdáֽʻĕţá̇׃"],[26,4,"אֶת־מִ֭י הִגַּ֣דְתָּ מִלִּ֑ין וְ⁠נִשְׁמַת־מִ֝י יָצְאָ֥ה מִמֶּֽ⁠ךָּ׃","ʼeţ-mi֭y higȧ֣dĕţá̇ mili֑̇yn wĕ⁠nişĕ̌maţ-mi֝y yáẕĕʼá֥h mimėֽ⁠ká̇׃"],[26,5,"הָ⁠רְפָאִ֥ים יְחוֹלָ֑לוּ מִ⁠תַּ֥חַת מַ֝֗יִם וְ⁠שֹׁכְנֵי⁠הֶֽם׃","há⁠rĕpáʼi֥ym yĕẖwòlá֑lẇ mi⁠ţȧ֥ẖaţ ma֝֗yim wĕ⁠şò̌kĕnéy⁠heֽm׃"],[26,6,"עָר֣וֹם שְׁא֣וֹל נֶגְדּ֑⁠וֹ וְ⁠אֵ֥ין כְּ֝ס֗וּת לָֽ⁠אֲבַדּֽוֹן׃","ʻár֣wòm şĕ̌ʼ֣wòl negĕḋ֑⁠wò wĕ⁠ʼé֥yn kĕ̇֝s֗ẇţ láֽ⁠ʼàbaḋֽwòn׃"],[26,7,"נֹטֶ֣ה צָפ֣וֹן עַל־תֹּ֑הוּ תֹּ֥לֶה אֶ֝֗רֶץ עַל־בְּלִי־מָֽה׃","nòte֣h ẕáp֣wòn ʻal-ţò֑̇hẇ ţò֥̇leh ʼe֝֗reẕ ʻal-bĕ̇liy-máֽh׃"],[26,8,"צֹרֵֽר־מַ֥יִם בְּ⁠עָבָ֑י⁠ו וְ⁠לֹא־נִבְקַ֖ע עָנָ֣ן תַּחְתָּֽ⁠ם׃","ẕòréֽr-ma֥yim bĕ̇⁠ʻábá֑y⁠w wĕ⁠lòʼ-nibĕqa֖ʻ ʻáná֣n ţȧẖĕţáֽ̇⁠m׃"],[26,9,"מְאַחֵ֥ז פְּנֵי־כִסֵּ֑ה פַּרְשֵׁ֖ז עָלָ֣י⁠ו עֲנָנֽ⁠וֹ׃","mĕʼaẖé֥z pĕ̇néy-kisé֑̇h pȧrĕşé֖̌z ʻálá֣y⁠w ʻànánֽ⁠wò׃"],[26,10,"חֹֽק־חָ֭ג עַל־פְּנֵי־מָ֑יִם עַד־תַּכְלִ֖ית א֣וֹר עִם־חֹֽשֶׁךְ׃","ẖòֽq-ẖá֭g ʻal-pĕ̇néy-má֑yim ʻad-ţȧkĕli֖yţ ʼ֣wòr ʻim-ẖòֽşěkĕ׃"],[26,11,"עַמּוּדֵ֣י שָׁמַ֣יִם יְרוֹפָ֑פוּ וְ֝⁠יִתְמְה֗וּ מִ⁠גַּעֲרָתֽ⁠וֹ׃","ʻaṁẇdé֣y şá̌ma֣yim yĕrwòpá֑pẇ wĕ֝⁠yiţĕmĕh֗ẇ mi⁠gȧʻàráţֽ⁠wò׃"],[26,12,"בְּ֭⁠כֹח⁠וֹ רָגַ֣ע הַ⁠יָּ֑ם ו⁠ב⁠תובנת⁠ו מָ֣חַץ רָֽהַב׃","bĕ֭̇⁠kòẖ⁠wò rága֣ʻ ha⁠yá֑̇m w⁠b⁠ţwbnţ⁠w má֣ẖaẕ ráֽhab׃"],[26,13,"בְּ֭⁠רוּח⁠וֹ שָׁמַ֣יִם שִׁפְרָ֑ה חֹֽלֲלָ֥ה יָ֝ד֗⁠וֹ נָחָ֥שׁ בָּרִֽיחַ׃","bĕ֭̇⁠rẇẖ⁠wò şá̌ma֣yim şǐpĕrá֑h ẖòֽlàlá֥h yá֝d֗⁠wò náẖá֥ş̌ bá̇riֽyẖa׃"],[26,14,"הֶן־אֵ֤לֶּה ׀ קְצ֬וֹת דרכ⁠ו וּ⁠מַה־שֵּׁ֣מֶץ דָּ֭בָר נִשְׁמַע־בּ֑⁠וֹ וְ⁠רַ֥עַם גבורת⁠ו מִ֣י יִתְבּוֹנָֽן׃ס","hen-ʼé֤lėh ׀ qĕẕ֬wòţ drk⁠w ẇ⁠mah-şé֣̇̌meẕ dá֭̇bár nişĕ̌maʻ-ḃ֑⁠wò wĕ⁠ra֥ʻam gbwrţ⁠w mi֣y yiţĕḃwònáֽn׃s"],[27,1,"וַ⁠יֹּ֣סֶף אִ֭יּוֹב שְׂאֵ֥ת מְשָׁל֗⁠וֹ וַ⁠יֹּאמַֽר׃","wa⁠yò֣̇sep ʼi֭ẏwòb şĕ̂ʼé֥ţ mĕşá̌l֗⁠wò wa⁠yò̇ʼmaֽr׃"],[27,2,"חַי־אֵ֭ל הֵסִ֣יר מִשְׁפָּטִ֑⁠י וְ֝⁠שַׁדַּ֗י הֵמַ֥ר נַפְשִֽׁ⁠י׃","ẖay-ʼé֭l hési֣yr mişĕ̌pá̇ti֑⁠y wĕ֝⁠şǎdȧ֗y héma֥r napĕşǐֽ⁠y׃"],[27,3,"כִּֽי־כָל־ע֣וֹד נִשְׁמָתִ֣⁠י בִ֑⁠י וְ⁠ר֖וּחַ אֱל֣וֹהַּ בְּ⁠אַפִּֽ⁠י׃","kiֽ̇y-kál-ʻ֣wòd nişĕ̌máţi֣⁠y bi֑⁠y wĕ⁠r֖ẇẖa ʼèl֣wòhȧ bĕ̇⁠ʼapiֽ̇⁠y׃"],[27,4,"אִם־תְּדַבֵּ֣רְנָה שְׂפָתַ֣⁠י עַוְלָ֑ה וּ֝⁠לְשׁוֹנִ֗⁠י אִם־יֶהְגֶּ֥ה רְמִיָּֽה׃","ʼim-ţĕ̇dabé֣̇rĕnáh şĕ̂páţa֣⁠y ʻawĕlá֑h ẇ֝⁠lĕş̌wòni֗⁠y ʼim-yehĕgė֥h rĕmiyáֽ̇h׃"],[27,5,"חָלִ֣ילָ⁠ה לִּ⁠י֮ אִם־אַצְדִּ֪יק אֶ֫תְ⁠כֶ֥ם עַד־אֶגְוָ֑ע לֹא־אָסִ֖יר תֻּמָּתִ֣⁠י מִמֶּֽ⁠נִּי׃","ẖáli֣ylá⁠h li̇⁠y֮ ʼim-ʼaẕĕdi֪̇yq ʼe֫ţĕ⁠ke֥m ʻad-ʼegĕwá֑ʻ lòʼ-ʼási֖yr ţu̇má̇ţi֣⁠y mimėֽ⁠ni̇y׃"],[27,6,"בְּ⁠צִדְקָתִ֣⁠י הֶ֭חֱזַקְתִּי וְ⁠לֹ֣א אַרְפֶּ֑⁠הָ לֹֽא־יֶחֱרַ֥ף לְ֝בָבִ֗⁠י מִ⁠יָּמָֽ⁠י׃","bĕ̇⁠ẕidĕqáţi֣⁠y he֭ẖèzaqĕţi̇y wĕ⁠lò֣ʼ ʼarĕpė֑⁠há lòֽʼ-yeẖèra֥p lĕ֝bábi֗⁠y mi⁠yá̇máֽ⁠y׃"],[27,7,"יְהִ֣י כְ֭⁠רָשָׁע אֹ֣יְבִ֑⁠י וּ⁠מִתְקוֹמְמִ֥⁠י כְ⁠עַוָּֽל׃","yĕhi֣y kĕ֭⁠ráşá̌ʻ ʼò֣yĕbi֑⁠y ẇ⁠miţĕqwòmĕmi֥⁠y kĕ⁠ʻawáֽ̇l׃"],[27,8,"כִּ֤י מַה־תִּקְוַ֣ת חָ֭נֵף כִּ֣י יִבְצָ֑ע כִּ֤י יֵ֖שֶׁל אֱל֣וֹהַּ נַפְשֽׁ⁠וֹ׃","ki֤̇y mah-ţi̇qĕwa֣ţ ẖá֭nép ki֣̇y yibĕẕá֑ʻ ki֤̇y yé֖şěl ʼèl֣wòhȧ napĕşֽ̌⁠wò׃"],[27,9,"הַֽ֭⁠צַעֲקָת⁠וֹ יִשְׁמַ֥ע ׀ אֵ֑ל כִּֽי־תָב֖וֹא עָלָ֣י⁠ו צָרָֽה׃","haֽ֭⁠ẕaʻàqáţ⁠wò yişĕ̌ma֥ʻ ׀ ʼé֑l kiֽ̇y-ţáb֖wòʼ ʻálá֣y⁠w ẕáráֽh׃"],[27,10,"אִם־עַל־שַׁדַּ֥י יִתְעַנָּ֑ג יִקְרָ֖א אֱל֣וֹהַּ בְּ⁠כָל־עֵֽת׃","ʼim-ʻal-şǎdȧ֥y yiţĕʻaná֑̇g yiqĕrá֖ʼ ʼèl֣wòhȧ bĕ̇⁠kál-ʻéֽţ׃"],[27,11,"אוֹרֶ֣ה אֶתְ⁠כֶ֣ם בְּ⁠יַד־אֵ֑ל אֲשֶׁ֥ר עִם־שַׁ֝דַּ֗י לֹ֣א אֲכַחֵֽד׃","ʼwòre֣h ʼeţĕ⁠ke֣m bĕ̇⁠yad-ʼé֑l ʼàşě֥r ʻim-şǎ֝dȧ֗y lò֣ʼ ʼàkaẖéֽd׃"],[27,12,"הֵן־אַתֶּ֣ם כֻּלְּ⁠כֶ֣ם חֲזִיתֶ֑ם וְ⁠לָ⁠מָּה־זֶּ֝֗ה הֶ֣בֶל תֶּהְבָּֽלוּ׃","hén-ʼaţė֣m ku̇lĕ̇⁠ke֣m ẖàziyţe֑m wĕ⁠lá⁠má̇h-zė֝֗h he֣bel ţėhĕbáֽ̇lẇ׃"],[27,13,"זֶ֤ה ׀ חֵֽלֶק־אָדָ֖ם רָשָׁ֥ע ׀ עִם־אֵ֑ל וְֽ⁠נַחֲלַ֥ת עָ֝רִיצִ֗ים מִ⁠שַּׁדַּ֥י יִקָּֽחוּ׃","ze֤h ׀ ẖéֽleq-ʼádá֖m ráşá֥̌ʻ ׀ ʻim-ʼé֑l wĕֽ⁠naẖàla֥ţ ʻá֝riyẕi֗ym mi⁠şȧ̌dȧ֥y yiqáֽ̇ẖẇ׃"],[27,14,"אִם־יִרְבּ֣וּ בָנָ֣י⁠ו לְמוֹ־חָ֑רֶב וְ֝⁠צֶאֱצָאָ֗י⁠ו לֹ֣א יִשְׂבְּעוּ־לָֽחֶם׃","ʼim-yirĕḃ֣ẇ báná֣y⁠w lĕmwò-ẖá֑reb wĕ֝⁠ẕeʼèẕáʼá֗y⁠w lò֣ʼ yişĕ̂bĕ̇ʻẇ-láֽẖem׃"],[27,15,"שריד⁠ו בַּ⁠מָּ֣וֶת יִקָּבֵ֑רוּ וְ֝⁠אַלְמְנֹתָ֗י⁠ו לֹ֣א תִבְכֶּֽינָה׃","şryd⁠w bȧ⁠má֣̇weţ yiqá̇bé֑rẇ wĕ֝⁠ʼalĕmĕnòţá֗y⁠w lò֣ʼ ţibĕkėֽynáh׃"],[27,16,"אִם־יִצְבֹּ֣ר כֶּ⁠עָפָ֣ר כָּ֑סֶף וְ֝⁠כַ⁠חֹ֗מֶר יָכִ֥ין מַלְבּֽוּשׁ׃","ʼim-yiẕĕbò֣̇r kė⁠ʻápá֣r ká֑̇sep wĕ֝⁠ka⁠ẖò֗mer yáki֥yn malĕḃֽẇş̌׃"],[27,17,"יָ֭כִין וְ⁠צַדִּ֣יק יִלְבָּ֑שׁ וְ֝⁠כֶ֗סֶף נָקִ֥י יַחֲלֹֽק׃","yá֭kiyn wĕ⁠ẕadi֣̇yq yilĕbá֑̇ş̌ wĕ֝⁠ke֗sep náqi֥y yaẖàlòֽq׃"],[27,18,"בָּנָ֣ה כָ⁠עָ֣שׁ בֵּית֑⁠וֹ וּ֝⁠כְ⁠סֻכָּ֗ה עָשָׂ֥ה נֹצֵֽר׃","bá̇ná֣h ká⁠ʻá֣ş̌ bé̇yţ֑⁠wò ẇ֝⁠kĕ⁠suká̇֗h ʻáşá֥̂h nòẕéֽr׃"],[27,19,"עָשִׁ֣יר יִ֭שְׁכַּב וְ⁠לֹ֣א יֵאָסֵ֑ף עֵינָ֖י⁠ו פָּקַ֣ח וְ⁠אֵינֶֽ⁠נּוּ׃","ʻáşǐ֣yr yi֭şĕ̌kȧb wĕ⁠lò֣ʼ yéʼásé֑p ʻéyná֖y⁠w pá̇qa֣ẖ wĕ⁠ʼéyneֽ⁠ṅẇ׃"],[27,20,"תַּשִּׂיגֵ֣⁠הוּ כַ֭⁠מַּיִם בַּלָּה֑וֹת לַ֝֗יְלָה גְּנָבַ֥תּ⁠וּ סוּפָֽה׃","ţȧşi̇̂ygé֣⁠hẇ ka֭⁠mȧyim bȧlá̇h֑wòţ la֝֗yĕláh gĕ̇nába֥ţ̇⁠ẇ sẇpáֽh׃"],[27,21,"יִשָּׂאֵ֣⁠הוּ קָדִ֣ים וְ⁠יֵלַ֑ךְ וִֽ֝⁠ישָׂעֲרֵ֗⁠הוּ מִ⁠מְּקֹמֽ⁠וֹ׃","yişá̇̂ʼé֣⁠hẇ qádi֣ym wĕ⁠yéla֑kĕ wiֽ֝⁠yşá̂ʻàré֗⁠hẇ mi⁠mĕ̇qòmֽ⁠wò׃"],[27,22,"וְ⁠יַשְׁלֵ֣ךְ עָ֭לָי⁠ו וְ⁠לֹ֣א יַחְמֹ֑ל מִ֝⁠יָּד֗⁠וֹ בָּר֥וֹחַ יִבְרָֽח׃","wĕ⁠yaşĕ̌lé֣kĕ ʻá֭láy⁠w wĕ⁠lò֣ʼ yaẖĕmò֑l mi֝⁠yá̇d֗⁠wò bá̇r֥wòẖa yibĕráֽẖ׃"],[27,23,"יִשְׂפֹּ֣ק עָלֵ֣י⁠מוֹ כַפֵּ֑י⁠מוֹ וְ⁠יִשְׁרֹ֥ק עָ֝לָ֗י⁠ו מִ⁠מְּקֹמֽ⁠וֹ׃","yişĕ̂pò֣̇q ʻálé֣y⁠mwò kapé֑̇y⁠mwò wĕ⁠yişĕ̌rò֥q ʻá֝lá֗y⁠w mi⁠mĕ̇qòmֽ⁠wò׃"],[28,1,"כִּ֤י יֵ֣שׁ לַ⁠כֶּ֣סֶף מוֹצָ֑א וּ֝⁠מָק֗וֹם לַ⁠זָּהָ֥ב יָזֹֽקּוּ׃","ki֤̇y yé֣ş̌ la⁠kė֣sep mwòẕá֑ʼ ẇ֝⁠máq֗wòm la⁠zá̇há֥b yázòֽq̇ẇ׃"],[28,2,"בַּ֭רְזֶל מֵ⁠עָפָ֣ר יֻקָּ֑ח וְ֝⁠אֶ֗בֶן יָצ֥וּק נְחוּשָֽׁה׃","bȧ֭rĕzel mé⁠ʻápá֣r yuqá֑̇ẖ wĕ֝⁠ʼe֗ben yáẕ֥ẇq nĕẖẇşáֽ̌h׃"],[28,3,"קֵ֤ץ ׀ שָׂ֤ם לַ⁠חֹ֗שֶׁךְ וּֽ⁠לְ⁠כָל־תַּ֭כְלִית ה֣וּא חוֹקֵ֑ר אֶ֖בֶן אֹ֣פֶל וְ⁠צַלְמָֽוֶת׃","qé֤ẕ ׀ şá֤̂m la⁠ẖò֗şěkĕ ẇֽ⁠lĕ⁠kál-ţȧ֭kĕliyţ h֣ẇʼ ẖwòqé֑r ʼe֖ben ʼò֣pel wĕ⁠ẕalĕmáֽweţ׃"],[28,4,"פָּ֤רַץ נַ֨חַל ׀ מֵֽ⁠עִם־גָּ֗ר הַֽ⁠נִּשְׁכָּחִ֥ים מִנִּי־רָ֑גֶל דַּ֖לּוּ מֵ⁠אֱנ֣וֹשׁ נָֽעוּ׃","pá֤̇raẕ na֨ẖal ׀ méֽ⁠ʻim-gá̇֗r haֽ⁠ni̇şĕ̌ká̇ẖi֥ym mini̇y-rá֑gel dȧ֖l̇ẇ mé⁠ʼèn֣wòş̌ náֽʻẇ׃"],[28,5,"אֶ֗רֶץ מִמֶּ֥⁠נָּה יֵֽצֵא־לָ֑חֶם וְ֝⁠תַחְתֶּ֗י⁠הָ נֶהְפַּ֥ךְ כְּמוֹ־אֵֽשׁ׃","ʼe֗reẕ mimė֥⁠ná̇h yéֽẕéʼ-lá֑ẖem wĕ֝⁠ţaẖĕţė֗y⁠há nehĕpȧ֥kĕ kĕ̇mwò-ʼéֽş̌׃"],[28,6,"מְקוֹם־סַפִּ֥יר אֲבָנֶ֑י⁠הָ וְ⁠עַפְרֹ֖ת זָהָ֣ב לֽ⁠וֹ׃","mĕqwòm-sapi֥̇yr ʼàbáne֑y⁠há wĕ⁠ʻapĕrò֖ţ záhá֣b lֽ⁠wò׃"],[28,7,"נָ֭תִיב לֹֽא־יְדָ֣ע⁠וֹ עָ֑יִט וְ⁠לֹ֥א שְׁ֝זָפַ֗תּ⁠וּ עֵ֣ין אַיָּֽה׃","ná֭ţiyb lòֽʼ-yĕdá֣ʻ⁠wò ʻá֑yit wĕ⁠lò֥ʼ şĕ̌֝zápa֗ţ̇⁠ẇ ʻé֣yn ʼayáֽ̇h׃"],[28,8,"לֹֽא־הִדְרִיכֻ֥⁠הוּ בְנֵי־שָׁ֑חַץ לֹֽא־עָדָ֖ה עָלָ֣י⁠ו שָֽׁחַל׃","lòֽʼ-hidĕriyku֥⁠hẇ bĕnéy-şá֑̌ẖaẕ lòֽʼ-ʻádá֖h ʻálá֣y⁠w şáֽ̌ẖal׃"],[28,9,"בַּֽ֭⁠חַלָּמִישׁ שָׁלַ֣ח יָד֑⁠וֹ הָפַ֖ךְ מִ⁠שֹּׁ֣רֶשׁ הָרִֽים׃","bȧֽ֭⁠ẖalá̇miyş̌ şá̌la֣ẖ yád֑⁠wò hápa֖kĕ mi⁠şò֣̇̌reş̌ háriֽym׃"],[28,10,"בַּ֭⁠צּוּרוֹת יְאֹרִ֣ים בִּקֵּ֑עַ וְ⁠כָל־יְ֝קָ֗ר רָאֲתָ֥ה עֵינֽ⁠וֹ׃","bȧ֭⁠ẕ̇ẇrwòţ yĕʼòri֣ym bi̇qé֑̇ʻa wĕ⁠kál-yĕ֝qá֗r ráʼàţá֥h ʻéynֽ⁠wò׃"],[28,11,"מִ֭⁠בְּכִי נְהָר֣וֹת חִבֵּ֑שׁ וְ֝⁠תַעֲלֻמָ֗הּ יֹ֣צִא אֽוֹר׃פ","mi֭⁠bĕ̇kiy nĕhár֣wòţ ẖibé֑̇ş̌ wĕ֝⁠ţaʻàlumá֗ḣ yò֣ẕiʼ ʼֽwòr׃p"],[28,12,"וְֽ֭⁠הַ⁠חָכְמָה מֵ⁠אַ֣יִן תִּמָּצֵ֑א וְ⁠אֵ֥י זֶ֝ה מְק֣וֹם בִּינָֽה׃","wĕֽ֭⁠ha⁠ẖákĕmáh mé⁠ʼa֣yin ţi̇má̇ẕé֑ʼ wĕ⁠ʼé֥y ze֝h mĕq֣wòm bi̇ynáֽh׃"],[28,13,"לֹא־יָדַ֣ע אֱנ֣וֹשׁ עֶרְכָּ֑⁠הּ וְ⁠לֹ֥א תִ֝מָּצֵ֗א בְּ⁠אֶ֣רֶץ הַֽ⁠חַיִּֽים׃","lòʼ-yáda֣ʻ ʼèn֣wòş̌ ʻerĕká֑̇⁠ḣ wĕ⁠lò֥ʼ ţi֝má̇ẕé֗ʼ bĕ̇⁠ʼe֣reẕ hֽa⁠ẖayiֽ̇ym׃"],[28,14,"תְּה֣וֹם אָ֭מַר לֹ֣א בִ⁠י־הִ֑יא וְ⁠יָ֥ם אָ֝מַ֗ר אֵ֣ין עִמָּדִֽ⁠י׃","ţĕ̇h֣wòm ʼá֭mar lò֣ʼ bi⁠y-hi֑yʼ wĕ⁠yá֥m ʼá֝ma֗r ʼé֣yn ʻimá̇diֽ⁠y׃"],[28,15,"לֹא־יֻתַּ֣ן סְג֣וֹר תַּחְתֶּ֑י⁠הָ וְ⁠לֹ֥א יִ֝שָּׁקֵ֗ל כֶּ֣סֶף מְחִירָֽ⁠הּ׃","lòʼ-yuţȧ֣n sĕg֣wòr ţȧẖĕţė֑y⁠há wĕ⁠lò֥ʼ yi֝şá̇̌qé֗l kė֣sep mĕẖiyráֽ⁠ḣ׃"],[28,16,"לֹֽא־תְ֭סֻלֶּה בְּ⁠כֶ֣תֶם אוֹפִ֑יר בְּ⁠שֹׁ֖הַם יָקָ֣ר וְ⁠סַפִּֽיר׃","lòֽʼ-ţĕ֭sulėh bĕ̇⁠ke֣ţem ʼwòpi֑yr bĕ̇⁠şò֖̌ham yáqá֣r wĕ⁠sapiֽ̇yr׃"],[28,17,"לֹא־יַעַרְכֶ֣⁠נָּה זָ֭הָב וּ⁠זְכוֹכִ֑ית וּ⁠תְמ֖וּרָתָ֣⁠הּ כְּלִי־פָֽז׃","lòʼ-yaʻarĕke֣⁠ná̇h zá֭háb ẇ⁠zĕkwòki֑yţ ẇ⁠ţĕm֖ẇráţá֣⁠ḣ kĕ̇liy-páֽz׃"],[28,18,"רָאמ֣וֹת וְ֭⁠גָבִישׁ לֹ֣א יִזָּכֵ֑ר וּ⁠מֶ֥שֶׁךְ חָ֝כְמָ֗ה מִ⁠פְּנִינִֽים׃","ráʼm֣wòţ wĕ֭⁠gábiyş̌ lò֣ʼ yizá̇ké֑r ẇ⁠me֥şěkĕ ẖá֝kĕmá֗h mi⁠pĕ̇niyniֽym׃"],[28,19,"לֹֽא־יַ֭עַרְכֶ⁠נָּה פִּטְדַת־כּ֑וּשׁ בְּ⁠כֶ֥תֶם טָ֝ה֗וֹר לֹ֣א תְסֻלֶּֽה׃פ","lòֽʼ-ya֭ʻarĕke⁠ná̇h pi̇tĕdaţ-k֑̇ẇş̌ bĕ̇⁠ke֥ţem tá֝h֗wòr lò֣ʼ ţĕsulėֽh׃p"],[28,20,"וְֽ֭⁠הַ⁠חָכְמָה מֵ⁠אַ֣יִן תָּב֑וֹא וְ⁠אֵ֥י זֶ֝֗ה מְק֣וֹם בִּינָֽה׃","wĕֽ֭⁠ha⁠ẖákĕmáh mé⁠ʼa֣yin ţá̇b֑wòʼ wĕ⁠ʼé֥y ze֝֗h mĕq֣wòm bi̇ynáֽh׃"],[28,21,"וְֽ֭⁠נֶעֶלְמָה מֵ⁠עֵינֵ֣י כָל־חָ֑י וּ⁠מֵ⁠ע֖וֹף הַ⁠שָּׁמַ֣יִם נִסְתָּֽרָה׃","wĕֽ֭⁠neʻelĕmáh mé⁠ʻéyné֣y kál-ẖá֑y ẇ⁠mé⁠ʻ֖wòp ha⁠şá̇̌ma֣yim nisĕţáֽ̇ráh׃"],[28,22,"אֲבַדּ֣וֹן וָ֭⁠מָוֶת אָ֣מְר֑וּ בְּ֝⁠אָזְנֵ֗י⁠נוּ שָׁמַ֥עְנוּ שִׁמְעָֽ⁠הּ׃","ʼàbaḋ֣wòn wá֭⁠máweţ ʼá֣mĕr֑ẇ bĕ̇֝⁠ʼázĕné֗y⁠nẇ şá̌ma֥ʻĕnẇ şǐmĕʻáֽ⁠ḣ׃"],[28,23,"אֱ֭לֹהִים הֵבִ֣ין דַּרְכָּ֑⁠הּ וְ֝⁠ה֗וּא יָדַ֥ע אֶת־מְקוֹמָֽ⁠הּ׃","ʼè֭lòhiym hébi֣yn dȧrĕká֑̇⁠ḣ wĕ֝⁠h֗ẇʼ yáda֥ʻ ʼeţ-mĕqwòmáֽ⁠ḣ׃"],[28,24,"כִּי־ה֭וּא לִ⁠קְצוֹת־הָ⁠אָ֣רֶץ יַבִּ֑יט תַּ֖חַת כָּל־הַ⁠שָּׁמַ֣יִם יִרְאֶֽה׃","ki̇y-h֭ẇʼ li⁠qĕẕwòţ-há⁠ʼá֣reẕ yabi֑̇yt ţȧ֖ẖaţ ká̇l-ha⁠şá̇̌ma֣yim yirĕʼeֽh׃"],[28,25,"לַ⁠עֲשׂ֣וֹת לָ⁠ר֣וּחַ מִשְׁקָ֑ל וּ֝⁠מַ֗יִם תִּכֵּ֥ן בְּ⁠מִדָּֽה׃","la⁠ʻàş֣̂wòţ lá⁠r֣ẇẖa mişĕ̌qá֑l ẇ֝⁠ma֗yim ţi̇ké֥̇n bĕ̇⁠midáֽ̇h׃"],[28,26,"בַּ⁠עֲשֹׂת֣⁠וֹ לַ⁠מָּטָ֣ר חֹ֑ק וְ֝⁠דֶ֗רֶךְ לַ⁠חֲזִ֥יז קֹלֽוֹת׃","bȧ⁠ʻàşò̂ţ֣⁠wò la⁠má̇tá֣r ẖò֑q wĕ֝⁠de֗rekĕ la⁠ẖàzi֥yz qòlֽwòţ׃"],[28,27,"אָ֣ז רָ֭אָ⁠הּ וַֽ⁠יְסַפְּרָ֑⁠הּ הֱ֝כִינָ֗⁠הּ וְ⁠גַם־חֲקָרָֽ⁠הּ׃","ʼá֣z rá֭ʼá⁠ḣ waֽ⁠yĕsapĕ̇rá֑⁠ḣ hè֝kiyná֗⁠ḣ wĕ⁠gam-ẖàqáráֽ⁠ḣ׃"],[28,28,"וַ⁠יֹּ֤אמֶר ׀ לָֽ⁠אָדָ֗ם הֵ֤ן יִרְאַ֣ת אֲ֭דֹנָ⁠י הִ֣יא חָכְמָ֑ה וְ⁠ס֖וּר מֵ⁠רָ֣ע בִּינָֽה׃ס","wa⁠yò֤̇ʼmer ׀ láֽ⁠ʼádá֗m hé֤n yirĕʼa֣ţ ʼà֭dòná⁠y hi֣yʼ ẖákĕmá֑h wĕ⁠s֖ẇr mé⁠rá֣ʻ bi̇ynáֽh׃s"],[29,1,"וַ⁠יֹּ֣סֶף אִ֭יּוֹב שְׂאֵ֥ת מְשָׁל֗⁠וֹ וַ⁠יֹּאמַֽר׃","wa⁠yò֣̇sep ʼi֭ẏwòb şĕ̂ʼé֥ţ mĕşá̌l֗⁠wò wa⁠yò̇ʼmaֽr׃"],[29,2,"מִֽי־יִתְּנֵ֥⁠נִי כְ⁠יַרְחֵי־קֶ֑דֶם כִּ֝⁠ימֵ֗י אֱל֣וֹהַּ יִשְׁמְרֵֽ⁠נִי׃","miֽy-yiţĕ̇né֥⁠niy kĕ⁠yarĕẖéy-qe֑dem ki̇֝⁠ymé֗y ʼèl֣wòhȧ yişĕ̌mĕréֽ⁠niy׃"],[29,3,"בְּ⁠הִלּ֣⁠וֹ נֵ֭ר⁠וֹ עֲלֵ֣י רֹאשִׁ֑⁠י לְ֝⁠אוֹר⁠וֹ אֵ֣לֶךְ חֹֽשֶׁךְ׃","bĕ̇⁠hil֣̇⁠wò né֭r⁠wò ʻàlé֣y ròʼşǐ֑⁠y lĕ֝⁠ʼwòr⁠wò ʼé֣lekĕ ẖòֽşěkĕ׃"],[29,4,"כַּ⁠אֲשֶׁ֣ר הָ֭יִיתִי בִּ⁠ימֵ֣י חָרְפִּ֑⁠י בְּ⁠ס֥וֹד אֱ֝ל֗וֹהַּ עֲלֵ֣י אָהֳלִֽ⁠י׃","kȧ⁠ʼàşě֣r há֭yiyţiy bi̇⁠ymé֣y ẖárĕpi֑̇⁠y bĕ̇⁠s֥wòd ʼè֝l֗wòhȧ ʻàlé֣y ʼáholiֽ⁠y׃"],[29,5,"בְּ⁠ע֣וֹד שַׁ֭דַּי עִמָּדִ֑⁠י סְבִ֖יבוֹתַ֣⁠י נְעָרָֽ⁠י׃","bĕ̇⁠ʻ֣wòd şǎ֭dȧy ʻimá̇di֑⁠y sĕbi֖ybwòţa֣⁠y nĕʻáráֽ⁠y׃"],[29,6,"בִּ⁠רְחֹ֣ץ הֲלִיכַ֣⁠י בְּ⁠חֵמָ֑ה וְ⁠צ֥וּר יָצ֥וּק עִ֝מָּדִ֗⁠י פַּלְגֵי־שָֽׁמֶן׃","bi̇⁠rĕẖò֣ẕ hàliyka֣⁠y bĕ̇⁠ẖémá֑h wĕ⁠ẕ֥ẇr yáẕ֥ẇq ʻi֝má̇di֗⁠y pȧlĕgéy-şáֽ̌men׃"],[29,7,"בְּ⁠צֵ֣אתִ⁠י שַׁ֣עַר עֲלֵי־קָ֑רֶת בָּ֝⁠רְח֗וֹב אָכִ֥ין מוֹשָׁבִֽ⁠י׃","bĕ̇⁠ẕé֣ʼţi⁠y şǎ֣ʻar ʻàléy-qá֑reţ bá̇֝⁠rĕẖ֗wòb ʼáki֥yn mwòşá̌biֽ⁠y׃"],[29,8,"רָא֣וּ⁠נִי נְעָרִ֣ים וְ⁠נֶחְבָּ֑אוּ וִֽ֝⁠ישִׁישִׁים קָ֣מוּ עָמָֽדוּ׃","ráʼ֣ẇ⁠niy nĕʻári֣ym wĕ⁠neẖĕbá֑̇ʼẇ wiֽ֝⁠yşǐyşǐym qá֣mẇ ʻámáֽdẇ׃"],[29,9,"שָׂ֭רִים עָצְר֣וּ בְ⁠מִלִּ֑ים וְ֝⁠כַ֗ף יָשִׂ֥ימוּ לְ⁠פִי⁠הֶֽם׃","şá֭̂riym ʻáẕĕr֣ẇ bĕ⁠mili֑̇ym wĕ֝⁠ka֗p yáşî֥ymẇ lĕ⁠piy⁠heֽm׃"],[29,10,"קוֹל־נְגִידִ֥ים נֶחְבָּ֑אוּ וּ֝⁠לְשׁוֹנָ֗⁠ם לְ⁠חִכָּ֥⁠ם דָּבֵֽקָה׃","qwòl-nĕgiydi֥ym neẖĕbá֑̇ʼẇ ẇ֝⁠lĕş̌wòná֗⁠m lĕ⁠ẖiká֥̇⁠m dá̇béֽqáh׃"],[29,11,"כִּ֤י אֹ֣זֶן שָׁ֭מְעָה וַֽ⁠תְּאַשְּׁרֵ֑⁠נִי וְ⁠עַ֥יִן רָ֝אֲתָ֗ה וַ⁠תְּעִידֵֽ⁠נִי׃","ki֤̇y ʼò֣zen şá֭̌mĕʻáh waֽ⁠ţĕ̇ʼaşĕ̇̌ré֑⁠niy wĕ⁠ʻa֥yin rá֝ʼàţá֗h wa⁠ţĕ̇ʻiydéֽ⁠niy׃"],[29,12,"כִּֽי־אֲ֭מַלֵּט עָנִ֣י מְשַׁוֵּ֑עַ וְ֝⁠יָת֗וֹם וְֽ⁠לֹא־עֹזֵ֥ר לֽ⁠וֹ׃","kiֽ̇y-ʼà֭malé̇t ʻáni֣y mĕşǎwé֑̇ʻa wĕ֝⁠yáţ֗wòm wĕֽ⁠lòʼ-ʻòzé֥r lֽ⁠wò׃"],[29,13,"בִּרְכַּ֣ת אֹ֭בֵד עָלַ֣⁠י תָּבֹ֑א וְ⁠לֵ֖ב אַלְמָנָ֣ה אַרְנִֽן׃","bi̇rĕkȧ֣ţ ʼò֭béd ʻála֣⁠y ţá̇bò֑ʼ wĕ⁠lé֖b ʼalĕmáná֣h ʼarĕniֽn׃"],[29,14,"צֶ֣דֶק לָ֭בַשְׁתִּי וַ⁠יִּלְבָּשֵׁ֑⁠נִי כִּֽ⁠מְעִ֥יל וְ֝⁠צָנִ֗יף מִשְׁפָּטִֽ⁠י׃","ẕe֣deq lá֭başĕ̌ţi̇y wa⁠yi̇lĕbá̇şé֑̌⁠niy kiֽ̇⁠mĕʻi֥yl wĕ֝⁠ẕáni֗yp mişĕ̌pá̇tiֽ⁠y׃"],[29,15,"עֵינַ֣יִם הָ֭יִיתִי לַֽ⁠עִוֵּ֑ר וְ⁠רַגְלַ֖יִם לַ⁠פִּסֵּ֣חַ אָֽנִי׃","ʻéyna֣yim há֭yiyţiy laֽ⁠ʻiwé֑̇r wĕ⁠ragĕla֖yim la⁠pi̇sé֣̇ẖa ʼáֽniy׃"],[29,16,"אָ֣ב אָ֭נֹכִֽי לָֽ⁠אֶבְיוֹנִ֑ים וְ⁠רִ֖ב לֹא־יָדַ֣עְתִּי אֶחְקְרֵֽ⁠הוּ׃","ʼá֣b ʼá֭nòkiֽy láֽ⁠ʼebĕywòni֑ym wĕ⁠ri֖b lòʼ-yáda֣ʻĕţi̇y ʼeẖĕqĕréֽ⁠hẇ׃"],[29,17,"וָֽ֭⁠אֲשַׁבְּרָ⁠ה מְתַלְּע֣וֹת עַוָּ֑ל וּ֝⁠מִ⁠שִּׁנָּ֗י⁠ו אַשְׁלִ֥יךְ טָֽרֶף׃","wáֽ֭⁠ʼàşǎbĕ̇rá⁠h mĕţalĕ̇ʻ֣wòţ ʻawá֑̇l ẇ֝⁠mi⁠şi̇̌ná̇֗y⁠w ʼaşĕ̌li֥ykĕ táֽrep׃"],[29,18,"וָ֭⁠אֹמַר עִם־קִנִּ֣⁠י אֶגְוָ֑ע וְ֝⁠כַ⁠ח֗וֹל אַרְבֶּ֥ה יָמִֽים׃","wá֭⁠ʼòmar ʻim-qini֣̇⁠y ʼegĕwá֑ʻ wĕ֝⁠ka⁠ẖ֗wòl ʼarĕbė֥h yámiֽym׃"],[29,19,"שָׁרְשִׁ֣⁠י פָת֣וּחַ אֱלֵי־מָ֑יִם וְ֝⁠טַ֗ל יָלִ֥ין בִּ⁠קְצִירִֽ⁠י׃","şá̌rĕşǐ֣⁠y páţ֣ẇẖa ʼèléy-má֑yim wĕ֝⁠ta֗l yáli֥yn bi̇⁠qĕẕiyrֽi⁠y׃"],[29,20,"כְּ֭בוֹדִ⁠י חָדָ֣שׁ עִמָּדִ֑⁠י וְ֝⁠קַשְׁתִּ֗⁠י בְּ⁠יָדִ֥⁠י תַחֲלִֽיף׃","kĕ֭̇bwòdi⁠y ẖádá֣ş̌ ʻimá̇di֑⁠y wĕ֝⁠qaşĕ̌ţi̇֗⁠y bĕ̇⁠yádi֥⁠y ţaẖàliֽyp׃"],[29,21,"לִֽ⁠י־שָׁמְע֥וּ וְ⁠יִחֵ֑לּוּ וְ֝⁠יִדְּמ֗וּ לְמ֣וֹ עֲצָתִֽ⁠י׃","liֽ⁠y-şá̌mĕʻ֥ẇ wĕ⁠yiẖé֑l̇ẇ wĕ֝⁠yidĕ̇m֗ẇ lĕm֣wò ʻàẕáţiֽ⁠y׃"],[29,22,"אַחֲרֵ֣י דְ֭בָרִ⁠י לֹ֣א יִשְׁנ֑וּ וְ֝⁠עָלֵ֗י⁠מוֹ תִּטֹּ֥ף מִלָּתִֽ⁠י׃","ʼaẖàré֣y dĕ֭bári⁠y lò֣ʼ yişĕ̌n֑ẇ wĕ֝⁠ʻálé֗y⁠mwò ţi̇tò֥̇p milá̇ţiֽ⁠y׃"],[29,23,"וְ⁠יִֽחֲל֣וּ כַ⁠מָּטָ֣ר לִ֑⁠י וּ֝⁠פִי⁠הֶ֗ם פָּעֲר֥וּ לְ⁠מַלְקֽוֹשׁ׃","wĕ⁠yiֽẖàl֣ẇ ka⁠má̇tá֣r li֑⁠y ẇ֝⁠piy⁠he֗m pá̇ʻàr֥ẇ lĕ⁠malĕqֽwòş̌׃"],[29,24,"אֶשְׂחַ֣ק אֲ֭לֵ⁠הֶם לֹ֣א יַאֲמִ֑ינוּ וְ⁠א֥וֹר פָּ֝נַ֗⁠י לֹ֣א יַפִּילֽוּ⁠ן׃","ʼeşĕ̂ẖa֣q ʼà֭lé⁠hem lò֣ʼ yaʼàmi֑ynẇ wĕ⁠ʼ֥wòr pá̇֝na֗⁠y lò֣ʼ yapi̇ylֽẇ⁠n׃"],[29,25,"אֶֽבֲחַ֣ר דַּרְכָּ⁠ם֮ וְ⁠אֵשֵׁ֪ב רֹ֥אשׁ וְ֭⁠אֶשְׁכּוֹן כְּ⁠מֶ֣לֶךְ בַּ⁠גְּד֑וּד כַּ⁠אֲשֶׁ֖ר אֲבֵלִ֣ים יְנַחֵֽם׃","ʼeֽbàẖa֣r dȧrĕká̇⁠m֮ wĕ⁠ʼéşé֪̌b rò֥ʼş̌ wĕ֭⁠ʼeşĕ̌k̇wòn kĕ̇⁠me֣lekĕ bȧ⁠gĕ̇d֑ẇd kȧ⁠ʼàşě֖r ʼàbéli֣ym yĕnaẖéֽm׃"],[30,1,"וְ⁠עַתָּ֤ה ׀ שָֽׂחֲק֣וּ עָלַ⁠י֮ צְעִירִ֥ים מִמֶּ֗⁠נִּי לְ⁠יָ֫מִ֥ים אֲשֶׁר־מָאַ֥סְתִּי אֲבוֹתָ֑⁠ם לָ֝⁠שִׁ֗ית עִם־כַּלְבֵ֥י צֹאנִֽ⁠י׃","wĕ⁠ʻaţá֤̇h ׀ şáֽ̂ẖàq֣ẇ ʻála⁠y֮ ẕĕʻiyri֥ym mimė֗⁠ni̇y lĕ⁠yá֫mi֥ym ʼàşěr-máʼa֥sĕţi̇y ʼàbwòţá֑⁠m lá֝⁠şǐ֗yţ ʻim-kȧlĕbé֥y ẕòʼniֽ⁠y׃"],[30,2,"גַּם־כֹּ֣חַ יְ֭דֵי⁠הֶם לָ֣⁠מָּה לִּ֑⁠י עָ֝לֵ֗י⁠מוֹ אָ֣בַד כָּֽלַח׃","gȧm-kò֣̇ẖa yĕ֭déy⁠hem lá֣⁠má̇h li֑̇⁠y ʻá֝lé֗y⁠mwò ʼá֣bad káֽ̇laẖ׃"],[30,3,"בְּ⁠חֶ֥סֶר וּ⁠בְ⁠כָפָ֗ן גַּ֫לְמ֥וּד הַֽ⁠עֹרְקִ֥ים צִיָּ֑ה אֶ֝֗מֶשׁ שׁוֹאָ֥ה וּ⁠מְשֹׁאָֽה׃","bĕ̇⁠ẖe֥ser ẇ⁠bĕ⁠kápá֗n gȧ֫lĕm֥ẇd haֽ⁠ʻòrĕqi֥ym ẕiyá֑̇h ʼe֝֗meş̌ ş̌wòʼá֥h ẇ⁠mĕşò̌ʼáֽh׃"],[30,4,"הַ⁠קֹּטְפִ֣ים מַלּ֣וּחַ עֲלֵי־שִׂ֑יחַ וְ⁠שֹׁ֖רֶשׁ רְתָמִ֣ים לַ⁠חְמָֽ⁠ם׃","ha⁠qò̇tĕpi֣ym mal֣̇ẇẖa ʻàléy-şî֑yẖa wĕ⁠şò֖̌reş̌ rĕţámi֣ym la⁠ẖĕmáֽ⁠m׃"],[30,5,"מִן־גֵּ֥ו יְגֹרָ֑שׁוּ יָרִ֥יעוּ עָ֝לֵ֗י⁠מוֹ כַּ⁠גַּנָּֽב׃","min-gé֥̇w yĕgòrá֑ş̌ẇ yári֥yʻẇ ʻá֝lé֗y⁠mwò kȧ⁠gȧnáֽ̇b׃"],[30,6,"בַּ⁠עֲר֣וּץ נְחָלִ֣ים לִ⁠שְׁכֹּ֑ן חֹרֵ֖י עָפָ֣ר וְ⁠כֵפִֽים׃","bȧ⁠ʻàr֣ẇẕ nĕẖáli֣ym li⁠şĕ̌kò֑̇n ẖòré֖y ʻápá֣r wĕ⁠képiֽym׃"],[30,7,"בֵּין־שִׂיחִ֥ים יִנְהָ֑קוּ תַּ֖חַת חָר֣וּל יְסֻפָּֽחוּ׃","bé̇yn-şîyẖi֥ym yinĕhá֑qẇ ţȧ֖ẖaţ ẖár֣ẇl yĕsupáֽ̇ẖẇ׃"],[30,8,"בְּֽנֵי־נָ֭בָל גַּם־בְּנֵ֣י בְלִי־שֵׁ֑ם נִ֝כְּא֗וּ מִן־הָ⁠אָֽרֶץ׃","bĕֽ̇néy-ná֭bál gȧm-bĕ̇né֣y bĕliy-şé֑̌m ni֝kĕ̇ʼ֗ẇ min-há⁠ʼáֽreẕ׃"],[30,9,"וְ֭⁠עַתָּה נְגִינָתָ֣⁠ם הָיִ֑יתִי וָ⁠אֱהִ֖י לָ⁠הֶ֣ם לְ⁠מִלָּֽה׃","wĕ֭⁠ʻaţá̇h nĕgiynáţá֣⁠m háyi֑yţiy wá⁠ʼèhi֖y lá⁠he֣m lĕ⁠miláֽ̇h׃"],[30,10,"תִּֽ֭עֲבוּ⁠נִי רָ֣חֲקוּ מֶ֑⁠נִּי וּ֝⁠מִ⁠פָּנַ֗⁠י לֹא־חָ֥שְׂכוּ רֹֽק׃","ţiֽ֭̇ʻàbẇ⁠niy rá֣ẖàqẇ me֑⁠ni̇y ẇ֝⁠mi⁠pá̇na֗⁠y lòʼ-ẖá֥şĕ̂kẇ ròֽq׃"],[30,11,"כִּֽי־יתר⁠ו פִ֭תַּח וַ⁠יְעַנֵּ֑⁠נִי וְ֝⁠רֶ֗סֶן מִ⁠פָּנַ֥⁠י שִׁלֵּֽחוּ׃","kiֽ̇y-yţr⁠w pi֭ţȧẖ wa⁠yĕʻané֑̇⁠niy wĕ֝⁠re֗sen mi⁠pá̇na֥⁠y şǐléֽ̇ẖẇ׃"],[30,12,"עַל־יָמִין֮ פִּרְחַ֪ח יָ֫ק֥וּמוּ רַגְלַ֥⁠י שִׁלֵּ֑חוּ וַ⁠יָּסֹ֥לּוּ עָ֝לַ֗⁠י אָרְח֥וֹת אֵידָֽ⁠ם׃","ʻal-yámiyn֮ pi̇rĕẖa֪ẖ yá֫q֥ẇmẇ ragĕla֥⁠y şǐlé֑̇ẖẇ wa⁠yá̇sò֥l̇ẇ ʻá֝la֗⁠y ʼárĕẖ֥wòţ ʼéydáֽ⁠m׃"],[30,13,"נָתְס֗וּ נְֽתִיבָ֫תִ֥⁠י לְ⁠הַוָּתִ֥⁠י יֹעִ֑ילוּ לֹ֖א עֹזֵ֣ר לָֽ⁠מוֹ׃","náţĕs֗ẇ nĕֽţiybá֫ţi֥⁠y lĕ⁠hawá̇ţi֥⁠y yòʻi֑ylẇ lò֖ʼ ʻòzé֣r láֽ⁠mwò׃"],[30,14,"כְּ⁠פֶ֣רֶץ רָחָ֣ב יֶאֱתָ֑יוּ תַּ֥חַת שֹׁ֝אָ֗ה הִתְגַּלְגָּֽלוּ׃","kĕ̇⁠pe֣reẕ ráẖá֣b yeʼèţá֑yẇ ţȧ֥ẖaţ şò̌֝ʼá֗h hiţĕgȧlĕgáֽ̇lẇ׃"],[30,15,"הָהְפַּ֥ךְ עָלַ֗⁠י בַּלָּ֫ה֥וֹת תִּרְדֹּ֣ף כָּ֭⁠רוּחַ נְדִבָתִ֑⁠י וּ֝⁠כְ⁠עָ֗ב עָבְרָ֥ה יְשֻׁעָתִֽ⁠י׃","háhĕpȧ֥kĕ ʻála֗⁠y bȧlá̇֫h֥wòţ ţi̇rĕdò֣̇p ká֭̇⁠rẇẖa nĕdibáţi֑⁠y ẇ֝⁠kĕ⁠ʻá֗b ʻábĕrá֥h yĕşǔʻáţiֽ⁠y׃"],[30,16,"וְ⁠עַתָּ֗ה עָ֭לַ⁠י תִּשְׁתַּפֵּ֣ךְ נַפְשִׁ֑⁠י יֹ֭אחֲז֣וּ⁠נִי יְמֵי־עֹֽנִי׃","wĕ⁠ʻaţá̇֗h ʻá֭la⁠y ţi̇şĕ̌ţȧpé֣̇kĕ napĕşǐ֑⁠y yò֭ʼẖàz֣ẇ⁠niy yĕméy-ʻòֽniy׃"],[30,17,"לַ֗יְלָה עֲ֭צָמַ⁠י נִקַּ֣ר מֵ⁠עָלָ֑⁠י וְ֝⁠עֹרְקַ֗⁠י לֹ֣א יִשְׁכָּבֽוּ⁠ן׃","la֗yĕláh ʻà֭ẕáma⁠y niqȧ֣r mé⁠ʻálá֑⁠y wĕ֝⁠ʻòrĕqa֗⁠y lò֣ʼ yişĕ̌ká̇bֽẇ⁠n׃"],[30,18,"בְּ⁠רָב־כֹּ֭חַ יִתְחַפֵּ֣שׂ לְבוּשִׁ֑⁠י כְּ⁠פִ֖י כֻתָּנְתִּ֣⁠י יַֽאַזְרֵֽ⁠נִי׃","bĕ̇⁠ráb-kò֭̇ẖa yiţĕẖapé֣̇ş̂ lĕbẇşǐ֑⁠y kĕ̇⁠pi֖y kuţá̇nĕţi֣̇⁠y yaֽʼazĕréֽ⁠niy׃"],[30,19,"הֹרָ֥⁠נִי לַ⁠חֹ֑מֶר וָ֝⁠אֶתְמַשֵּׁ֗ל כֶּ⁠עָפָ֥ר וָ⁠אֵֽפֶר׃","hòrá֥⁠niy la⁠ẖò֑mer wá֝⁠ʼeţĕmaşé̇̌֗l kė⁠ʻápá֥r wá⁠ʼéֽper׃"],[30,20,"אֲשַׁוַּ֣ע אֵ֭לֶי⁠ךָ וְ⁠לֹ֣א תַעֲנֵ֑⁠נִי עָ֝מַ֗דְתִּי וַ⁠תִּתְבֹּ֥נֶן בִּֽ⁠י׃","ʼàşǎwȧ֣ʻ ʼé֭ley⁠ká wĕ⁠lò֣ʼ ţaʻàné֑⁠niy ʻá֝ma֗dĕţi̇y wa⁠ţi̇ţĕbò֥̇nen biֽ̇⁠y׃"],[30,21,"תֵּהָפֵ֣ךְ לְ⁠אַכְזָ֣ר לִ֑⁠י בְּ⁠עֹ֖צֶם יָדְ⁠ךָ֣ תִשְׂטְמֵֽ⁠נִי׃","ţé̇hápé֣kĕ lĕ⁠ʼakĕzá֣r li֑⁠y bĕ̇⁠ʻò֖ẕem yádĕ⁠ká֣ ţişĕ̂tĕméֽ⁠niy׃"],[30,22,"תִּשָּׂאֵ֣⁠נִי אֶל־ר֭וּחַ תַּרְכִּיבֵ֑⁠נִי וּ֝⁠תְמֹגְגֵ֗⁠נִי תשוה׃","ţi̇şá̇̂ʼé֣⁠niy ʼel-r֭ẇẖa ţȧrĕki̇ybé֑⁠niy ẇ֝⁠ţĕmògĕgé֗⁠niy ţşwh׃"],[30,23,"כִּֽי־יָ֭דַעְתִּי מָ֣וֶת תְּשִׁיבֵ֑⁠נִי וּ⁠בֵ֖ית מוֹעֵ֣ד לְ⁠כָל־חָֽי׃","kiֽ̇y-yá֭daʻĕţi̇y má֣weţ ţĕ̇şǐybé֑⁠niy ẇ⁠bé֖yţ mwòʻé֣d lĕ⁠kál-ẖáֽy׃"],[30,24,"אַ֣ךְ לֹא־בְ֭⁠עִי יִשְׁלַח־יָ֑ד אִם־בְּ֝⁠פִיד֗⁠וֹ לָהֶ֥ן שֽׁוּעַ׃","ʼa֣kĕ lòʼ-bĕ֭⁠ʻiy yişĕ̌laẖ-yá֑d ʼim-bĕ̇֝⁠piyd֗⁠wò láhe֥n şֽ̌ẇʻa׃"],[30,25,"אִם־לֹ֣א בָ֭כִיתִי לִ⁠קְשֵׁה־י֑וֹם עָֽגְמָ֥ה נַ֝פְשִׁ֗⁠י לָ⁠אֶבְיֽוֹן׃","ʼim-lò֣ʼ bá֭kiyţiy li⁠qĕşé̌h-y֑wòm ʻáֽgĕmá֥h na֝pĕşǐ֗⁠y lá⁠ʼebĕyֽwòn׃"],[30,26,"כִּ֤י ט֣וֹב קִ֭וִּיתִי וַ⁠יָּ֣בֹא רָ֑ע וַֽ⁠אֲיַחֲלָ֥ה לְ֝⁠א֗וֹר וַ⁠יָּ֥בֹא אֹֽפֶל׃","ki֤̇y t֣wòb qi֭wi̇yţiy wa⁠yá֣̇bòʼ rá֑ʻ waֽ⁠ʼàyaẖàlá֥h lĕ֝⁠ʼ֗wòr wa⁠yá֥̇bòʼ ʼòֽpel׃"],[30,27,"מֵעַ֖⁠י רֻתְּח֥וּ וְ⁠לֹא־דָ֗מּוּ קִדְּמֻ֥⁠נִי יְמֵי־עֹֽנִי׃","méʻa֖⁠y ruţĕ̇ẖ֥ẇ wĕ⁠lòʼ-dá֗ṁẇ qidĕ̇mu֥⁠niy yĕméy-ʻòֽniy׃"],[30,28,"קֹדֵ֣ר הִ֭לַּכְתִּי בְּ⁠לֹ֣א חַמָּ֑ה קַ֖מְתִּי בַ⁠קָּהָ֣ל אֲשַׁוֵּֽעַ׃","qòdé֣r hi֭lȧkĕţi̇y bĕ̇⁠lò֣ʼ ẖamá֑̇h qa֖mĕţi̇y ba⁠qá̇há֣l ʼàşǎwéֽ̇ʻa׃"],[30,29,"אָ֭ח הָיִ֣יתִי לְ⁠תַנִּ֑ים וְ֝⁠רֵ֗עַ לִ⁠בְנ֥וֹת יַעֲנָֽה׃","ʼá֭ẖ háyi֣yţiy lĕ⁠ţani֑̇ym wĕ֝⁠ré֗ʻa li⁠bĕn֥wòţ yaʻànáֽh׃"],[30,30,"ע֭וֹרִ⁠י שָׁחַ֣ר מֵ⁠עָלָ֑⁠י וְ⁠עַצְמִ⁠י־חָ֝֗רָה מִנִּי־חֹֽרֶב׃","ʻ֭wòri⁠y şá̌ẖa֣r mé⁠ʻálá֑⁠y wĕ⁠ʻaẕĕmi⁠y-ẖá֝֗ráh mini̇y-ẖòֽreb׃"],[30,31,"וַ⁠יְהִ֣י לְ֭⁠אֵבֶל כִּנֹּרִ֑⁠י וְ֝⁠עֻגָבִ֗⁠י לְ⁠ק֣וֹל בֹּכִֽים׃","wa⁠yĕhi֣y lĕ֭⁠ʼébel ki̇nò̇ri֑⁠y wĕ֝⁠ʻugábi֗⁠y lĕ⁠q֣wòl bò̇kiֽym׃"],[31,1,"בְּ֭רִית כָּרַ֣תִּי לְ⁠עֵינָ֑⁠י וּ⁠מָ֥ה אֶ֝תְבּוֹנֵ֗ן עַל־בְּתוּלָֽה׃","bĕ֭̇riyţ ká̇ra֣ţi̇y lĕ⁠ʻéyná֑⁠y ẇ⁠má֥h ʼe֝ţĕḃwòné֗n ʻal-bĕ̇ţẇláֽh׃"],[31,2,"וּ⁠מֶ֤ה ׀ חֵ֣לֶק אֱל֣וֹהַּ מִ⁠מָּ֑עַל וְֽ⁠נַחֲלַ֥ת שַׁ֝דַּ֗י מִ⁠מְּרֹמִֽים׃","ẇ⁠me֤h ׀ ẖé֣leq ʼèl֣wòhȧ mi⁠má֑̇ʻal wĕֽ⁠naẖàla֥ţ şǎ֝dȧ֗y mi⁠mĕ̇ròmiֽym׃"],[31,3,"הֲ⁠לֹא־אֵ֥יד לְ⁠עַוָּ֑ל וְ֝⁠נֵ֗כֶר לְ⁠פֹ֣עֲלֵי אָֽוֶן׃","hà⁠lòʼ-ʼé֥yd lĕ⁠ʻawá֑̇l wĕ֝⁠né֗ker lĕ⁠pò֣ʻàléy ʼáֽwen׃"],[31,4,"הֲ⁠לֹא־ה֭וּא יִרְאֶ֣ה דְרָכָ֑⁠י וְֽ⁠כָל־צְעָדַ֥⁠י יִסְפּֽוֹר׃","hà⁠lòʼ-h֭ẇʼ yirĕʼe֣h dĕráká֑⁠y wĕֽ⁠kál-ẕĕʻáda֥⁠y yisĕṗֽwòr׃"],[31,5,"אִם־הָלַ֥כְתִּי עִם־שָׁ֑וְא וַ⁠תַּ֖חַשׁ עַל־מִרְמָ֣ה רַגְלִֽ⁠י׃","ʼim-hála֥kĕţi̇y ʻim-şá֑̌wĕʼ wa⁠ţȧ֖ẖaş̌ ʻal-mirĕmá֣h ragĕliֽ⁠y׃"],[31,6,"יִשְׁקְלֵ֥⁠נִי בְ⁠מֹאזְנֵי־צֶ֑דֶק וְ⁠יֵדַ֥ע אֱ֝ל֗וֹהַּ תֻּמָּתִֽ⁠י׃","yişĕ̌qĕlé֥⁠niy bĕ⁠mòʼzĕnéy-ẕe֑deq wĕ⁠yéda֥ʻ ʼè֝l֗wòhȧ ţu̇má̇ţiֽ⁠y׃"],[31,7,"אִ֥ם תִּטֶּ֣ה אַשֻּׁרִ⁠י֮ מִנִּ֪י הַ֫⁠דָּ֥רֶךְ וְ⁠אַחַ֣ר עֵ֭ינַ⁠י הָלַ֣ךְ לִבִּ֑⁠י וּ֝⁠בְ⁠כַפַּ֗⁠י דָּ֣בַק מֻאֽוּם׃פ","ʼi֥m ţi̇tė֣h ʼaşu̇̌ri⁠y֮ mini֪̇y ha֫⁠dá֥̇rekĕ wĕ⁠ʼaẖa֣r ʻé֭yna⁠y hála֣kĕ libi֑̇⁠y ẇ֝⁠bĕ⁠kapȧ֗⁠y dá֣̇baq muʼֽẇm׃p"],[31,8,"אֶ֭זְרְעָה וְ⁠אַחֵ֣ר יֹאכֵ֑ל וְֽ⁠צֶאֱצָאַ֥⁠י יְשֹׁרָֽשׁוּ׃","ʼe֭zĕrĕʻáh wĕ⁠ʼaẖé֣r yòʼké֑l wĕֽ⁠ẕeʼèẕáʼa֥⁠y yĕşò̌ráֽş̌ẇ׃"],[31,9,"אִם־נִפְתָּ֣ה לִ֭בִּ⁠י עַל־אִשָּׁ֑ה וְ⁠עַל־פֶּ֖תַח רֵעִ֣⁠י אָרָֽבְתִּי׃","ʼim-nipĕţá֣̇h li֭bi̇⁠y ʻal-ʼişá֑̇̌h wĕ⁠ʻal-pė֖ţaẖ réʻi֣⁠y ʼáráֽbĕţi̇y׃"],[31,10,"תִּטְחַ֣ן לְ⁠אַחֵ֣ר אִשְׁתִּ֑⁠י וְ֝⁠עָלֶ֗י⁠הָ יִכְרְע֥וּ⁠ן אֲחֵרִֽין׃","ţi̇tĕẖa֣n lĕ⁠ʼaẖé֣r ʼişĕ̌ţi֑̇⁠y wĕ֝⁠ʻále֗y⁠há yikĕrĕʻ֥ẇ⁠n ʼàẖériֽyn׃"],[31,11,"כִּי־הוא זִמָּ֑ה ו⁠היא עָוֺ֥ן פְּלִילִֽים׃","ki̇y-hwʼ zimá֑̇h w⁠hyʼ ʻáwֺ֥n pĕ̇liyliֽym׃"],[31,12,"כִּ֤י אֵ֣שׁ הִ֭יא עַד־אֲבַדּ֣וֹן תֹּאכֵ֑ל וּֽ⁠בְ⁠כָל־תְּב֖וּאָתִ֣⁠י תְשָׁרֵֽשׁ׃","ki֤̇y ʼé֣ş̌ hi֭yʼ ʻad-ʼàbaḋ֣wòn ţò̇ʼké֑l ẇֽ⁠bĕ⁠kál-ţĕ̇b֖ẇʼáţi֣⁠y ţĕşá̌réֽş̌׃"],[31,13,"אִם־אֶמְאַ֗ס מִשְׁפַּ֣ט עַ֭בְדִּ⁠י וַ⁠אֲמָתִ֑⁠י בְּ֝⁠רִבָ֗⁠ם עִמָּדִֽ⁠י׃","ʼim-ʼemĕʼa֗s mişĕ̌pȧ֣t ʻa֭bĕdi̇⁠y wa⁠ʼàmáţi֑⁠y bĕ̇֝⁠ribá֗⁠m ʻimá̇diֽ⁠y׃"],[31,14,"וּ⁠מָ֣ה אֶֽ֭עֱשֶׂה כִּֽי־יָק֣וּם אֵ֑ל וְ⁠כִֽי־יִ֝פְקֹ֗ד מָ֣ה אֲשִׁיבֶֽ⁠נּוּ׃","ẇ⁠má֣h ʼeֽ֭ʻèşêh kiֽ̇y-yáq֣ẇm ʼé֑l wĕ⁠kiֽy-yi֝pĕqò֗d má֣h ʼàşǐybeֽ⁠ṅẇ׃"],[31,15,"הֲֽ֝⁠לֹא־בַ֭⁠בֶּטֶן עֹשֵׂ֣⁠נִי עָשָׂ֑⁠הוּ וַ֝⁠יְכֻנֶ֗⁠נּוּ בָּ⁠רֶ֥חֶם אֶחָֽד׃","hàֽ֝⁠lòʼ-ba֭⁠bėten ʻòşé֣̂⁠niy ʻáşá֑̂⁠hẇ wa֝⁠yĕkune֗⁠ṅẇ bá̇⁠re֥ẖem ʼeẖáֽd׃"],[31,16,"אִם־אֶ֭מְנַע מֵ⁠חֵ֣פֶץ דַּלִּ֑ים וְ⁠עֵינֵ֖י אַלְמָנָ֣ה אֲכַלֶּֽה׃","ʼim-ʼe֭mĕnaʻ mé⁠ẖé֣peẕ dȧli֑̇ym wĕ⁠ʻéyné֖y ʼalĕmáná֣h ʼàkalėֽh׃"],[31,17,"וְ⁠אֹכַ֣ל פִּתִּ֣⁠י לְ⁠בַדִּ֑⁠י וְ⁠לֹא־אָכַ֖ל יָת֣וֹם מִמֶּֽ⁠נָּה׃","wĕ⁠ʼòka֣l pi̇ţi֣̇⁠y lĕ⁠badi֑̇⁠y wĕ⁠lòʼ-ʼáka֖l yáţ֣wòm mimėֽ⁠ná̇h׃"],[31,18,"כִּ֣י מִ֭⁠נְּעוּרַ⁠י גְּדֵלַ֣⁠נִי כְ⁠אָ֑ב וּ⁠מִ⁠בֶּ֖טֶן אִמִּ֣⁠י אַנְחֶֽ⁠נָּה׃","ki֣̇y mi֭⁠nĕ̇ʻẇra⁠y gĕ̇déla֣⁠niy kĕ⁠ʼá֑b ẇ⁠mi⁠bė֖ten ʼimi֣̇⁠y ʼanĕẖeֽ⁠ná̇h׃"],[31,19,"אִם־אֶרְאֶ֣ה א֭וֹבֵד מִ⁠בְּלִ֣י לְב֑וּשׁ וְ⁠אֵ֥ין כְּ֝ס֗וּת לָ⁠אֶבְיֽוֹן׃","ʼim-ʼerĕʼe֣h ʼ֭wòbéd mi⁠bĕ̇li֣y lĕb֑ẇş̌ wĕ⁠ʼé֥yn kĕ̇֝s֗ẇţ lá⁠ʼebĕyֽwòn׃"],[31,20,"אִם־לֹ֣א בֵרֲכ֣וּ⁠נִי חלצ⁠ו וּ⁠מִ⁠גֵּ֥ז כְּ֝בָשַׂ⁠י יִתְחַמָּֽם׃","ʼim-lò֣ʼ béràk֣ẇ⁠niy ẖlẕ⁠w ẇ⁠mi⁠gé֥̇z kĕ̇֝báşâ⁠y yiţĕẖamáֽ̇m׃"],[31,21,"אִם־הֲנִיפ֣וֹתִי עַל־יָת֣וֹם יָדִ֑⁠י כִּֽי־אֶרְאֶ֥ה בַ֝⁠שַּׁ֗עַר עֶזְרָתִֽ⁠י׃","ʼim-hàniyp֣wòţiy ʻal-yáţ֣wòm yádi֑⁠y kiֽ̇y-ʼerĕʼe֥h ba֝⁠şȧ̌֗ʻar ʻezĕráţiֽ⁠y׃"],[31,22,"כְּ֭תֵפִ⁠י מִ⁠שִּׁכְמָ֣⁠ה תִפּ֑וֹל וְ֝⁠אֶזְרֹעִ֗⁠י מִ⁠קָּנָ֥⁠ה תִשָּׁבֵֽר׃","kĕ֭̇ţépi⁠y mi⁠şi̇̌kĕmá֣⁠h ţiṗ֑wòl wĕ֝⁠ʼezĕròʻi֗⁠y mi⁠qá̇ná֥⁠h ţişá̇̌béֽr׃"],[31,23,"כִּ֤י פַ֣חַד אֵ֭לַ⁠י אֵ֣יד אֵ֑ל וּ֝⁠מִ⁠שְּׂאֵת֗⁠וֹ לֹ֣א אוּכָֽל׃","ki֤̇y pa֣ẖad ʼé֭la⁠y ʼé֣yd ʼé֑l ẇ֝⁠mi⁠şĕ̇̂ʼéţ֗⁠wò lò֣ʼ ʼẇkáֽl׃"],[31,24,"אִם־שַׂ֣מְתִּי זָהָ֣ב כִּסְלִ֑⁠י וְ֝⁠לַ⁠כֶּ֗תֶם אָמַ֥רְתִּי מִבְטַחִֽ⁠י׃","ʼim-şâ֣mĕţi̇y záhá֣b ki̇sĕli֑⁠y wĕ֝⁠la⁠kė֗ţem ʼáma֥rĕţi̇y mibĕtaẖiֽ⁠y׃"],[31,25,"אִם־אֶ֭שְׂמַח כִּי־רַ֣ב חֵילִ֑⁠י וְ⁠כִֽי־כַ֝בִּ֗יר מָצְאָ֥ה יָדִֽ⁠י׃","ʼim-ʼe֭şĕ̂maẖ ki̇y-ra֣b ẖéyli֑⁠y wĕ⁠kiֽy-ka֝bi̇֗yr máẕĕʼá֥h yádiֽ⁠y׃"],[31,26,"אִם־אֶרְאֶ֣ה א֖וֹר כִּ֣י יָהֵ֑ל וְ֝⁠יָרֵ֗חַ יָקָ֥ר הֹלֵֽךְ׃","ʼim-ʼerĕʼe֣h ʼ֖wòr ki֣̇y yáhé֑l wĕ֝⁠yáré֗ẖa yáqá֥r hòléֽkĕ׃"],[31,27,"וַ⁠יִּ֣פְתְּ בַּ⁠סֵּ֣תֶר לִבִּ֑⁠י וַ⁠תִּשַּׁ֖ק יָדִ֣⁠י לְ⁠פִֽ⁠י׃","wa⁠yi֣̇pĕţĕ̇ bȧ⁠sé֣̇ţer libi֑̇⁠y wa⁠ţi̇şȧ֖̌q yádi֣⁠y lĕ⁠piֽ⁠y׃"],[31,28,"גַּם־ה֭וּא עָוֺ֣ן פְּלִילִ֑י כִּֽי־כִחַ֖שְׁתִּי לָ⁠אֵ֣ל מִ⁠מָּֽעַל׃","gȧm-h֭ẇʼ ʻáwֺ֣n pĕ̇liyli֑y kiֽ̇y-kiẖa֖şĕ̌ţi̇y lá⁠ʼé֣l mi⁠máֽ̇ʻal׃"],[31,29,"אִם־אֶ֭שְׂמַח בְּ⁠פִ֣יד מְשַׂנְאִ֑⁠י וְ֝⁠הִתְעֹרַ֗רְתִּי כִּֽי־מְצָ֥א⁠וֹ רָֽע׃","ʼim-ʼe֭şĕ̂maẖ bĕ̇⁠pi֣yd mĕşânĕʼi֑⁠y wĕ֝⁠hiţĕʻòra֗rĕţi̇y kiֽ̇y-mĕẕá֥ʼ⁠wò ráֽʻ׃"],[31,30,"וְ⁠לֹא־נָתַ֣תִּי לַ⁠חֲטֹ֣א חִכִּ֑⁠י לִ⁠שְׁאֹ֖ל בְּ⁠אָלָ֣ה נַפְשֽׁ⁠וֹ׃","wĕ⁠lòʼ-náţa֣ţi̇y la⁠ẖàtò֣ʼ ẖiki֑̇⁠y li⁠şĕ̌ʼò֖l bĕ̇⁠ʼálá֣h napĕşֽ̌⁠wò׃"],[31,31,"אִם־לֹ֣א אָ֭מְרוּ מְתֵ֣י אָהֳלִ֑⁠י מִֽי־יִתֵּ֥ן מִ֝⁠בְּשָׂר֗⁠וֹ לֹ֣א נִשְׂבָּֽע׃","ʼim-lò֣ʼ ʼá֭mĕrẇ mĕţé֣y ʼáholi֑⁠y miֽy-yiţé֥̇n mi֝⁠bĕ̇şá̂r֗⁠wò lò֣ʼ nişĕ̂báֽ̇ʻ׃"],[31,32,"בַּ֭⁠חוּץ לֹא־יָלִ֣ין גֵּ֑ר דְּ֝לָתַ֗⁠י לָ⁠אֹ֥רַח אֶפְתָּֽח׃","bȧ֭⁠ẖẇẕ lòʼ-yáli֣yn gé֑̇r dĕ̇֝láţa֗⁠y lá⁠ʼò֥raẖ ʼepĕţáֽ̇ẖ׃"],[31,33,"אִם־כִּסִּ֣יתִי כְ⁠אָדָ֣ם פְּשָׁעָ֑⁠י לִ⁠טְמ֖וֹן בְּ⁠חֻבִּ֣⁠י עֲוֺֽנִ⁠י׃","ʼim-ki̇si֣̇yţiy kĕ⁠ʼádá֣m pĕ̇şá̌ʻá֑⁠y li⁠tĕm֖wòn bĕ̇⁠ẖubi֣̇⁠y ʻàwֺֽni⁠y׃"],[31,34,"כִּ֤י אֶֽעֱר֨וֹץ ׀ הָ֘מ֤וֹן רַבָּ֗ה וּ⁠בוּז־מִשְׁפָּח֥וֹת יְחִתֵּ֑⁠נִי וָ֝⁠אֶדֹּ֗ם לֹא־אֵ֥צֵא פָֽתַח׃","ki֤̇y ʼeֽʻèr֨wòẕ ׀ há֘m֤wòn rabá̇֗h ẇ⁠bẇz-mişĕ̌pá̇ẖ֥wòţ yĕẖiţé֑̇⁠niy wá֝⁠ʼedò̇֗m lòʼ-ʼé֥ẕéʼ páֽţaẖ׃"],[31,35,"מִ֤י יִתֶּן־לִ֨⁠י ׀ שֹׁ֘מֵ֤עַֽ לִ֗⁠י הֶן־תָּ֭וִ⁠י שַׁדַּ֣י יַעֲנֵ֑⁠נִי וְ⁠סֵ֥פֶר כָּ֝תַ֗ב אִ֣ישׁ רִיבִֽ⁠י׃","mi֤y yiţėn-li֨⁠y ׀ şò̌֘mé֤ʻaֽ li֗⁠y hen-ţá֭̇wi⁠y şǎdȧ֣y yaʻàné֑⁠niy wĕ⁠sé֥per ká̇֝ţa֗b ʼi֣yş̌ riybiֽ⁠y׃"],[31,36,"אִם־לֹ֣א עַל־שִׁ֭כְמִ⁠י אֶשָּׂאֶ֑⁠נּוּ אֶֽעֶנְדֶ֖⁠נּוּ עֲטָר֣וֹת לִֽ⁠י׃","ʼim-lò֣ʼ ʻal-şǐ֭kĕmi⁠y ʼeşá̇̂ʼe֑⁠ṅẇ ʼeֽʻenĕde֖⁠ṅẇ ʻàtár֣wòţ liֽ⁠y׃"],[31,37,"מִסְפַּ֣ר צְ֭עָדַ⁠י אַגִּידֶ֑⁠נּוּ כְּמוֹ־נָ֝גִ֗יד אֲקָרֲבֶֽ⁠נּוּ׃","misĕpȧ֣r ẕĕ֭ʻáda⁠y ʼagi̇yde֑⁠ṅẇ kĕ̇mwò-ná֝gi֗yd ʼàqáràbeֽ⁠ṅẇ׃"],[31,38,"אִם־עָ֭לַ⁠י אַדְמָתִ֣⁠י תִזְעָ֑ק וְ֝⁠יַ֗חַד תְּלָמֶ֥י⁠הָ יִבְכָּיֽוּ⁠ן׃","ʼim-ʻá֭la⁠y ʼadĕmáţi֣⁠y ţizĕʻá֑q wĕ֝⁠ya֗ẖad ţĕ̇láme֥y⁠há yibĕká̇yֽẇ⁠n׃"],[31,39,"אִם־כֹּ֭חָ⁠הּ אָכַ֣לְתִּי בְלִי־כָ֑סֶף וְ⁠נֶ֖פֶשׁ בְּעָלֶ֣י⁠הָ הִפָּֽחְתִּי׃","ʼim-kò֭̇ẖá⁠ḣ ʼáka֣lĕţi̇y bĕliy-ká֑sep wĕ⁠ne֖peş̌ bĕ̇ʻále֣y⁠há hipáֽ̇ẖĕţi̇y׃"],[31,40,"תַּ֤חַת חִטָּ֨ה ׀ יֵ֥צֵא ח֗וֹחַ וְ⁠תַֽחַת־שְׂעֹרָ֥ה בָאְשָׁ֑ה תַּ֝֗מּוּ דִּבְרֵ֥י אִיּֽוֹב׃פ","ţȧ֤ẖaţ ẖitá̇֨h ׀ yé֥ẕéʼ ẖ֗wòẖa wĕ⁠ţaֽẖaţ-şĕ̂ʻòrá֥h báʼĕşá֑̌h ţȧ֝֗ṁẇ di̇bĕré֥y ʼiẏֽwòb׃p"],[32,1,"וַֽ⁠יִּשְׁבְּת֡וּ שְׁלֹ֤שֶׁת הָ⁠אֲנָשִׁ֣ים הָ֭⁠אֵלֶּה מֵ⁠עֲנ֣וֹת אֶת־אִיּ֑וֹב כִּ֤י ה֖וּא צַדִּ֣יק בְּ⁠עֵינָֽי⁠ו׃פ","waֽ⁠yi̇şĕ̌bĕ̇ţ֡ẇ şĕ̌lò֤şěţ há⁠ʼànáşǐ֣ym há֭⁠ʼélėh mé⁠ʻàn֣wòţ ʼeţ-ʼiẏ֑wòb ki֤̇y h֖ẇʼ ẕadi֣̇yq bĕ̇⁠ʻéynáֽy⁠w׃p"],[32,2,"וַ⁠יִּ֤חַר אַ֨ף ׀ אֱלִיה֣וּא בֶן־בַּרַכְאֵ֣ל הַ⁠בּוּזִי֮ מִ⁠מִּשְׁפַּ֪חַ֫ת רָ֥ם בְּ֭⁠אִיּוֹב חָרָ֣ה אַפּ֑⁠וֹ עַֽל־צַדְּק֥⁠וֹ נַ֝פְשׁ֗⁠וֹ מֵ⁠אֱלֹהִֽים׃","wa⁠yi֤̇ẖar ʼa֨p ׀ ʼèliyh֣ẇʼ ben-bȧrakĕʼé֣l ha⁠ḃẇziy֮ mi⁠mi̇şĕ̌pȧ֪ẖa֫ţ rá֥m bĕ֭̇⁠ʼiẏwòb ẖárá֣h ʼaṗ֑⁠wò ʻaֽl-ẕadĕ̇q֥⁠wò na֝pĕş̌֗⁠wò mé⁠ʼèlòhiֽym׃"],[32,3,"וּ⁠בִ⁠שְׁלֹ֣שֶׁת רֵעָי⁠ו֮ חָרָ֪ה אַ֫פּ֥⁠וֹ עַ֤ל אֲשֶׁ֣ר לֹא־מָצְא֣וּ מַעֲנֶ֑ה וַ֝⁠יַּרְשִׁ֗יעוּ אֶת־אִיּֽוֹב׃","ẇ⁠bi⁠şĕ̌lò֣şěţ réʻáy⁠w֮ ẖárá֪h ʼa֫ṗ֥⁠wò ʻa֤l ʼàşě֣r lòʼ-máẕĕʼ֣ẇ maʻàne֑h wa֝⁠yȧrĕşǐ֗yʻẇ ʼeţ-ʼiẏֽwòb׃"],[32,4,"וֶֽ⁠אֱלִיה֗וּ חִכָּ֣ה אֶת־אִ֭יּוֹב בִּ⁠דְבָרִ֑ים כִּ֤י זְֽקֵנִים־הֵ֖מָּה מִמֶּ֣⁠נּוּ לְ⁠יָמִֽים׃","weֽ⁠ʼèliyh֗ẇ ẖiká֣̇h ʼeţ-ʼi֭ẏwòb bi̇⁠dĕbári֑ym ki֤̇y zĕֽqéniym-hé֖má̇h mimė֣⁠ṅẇ lĕ⁠yámiֽym׃"],[32,5,"וַ⁠יַּ֤רְא אֱלִיה֗וּא כִּ֘י אֵ֤ין מַעֲנֶ֗ה בְּ֭⁠פִי שְׁלֹ֥שֶׁת הָ⁠אֲנָשִׁ֗ים וַ⁠יִּ֥חַר אַפּֽ⁠וֹ׃פ","wa⁠yȧ֤rĕʼ ʼèliyh֗ẇʼ ki̇֘y ʼé֤yn maʻàne֗h bĕ֭̇⁠piy şĕ̌lò֥şěţ há⁠ʼànáşǐ֗ym wa⁠yi֥̇ẖar ʼaṗֽ⁠wò׃p"],[32,6,"וַ⁠יַּ֤עַן ׀ אֱלִיה֖וּא בֶן־בַּֽרַכְאֵ֥ל הַ⁠בּוּזִ֗י וַ⁠יֹּ֫אמַ֥ר צָ֘עִ֤יר אֲנִ֣י לְ֭⁠יָמִים וְ⁠אַתֶּ֣ם יְשִׁישִׁ֑ים עַל־כֵּ֖ן זָחַ֥לְתִּי וָֽ⁠אִירָ֓א ׀ מֵ⁠חַוֺּ֖ת דֵּעִ֣⁠י אֶתְ⁠כֶֽם׃","wa⁠yȧ֤ʻan ׀ ʼèliyh֖ẇʼ ben-bȧֽrakĕʼé֥l ha⁠ḃẇzi֗y wa⁠yò̇֫ʼma֥r ẕá֘ʻi֤yr ʼàni֣y lĕ֭⁠yámiym wĕ⁠ʼaţė֣m yĕşǐyşǐ֑ym ʻal-ké֖̇n záẖa֥lĕţi̇y wáֽ⁠ʼiyrá֓ʼ ׀ mé⁠ẖaẇֺ֖ţ dé̇ʻi֣⁠y ʼeţĕ⁠keֽm׃"],[32,7,"אָ֭מַרְתִּי יָמִ֣ים יְדַבֵּ֑רוּ וְ⁠רֹ֥ב שָׁ֝נִ֗ים יֹדִ֥יעוּ חָכְמָֽה׃","ʼá֭marĕţi̇y yámi֣ym yĕdabé֑̇rẇ wĕ⁠rò֥b şá̌֝ni֗ym yòdi֥yʻẇ ẖákĕmáֽh׃"],[32,8,"אָ֭כֵן רֽוּחַ־הִ֣יא בֶ⁠אֱנ֑וֹשׁ וְ⁠נִשְׁמַ֖ת שַׁדַּ֣י תְּבִינֵֽ⁠ם׃","ʼá֭kén rֽẇẖa-hi֣yʼ be⁠ʼèn֑wòş̌ wĕ⁠nişĕ̌ma֖ţ şǎdȧ֣y ţĕ̇biynéֽ⁠m׃"],[32,9,"לֹֽא־רַבִּ֥ים יֶחְכָּ֑מוּ וּ֝⁠זְקֵנִ֗ים יָבִ֥ינוּ מִשְׁפָּֽט׃","lòֽʼ-rabi֥̇ym yeẖĕká֑̇mẇ ẇ֝⁠zĕqéni֗ym yábi֥ynẇ mişĕ̌páֽ̇t׃"],[32,10,"לָ⁠כֵ֣ן אָ֭מַרְתִּי שִׁמְעָ⁠ה־לִּ֑⁠י אֲחַוֶּ֖ה דֵּעִ֣⁠י אַף־אָֽנִי׃","lá⁠ké֣n ʼá֭marĕţi̇y şǐmĕʻá⁠h-li֑̇⁠y ʼàẖawė֖h dé̇ʻi֣⁠y ʼap-ʼáֽniy׃"],[32,11,"הֵ֤ן הוֹחַ֨לְתִּי לְֽ⁠דִבְרֵי⁠כֶ֗ם אָ֭זִין עַד־תְּב֥וּנֹֽתֵי⁠כֶ֑ם עַֽד־תַּחְקְר֥וּ⁠ן מִלִּֽין׃","hé֤n hwòẖa֨lĕţi̇y lĕֽ⁠dibĕréy⁠ke֗m ʼá֭ziyn ʻad-ţĕ̇b֥ẇnòֽţéy⁠ke֑m ʻaֽd-ţȧẖĕqĕr֥ẇ⁠n miliֽ̇yn׃"],[32,12,"וְ⁠עָֽדֵי⁠כֶ֗ם אֶתְבּ֫וֹנָ֥ן וְ⁠הִנֵּ֤ה אֵ֣ין לְ⁠אִיּ֣וֹב מוֹכִ֑יחַ עוֹנֶ֖ה אֲמָרָ֣י⁠ו מִ⁠כֶּֽם׃","wĕ⁠ʻáֽdéy⁠ke֗m ʼeţĕḃ֫wòná֥n wĕ⁠hiné֤̇h ʼé֣yn lĕ⁠ʼiẏ֣wòb mwòki֑yẖa ʻwòne֖h ʼàmárá֣y⁠w mi⁠kėֽm׃"],[32,13,"פֶּן־תֹּ֣֭אמְרוּ מָצָ֣אנוּ חָכְמָ֑ה אֵ֖ל יִדְּפֶ֣⁠נּוּ לֹא־אִֽישׁ׃","pėn-ţò֣֭̇ʼmĕrẇ máẕá֣ʼnẇ ẖákĕmá֑h ʼé֖l yidĕ̇pe֣⁠ṅẇ lòʼ-ʼiֽyş̌׃"],[32,14,"וְ⁠לֹא־עָרַ֣ךְ אֵלַ֣⁠י מִלִּ֑ין וּ֝⁠בְ⁠אִמְרֵי⁠כֶ֗ם לֹ֣א אֲשִׁיבֶֽ⁠נּוּ׃","wĕ⁠lòʼ-ʻára֣kĕ ʼéla֣⁠y mili֑̇yn ẇ֝⁠bĕ⁠ʼimĕréy⁠ke֗m lò֣ʼ ʼàşǐybeֽ⁠ṅẇ׃"],[32,15,"חַ֭תּוּ לֹא־עָ֣נוּ ע֑וֹד הֶעְתִּ֖יקוּ מֵ⁠הֶ֣ם מִלִּֽים׃","ẖa֭ţ̇ẇ lòʼ-ʻá֣nẇ ʻ֑wòd heʻĕţi֖̇yqẇ mé⁠he֣m miliֽ̇ym׃"],[32,16,"וְ֭⁠הוֹחַלְתִּי כִּי־לֹ֣א יְדַבֵּ֑רוּ כִּ֥י עָ֝מְד֗וּ לֹא־עָ֥נוּ עֽוֹד׃","wĕ֭⁠hwòẖalĕţi̇y ki̇y-lò֣ʼ yĕdabé֑̇rẇ ki֥̇y ʻá֝mĕd֗ẇ lòʼ-ʻá֥nẇ ʻֽwòd׃"],[32,17,"אַעֲנֶ֣ה אַף־אֲנִ֣י חֶלְקִ֑⁠י אֲחַוֶּ֖ה דֵעִ֣⁠י אַף־אָֽנִי׃","ʼaʻàne֣h ʼap-ʼàni֣y ẖelĕqi֑⁠y ʼàẖawė֖h déʻi֣⁠y ʼap-ʼáֽniy׃"],[32,18,"כִּ֭י מָלֵ֣תִי מִלִּ֑ים הֱ֝צִיקַ֗תְ⁠נִי ר֣וּחַ בִּטְנִֽ⁠י׃","ki֭̇y málé֣ţiy mili֑̇ym hè֝ẕiyqa֗ţĕ⁠niy r֣ẇẖa bi̇tĕniֽ⁠y׃"],[32,19,"הִנֵּֽה־בִטְנִ֗⁠י כְּ⁠יַ֥יִן לֹא־יִפָּתֵ֑חַ כְּ⁠אֹב֥וֹת חֲ֝דָשִׁ֗ים יִבָּקֵֽעַ׃","hinéֽ̇h-bitĕni֗⁠y kĕ̇⁠ya֥yin lòʼ-yipá̇ţé֑ẖa kĕ̇⁠ʼòb֥wòţ ẖà֝dáşǐ֗ym yibá̇qéֽʻa׃"],[32,20,"אֲדַבְּרָ֥ה וְ⁠יִֽרְוַֽח־לִ֑⁠י אֶפְתַּ֖ח שְׂפָתַ֣⁠י וְ⁠אֶֽעֱנֶֽה׃","ʼàdabĕ̇rá֥h wĕ⁠yiֽrĕwaֽẖ-li֑⁠y ʼepĕţȧ֖ẖ şĕ̂páţa֣⁠y wĕ⁠ʼeֽʻèneֽh׃"],[32,21,"אַל־נָ֭א אֶשָּׂ֣א פְנֵי־אִ֑ישׁ וְ⁠אֶל־אָ֝דָ֗ם לֹ֣א אֲכַנֶּֽה׃","ʼal-ná֭ʼ ʼeşá֣̇̂ʼ pĕnéy-ʼi֑yş̌ wĕ⁠ʼel-ʼá֝dá֗m lò֣ʼ ʼàkanėֽh׃"],[32,22,"כִּ֤י לֹ֣א יָדַ֣עְתִּי אֲכַנֶּ֑ה כִּ֝⁠מְעַ֗ט יִשָּׂאֵ֥⁠נִי עֹשֵֽׂ⁠נִי׃","ki֤̇y lò֣ʼ yáda֣ʻĕţi̇y ʼàkanė֑h ki̇֝⁠mĕʻa֗t yişá̇̂ʼé֥⁠niy ʻòşéֽ̂⁠niy׃"],[33,1,"וְֽ⁠אוּלָ֗ם שְׁמַֽע־נָ֣א אִיּ֣וֹב מִלָּ֑⁠י וְֽ⁠כָל־דְּבָרַ֥⁠י הַאֲזִֽינָ⁠ה׃","wĕֽ⁠ʼẇlá֗m şĕ̌maֽʻ-ná֣ʼ ʼiẏ֣wòb milá֑̇⁠y wĕֽ⁠kál-dĕ̇bára֥⁠y haʼàziֽyná⁠h׃"],[33,2,"הִנֵּה־נָ֭א פָּתַ֣חְתִּי פִ֑⁠י דִּבְּרָ֖ה לְשׁוֹנִ֣⁠י בְ⁠חִכִּֽ⁠י׃","hiné̇h-ná֭ʼ pá̇ţa֣ẖĕţi̇y pi֑⁠y di̇bĕ̇rá֖h lĕş̌wòni֣⁠y bĕ⁠ẖikiֽ̇⁠y׃"],[33,3,"יֹֽשֶׁר־לִבִּ֥⁠י אֲמָרָ֑⁠י וְ⁠דַ֥עַת שְׂ֝פָתַ֗⁠י בָּר֥וּר מִלֵּֽלוּ׃","yòֽşěr-libi֥̇⁠y ʼàmárá֑⁠y wĕ⁠da֥ʻaţ şĕ̂֝páţa֗⁠y bá̇r֥ẇr miléֽ̇lẇ׃"],[33,4,"רֽוּחַ־אֵ֥ל עָשָׂ֑תְ⁠נִי וְ⁠נִשְׁמַ֖ת שַׁדַּ֣י תְּחַיֵּֽ⁠נִי׃","rֽẇẖa-ʼé֥l ʻáşá֑̂ţĕ⁠niy wĕ⁠nişĕ̌ma֖ţ şǎdȧ֣y ţĕ̇ẖayéֽ̇⁠niy׃"],[33,5,"אִם־תּוּכַ֥ל הֲשִׁיבֵ֑⁠נִי עֶרְכָ֥⁠ה לְ֝⁠פָנַ֗⁠י הִתְיַצָּֽבָ⁠ה׃","ʼim-ţ̇ẇka֥l hàşǐybé֑⁠niy ʻerĕká֥⁠h lĕ֝⁠pána֗⁠y hiţĕyaẕáֽ̇bá⁠h׃"],[33,6,"הֵן־אֲנִ֣י כְ⁠פִ֣י⁠ךָ לָ⁠אֵ֑ל מֵ֝⁠חֹ֗מֶר קֹרַ֥צְתִּי גַם־אָֽנִי׃","hén-ʼàni֣y kĕ⁠pi֣y⁠ká lá⁠ʼé֑l mé֝⁠ẖò֗mer qòra֥ẕĕţi̇y gam-ʼáֽniy׃"],[33,7,"הִנֵּ֣ה אֵ֭מָתִ⁠י לֹ֣א תְבַעֲתֶ֑⁠ךָּ וְ֝⁠אַכְפִּ֗⁠י עָלֶ֥י⁠ךָ לֹא־יִכְבָּֽד׃","hiné֣̇h ʼé֭máţi⁠y lò֣ʼ ţĕbaʻàţe֑⁠ká̇ wĕ֝⁠ʼakĕpi̇֗⁠y ʻále֥y⁠ká lòʼ-yikĕbáֽ̇d׃"],[33,8,"אַ֭ךְ אָמַ֣רְתָּ בְ⁠אָזְנָ֑⁠י וְ⁠ק֖וֹל מִלִּ֣ין אֶשְׁמָֽע׃","ʼa֭kĕ ʼáma֣rĕţá̇ bĕ⁠ʼázĕná֑⁠y wĕ⁠q֖wòl mili֣̇yn ʼeşĕ̌máֽʻ׃"],[33,9,"זַ֥ךְ אֲנִ֗י בְּֽלִ֫י פָ֥שַׁע חַ֥ף אָנֹכִ֑י וְ⁠לֹ֖א עָוֺ֣ן לִֽ⁠י׃","za֥kĕ ʼàni֗y bĕֽ̇li֫y pá֥şǎʻ ẖa֥p ʼánòki֑y wĕ⁠lò֖ʼ ʻáwֺ֣n liֽ⁠y׃"],[33,10,"הֵ֣ן תְּ֭נוּאוֹת עָלַ֣⁠י יִמְצָ֑א יַחְשְׁבֵ֖⁠נִי לְ⁠אוֹיֵ֣ב לֽ⁠וֹ׃","hé֣n ţĕ֭̇nẇʼwòţ ʻála֣⁠y yimĕẕá֑ʼ yaẖĕşĕ̌bé֖⁠niy lĕ⁠ʼwòyé֣b lֽ⁠wò׃"],[33,11,"יָשֵׂ֣ם בַּ⁠סַּ֣ד רַגְלָ֑⁠י יִ֝שְׁמֹ֗ר כָּל־אָרְחֹתָֽ⁠י׃","yáşé֣̂m bȧ⁠sȧ֣d ragĕlá֑⁠y yi֝şĕ̌mò֗r ká̇l-ʼárĕẖòţáֽ⁠y׃"],[33,12,"הֶן־זֹ֣את לֹא־צָדַ֣קְתָּ אֶעֱנֶ֑⁠ךָּ כִּֽי־יִרְבֶּ֥ה אֱ֝ל֗וֹהַ מֵ⁠אֱנֽוֹשׁ׃","hen-zò֣ʼţ lòʼ-ẕáda֣qĕţá̇ ʼeʻène֑⁠ká̇ kiֽ̇y-yirĕbė֥h ʼè֝l֗wòha mé⁠ʼènֽwòş̌׃"],[33,13,"מַ֭דּוּעַ אֵלָ֣י⁠ו רִיב֑וֹתָ כִּ֥י כָל־דְּ֝בָרָ֗י⁠ו לֹ֣א־יַעֲנֶֽה׃","ma֭ḋẇʻa ʼélá֣y⁠w riyb֑wòţá ki֥̇y kál-dĕ̇֝bárá֗y⁠w lò֣ʼ-yaʻàneֽh׃"],[33,14,"כִּֽי־בְ⁠אַחַ֥ת יְדַבֶּר־אֵ֑ל וּ֝⁠בִ⁠שְׁתַּ֗יִם לֹ֣א יְשׁוּרֶֽ⁠נָּה׃","kiֽ̇y-bĕ⁠ʼaẖa֥ţ yĕdabėr-ʼé֑l ẇ֝⁠bi⁠şĕ̌ţȧ֗yim lò֣ʼ yĕş̌ẇreֽ⁠ná̇h׃"],[33,15,"בַּ⁠חֲל֤וֹם ׀ חֶזְי֬וֹן לַ֗יְלָה בִּ⁠נְפֹ֣ל תַּ֭רְדֵּמָה עַל־אֲנָשִׁ֑ים בִּ֝⁠תְנוּמ֗וֹת עֲלֵ֣י מִשְׁכָּֽב׃","bȧ⁠ẖàl֤wòm ׀ ẖezĕy֬wòn la֗yĕláh bi̇⁠nĕpò֣l ţȧ֭rĕdé̇máh ʻal-ʼànáşǐ֑ym bi̇֝⁠ţĕnẇm֗wòţ ʻàlé֣y mişĕ̌káֽ̇b׃"],[33,16,"אָ֣ז יִ֭גְלֶה אֹ֣זֶן אֲנָשִׁ֑ים וּ⁠בְ⁠מֹ֖סָרָ֣⁠ם יַחְתֹּֽם׃","ʼá֣z yi֭gĕleh ʼò֣zen ʼànáşǐ֑ym ẇ⁠bĕ⁠mò֖sárá֣⁠m yaẖĕţòֽ̇m׃"],[33,17,"לְ֭⁠הָסִיר אָדָ֣ם מַעֲשֶׂ֑ה וְ⁠גֵוָ֖ה מִ⁠גֶּ֣בֶר יְכַסֶּֽה׃","lĕ֭⁠hásiyr ʼádá֣m maʻàşê֑h wĕ⁠géwá֖h mi⁠gė֣ber yĕkasėֽh׃"],[33,18,"יַחְשֹׂ֣ךְ נַ֭פְשׁ⁠וֹ מִנִּי־שָׁ֑חַת וְ֝⁠חַיָּת֗⁠וֹ מֵ⁠עֲבֹ֥ר בַּ⁠שָּֽׁלַח׃","yaẖĕşò֣̂kĕ na֭pĕş̌⁠wò mini̇y-şá֑̌ẖaţ wĕ֝⁠ẖayá̇ţ֗⁠wò mé⁠ʻàbò֥r bȧ⁠şáֽ̇̌laẖ׃"],[33,19,"וְ⁠הוּכַ֣ח בְּ֭⁠מַכְאוֹב עַל־מִשְׁכָּב֑⁠וֹ ו⁠ריב עֲצָמָ֣י⁠ו אֵתָֽן׃","wĕ⁠hẇka֣ẖ bĕ֭̇⁠makĕʼwòb ʻal-mişĕ̌ká̇b֑⁠wò w⁠ryb ʻàẕámá֣y⁠w ʼéţáֽn׃"],[33,20,"וְ⁠זִֽהֲמַ֣תּ⁠וּ חַיָּת֣⁠וֹ לָ֑חֶם וְ֝⁠נַפְשׁ֗⁠וֹ מַאֲכַ֥ל תַּאֲוָֽה׃","wĕ⁠ziֽhàma֣ţ̇⁠ẇ ẖayá̇ţ֣⁠wò lá֑ẖem wĕ֝⁠napĕş̌֗⁠wò maʼàka֥l ţȧʼàwáֽh׃"],[33,21,"יִ֣כֶל בְּשָׂר֣⁠וֹ מֵ⁠רֹ֑אִי ו⁠שפי עַ֝צְמוֹתָ֗י⁠ו לֹ֣א רֻאּֽוּ׃","yi֣kel bĕ̇şá̂r֣⁠wò mé⁠rò֑ʼiy w⁠şpy ʻa֝ẕĕmwòţá֗y⁠w lò֣ʼ ruʼֽ̇ẇ׃"],[33,22,"וַ⁠תִּקְרַ֣ב לַ⁠שַּׁ֣חַת נַפְשׁ֑⁠וֹ וְ֝⁠חַיָּת֗⁠וֹ לַֽ⁠מְמִתִֽים׃","wa⁠ţi̇qĕra֣b la⁠şȧ֣̌ẖaţ napĕş֑̌⁠wò wĕ֝⁠ẖayá̇ţ֗⁠wò laֽ⁠mĕmiţiֽym׃"],[33,23,"אִם־יֵ֤שׁ עָלָ֨י⁠ו ׀ מַלְאָ֗ךְ מֵלִ֗יץ אֶחָ֥ד מִנִּי־אָ֑לֶף לְ⁠הַגִּ֖יד לְ⁠אָדָ֣ם יָשְׁרֽ⁠וֹ׃","ʼim-yé֤ş̌ ʻálá֨y⁠w ׀ malĕʼá֗kĕ méli֗yẕ ʼeẖá֥d mini̇y-ʼá֑lep lĕ⁠hagi֖̇yd lĕ⁠ʼádá֣m yáşĕ̌rֽ⁠wò׃"],[33,24,"וַ⁠יְחֻנֶּ֗⁠נּוּ וַ⁠יֹּ֗אמֶר פְּ֭דָעֵ⁠הוּ מֵ⁠רֶ֥דֶת שָׁ֗חַת מָצָ֥אתִי כֹֽפֶר׃","wa⁠yĕẖunė֗⁠ṅẇ wa⁠yò̇֗ʼmer pĕ֭̇dáʻé⁠hẇ mé⁠re֥deţ şá̌֗ẖaţ máẕá֥ʼţiy kòֽper׃"],[33,25,"רֻֽטֲפַ֣שׁ בְּשָׂר֣⁠וֹ מִ⁠נֹּ֑עַר יָ֝שׁ֗וּב לִ⁠ימֵ֥י עֲלוּמָֽי⁠ו׃","ruֽtàpa֣ş̌ bĕ̇şá̂r֣⁠wò mi⁠nò֑̇ʻar yá֝ş̌֗ẇb li⁠ymé֥y ʻàlẇmáֽy⁠w׃"],[33,26,"יֶעְתַּ֤ר אֶל־אֱל֨וֹהַּ ׀ וַ⁠יִּרְצֵ֗⁠הוּ וַ⁠יַּ֣רְא פָּ֭נָי⁠ו בִּ⁠תְרוּעָ֑ה וַ⁠יָּ֥שֶׁב לֶ֝⁠אֱנ֗וֹשׁ צִדְקָתֽ⁠וֹ׃","yeʻĕţȧ֤r ʼel-ʼèl֨wòhȧ ׀ wa⁠yi̇rĕẕé֗⁠hẇ wa⁠yȧ֣rĕʼ pá֭̇náy⁠w bi̇⁠ţĕrẇʻá֑h wa⁠yá֥̇şěb le֝⁠ʼèn֗wòş̌ ẕidĕqáţֽ⁠wò׃"],[33,27,"יָשֹׁ֤ר ׀ עַל־אֲנָשִׁ֗ים וַ⁠יֹּ֗אמֶר חָ֭טָאתִי וְ⁠יָשָׁ֥ר הֶעֱוֵ֗יתִי וְ⁠לֹא־שָׁ֥וָה לִֽ⁠י׃","yáşò֤̌r ׀ ʻal-ʼànáşǐ֗ym wa⁠yò̇֗ʼmer ẖá֭táʼţiy wĕ⁠yáşá֥̌r heʻèwé֗yţiy wĕ⁠lòʼ-şá֥̌wáh liֽ⁠y׃"],[33,28,"פָּדָ֣ה נפש⁠י מֵ⁠עֲבֹ֣ר בַּ⁠שָּׁ֑חַת ו⁠חית⁠י בָּ⁠א֥וֹר תִּרְאֶֽה׃","pá̇dá֣h npş⁠y mé⁠ʻàbò֣r bȧ⁠şá֑̇̌ẖaţ w⁠ẖyţ⁠y bá̇⁠ʼ֥wòr ţi̇rĕʼeֽh׃"],[33,29,"הֶן־כָּל־אֵ֭לֶּה יִפְעַל־אֵ֑ל פַּעֲמַ֖יִם שָׁל֣וֹשׁ עִם־גָּֽבֶר׃","hen-ká̇l-ʼé֭lėh yipĕʻal-ʼé֑l pȧʻàma֖yim şá̌l֣wòş̌ ʻim-gáֽ̇ber׃"],[33,30,"לְ⁠הָשִׁ֣יב נַ֭פְשׁ⁠וֹ מִנִּי־שָׁ֑חַת לֵ֝⁠א֗וֹר בְּ⁠א֣וֹר הַֽ⁠חַיִּים׃","lĕ⁠háşǐ֣yb na֭pĕş̌⁠wò mini̇y-şá֑̌ẖaţ lé֝⁠ʼ֗wòr bĕ̇⁠ʼ֣wòr haֽ⁠ẖayi̇ym׃"],[33,31,"הַקְשֵׁ֖ב אִיּ֥וֹב שְֽׁמַֽע־לִ֑⁠י הַ֝חֲרֵ֗שׁ וְ⁠אָנֹכִ֥י אֲדַבֵּֽר׃","haqĕşé֖̌b ʼiẏ֥wòb şĕֽ̌maֽʻ-li֑⁠y ha֝ẖàré֗ş̌ wĕ⁠ʼánòki֥y ʼàdabéֽ̇r׃"],[33,32,"אִם־יֵשׁ־מִלִּ֥ין הֲשִׁיבֵ֑⁠נִי דַּ֝בֵּ֗ר כִּֽי־חָפַ֥צְתִּי צַדְּקֶֽ⁠ךָּ׃","ʼim-yéş̌-mili֥̇yn hàşǐybé֑⁠niy dȧ֝bé̇֗r kiֽ̇y-ẖápa֥ẕĕţi̇y ẕadĕ̇qeֽ⁠ká̇׃"],[33,33,"אִם־אַ֭יִן אַתָּ֥ה שְֽׁמַֽע־לִ֑⁠י הַ֝חֲרֵ֗שׁ וַ⁠אֲאַלֶּפְ⁠ךָ֥ חָכְמָֽה׃ס","ʼim-ʼa֭yin ʼaţá֥̇h şĕֽ̌maֽʻ-li֑⁠y ha֝ẖàré֗ş̌ wa⁠ʼàʼalėpĕ⁠ká֥ ẖákĕmáֽh׃s"],[34,1,"וַ⁠יַּ֥עַן אֱלִיה֗וּא וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼèliyh֗ẇʼ wa⁠yò̇ʼmaֽr׃"],[34,2,"שִׁמְע֣וּ חֲכָמִ֣ים מִלָּ֑⁠י וְ֝⁠יֹדְעִ֗ים הַאֲזִ֥ינוּ לִֽ⁠י׃","şǐmĕʻ֣ẇ ẖàkámi֣ym milá֑̇⁠y wĕ֝⁠yòdĕʻi֗ym haʼàzi֥ynẇ liֽ⁠y׃"],[34,3,"כִּי־אֹ֭זֶן מִלִּ֣ין תִּבְחָ֑ן וְ֝⁠חֵ֗ךְ יִטְעַ֥ם לֶ⁠אֱכֹֽל׃","ki̇y-ʼò֭zen mili֣̇yn ţi̇bĕẖá֑n wĕ֝⁠ẖé֗kĕ yitĕʻa֥m le⁠ʼèkòֽl׃"],[34,4,"מִשְׁפָּ֥ט נִבְחֲרָה־לָּ֑⁠נוּ נֵדְעָ֖ה בֵינֵ֣י⁠נוּ מַה־טּֽוֹב׃","mişĕ̌pá֥̇t nibĕẖàráh-lá֑̇⁠nẇ nédĕʻá֖h béyné֣y⁠nẇ mah-ṫֽwòb׃"],[34,5,"כִּֽי־אָ֭מַר אִיּ֣וֹב צָדַ֑קְתִּי וְ֝⁠אֵ֗ל הֵסִ֥יר מִשְׁפָּטִֽ⁠י׃","kiֽ̇y-ʼá֭mar ʼiẏ֣wòb ẕáda֑qĕţi̇y wĕ֝⁠ʼé֗l hési֥yr mişĕ̌pá̇tiֽ⁠y׃"],[34,6,"עַל־מִשְׁפָּטִ֥⁠י אֲכַזֵּ֑ב אָנ֖וּשׁ חִצִּ֣⁠י בְלִי־פָֽשַׁע׃","ʻal-mişĕ̌pá̇ti֥⁠y ʼàkazé֑̇b ʼán֖ẇş̌ ẖiẕi֣̇⁠y bĕliy-páֽşǎʻ׃"],[34,7,"מִי־גֶ֥בֶר כְּ⁠אִיּ֑וֹב יִֽשְׁתֶּה־לַּ֥עַג כַּ⁠מָּֽיִם׃","miy-ge֥ber kĕ̇⁠ʼiẏ֑wòb yiֽşĕ̌ţėh-lȧ֥ʻag kȧ⁠máֽ̇yim׃"],[34,8,"וְ⁠אָרַ֣ח לְ֭⁠חֶבְרָה עִם־פֹּ֣עֲלֵי אָ֑וֶן וְ֝⁠לָ⁠לֶ֗כֶת עִם־אַנְשֵׁי־רֶֽשַׁע׃","wĕ⁠ʼára֣ẖ lĕ֭⁠ẖebĕráh ʻim-pò֣̇ʻàléy ʼá֑wen wĕ֝⁠lá⁠le֗keţ ʻim-ʼanĕşé̌y-reֽşǎʻ׃"],[34,9,"כִּֽי־אָ֭מַר לֹ֣א יִסְכָּן־גָּ֑בֶר בִּ֝⁠רְצֹת֗⁠וֹ עִם־אֱלֹהִֽים׃","kiֽ̇y-ʼá֭mar lò֣ʼ yisĕká̇n-gá֑̇ber bi̇֝⁠rĕẕòţ֗⁠wò ʻim-ʼèlòhiֽym׃"],[34,10,"לָ⁠כֵ֤ן ׀ אַ֥נֲשֵׁ֥י לֵבָ֗ב שִׁמְע֫וּ לִ֥⁠י חָלִ֖לָ⁠ה לָ⁠אֵ֥ל מֵ⁠רֶ֗שַׁע וְ⁠שַׁדַּ֥י מֵ⁠עָֽוֶל׃","lá⁠ké֤n ׀ ʼa֥nàşé֥̌y lébá֗b şǐmĕʻ֫ẇ li֥⁠y ẖáli֖lá⁠h lá⁠ʼé֥l mé⁠re֗şǎʻ wĕ⁠şǎdȧ֥y mé⁠ʻáֽwel׃"],[34,11,"כִּ֤י פֹ֣עַל אָ֭דָם יְשַׁלֶּם־ל֑⁠וֹ וּֽ⁠כְ⁠אֹ֥רַח אִ֝֗ישׁ יַמְצִאֶֽ⁠נּוּ׃","ki֤̇y pò֣ʻal ʼá֭dám yĕşǎlėm-l֑⁠wò ẇֽ⁠kĕ⁠ʼò֥raẖ ʼi֝֗yş̌ yamĕẕiʼeֽ⁠ṅẇ׃"],[34,12,"אַף־אָמְנָ֗ם אֵ֥ל לֹֽא־יַרְשִׁ֑יעַ וְ֝⁠שַׁדַּ֗י לֹֽא־יְעַוֵּ֥ת מִשְׁפָּֽט׃","ʼap-ʼámĕná֗m ʼé֥l lòֽʼ-yarĕşǐ֑yʻa wĕ֝⁠şǎdȧ֗y lòֽʼ-yĕʻawé֥̇ţ mişĕ̌páֽ̇t׃"],[34,13,"מִֽי־פָקַ֣ד עָלָ֣י⁠ו אָ֑רְצָ⁠ה וּ⁠מִ֥י שָׂ֝֗ם תֵּבֵ֥ל כֻּלָּֽ⁠הּ׃","miֽy-páqa֣d ʻálá֣y⁠w ʼá֑rĕẕá⁠h ẇ⁠mi֥y şá̂֝֗m ţé̇bé֥l ku̇láֽ̇⁠ḣ׃"],[34,14,"אִם־יָשִׂ֣ים אֵלָ֣י⁠ו לִבּ֑⁠וֹ רוּח֥⁠וֹ וְ֝⁠נִשְׁמָת֗⁠וֹ אֵלָ֥י⁠ו יֶאֱסֹֽף׃","ʼim-yáşî֣ym ʼélá֣y⁠w liḃ֑⁠wò rẇẖ֥⁠wò wĕ֝⁠nişĕ̌máţ֗⁠wò ʼélá֥y⁠w yeʼèsòֽp׃"],[34,15,"יִגְוַ֣ע כָּל־בָּשָׂ֣ר יָ֑חַד וְ֝⁠אָדָ֗ם עַל־עָפָ֥ר יָשֽׁוּב׃","yigĕwa֣ʻ ká̇l-bá̇şá֣̂r yá֑ẖad wĕ֝⁠ʼádá֗m ʻal-ʻápá֥r yáşֽ̌ẇb׃"],[34,16,"וְ⁠אִם־בִּ֥ינָה שִׁמְעָ⁠ה־זֹּ֑את הַ֝אֲזִ֗ינָ⁠ה לְ⁠ק֣וֹל מִלָּֽ⁠י׃","wĕ⁠ʼim-bi֥̇ynáh şǐmĕʻá⁠h-zò֑̇ʼţ ha֝ʼàzi֗yná⁠h lĕ⁠q֣wòl miláֽ̇⁠y׃"],[34,17,"הַ⁠אַ֬ף שׂוֹנֵ֣א מִשְׁפָּ֣ט יַחֲב֑וֹשׁ וְ⁠אִם־צַדִּ֖יק כַּבִּ֣יר תַּרְשִֽׁיעַ׃","ha⁠ʼa֬p ş̂wòné֣ʼ mişĕ̌pá֣̇t yaẖàb֑wòş̌ wĕ⁠ʼim-ẕadi֖̇yq kȧbi֣̇yr ţȧrĕşǐֽyʻa׃"],[34,18,"הַ⁠אֲמֹ֣ר לְ⁠מֶ֣לֶךְ בְּלִיָּ֑עַל רָ֝שָׁ֗ע אֶל־נְדִיבִֽים׃","ha⁠ʼàmò֣r lĕ⁠me֣lekĕ bĕ̇liyá֑̇ʻal rá֝şá̌֗ʻ ʼel-nĕdiybiֽym׃"],[34,19,"אֲשֶׁ֤ר לֹֽא־נָשָׂ֨א ׀ פְּנֵ֥י שָׂרִ֗ים וְ⁠לֹ֣א נִכַּר־שׁ֭וֹעַ לִ⁠פְנֵי־דָ֑ל כִּֽי־מַעֲשֵׂ֖ה יָדָ֣י⁠ו כֻּלָּֽ⁠ם׃","ʼàşě֤r lòֽʼ-náşá̂֨ʼ ׀ pĕ̇né֥y şá̂ri֗ym wĕ⁠lò֣ʼ nikȧr-ş֭̌wòʻa li⁠pĕnéy-dá֑l kiֽ̇y-maʻàşé֖̂h yádá֣y⁠w ku̇láֽ̇⁠m׃"],[34,20,"רֶ֤גַע ׀ יָמֻתוּ֮ וַ⁠חֲצ֪וֹת לָ֥יְלָה יְגֹעֲשׁ֣וּ עָ֣ם וְ⁠יַעֲבֹ֑רוּ וְ⁠יָסִ֥ירוּ אַ֝בִּ֗יר לֹ֣א בְ⁠יָֽד׃","re֤gaʻ ׀ yámuţẇ֮ wa⁠ẖàẕ֪wòţ lá֥yĕláh yĕgòʻàş֣̌ẇ ʻá֣m wĕ⁠yaʻàbò֑rẇ wĕ⁠yási֥yrẇ ʼa֝bi̇֗yr lò֣ʼ bĕ⁠yáֽd׃"],[34,21,"כִּי־עֵ֭ינָי⁠ו עַל־דַּרְכֵי־אִ֑ישׁ וְֽ⁠כָל־צְעָדָ֥י⁠ו יִרְאֶֽה׃","ki̇y-ʻé֭ynáy⁠w ʻal-dȧrĕkéy-ʼi֑yş̌ wĕֽ⁠kál-ẕĕʻádá֥y⁠w yirĕʼeֽh׃"],[34,22,"אֵֽין־חֹ֭שֶׁךְ וְ⁠אֵ֣ין צַלְמָ֑וֶת לְ⁠הִסָּ֥תֶר שָׁ֝֗ם פֹּ֣עֲלֵי אָֽוֶן׃","ʼéֽyn-ẖò֭şěkĕ wĕ⁠ʼé֣yn ẕalĕmá֑weţ lĕ⁠hisá֥̇ţer şá̌֝֗m pò֣̇ʻàléy ʼáֽwen׃"],[34,23,"כִּ֤י לֹ֣א עַל־אִ֭ישׁ יָשִׂ֣ים ע֑וֹד לַ⁠הֲלֹ֥ךְ אֶל־אֵ֝֗ל בַּ⁠מִּשְׁפָּֽט׃","ki֤̇y lò֣ʼ ʻal-ʼi֭yş̌ yáşî֣ym ʻ֑wòd la⁠hàlò֥kĕ ʼel-ʼé֝֗l bȧ⁠mi̇şĕ̌páֽ̇t׃"],[34,24,"יָרֹ֣עַ כַּבִּירִ֣ים לֹא־חֵ֑קֶר וַ⁠יַּעֲמֵ֖ד אֲחֵרִ֣ים תַּחְתָּֽ⁠ם׃","yárò֣ʻa kȧbi̇yri֣ym lòʼ-ẖé֑qer wa⁠yȧʻàmé֖d ʼàẖéri֣ym ţȧẖĕţáֽ̇⁠m׃"],[34,25,"לָ⁠כֵ֗ן יַ֭כִּיר מַעְבָּֽדֵי⁠הֶ֑ם וְ⁠הָ֥פַךְ לַ֝֗יְלָה וְ⁠יִדַּכָּֽאוּ׃","lá⁠ké֗n ya֭ki̇yr maʻĕbáֽ̇déy⁠he֑m wĕ⁠há֥pakĕ la֝֗yĕláh wĕ⁠yidȧkáֽ̇ʼẇ׃"],[34,26,"תַּֽחַת־רְשָׁעִ֥ים סְפָקָ֗⁠ם בִּ⁠מְק֥וֹם רֹאִֽים׃","ţȧֽẖaţ-rĕşá̌ʻi֥ym sĕpáqá֗⁠m bi̇⁠mĕq֥wòm ròʼiֽym׃"],[34,27,"אֲשֶׁ֣ר עַל־כֵּ֭ן סָ֣רוּ מֵֽ⁠אַחֲרָ֑י⁠ו וְ⁠כָל־דְּ֝רָכָ֗י⁠ו לֹ֣א הִשְׂכִּֽילוּ׃","ʼàşě֣r ʻal-ké֭̇n sá֣rẇ méֽ⁠ʼaẖàrá֑y⁠w wĕ⁠kál-dĕ̇֝ráká֗y⁠w lò֣ʼ hişĕ̂kiֽ̇ylẇ׃"],[34,28,"לְ⁠הָבִ֣יא עָ֭לָי⁠ו צַֽעֲקַת־דָּ֑ל וְ⁠צַעֲקַ֖ת עֲנִיִּ֣ים יִשְׁמָֽע׃","lĕ⁠hábi֣yʼ ʻá֭láy⁠w ẕaֽʻàqaţ-dá֑̇l wĕ⁠ẕaʻàqa֖ţ ʻàniyi֣̇ym yişĕ̌máֽʻ׃"],[34,29,"וְ⁠ה֤וּא יַשְׁקִ֨ט ׀ וּ⁠מִ֥י יַרְשִׁ֗עַ וְ⁠יַסְתֵּ֣ר פָּ֭נִים וּ⁠מִ֣י יְשׁוּרֶ֑⁠נּוּ וְ⁠עַל־גּ֖וֹי וְ⁠עַל־אָדָ֣ם יָֽחַד׃","wĕ⁠h֤ẇʼ yaşĕ̌qi֨t ׀ ẇ⁠mi֥y yarĕşǐ֗ʻa wĕ⁠yasĕţé֣̇r pá֭̇niym ẇ⁠mi֣y yĕş̌ẇre֑⁠ṅẇ wĕ⁠ʻal-ġ֖wòy wĕ⁠ʻal-ʼádá֣m yáֽẖad׃"],[34,30,"מִ֭⁠מְּלֹךְ אָדָ֥ם חָנֵ֗ף מִ⁠מֹּ֥קְשֵׁי עָֽם׃","mi֭⁠mĕ̇lòkĕ ʼádá֥m ẖáné֗p mi⁠mò֥̇qĕşé̌y ʻáֽm׃"],[34,31,"כִּֽי־אֶל־אֵ֭ל הֶ⁠אָמַ֥ר נָשָׂ֗אתִי לֹ֣א אֶחְבֹּֽל׃","kiֽ̇y-ʼel-ʼé֭l he⁠ʼáma֥r náşá̂֗ʼţiy lò֣ʼ ʼeẖĕbòֽ̇l׃"],[34,32,"בִּלְעֲדֵ֣י אֶ֭חֱזֶה אַתָּ֣ה הֹרֵ֑⁠נִי אִֽם־עָ֥וֶל פָּ֝עַ֗לְתִּי לֹ֣א אֹסִֽיף׃","bi̇lĕʻàdé֣y ʼe֭ẖèzeh ʼaţá֣̇h hòré֑⁠niy ʼiֽm-ʻá֥wel pá̇֝ʻa֗lĕţi̇y lò֣ʼ ʼòsiֽyp׃"],[34,33,"הַֽ⁠מֵ⁠עִמְּ⁠ךָ֬ יְשַׁלְמֶ֨⁠נָּה כִּֽי־מָאַ֗סְתָּ כִּי־אַתָּ֣ה תִבְחַ֣ר וְ⁠לֹא־אָ֑נִי וּֽ⁠מַה־יָדַ֥עְתָּ דַבֵּֽר׃","haֽ⁠mé⁠ʻimĕ̇⁠ká֬ yĕşǎlĕme֨⁠ná̇h kiֽ̇y-máʼa֗sĕţá̇ ki̇y-ʼaţá֣̇h ţibĕẖa֣r wĕ⁠lòʼ-ʼá֑niy ẇֽ⁠mah-yáda֥ʻĕţá̇ dabéֽ̇r׃"],[34,34,"אַנְשֵׁ֣י לֵ֭בָב יֹ֣אמְרוּ לִ֑⁠י וְ⁠גֶ֥בֶר חָ֝כָ֗ם שֹׁמֵ֥עַֽ לִֽ⁠י׃","ʼanĕşé֣̌y lé֭báb yò֣ʼmĕrẇ li֑⁠y wĕ⁠ge֥ber ẖá֝ká֗m şò̌mé֥ʻaֽ liֽ⁠y׃"],[34,35,"אִ֭יּוֹב לֹא־בְ⁠דַ֣עַת יְדַבֵּ֑ר וּ֝⁠דְבָרָ֗י⁠ו לֹ֣א בְ⁠הַשְׂכֵּֽיל׃","ʼi֭ẏwòb lòʼ-bĕ⁠da֣ʻaţ yĕdabé֑̇r ẇ֝⁠dĕbárá֗y⁠w lò֣ʼ bĕ⁠haşĕ̂kéֽ̇yl׃"],[34,36,"אָבִ֗י יִבָּחֵ֣ן אִיּ֣וֹב עַד־נֶ֑צַח עַל־תְּ֝שֻׁבֹ֗ת בְּ⁠אַנְשֵׁי־אָֽוֶן׃","ʼábi֗y yibá̇ẖé֣n ʼiẏ֣wòb ʻad-ne֑ẕaẖ ʻal-ţĕ̇֝şǔbò֗ţ bĕ̇⁠ʼanĕşé̌y-ʼáֽwen׃"],[34,37,"כִּ֥י יֹ֘סִ֤יף עַֽל־חַטָּאת֣⁠וֹ פֶ֭שַׁע בֵּינֵ֣י⁠נוּ יִסְפּ֑וֹק וְ⁠יֶ֖רֶב אֲמָרָ֣י⁠ו לָ⁠אֵֽל׃ס","ki֥̇y yò֘si֤yp ʻaֽl-ẖatá̇ʼţ֣⁠wò pe֭şǎʻ bé̇yné֣y⁠nẇ yisĕṗ֑wòq wĕ⁠ye֖reb ʼàmárá֣y⁠w lá⁠ʼéֽl׃s"],[35,1,"וַ⁠יַּ֥עַן אֱלִיה֗וּ וַ⁠יֹּאמַֽר׃","wa⁠yȧ֥ʻan ʼèliyh֗ẇ wa⁠yò̇ʼmaֽr׃"],[35,2,"הֲ֭⁠זֹאת חָשַׁ֣בְתָּ לְ⁠מִשְׁפָּ֑ט אָ֝מַ֗רְתָּ צִדְקִ֥⁠י מֵ⁠אֵֽל׃","hà֭⁠zòʼţ ẖáşǎ֣bĕţá̇ lĕ⁠mişĕ̌pá֑̇t ʼá֝ma֗rĕţá̇ ẕidĕqi֥⁠y mé⁠ʼéֽl׃"],[35,3,"כִּֽי־תֹ֭אמַר מַה־יִּסְכָּן־לָ֑⁠ךְ מָֽה־אֹ֝עִ֗יל מֵֽ⁠חַטָּאתִֽ⁠י׃","kiֽ̇y-ţò֭ʼmar mah-yi̇sĕká̇n-lá֑⁠kĕ máֽh-ʼò֝ʻi֗yl méֽ⁠ẖatá̇ʼţiֽ⁠y׃"],[35,4,"אֲ֭נִי אֲשִֽׁיבְ⁠ךָ֣ מִלִּ֑ין וְֽ⁠אֶת־רֵעֶ֥י⁠ךָ עִמָּֽ⁠ךְ׃","ʼà֭niy ʼàşǐֽybĕ⁠ká֣ mili֑̇yn wĕֽ⁠ʼeţ-réʻe֥y⁠ká ʻimáֽ̇⁠kĕ׃"],[35,5,"הַבֵּ֣ט שָׁמַ֣יִם וּ⁠רְאֵ֑ה וְ⁠שׁ֥וּר שְׁ֝חָקִ֗ים גָּבְה֥וּ מִמֶּֽ⁠ךָּ׃","habé֣̇t şá̌ma֣yim ẇ⁠rĕʼé֑h wĕ⁠ş֥̌ẇr şĕ̌֝ẖáqi֗ym gá̇bĕh֥ẇ mimėֽ⁠ká̇׃"],[35,6,"אִם־חָ֭טָאתָ מַה־תִּפְעָל־בּ֑⁠וֹ וְ⁠רַבּ֥וּ פְ֝שָׁעֶ֗י⁠ךָ מַה־תַּעֲשֶׂה־לּֽ⁠וֹ׃","ʼim-ẖá֭táʼţá mah-ţi̇pĕʻál-ḃ֑⁠wò wĕ⁠raḃ֥ẇ pĕ֝şá̌ʻe֗y⁠ká mah-ţȧʻàşêh-lֽ̇⁠wò׃"],[35,7,"אִם־צָ֭דַקְתָּ מַה־תִּתֶּן־ל֑⁠וֹ א֥וֹ מַה־מִ⁠יָּדְ⁠ךָ֥ יִקָּֽח׃","ʼim-ẕá֭daqĕţá̇ mah-ţi̇ţėn-l֑⁠wò ʼ֥wò mah-mi⁠yá̇dĕ⁠ká֥ yiqáֽ̇ẖ׃"],[35,8,"לְ⁠אִישׁ־כָּמ֥וֹ⁠ךָ רִשְׁעֶ֑⁠ךָ וּ⁠לְ⁠בֶן־אָ֝דָ֗ם צִדְקָתֶֽ⁠ךָ׃","lĕ⁠ʼiyş̌-ká̇m֥wò⁠ká rişĕ̌ʻe֑⁠ká ẇ⁠lĕ⁠ben-ʼá֝dá֗m ẕidĕqáţeֽ⁠ká׃"],[35,9,"מֵ֭⁠רֹב עֲשׁוּקִ֣ים יַזְעִ֑יקוּ יְשַׁוְּע֖וּ מִ⁠זְּר֣וֹעַ רַבִּֽים׃","mé֭⁠ròb ʻàş̌ẇqi֣ym yazĕʻi֑yqẇ yĕşǎwĕ̇ʻ֖ẇ mi⁠zĕ̇r֣wòʻa rabiֽ̇ym׃"],[35,10,"וְֽ⁠לֹא־אָמַ֗ר אַ֭יֵּה אֱל֣וֹהַּ עֹשָׂ֑⁠י נֹתֵ֖ן זְמִר֣וֹת בַּ⁠לָּֽיְלָה׃","wĕֽ⁠lòʼ-ʼáma֗r ʼa֭yé̇h ʼèl֣wòhȧ ʻòşá֑̂⁠y nòţé֖n zĕmir֣wòţ bȧ⁠láֽ̇yĕláh׃"],[35,11,"מַ֭לְּפֵ⁠נוּ מִ⁠בַּהֲמ֣וֹת אָ֑רֶץ וּ⁠מֵ⁠ע֖וֹף הַ⁠שָּׁמַ֣יִם יְחַכְּמֵֽ⁠נוּ׃","ma֭lĕ̇pé⁠nẇ mi⁠bȧhàm֣wòţ ʼá֑reẕ ẇ⁠mé⁠ʻ֖wòp ha⁠şá̇̌ma֣yim yĕẖakĕ̇méֽ⁠nẇ׃"],[35,12,"שָׁ֣ם יִ֭צְעֲקוּ וְ⁠לֹ֣א יַעֲנֶ֑ה מִ֝⁠פְּנֵ֗י גְּא֣וֹן רָעִֽים׃","şá֣̌m yi֭ẕĕʻàqẇ wĕ⁠lò֣ʼ yaʻàne֑h mi֝⁠pĕ̇né֗y gĕ̇ʼ֣wòn ráʻiֽym׃"],[35,13,"אַךְ־שָׁ֭וְא לֹא־יִשְׁמַ֥ע ׀ אֵ֑ל וְ֝⁠שַׁדַּ֗י לֹ֣א יְשׁוּרֶֽ⁠נָּה׃","ʼakĕ-şá֭̌wĕʼ lòʼ-yişĕ̌ma֥ʻ ׀ ʼé֑l wĕ֝⁠şǎdȧ֗y lò֣ʼ yĕş̌ẇreֽ⁠ná̇h׃"],[35,14,"אַ֣ף כִּֽי־תֹ֭אמַר לֹ֣א תְשׁוּרֶ֑⁠נּוּ דִּ֥ין לְ֝⁠פָנָ֗י⁠ו וּ⁠תְח֥וֹלֵֽל לֽ⁠וֹ׃","ʼa֣p kiֽ̇y-ţò֭ʼmar lò֣ʼ ţĕş̌ẇre֑⁠ṅẇ di֥̇yn lĕ֝⁠páná֗y⁠w ẇ⁠ţĕẖ֥wòléֽl lֽ⁠wò׃"],[35,15,"וְ⁠עַתָּ֗ה כִּי־אַ֭יִן פָּקַ֣ד אַפּ֑⁠וֹ וְ⁠לֹֽא־יָדַ֖ע בַּ⁠פַּ֣שׁ מְאֹֽד׃","wĕ⁠ʻaţá̇֗h ki̇y-ʼa֭yin pá̇qa֣d ʼaṗ֑⁠wò wĕ⁠lòֽʼ-yáda֖ʻ bȧ⁠pȧ֣ş̌ mĕʼòֽd׃"],[35,16,"וְ֭⁠אִיּוֹב הֶ֣בֶל יִפְצֶה־פִּ֑י⁠הוּ בִּ⁠בְלִי־דַ֝֗עַת מִלִּ֥ין יַכְבִּֽר׃פ","wĕ֭⁠ʼiẏwòb he֣bel yipĕẕeh-pi֑̇y⁠hẇ bi̇⁠bĕliy-da֝֗ʻaţ mili֥̇yn yakĕbiֽ̇r׃p"],[36,1,"וַ⁠יֹּ֥סֶף אֱלִיה֗וּא וַ⁠יֹּאמַֽר׃","wa⁠yò֥̇sep ʼèliyh֗ẇʼ wa⁠yò̇ʼmaֽr׃"],[36,2,"כַּתַּר־לִ֣⁠י זְ֭עֵיר וַ⁠אֲחַוֶּ֑⁠ךָּ כִּ֤י ע֖וֹד לֶ⁠אֱל֣וֹהַּ מִלִּֽים׃","kȧţȧr-li֣⁠y zĕ֭ʻéyr wa⁠ʼàẖawė֑⁠ká̇ ki֤̇y ʻ֖wòd le⁠ʼèl֣wòhȧ miliֽ̇ym׃"],[36,3,"אֶשָּׂ֣א דֵ֭עִ⁠י לְ⁠מֵ⁠רָח֑וֹק וּ֝⁠לְ⁠פֹעֲלִ֗⁠י אֶֽתֵּֽן־צֶֽדֶק׃","ʼeşá֣̇̂ʼ dé֭ʻi⁠y lĕ⁠mé⁠ráẖ֑wòq ẇ֝⁠lĕ⁠pòʻàli֗⁠y ʼeֽţéֽ̇n-ẕeֽdeq׃"],[36,4,"כִּֽי־אָ֭מְנָם לֹא־שֶׁ֣קֶר מִלָּ֑⁠י תְּמִ֖ים דֵּע֣וֹת עִמָּֽ⁠ךְ׃","kiֽ̇y-ʼá֭mĕnám lòʼ-şě֣qer milá֑̇⁠y ţĕ̇mi֖ym dé̇ʻ֣wòţ ʻimáֽ̇⁠kĕ׃"],[36,5,"הֶן־אֵ֣ל כַּ֭בִּיר וְ⁠לֹ֣א יִמְאָ֑ס כַּ֝בִּ֗יר כֹּ֣חַֽ לֵֽב׃","hen-ʼé֣l kȧ֭bi̇yr wĕ⁠lò֣ʼ yimĕʼá֑s kȧ֝bi̇֗yr kò֣̇ẖaֽ léֽb׃"],[36,6,"לֹא־יְחַיֶּ֥ה רָשָׁ֑ע וּ⁠מִשְׁפַּ֖ט עֲנִיִּ֣ים יִתֵּֽן׃","lòʼ-yĕẖayė֥h ráşá֑̌ʻ ẇ⁠mişĕ̌pȧ֖t ʻàniyi֣̇ym yiţéֽ̇n׃"],[36,7,"לֹֽא־יִגְרַ֥ע מִ⁠צַּדִּ֗יק עֵ֫ינָ֥י⁠ו וְ⁠אֶת־מְלָכִ֥ים לַ⁠כִּסֵּ֑א וַ⁠יֹּשִׁיבֵ֥⁠ם לָ֝⁠נֶ֗צַח וַ⁠יִּגְבָּֽהוּ׃","lòֽʼ-yigĕra֥ʻ mi⁠ẕȧdi̇֗yq ʻé֫yná֥y⁠w wĕ⁠ʼeţ-mĕláki֥ym la⁠ki̇sé֑̇ʼ wa⁠yò̇şǐybé֥⁠m lá֝⁠ne֗ẕaẖ wa⁠yi̇gĕbáֽ̇hẇ׃"],[36,8,"וְ⁠אִם־אֲסוּרִ֥ים בַּ⁠זִּקִּ֑ים יִ֝לָּכְד֗וּ⁠ן בְּ⁠חַבְלֵי־עֹֽנִי׃","wĕ⁠ʼim-ʼàsẇri֥ym bȧ⁠zi̇qi֑̇ym yi֝lá̇kĕd֗ẇ⁠n bĕ̇⁠ẖabĕléy-ʻòֽniy׃"],[36,9,"וַ⁠יַּגֵּ֣ד לָ⁠הֶ֣ם פָּעֳלָ֑⁠ם וּ֝⁠פִשְׁעֵי⁠הֶ֗ם כִּ֣י יִתְגַּבָּֽרוּ׃","wa⁠yȧgé֣̇d lá⁠he֣m pá̇ʻolá֑⁠m ẇ֝⁠pişĕ̌ʻéy⁠he֗m ki֣̇y yiţĕgȧbáֽ̇rẇ׃"],[36,10,"וַ⁠יִּ֣גֶל אָ֭זְנָ⁠ם לַ⁠מּוּסָ֑ר וַ֝⁠יֹּ֗אמֶר כִּֽי־יְשֻׁב֥וּ⁠ן מֵ⁠אָֽוֶן׃","wa⁠yi֣̇gel ʼá֭zĕná⁠m la⁠ṁẇsá֑r wa֝⁠yò̇֗ʼmer kiֽ̇y-yĕşǔb֥ẇ⁠n mé⁠ʼáֽwen׃"],[36,11,"אִֽם־יִשְׁמְע֗וּ וְֽ⁠יַ֫עֲבֹ֥דוּ יְכַלּ֣וּ יְמֵי⁠הֶ֣ם בַּ⁠טּ֑וֹב וּ֝⁠שְׁנֵי⁠הֶ֗ם בַּ⁠נְּעִימִֽים׃","ʼiֽm-yişĕ̌mĕʻ֗ẇ wĕֽ⁠ya֫ʻàbò֥dẇ yĕkal֣̇ẇ yĕméy⁠he֣m bȧ⁠ṫ֑wòb ẇ֝⁠şĕ̌néy⁠he֗m bȧ⁠nĕ̇ʻiymiֽym׃"],[36,12,"וְ⁠אִם־לֹ֣א יִ֭שְׁמְעוּ בְּ⁠שֶׁ֣לַח יַעֲבֹ֑רוּ וְ֝⁠יִגְוְע֗וּ כִּ⁠בְלִי־דָֽעַת׃","wĕ⁠ʼim-lò֣ʼ yi֭şĕ̌mĕʻẇ bĕ̇⁠şě֣laẖ yaʻàbò֑rẇ wĕ֝⁠yigĕwĕʻ֗ẇ ki̇⁠bĕliy-dáֽʻaţ׃"],[36,13,"וְֽ⁠חַנְפֵי־לֵ֭ב יָשִׂ֣ימוּ אָ֑ף לֹ֥א יְ֝שַׁוְּע֗וּ כִּ֣י אֲסָרָֽ⁠ם׃","wĕֽ⁠ẖanĕpéy-lé֭b yáşî֣ymẇ ʼá֑p lò֥ʼ yĕ֝şǎwĕ̇ʻ֗ẇ ki֣̇y ʼàsáráֽ⁠m׃"],[36,14,"תָּמֹ֣ת בַּ⁠נֹּ֣עַר נַפְשָׁ֑⁠ם וְ֝⁠חַיָּתָ֗⁠ם בַּ⁠קְּדֵשִֽׁים׃","ţá̇mò֣ţ bȧ⁠nò֣̇ʻar napĕşá֑̌⁠m wĕ֝⁠ẖayá̇ţá֗⁠m bȧ⁠qĕ̇déşǐֽym׃"],[36,15,"יְחַלֵּ֣ץ עָנִ֣י בְ⁠עָנְי֑⁠וֹ וְ⁠יִ֖גֶל בַּ⁠לַּ֣חַץ אָזְנָֽ⁠ם׃","yĕẖalé֣̇ẕ ʻáni֣y bĕ⁠ʻánĕy֑⁠wò wĕ⁠yi֖gel bȧ⁠lȧ֣ẖaẕ ʼázĕnáֽ⁠m׃"],[36,16,"וְ⁠אַ֤ף הֲסִיתְ⁠ךָ֨ ׀ מִ⁠פִּי־צָ֗ר רַ֭חַב לֹא־מוּצָ֣ק תַּחְתֶּ֑י⁠הָ וְ⁠נַ֥חַת שֻׁ֝לְחָנְ⁠ךָ֗ מָ֣לֵא דָֽשֶׁן׃","wĕ⁠ʼa֤p hàsiyţĕ⁠ká֨ ׀ mi⁠pi̇y-ẕá֗r ra֭ẖab lòʼ-mẇẕá֣q ţȧẖĕţė֑y⁠há wĕ⁠na֥ẖaţ şǔ֝lĕẖánĕ⁠ká֗ má֣léʼ dáֽşěn׃"],[36,17,"וְ⁠דִין־רָשָׁ֥ע מָלֵ֑אתָ דִּ֖ין וּ⁠מִשְׁפָּ֣ט יִתְמֹֽכוּ׃","wĕ⁠diyn-ráşá֥̌ʻ málé֑ʼţá di֖̇yn ẇ⁠mişĕ̌pá֣̇t yiţĕmòֽkẇ׃"],[36,18,"כִּֽי־חֵ֭מָה פֶּן־יְסִֽיתְ⁠ךָ֣ בְ⁠סָ֑פֶק וְ⁠רָב־כֹּ֝֗פֶר אַל־יַטֶּֽ⁠ךָּ׃","kiֽ̇y-ẖé֭máh pėn-yĕsiֽyţĕ⁠ká֣ bĕ⁠sá֑peq wĕ⁠ráb-kò̇֝֗per ʼal-yatėֽ⁠ká̇׃"],[36,19,"הֲ⁠יַעֲרֹ֣ךְ שׁ֭וּעֲ⁠ךָ לֹ֣א בְ⁠צָ֑ר וְ֝⁠כֹ֗ל מַאֲמַצֵּי־כֹֽחַ׃","hà⁠yaʻàrò֣kĕ ş֭̌ẇʻà⁠ká lò֣ʼ bĕ⁠ẕá֑r wĕ֝⁠kò֗l maʼàmaẕé̇y-kòֽẖa׃"],[36,20,"אַל־תִּשְׁאַ֥ף הַ⁠לָּ֑יְלָה לַ⁠עֲל֖וֹת עַמִּ֣ים תַּחְתָּֽ⁠ם׃","ʼal-ţi̇şĕ̌ʼa֥p ha⁠lá֑̇yĕláh la⁠ʻàl֖wòţ ʻami֣̇ym ţȧẖĕţáֽ̇⁠m׃"],[36,21,"הִ֭שָּׁמֶר אַל־תֵּ֣פֶן אֶל־אָ֑וֶן כִּֽי־עַל־זֶ֝֗ה בָּחַ֥רְתָּ מֵ⁠עֹֽנִי׃","hi֭şá̇̌mer ʼal-ţé֣̇pen ʼel-ʼá֑wen kiֽ̇y-ʻal-ze֝֗h bá̇ẖa֥rĕţá̇ mé⁠ʻòֽniy׃"],[36,22,"הֶן־אֵ֭ל יַשְׂגִּ֣יב בְּ⁠כֹח֑⁠וֹ מִ֖י כָמֹ֣⁠הוּ מוֹרֶֽה׃","hen-ʼé֭l yaşĕ̂gi֣̇yb bĕ̇⁠kòẖ֑⁠wò mi֖y kámò֣⁠hẇ mwòreֽh׃"],[36,23,"מִֽי־פָקַ֣ד עָלָ֣י⁠ו דַּרְכּ֑⁠וֹ וּ⁠מִֽי־אָ֝מַ֗ר פָּעַ֥לְתָּ עַוְלָֽה׃","miֽy-páqa֣d ʻálá֣y⁠w dȧrĕk֑̇⁠wò ẇ⁠miֽy-ʼá֝ma֗r pá̇ʻa֥lĕţá̇ ʻawĕláֽh׃"],[36,24,"זְ֭כֹר כִּֽי־תַשְׂגִּ֣יא פָעֳל֑⁠וֹ אֲשֶׁ֖ר שֹׁרְר֣וּ אֲנָשִֽׁים׃","zĕ֭kòr kiֽ̇y-ţaşĕ̂gi֣̇yʼ páʻol֑⁠wò ʼàşě֖r şò̌rĕr֣ẇ ʼànáşǐֽym׃"],[36,25,"כָּל־אָדָ֥ם חָֽזוּ־ב֑⁠וֹ אֱ֝נ֗וֹשׁ יַבִּ֥יט מֵ⁠רָחֽוֹק׃","ká̇l-ʼádá֥m ẖáֽzẇ-b֑⁠wò ʼè֝n֗wòş̌ yabi֥̇yt mé⁠ráẖֽwòq׃"],[36,26,"הֶן־אֵ֣ל שַׂ֭גִּיא וְ⁠לֹ֣א נֵדָ֑ע מִסְפַּ֖ר שָׁנָ֣י⁠ו וְ⁠לֹא־חֵֽקֶר׃","hen-ʼé֣l şâ֭gi̇yʼ wĕ⁠lò֣ʼ nédá֑ʻ misĕpȧ֖r şá̌ná֣y⁠w wĕ⁠lòʼ-ẖéֽqer׃"],[36,27,"כִּ֭י יְגָרַ֣ע נִטְפֵי־מָ֑יִם יָזֹ֖קּוּ מָטָ֣ר לְ⁠אֵדֽ⁠וֹ׃","ki֭̇y yĕgára֣ʻ nitĕpéy-má֑yim yázò֖q̇ẇ mátá֣r lĕ⁠ʼédֽ⁠wò׃"],[36,28,"אֲשֶֽׁר־יִזְּל֥וּ שְׁחָקִ֑ים יִ֝רְעֲפ֗וּ עֲלֵ֤י ׀ אָדָ֬ם רָֽב׃","ʼàşěֽr-yizĕ̇l֥ẇ şĕ̌ẖáqi֑ym yi֝rĕʻàp֗ẇ ʻàlé֤y ׀ ʼádá֬m ráֽb׃"],[36,29,"אַ֣ף אִם־יָ֭בִין מִפְרְשֵׂי־עָ֑ב תְּ֝שֻׁא֗וֹת סֻכָּתֽ⁠וֹ׃","ʼa֣p ʼim-yá֭biyn mipĕrĕşé̂y-ʻá֑b ţĕ̇֝şǔʼ֗wòţ suká̇ţֽ⁠wò׃"],[36,30,"הֵן־פָּרַ֣שׂ עָלָ֣י⁠ו אוֹר֑⁠וֹ וְ⁠שָׁרְשֵׁ֖י הַ⁠יָּ֣ם כִּסָּֽה׃","hén-pá̇ra֣ş̂ ʻálá֣y⁠w ʼwòr֑⁠wò wĕ⁠şá̌rĕşé֖̌y ha⁠yá֣̇m ki̇sáֽ̇h׃"],[36,31,"כִּי־בָ֭⁠ם יָדִ֣ין עַמִּ֑ים יִֽתֶּן־אֹ֥כֶל לְ⁠מַכְבִּֽיר׃","ki̇y-bá֭⁠m yádi֣yn ʻami֑̇ym yiֽţėn-ʼò֥kel lĕ⁠makĕbiֽ̇yr׃"],[36,32,"עַל־כַּפַּ֥יִם כִּסָּה־א֑וֹר וַ⁠יְצַ֖ו עָלֶ֣י⁠הָ בְ⁠מַפְגִּֽיעַ׃","ʻal-kȧpȧ֥yim ki̇sá̇h-ʼ֑wòr wa⁠yĕẕa֖w ʻále֣y⁠há bĕ⁠mapĕgiֽ̇yʻa׃"],[36,33,"יַגִּ֣יד עָלָ֣י⁠ו רֵע֑⁠וֹ מִ֝קְנֶ֗ה אַ֣ף עַל־עוֹלֶֽה׃","yagi֣̇yd ʻálá֣y⁠w réʻ֑⁠wò mi֝qĕne֗h ʼa֣p ʻal-ʻwòleֽh׃"],[37,1,"אַף־לְ֭⁠זֹאת יֶחֱרַ֣ד לִבִּ֑⁠י וְ֝⁠יִתַּ֗ר מִ⁠מְּקוֹמֽ⁠וֹ׃","ʼap-lĕ֭⁠zòʼţ yeẖèra֣d libi֑̇⁠y wĕ֝⁠yiţȧ֗r mi⁠mĕ̇qwòmֽ⁠wò׃"],[37,2,"שִׁמְע֤וּ שָׁמ֣וֹעַ בְּ⁠רֹ֣גֶז קֹל֑⁠וֹ וְ֝⁠הֶ֗גֶה מִ⁠פִּ֥י⁠ו יֵצֵֽא׃","şǐmĕʻ֤ẇ şá̌m֣wòʻa bĕ̇⁠rò֣gez qòl֑⁠wò wĕ֝⁠he֗geh mi⁠pi֥̇y⁠w yéẕéֽʼ׃"],[37,3,"תַּֽחַת־כָּל־הַ⁠שָּׁמַ֥יִם יִשְׁרֵ֑⁠הוּ וְ֝⁠אוֹר֗⁠וֹ עַל־כַּנְפ֥וֹת הָ⁠אָֽרֶץ׃","ţȧֽẖaţ-ká̇l-ha⁠şá̇̌ma֥yim yişĕ̌ré֑⁠hẇ wĕ֝⁠ʼwòr֗⁠wò ʻal-kȧnĕp֥wòţ há⁠ʼáֽreẕ׃"],[37,4,"אַחֲרָ֤י⁠ו ׀ יִשְׁאַג־ק֗וֹל יַ֭רְעֵם בְּ⁠ק֣וֹל גְּאוֹנ֑⁠וֹ וְ⁠לֹ֥א יְ֝עַקְּבֵ֗⁠ם כִּֽי־יִשָּׁמַ֥ע קוֹלֽ⁠וֹ׃","ʼaẖàrá֤y⁠w ׀ yişĕ̌ʼag-q֗wòl ya֭rĕʻém bĕ̇⁠q֣wòl gĕ̇ʼwòn֑⁠wò wĕ⁠lò֥ʼ yĕ֝ʻaqĕ̇bé֗⁠m kiֽ̇y-yişá̇̌ma֥ʻ qwòlֽ⁠wò׃"],[37,5,"יַרְעֵ֤ם אֵ֣ל בְּ֭⁠קוֹל⁠וֹ נִפְלָא֑וֹת עֹשֶׂ֥ה גְ֝דֹל֗וֹת וְ⁠לֹ֣א נֵדָֽע׃","yarĕʻé֤m ʼé֣l bĕ֭̇⁠qwòl⁠wò nipĕláʼ֑wòţ ʻòşê֥h gĕ֝dòl֗wòţ wĕ⁠lò֣ʼ nédáֽʻ׃"],[37,6,"כִּ֤י לַ⁠שֶּׁ֨לַג ׀ יֹאמַ֗ר הֱוֵ֫א אָ֥רֶץ וְ⁠גֶ֥שֶׁם מָטָ֑ר וְ֝⁠גֶ֗שֶׁם מִטְר֥וֹת עֻזּֽ⁠וֹ׃","ki֤̇y la⁠şė̌֨lag ׀ yòʼma֗r hèwé֫ʼ ʼá֥reẕ wĕ⁠ge֥şěm mátá֑r wĕ֝⁠ge֗şěm mitĕr֥wòţ ʻużֽ⁠wò׃"],[37,7,"בְּ⁠יַד־כָּל־אָדָ֥ם יַחְתּ֑וֹם לָ֝⁠דַ֗עַת כָּל־אַנְשֵׁ֥י מַעֲשֵֽׂ⁠הוּ׃","bĕ̇⁠yad-ká̇l-ʼádá֥m yaẖĕţ֑̇wòm lá֝⁠da֗ʻaţ ká̇l-ʼanĕşé֥̌y maʻàşéֽ̂⁠hẇ׃"],[37,8,"וַ⁠תָּבֹ֣א חַיָּ֣ה בְמוֹ־אָ֑רֶב וּ⁠בִ⁠מְע֖וֹנֹתֶ֣י⁠הָ תִשְׁכֹּֽן׃","wa⁠ţá̇bò֣ʼ ẖayá֣̇h bĕmwò-ʼá֑reb ẇ⁠bi⁠mĕʻ֖wònòţe֣y⁠há ţişĕ̌kòֽ̇n׃"],[37,9,"מִן־הַ֭⁠חֶדֶר תָּב֣וֹא סוּפָ֑ה וּֽ⁠מִ⁠מְּזָרִ֥ים קָרָֽה׃","min-ha֭⁠ẖeder ţá̇b֣wòʼ sẇpá֑h ẇֽ⁠mi⁠mĕ̇zári֥ym qáráֽh׃"],[37,10,"מִ⁠נִּשְׁמַת־אֵ֥ל יִתֶּן־קָ֑רַח וְ⁠רֹ֖חַב מַ֣יִם בְּ⁠מוּצָֽק׃","mi⁠ni̇şĕ̌maţ-ʼé֥l yiţėn-qá֑raẖ wĕ⁠rò֖ẖab ma֣yim bĕ̇⁠mẇẕáֽq׃"],[37,11,"אַף־בְּ֭⁠רִי יַטְרִ֣יחַ עָ֑ב יָ֝פִ֗יץ עֲנַ֣ן אוֹרֽ⁠וֹ׃","ʼap-bĕ֭̇⁠riy yatĕri֣yẖa ʻá֑b yá֝pi֗yẕ ʻàna֣n ʼwòrֽ⁠wò׃"],[37,12,"וְ⁠ה֤וּא מְסִבּ֨וֹת ׀ מִתְהַפֵּ֣ךְ ב⁠תחבולת⁠ו לְ⁠פָעֳלָ֑⁠ם כֹּ֖ל אֲשֶׁ֥ר יְצַוֵּ֓⁠ם ׀ עַל־פְּנֵ֖י תֵבֵ֣ל אָֽרְצָ⁠ה׃","wĕ⁠h֤ẇʼ mĕsiḃ֨wòţ ׀ miţĕhapé֣̇kĕ b⁠ţẖbwlţ⁠w lĕ⁠páʻolá֑⁠m kò֖̇l ʼàşě֥r yĕẕawé̇֓⁠m ׀ ʻal-pĕ̇né֖y ţébé֣l ʼáֽrĕẕá⁠h׃"],[37,13,"אִם־לְ⁠שֵׁ֥בֶט אִם־לְ⁠אַרְצ֑⁠וֹ אִם־לְ֝⁠חֶ֗סֶד יַמְצִאֵֽ⁠הוּ׃","ʼim-lĕ⁠şé֥̌bet ʼim-lĕ⁠ʼarĕẕ֑⁠wò ʼim-lĕ֝⁠ẖe֗sed yamĕẕiʼéֽ⁠hẇ׃"],[37,14,"הַאֲזִ֣ינָ⁠ה זֹּ֣את אִיּ֑וֹב עֲ֝מֹ֗ד וְ⁠הִתְבּוֹנֵ֤ן ׀ נִפְלְא֬וֹת אֵֽל׃","haʼàzi֣yná⁠h zò֣̇ʼţ ʼiẏ֑wòb ʻà֝mò֗d wĕ⁠hiţĕḃwòné֤n ׀ nipĕlĕʼ֬wòţ ʼéֽl׃"],[37,15,"הֲ֭⁠תֵדַע בְּ⁠שׂוּם־אֱל֣וֹהַּ עֲלֵי⁠הֶ֑ם וְ֝⁠הוֹפִ֗יעַ א֣וֹר עֲנָנֽ⁠וֹ׃","hà֭⁠ţédaʻ bĕ̇⁠ş̂ẇm-ʼèl֣wòhȧ ʻàléy⁠he֑m wĕ֝⁠hwòpi֗yʻa ʼ֣wòr ʻànánֽ⁠wò׃"],[37,16,"הֲ֭⁠תֵדַע עַל־מִפְלְשֵׂי־עָ֑ב מִ֝פְלְא֗וֹת תְּמִ֣ים דֵּעִֽים׃","hà֭⁠ţédaʻ ʻal-mipĕlĕşé̂y-ʻá֑b mi֝pĕlĕʼ֗wòţ ţĕ̇mi֣ym dé̇ʻiֽym׃"],[37,17,"אֲשֶׁר־בְּגָדֶ֥י⁠ךָ חַמִּ֑ים בְּ⁠הַשְׁקִ֥ט אֶ֝֗רֶץ מִ⁠דָּרֽוֹם׃","ʼàşěr-bĕ̇gáde֥y⁠ká ẖami֑̇ym bĕ̇⁠haşĕ̌qi֥t ʼe֝֗reẕ mi⁠dá̇rֽwòm׃"],[37,18,"תַּרְקִ֣יעַ עִ֭מּ⁠וֹ לִ⁠שְׁחָקִ֑ים חֲ֝זָקִ֗ים כִּ⁠רְאִ֥י מוּצָֽק׃","ţȧrĕqi֣yʻa ʻi֭ṁ⁠wò li⁠şĕ̌ẖáqi֑ym ẖà֝záqi֗ym ki̇⁠rĕʼi֥y mẇẕáֽq׃"],[37,19,"ה֭וֹדִיעֵ⁠נוּ מַה־נֹּ֣אמַר ל֑⁠וֹ לֹ֥א־נַ֝עֲרֹ֗ךְ מִ⁠פְּנֵי־חֹֽשֶׁךְ׃","h֭wòdiyʻé⁠nẇ mah-nò֣̇ʼmar l֑⁠wò lò֥ʼ-na֝ʻàrò֗kĕ mi⁠pĕ̇néy-ẖòֽşěkĕ׃"],[37,20,"הַֽ⁠יְסֻפַּר־ל֭⁠וֹ כִּ֣י אֲדַבֵּ֑ר אִֽם־אָ֥מַר אִ֝֗ישׁ כִּ֣י יְבֻלָּֽע׃","hֽa⁠yĕsupȧr-l֭⁠wò ki֣̇y ʼàdabé֑̇r ʼiֽm-ʼá֥mar ʼi֝֗yş̌ ki֣̇y yĕbuláֽ̇ʻ׃"],[37,21,"וְ⁠עַתָּ֤ה ׀ לֹ֘א רָ֤אוּ א֗וֹר בָּהִ֣יר ה֭וּא בַּ⁠שְּׁחָקִ֑ים וְ⁠ר֥וּחַ עָ֝בְרָ֗ה וַֽ⁠תְּטַהֲרֵֽ⁠ם׃","wĕ⁠ʻaţá֤̇h ׀ lò֘ʼ rá֤ʼẇ ʼ֗wòr bá̇hi֣yr h֭ẇʼ bȧ⁠şĕ̇̌ẖáqi֑ym wĕ⁠r֥ẇẖa ʻá֝bĕrá֗h waֽ⁠ţĕ̇tahàréֽ⁠m׃"],[37,22,"מִ֭⁠צָּפוֹן זָהָ֣ב יֶֽאֱתֶ֑ה עַל־אֱ֝ל֗וֹהַּ נ֣וֹרָא הֽוֹד׃","mi֭⁠ẕá̇pwòn záhá֣b yeֽʼèţe֑h ʻal-ʼè֝l֗wòhȧ n֣wòráʼ hֽwòd׃"],[37,23,"שַׁדַּ֣י לֹֽא־מְ֭צָאנֻ⁠הוּ שַׂגִּיא־כֹ֑חַ וּ⁠מִשְׁפָּ֥ט וְ⁠רֹב־צְ֝דָקָ֗ה לֹ֣א יְעַנֶּֽה׃","şǎdȧ֣y lòֽʼ-mĕ֭ẕáʼnu⁠hẇ şâgi̇yʼ-kò֑ẖa ẇ⁠mişĕ̌pá֥̇t wĕ⁠ròb-ẕĕ֝dáqá֗h lò֣ʼ yĕʻanėֽh׃"],[37,24,"לָ֭⁠כֵן יְרֵא֣וּ⁠הוּ אֲנָשִׁ֑ים לֹֽא־יִ֝רְאֶ֗ה כָּל־חַכְמֵי־לֵֽב׃פ","lá֭⁠kén yĕréʼ֣ẇ⁠hẇ ʼànáşǐ֑ym lòֽʼ-yi֝rĕʼe֗h ká̇l-ẖakĕméy-léֽb׃p"],[38,1,"וַ⁠יַּֽעַן־יְהוָ֣ה אֶת־אִ֭יּוֹב מנ ה⁠סערה וַ⁠יֹּאמַֽר׃","wa⁠yȧֽʻan-yĕhwá֣h ʼeţ-ʼi֭ẏwòb mn h⁠sʻrh wa⁠yò̇ʼmaֽr׃"],[38,2,"מִ֤י זֶ֨ה ׀ מַחְשִׁ֖יךְ עֵצָ֥ה בְ⁠מִלִּ֗ין בְּֽלִי־דָֽעַת׃","mi֤y ze֨h ׀ maẖĕşǐ֖ykĕ ʻéẕá֥h bĕ⁠mili̇֗yn bĕֽ̇liy-dáֽʻaţ׃"],[38,3,"אֱזָר־נָ֣א כְ⁠גֶ֣בֶר חֲלָצֶ֑י⁠ךָ וְ֝⁠אֶשְׁאָלְ⁠ךָ֗ וְ⁠הוֹדִיעֵֽ⁠נִי׃","ʼèzár-ná֣ʼ kĕ⁠ge֣ber ẖàláẕe֑y⁠ká wĕ֝⁠ʼeşĕ̌ʼálĕ⁠ká֗ wĕ⁠hwòdiyʻéֽ⁠niy׃"],[38,4,"אֵיפֹ֣ה הָ֭יִיתָ בְּ⁠יָסְדִ⁠י־אָ֑רֶץ הַ֝גֵּ֗ד אִם־יָדַ֥עְתָּ בִינָֽה׃","ʼéypò֣h há֭yiyţá bĕ̇⁠yásĕdi⁠y-ʼá֑reẕ ha֝gé̇֗d ʼim-yáda֥ʻĕţá̇ biynáֽh׃"],[38,5,"מִי־שָׂ֣ם מְ֭מַדֶּי⁠הָ כִּ֣י תֵדָ֑ע א֤וֹ מִֽי־נָטָ֖ה עָלֶ֣י⁠הָ קָּֽו׃","miy-şá֣̂m mĕ֭madėy⁠há ki֣̇y ţédá֑ʻ ʼ֤wò miֽy-nátá֖h ʻále֣y⁠há qáֽ̇w׃"],[38,6,"עַל־מָ֭ה אֲדָנֶ֣י⁠הָ הָטְבָּ֑עוּ א֥וֹ מִֽי־יָ֝רָ֗ה אֶ֣בֶן פִּנָּתָֽ⁠הּ׃","ʻal-má֭h ʼàdáne֣y⁠há hátĕbá֑̇ʻẇ ʼ֥wò miֽy-yá֝rá֗h ʼe֣ben pi̇ná̇ţáֽ⁠ḣ׃"],[38,7,"בְּ⁠רָן־יַ֭חַד כּ֣וֹכְבֵי בֹ֑קֶר וַ֝⁠יָּרִ֗יעוּ כָּל־בְּנֵ֥י אֱלֹהִֽים׃","bĕ̇⁠rán-ya֭ẖad k֣̇wòkĕbéy bò֑qer wa֝⁠yá̇ri֗yʻẇ ká̇l-bĕ̇né֥y ʼèlòhiֽym׃"],[38,8,"וַ⁠יָּ֣סֶךְ בִּ⁠דְלָתַ֣יִם יָ֑ם בְּ֝⁠גִיח֗⁠וֹ מֵ⁠רֶ֥חֶם יֵצֵֽא׃","wa⁠yá֣̇sekĕ bi̇⁠dĕláţa֣yim yá֑m bĕ̇֝⁠giyẖ֗⁠wò mé⁠re֥ẖem yéẕéֽʼ׃"],[38,9,"בְּ⁠שׂוּמִ֣⁠י עָנָ֣ן לְבֻשׁ֑⁠וֹ וַ֝⁠עֲרָפֶ֗ל חֲתֻלָּתֽ⁠וֹ׃","bĕ̇⁠ş̂ẇmi֣⁠y ʻáná֣n lĕbuş֑̌⁠wò wa֝⁠ʻàrápe֗l ẖàţulá̇ţֽ⁠wò׃"],[38,10,"וָ⁠אֶשְׁבֹּ֣ר עָלָ֣י⁠ו חֻקִּ֑⁠י וָֽ֝⁠אָשִׂ֗ים בְּרִ֣יחַ וּ⁠דְלָתָֽיִם׃","wá⁠ʼeşĕ̌bò֣̇r ʻálá֣y⁠w ẖuqi֑̇⁠y wáֽ֝⁠ʼáşî֗ym bĕ̇ri֣yẖa ẇ⁠dĕláţáֽyim׃"],[38,11,"וָ⁠אֹמַ֗ר עַד־פֹּ֣ה תָ֭בוֹא וְ⁠לֹ֣א תֹסִ֑יף וּ⁠פֹ֥א־יָ֝שִׁ֗ית בִּ⁠גְא֥וֹן גַּלֶּֽי⁠ךָ׃","wá⁠ʼòma֗r ʻad-pò֣̇h ţá֭bwòʼ wĕ⁠lò֣ʼ ţòsi֑yp ẇ⁠pò֥ʼ-yá֝şǐ֗yţ bi̇⁠gĕʼ֥wòn gȧlėֽy⁠ká׃"],[38,12,"הְֽ֭⁠מִ⁠יָּמֶי⁠ךָ צִוִּ֣יתָ בֹּ֑קֶר ידעתה שחר מְקֹמֽ⁠וֹ׃","hĕֽ֭⁠mi⁠yá̇mey⁠ká ẕiwi֣̇yţá bò֑̇qer ydʻţh şẖr mĕqòmֽ⁠wò׃"],[38,13,"לֶ֭⁠אֱחֹז בְּ⁠כַנְפ֣וֹת הָ⁠אָ֑רֶץ וְ⁠יִנָּעֲר֖וּ רְשָׁעִ֣ים מִמֶּֽ⁠נָּה׃","le֭⁠ʼèẖòz bĕ̇⁠kanĕp֣wòţ há⁠ʼá֑reẕ wĕ⁠yiná̇ʻàr֖ẇ rĕşá̌ʻi֣ym mimėֽ⁠ná̇h׃"],[38,14,"תִּ֭תְהַפֵּךְ כְּ⁠חֹ֣מֶר חוֹתָ֑ם וְ֝⁠יִֽתְיַצְּב֗וּ כְּמ֣וֹ לְבֽוּשׁ׃","ţi֭̇ţĕhapé̇kĕ kĕ̇⁠ẖò֣mer ẖwòţá֑m wĕ֝⁠yiֽţĕyaẕĕ̇b֗ẇ kĕ̇m֣wò lĕbֽẇş̌׃"],[38,15,"וְ⁠יִמָּנַ֣ע מֵרְשָׁעִ֣ים אוֹרָ֑⁠ם וּ⁠זְר֥וֹעַ רָ֝מָ֗ה תִּשָּׁבֵֽר׃","wĕ⁠yimá̇na֣ʻ mérĕşá̌ʻi֣ym ʼwòrá֑⁠m ẇ⁠zĕr֥wòʻa rá֝má֗h ţi̇şá̇̌béֽr׃"],[38,16,"הֲ֭⁠בָאתָ עַד־נִבְכֵי־יָ֑ם וּ⁠בְ⁠חֵ֥קֶר תְּ֝ה֗וֹם הִתְהַלָּֽכְתָּ׃","hà֭⁠báʼţá ʻad-nibĕkéy-yá֑m ẇ⁠bĕ⁠ẖé֥qer ţĕ̇֝h֗wòm hiţĕhaláֽ̇kĕţá̇׃"],[38,17,"הֲ⁠נִגְל֣וּ לְ֭⁠ךָ שַׁעֲרֵי־מָ֑וֶת וְ⁠שַׁעֲרֵ֖י צַלְמָ֣וֶת תִּרְאֶֽה׃","hà⁠nigĕl֣ẇ lĕ֭⁠ká şǎʻàréy-má֑weţ wĕ⁠şǎʻàré֖y ẕalĕmá֣weţ ţi̇rĕʼeֽh׃"],[38,18,"הִ֭תְבֹּנַנְתָּ עַד־רַחֲבֵי־אָ֑רֶץ הַ֝גֵּ֗ד אִם־יָדַ֥עְתָּ כֻלָּֽ⁠הּ׃","hi֭ţĕbò̇nanĕţá̇ ʻad-raẖàbéy-ʼá֑reẕ ha֝gé̇֗d ʼim-yáda֥ʻĕţá̇ kuláֽ̇⁠ḣ׃"],[38,19,"אֵי־זֶ֣ה הַ֭⁠דֶּרֶךְ יִשְׁכָּן־א֑וֹר וְ֝⁠חֹ֗שֶׁךְ אֵי־זֶ֥ה מְקֹמֽ⁠וֹ׃","ʼéy-ze֣h ha֭⁠dėrekĕ yişĕ̌ká̇n-ʼ֑wòr wĕ֝⁠ẖò֗şěkĕ ʼéy-ze֥h mĕqòmֽ⁠wò׃"],[38,20,"כִּ֣י תִ֭קָּחֶ⁠נּוּ אֶל־גְּבוּל֑⁠וֹ וְ⁠כִֽי־תָ֝בִ֗ין נְתִיב֥וֹת בֵּיתֽ⁠וֹ׃","ki֣̇y ţi֭qá̇ẖe⁠ṅẇ ʼel-gĕ̇bẇl֑⁠wò wĕ⁠kiֽy-ţá֝bi֗yn nĕţiyb֥wòţ bé̇yţֽ⁠wò׃"],[38,21,"יָ֭דַעְתָּ כִּי־אָ֣ז תִּוָּלֵ֑ד וּ⁠מִסְפַּ֖ר יָמֶ֣י⁠ךָ רַבִּֽים׃","yá֭daʻĕţá̇ ki̇y-ʼá֣z ţi̇wá̇lé֑d ẇ⁠misĕpȧ֖r yáme֣y⁠ká rabiֽ̇ym׃"],[38,22,"הֲ֭⁠בָאתָ אֶל־אֹצְר֣וֹת שָׁ֑לֶג וְ⁠אֹצְר֖וֹת בָּרָ֣ד תִּרְאֶֽה׃","hà֭⁠báʼţá ʼel-ʼòẕĕr֣wòţ şá֑̌leg wĕ⁠ʼòẕĕr֖wòţ bá̇rá֣d ţi̇rĕʼeֽh׃"],[38,23,"אֲשֶׁר־חָשַׂ֥כְתִּי לְ⁠עֶת־צָ֑ר לְ⁠י֥וֹם קְ֝רָ֗ב וּ⁠מִלְחָמָֽה׃","ʼàşěr-ẖáşâ֥kĕţi̇y lĕ⁠ʻeţ-ẕá֑r lĕ⁠y֥wòm qĕ֝rá֗b ẇ⁠milĕẖámáֽh׃"],[38,24,"אֵי־זֶ֣ה הַ֭⁠דֶּרֶךְ יֵחָ֣לֶק א֑וֹר יָפֵ֖ץ קָדִ֣ים עֲלֵי־אָֽרֶץ׃","ʼéy-ze֣h ha֭⁠dėrekĕ yéẖá֣leq ʼ֑wòr yápé֖ẕ qádi֣ym ʻàléy-ʼáֽreẕ׃"],[38,25,"מִֽי־פִלַּ֣ג לַ⁠שֶּׁ֣טֶף תְּעָלָ֑ה וְ֝⁠דֶ֗רֶךְ לַ⁠חֲזִ֥יז קֹלֽוֹת׃","miֽy-pilȧ֣g la⁠şė֣̌tep ţĕ̇ʻálá֑h wĕ֝⁠de֗rekĕ la⁠ẖàzi֥yz qòlֽwòţ׃"],[38,26,"לְ֭⁠הַמְטִיר עַל־אֶ֣רֶץ לֹא־אִ֑ישׁ מִ֝דְבָּ֗ר לֹא־אָדָ֥ם בּֽ⁠וֹ׃","lĕ֭⁠hamĕtiyr ʻal-ʼe֣reẕ lòʼ-ʼi֑yş̌ mi֝dĕbá̇֗r lòʼ-ʼádá֥m ḃֽ⁠wò׃"],[38,27,"לְ⁠הַשְׂבִּ֣יעַ שֹׁ֭אָה וּ⁠מְשֹׁאָ֑ה וּ֝⁠לְ⁠הַצְמִ֗יחַ מֹ֣צָא דֶֽשֶׁא׃","lĕ⁠haşĕ̂bi֣̇yʻa şò֭̌ʼáh ẇ⁠mĕşò̌ʼá֑h ẇ֝⁠lĕ⁠haẕĕmi֗yẖa mò֣ẕáʼ deֽşěʼ׃"],[38,28,"הֲ⁠יֵשׁ־לַ⁠מָּטָ֥ר אָ֑ב א֥וֹ מִי־ה֝וֹלִ֗יד אֶגְלֵי־טָֽל׃","hà⁠yéş̌-la⁠má̇tá֥r ʼá֑b ʼ֥wò miy-h֝wòli֗yd ʼegĕléy-táֽl׃"],[38,29,"מִ⁠בֶּ֣טֶן מִ֭י יָצָ֣א הַ⁠קָּ֑רַח וּ⁠כְפֹ֥ר שָׁ֝מַיִם מִ֣י יְלָדֽ⁠וֹ׃","mi⁠bė֣ten mi֭y yáẕá֣ʼ ha⁠qá֑̇raẖ ẇ⁠kĕpò֥r şá̌֝mayim mi֣y yĕládֽ⁠wò׃"],[38,30,"כָּ֭⁠אֶבֶן מַ֣יִם יִתְחַבָּ֑אוּ וּ⁠פְנֵ֥י תְ֝ה֗וֹם יִתְלַכָּֽדוּ׃","ká֭̇⁠ʼeben ma֣yim yiţĕẖabá֑̇ʼẇ ẇ⁠pĕné֥y ţĕ֝h֗wòm yiţĕlakáֽ̇dẇ׃"],[38,31,"הַֽ֭⁠תְקַשֵּׁר מַעֲדַנּ֣וֹת כִּימָ֑ה אֽוֹ־מֹשְׁכ֖וֹת כְּסִ֣יל תְּפַתֵּֽחַ׃","haֽ֭⁠ţĕqaşé̇̌r maʻàdaṅ֣wòţ ki̇ymá֑h ʼֽwò-mòşĕ̌k֖wòţ kĕ̇si֣yl ţĕ̇paţéֽ̇ẖa׃"],[38,32,"הֲ⁠תֹצִ֣יא מַזָּר֣וֹת בְּ⁠עִתּ֑⁠וֹ וְ֝⁠עַ֗יִשׁ עַל־בָּנֶ֥י⁠הָ תַנְחֵֽ⁠ם׃","hà⁠ţòẕi֣yʼ mazá̇r֣wòţ bĕ̇⁠ʻiţ֑̇⁠wò wĕ֝⁠ʻa֗yiş̌ ʻal-bá̇ne֥y⁠há ţanĕẖéֽ⁠m׃"],[38,33,"הֲ֭⁠יָדַעְתָּ חֻקּ֣וֹת שָׁמָ֑יִם אִם־תָּשִׂ֖ים מִשְׁטָר֣⁠וֹ בָ⁠אָֽרֶץ׃","hà֭⁠yádaʻĕţá̇ ẖuq֣̇wòţ şá̌má֑yim ʼim-ţá̇şî֖ym mişĕ̌tár֣⁠wò bá⁠ʼáֽreẕ׃"],[38,34,"הֲ⁠תָרִ֣ים לָ⁠עָ֣ב קוֹלֶ֑⁠ךָ וְֽ⁠שִׁפְעַת־מַ֥יִם תְּכַסֶּֽ⁠ךָּ׃","hà⁠ţári֣ym lá⁠ʻá֣b qwòle֑⁠ká wĕֽ⁠şǐpĕʻaţ-ma֥yim ţĕ̇kasėֽ⁠ká̇׃"],[38,35,"הַֽ⁠תְשַׁלַּ֣ח בְּרָקִ֣ים וְ⁠יֵלֵ֑כוּ וְ⁠יֹאמְר֖וּ לְ⁠ךָ֣ הִנֵּֽ⁠נוּ׃","hֽa⁠ţĕşǎlȧ֣ẖ bĕ̇ráqi֣ym wĕ⁠yélé֑kẇ wĕ⁠yòʼmĕr֖ẇ lĕ⁠ká֣ hinéֽ̇⁠nẇ׃"],[38,36,"מִי־שָׁ֭ת בַּ⁠טֻּח֣וֹת חָכְמָ֑ה א֤וֹ מִֽי־נָתַ֖ן לַ⁠שֶּׂ֣כְוִי בִינָֽה׃","miy-şá֭̌ţ bȧ⁠tu̇ẖ֣wòţ ẖákĕmá֑h ʼ֤wò miֽy-náţa֖n la⁠şė֣̂kĕwiy biynáֽh׃"],[38,37,"מִֽי־יְסַפֵּ֣ר שְׁחָקִ֣ים בְּ⁠חָכְמָ֑ה וְ⁠נִבְלֵ֥י שָׁ֝מַ֗יִם מִ֣י יַשְׁכִּֽיב׃","miֽy-yĕsapé֣̇r şĕ̌ẖáqi֣ym bĕ̇⁠ẖákĕmá֑h wĕ⁠nibĕlé֥y şá̌֝ma֗yim mi֣y yaşĕ̌kiֽ̇yb׃"],[38,38,"בְּ⁠צֶ֣קֶת עָ֭פָר לַ⁠מּוּצָ֑ק וּ⁠רְגָבִ֥ים יְדֻבָּֽקוּ׃","bĕ̇⁠ẕe֣qeţ ʻá֭pár la⁠ṁẇẕá֑q ẇ⁠rĕgábi֥ym yĕdubáֽ̇qẇ׃"],[38,39,"הֲ⁠תָצ֣וּד לְ⁠לָבִ֣יא טָ֑רֶף וְ⁠חַיַּ֖ת כְּפִירִ֣ים תְּמַלֵּֽא׃","hà⁠ţáẕ֣ẇd lĕ⁠lábi֣yʼ tá֑rep wĕ⁠ẖayȧ֖ţ kĕ̇piyri֣ym ţĕ̇maléֽ̇ʼ׃"],[38,40,"כִּי־יָשֹׁ֥חוּ בַ⁠מְּעוֹנ֑וֹת יֵשְׁב֖וּ בַ⁠סֻּכָּ֣ה לְמוֹ־אָֽרֶב׃","ki̇y-yáşò֥̌ẖẇ ba⁠mĕ̇ʻwòn֑wòţ yéşĕ̌b֖ẇ ba⁠su̇ká֣̇h lĕmwò-ʼáֽreb׃"],[38,41,"מִ֤י יָכִ֥ין לָ⁠עֹרֵ֗ב צֵ֫יד֥⁠וֹ כִּֽי־ילד⁠ו אֶל־אֵ֣ל יְשַׁוֵּ֑עוּ יִ֝תְע֗וּ לִ⁠בְלִי־אֹֽכֶל׃","mi֤y yáki֥yn lá⁠ʻòré֗b ẕé֫yd֥⁠wò kiֽ̇y-yld⁠w ʼel-ʼé֣l yĕşǎwé֑̇ʻẇ yi֝ţĕʻ֗ẇ li⁠bĕliy-ʼòֽkel׃"],[39,1,"הֲ⁠יָדַ֗עְתָּ עֵ֭ת לֶ֣דֶת יַעֲלֵי־סָ֑לַע חֹלֵ֖ל אַיָּל֣וֹת תִּשְׁמֹֽר׃","hà⁠yáda֗ʻĕţá̇ ʻé֭ţ le֣deţ yaʻàléy-sá֑laʻ ẖòlé֖l ʼayá̇l֣wòţ ţi̇şĕ̌mòֽr׃"],[39,2,"תִּסְפֹּ֣ר יְרָחִ֣ים תְּמַלֶּ֑אנָה וְ֝⁠יָדַ֗עְתָּ עֵ֣ת לִדְתָּֽ⁠נָה׃","ţi̇sĕpò֣̇r yĕráẖi֣ym ţĕ̇malė֑ʼnáh wĕ֝⁠yáda֗ʻĕţá̇ ʻé֣ţ lidĕţáֽ̇⁠náh׃"],[39,3,"תִּ֭כְרַעְנָה יַלְדֵי⁠הֶ֣ן תְּפַלַּ֑חְנָה חֶבְלֵי⁠הֶ֥ם תְּשַׁלַּֽחְנָה׃","ţi֭̇kĕraʻĕnáh yalĕdéy⁠he֣n ţĕ̇palȧ֑ẖĕnáh ẖebĕléy⁠he֥m ţĕ̇şǎlȧֽẖĕnáh׃"],[39,4,"יַחְלְמ֣וּ בְ֭נֵי⁠הֶם יִרְבּ֣וּ בַ⁠בָּ֑ר יָ֝צְא֗וּ וְ⁠לֹא־שָׁ֥בוּ לָֽ⁠מוֹ׃","yaẖĕlĕm֣ẇ bĕ֭néy⁠hem yirĕḃ֣ẇ ba⁠bá֑̇r yá֝ẕĕʼ֗ẇ wĕ⁠lòʼ-şá֥̌bẇ láֽ⁠mwò׃"],[39,5,"מִֽי־שִׁלַּ֣ח פֶּ֣רֶא חָפְשִׁ֑י וּ⁠מֹסְר֥וֹת עָ֝ר֗וֹד מִ֣י פִתֵּֽחַ׃","miֽy-şǐlȧ֣ẖ pė֣reʼ ẖápĕşǐ֑y ẇ⁠mòsĕr֥wòţ ʻá֝r֗wòd mi֣y piţéֽ̇ẖa׃"],[39,6,"אֲשֶׁר־שַׂ֣מְתִּי עֲרָבָ֣ה בֵית֑⁠וֹ וּֽ⁠מִשְׁכְּנוֹתָ֥י⁠ו מְלֵֽחָה׃","ʼàşěr-şâ֣mĕţi̇y ʻàrábá֣h béyţ֑⁠wò ẇֽ⁠mişĕ̌kĕ̇nwòţá֥y⁠w mĕléֽẖáh׃"],[39,7,"יִ֭שְׂחַק לַ⁠הֲמ֣וֹן קִרְיָ֑ה תְּשֻׁא֥וֹת נ֝וֹגֵ֗שׂ לֹ֣א יִשְׁמָֽע׃","yi֭şĕ̂ẖaq la⁠hàm֣wòn qirĕyá֑h ţĕ̇şǔʼ֥wòţ n֝wògé֗ş̂ lò֣ʼ yişĕ̌máֽʻ׃"],[39,8,"יְת֣וּר הָרִ֣ים מִרְעֵ֑⁠הוּ וְ⁠אַחַ֖ר כָּל־יָר֣וֹק יִדְרֽוֹשׁ׃","yĕţ֣ẇr hári֣ym mirĕʻé֑⁠hẇ wĕ⁠ʼaẖa֖r ká̇l-yár֣wòq yidĕrֽwòş̌׃"],[39,9,"הֲ⁠יֹ֣אבֶה רֵּ֣ים עָבְדֶ֑⁠ךָ אִם־יָ֝לִ֗ין עַל־אֲבוּסֶֽ⁠ךָ׃","hà⁠yò֣ʼbeh ré֣̇ym ʻábĕde֑⁠ká ʼim-yá֝li֗yn ʻal-ʼàbẇseֽ⁠ká׃"],[39,10,"הֲֽ⁠תִקְשָׁר־רֵ֭ים בְּ⁠תֶ֣לֶם עֲבֹת֑⁠וֹ אִם־יְשַׂדֵּ֖ד עֲמָקִ֣ים אַחֲרֶֽי⁠ךָ׃","hàֽ⁠ţiqĕşá̌r-ré֭ym bĕ̇⁠ţe֣lem ʻàbòţ֑⁠wò ʼim-yĕşâdé֖̇d ʻàmáqi֣ym ʼaẖàreֽy⁠ká׃"],[39,11,"הֲֽ⁠תִבְטַח־בּ֭⁠וֹ כִּי־רַ֣ב כֹּח֑⁠וֹ וְ⁠תַעֲזֹ֖ב אֵלָ֣י⁠ו יְגִיעֶֽ⁠ךָ׃","hàֽ⁠ţibĕtaẖ-ḃ֭⁠wò ki̇y-ra֣b kò̇ẖ֑⁠wò wĕ⁠ţaʻàzò֖b ʼélá֣y⁠w yĕgiyʻeֽ⁠ká׃"],[39,12,"הֲ⁠תַאֲמִ֣ין בּ֭⁠וֹ כִּי־ישוב זַרְעֶ֑⁠ךָ וְֽ⁠גָרְנְ⁠ךָ֥ יֶאֱסֹֽף׃","hà⁠ţaʼàmi֣yn ḃ֭⁠wò ki̇y-yşwb zarĕʻe֑⁠ká wĕֽ⁠gárĕnĕ⁠ká֥ yeʼèsòֽp׃"],[39,13,"כְּנַף־רְנָנִ֥ים נֶעֱלָ֑סָה אִם־אֶ֝בְרָ֗ה חֲסִידָ֥ה וְ⁠נֹצָֽה׃","kĕ̇nap-rĕnáni֥ym neʻèlá֑sáh ʼim-ʼe֝bĕrá֗h ẖàsiydá֥h wĕ⁠nòẕáֽh׃"],[39,14,"כִּֽי־תַעֲזֹ֣ב לָ⁠אָ֣רֶץ בֵּצֶ֑י⁠הָ וְֽ⁠עַל־עָפָ֥ר תְּחַמֵּֽם׃","kiֽ̇y-ţaʻàzò֣b lá⁠ʼá֣reẕ bé̇ẕe֑y⁠há wĕֽ⁠ʻal-ʻápá֥r ţĕ̇ẖaméֽ̇m׃"],[39,15,"וַ֭⁠תִּשְׁכַּח כִּי־רֶ֣גֶל תְּזוּרֶ֑⁠הָ וְ⁠חַיַּ֖ת הַ⁠שָּׂדֶ֣ה תְּדוּשֶֽׁ⁠הָ׃","wa֭⁠ţi̇şĕ̌kȧẖ ki̇y-re֣gel ţĕ̇zẇre֑⁠há wĕ⁠ẖayȧ֖ţ ha⁠şá̇̂de֣h ţĕ̇dẇşěֽ⁠há׃"],[39,16,"הִקְשִׁ֣יחַ בָּנֶ֣י⁠הָ לְּ⁠לֹא־לָ֑⁠הּ לְ⁠רִ֖יק יְגִיעָ֣⁠הּ בְּלִי־פָֽחַד׃","hiqĕşǐ֣yẖa bá̇ne֣y⁠há lĕ̇⁠lòʼ-lá֑⁠ḣ lĕ⁠ri֖yq yĕgiyʻá֣⁠ḣ bĕ̇liy-páֽẖad׃"],[39,17,"כִּֽי־הִשָּׁ֣⁠הּ אֱל֣וֹהַּ חָכְמָ֑ה וְ⁠לֹא־חָ֥לַק לָ֝֗⁠הּ בַּ⁠בִּינָֽה׃","kiֽ̇y-hişá֣̇̌⁠ḣ ʼèl֣wòhȧ ẖákĕmá֑h wĕ⁠lòʼ-ẖá֥laq lá֝֗⁠ḣ bȧ⁠bi̇ynáֽh׃"],[39,18,"כָּ֭⁠עֵת בַּ⁠מָּר֣וֹם תַּמְרִ֑יא תִּֽשְׂחַ֥ק לַ֝⁠סּ֗וּס וּ⁠לְ⁠רֹֽכְבֽ⁠וֹ׃","ká֭̇⁠ʻéţ bȧ⁠má̇r֣wòm ţȧmĕri֑yʼ ţiֽ̇şĕ̂ẖa֥q la֝⁠ṡ֗ẇs ẇ⁠lĕ⁠ròֽkĕbֽ⁠wò׃"],[39,19,"הֲ⁠תִתֵּ֣ן לַ⁠סּ֣וּס גְּבוּרָ֑ה הֲ⁠תַלְבִּ֖ישׁ צַוָּאר֣⁠וֹ רַעְמָֽה׃","hà⁠ţiţé֣̇n la⁠ṡ֣ẇs gĕ̇bẇrá֑h hà⁠ţalĕbi֖̇yş̌ ẕawá̇ʼr֣⁠wò raʻĕmáֽh׃"],[39,20,"הְֽ֭⁠תַרְעִישֶׁ⁠נּוּ כָּ⁠אַרְבֶּ֑ה ה֖וֹד נַחְר֣⁠וֹ אֵימָֽה׃","hĕֽ֭⁠ţarĕʻiyşě⁠ṅẇ ká̇⁠ʼarĕbė֑h h֖wòd naẖĕr֣⁠wò ʼéymáֽh׃"],[39,21,"יַחְפְּר֣וּ בָ֭⁠עֵמֶק וְ⁠יָשִׂ֣ישׂ בְּ⁠כֹ֑חַ יֵ֝צֵ֗א לִ⁠קְרַאת־נָֽשֶׁק׃","yaẖĕpĕ̇r֣ẇ bá֭⁠ʻémeq wĕ⁠yáşî֣yş̂ bĕ̇⁠kò֑ẖa yé֝ẕé֗ʼ li⁠qĕraʼţ-náֽşěq׃"],[39,22,"יִשְׂחַ֣ק לְ֭⁠פַחַד וְ⁠לֹ֣א יֵחָ֑ת וְ⁠לֹֽא־יָ֝שׁ֗וּב מִ⁠פְּנֵי־חָֽרֶב׃","yişĕ̂ẖa֣q lĕ֭⁠paẖad wĕ⁠lò֣ʼ yéẖá֑ţ wĕ⁠lòֽʼ-yá֝ş̌֗ẇb mi⁠pĕ̇néy-ẖáֽreb׃"],[39,23,"עָ֭לָי⁠ו תִּרְנֶ֣ה אַשְׁפָּ֑ה לַ֖הַב חֲנִ֣ית וְ⁠כִידֽוֹן׃","ʻá֭láy⁠w ţi̇rĕne֣h ʼaşĕ̌pá֑̇h la֖hab ẖàni֣yţ wĕ⁠kiydֽwòn׃"],[39,24,"בְּ⁠רַ֣עַשׁ וְ֭⁠רֹגֶז יְגַמֶּא־אָ֑רֶץ וְ⁠לֹֽא־יַ֝אֲמִ֗ין כִּי־ק֥וֹל שׁוֹפָֽר׃","bĕ̇⁠ra֣ʻaş̌ wĕ֭⁠rògez yĕgamėʼ-ʼá֑reẕ wĕ⁠lòֽʼ-ya֝ʼàmi֗yn ki̇y-q֥wòl ş̌wòpáֽr׃"],[39,25,"בְּ⁠דֵ֤י שֹׁפָ֨ר ׀ יֹ֘אמַ֤ר הֶאָ֗ח וּֽ֭⁠מֵ⁠רָחוֹק יָרִ֣יחַ מִלְחָמָ֑ה רַ֥עַם שָׂ֝רִים וּ⁠תְרוּעָֽה׃","bĕ̇⁠dé֤y şò̌pá֨r ׀ yò֘ʼma֤r heʼá֗ẖ ẇֽ֭⁠mé⁠ráẖwòq yári֣yẖa milĕẖámá֑h ra֥ʻam şá̂֝riym ẇ⁠ţĕrẇʻáֽh׃"],[39,26,"הֲֽ֭⁠מִ⁠בִּינָ֣תְ⁠ךָ יַֽאֲבֶר־נֵ֑ץ יִפְרֹ֖שׂ כנפ⁠ו לְ⁠תֵימָֽן׃","hàֽ֭⁠mi⁠bi̇yná֣ţĕ⁠ká yaֽʼàber-né֑ẕ yipĕrò֖ş̂ knp⁠w lĕ⁠ţéymáֽn׃"],[39,27,"אִם־עַל־פִּ֭י⁠ךָ יַגְבִּ֣יהַּ נָ֑שֶׁר וְ֝⁠כִ֗י יָרִ֥ים קִנּֽ⁠וֹ׃","ʼim-ʻal-pi֭̇y⁠ká yagĕbi֣̇yhȧ ná֑şěr wĕ֝⁠ki֗y yári֥ym qiṅֽ⁠wò׃"],[39,28,"סֶ֣לַע יִ֭שְׁכֹּן וְ⁠יִתְלֹנָ֑ן עַֽל־שֶׁן־סֶ֝֗לַע וּ⁠מְצוּדָֽה׃","se֣laʻ yi֭şĕ̌kò̇n wĕ⁠yiţĕlòná֑n ʻaֽl-şěn-se֝֗laʻ ẇ⁠mĕẕẇdáֽh׃"],[39,29,"מִ⁠שָּׁ֥ם חָֽפַר־אֹ֑כֶל לְ֝⁠מֵ⁠רָח֗וֹק עֵינָ֥י⁠ו יַבִּֽיטוּ׃","mi⁠şá֥̇̌m ẖáֽpar-ʼò֑kel lĕ֝⁠mé⁠ráẖ֗wòq ʻéyná֥y⁠w yabiֽ̇ytẇ׃"],[39,30,"ו⁠אפרח⁠ו יְעַלְעוּ־דָ֑ם וּ⁠בַ⁠אֲשֶׁ֥ר חֲ֝לָלִ֗ים שָׁ֣ם הֽוּא׃פ","w⁠ʼprẖ⁠w yĕʻalĕʻẇ-dá֑m ẇ⁠ba⁠ʼàşě֥r ẖà֝láli֗ym şá֣̌m hֽẇʼ׃p"],[40,1,"וַ⁠יַּ֖עַן יְהוָ֥ה אֶת־אִיּ֗וֹב וַ⁠יֹּאמַֽר׃","wa⁠yȧ֖ʻan yĕhwá֥h ʼeţ-ʼiẏ֗wòb wa⁠yò̇ʼmaֽr׃"],[40,2,"הֲ֭⁠רֹב עִם־שַׁדַּ֣י יִסּ֑וֹר מוֹכִ֖יחַ אֱל֣וֹהַּ יַעֲנֶֽ⁠נָּה׃פ","hà֭⁠ròb ʻim-şǎdȧ֣y yiṡ֑wòr mwòki֖yẖa ʼèl֣wòhȧ yaʻàneֽ⁠ná̇h׃p"],[40,3,"וַ⁠יַּ֖עַן אִיּ֥וֹב אֶת־יְהוָ֗ה וַ⁠יֹּאמַֽר׃","wa⁠yȧ֖ʻan ʼiẏ֥wòb ʼeţ-yĕhwá֗h wa⁠yò̇ʼmaֽr׃"],[40,4,"הֵ֣ן קַ֭לֹּתִי מָ֣ה אֲשִׁיבֶ֑⁠ךָּ יָ֝דִ֗⁠י שַׂ֣מְתִּי לְמוֹ־פִֽ⁠י׃","hé֣n qa֭lò̇ţiy má֣h ʼàşǐybe֑⁠ká̇ yá֝di֗⁠y şâ֣mĕţi̇y lĕmwò-piֽ⁠y׃"],[40,5,"אַחַ֣ת דִּ֭בַּרְתִּי וְ⁠לֹ֣א אֶֽעֱנֶ֑ה וּ֝⁠שְׁתַּ֗יִם וְ⁠לֹ֣א אוֹסִֽיף׃פ","ʼaẖa֣ţ di֭̇bȧrĕţi̇y wĕ⁠lò֣ʼ ʼeֽʻène֑h ẇ֝⁠şĕ̌ţȧ֗yim wĕ⁠lò֣ʼ ʼwòsiֽyp׃p"],[40,6,"וַ⁠יַּֽעַן־יְהוָ֣ה אֶת־אִ֭יּוֹב מנ סערה וַ⁠יֹּאמַֽר׃","wa⁠yȧֽʻan-yĕhwá֣h ʼeţ-ʼi֭ẏwòb mn sʻrh wa⁠yò̇ʼmaֽr׃"],[40,7,"אֱזָר־נָ֣א כְ⁠גֶ֣בֶר חֲלָצֶ֑י⁠ךָ אֶ֝שְׁאָלְ⁠ךָ֗ וְ⁠הוֹדִיעֵֽ⁠נִי׃","ʼèzár-ná֣ʼ kĕ⁠ge֣ber ẖàláẕe֑y⁠ká ʼe֝şĕ̌ʼálĕ⁠ká֗ wĕ⁠hwòdiyʻéֽ⁠niy׃"],[40,8,"הַ֭⁠אַף תָּפֵ֣ר מִשְׁפָּטִ֑⁠י תַּ֝רְשִׁיעֵ֗⁠נִי לְמַ֣עַן תִּצְדָּֽק׃","ha֭⁠ʼap ţá̇pé֣r mişĕ̌pá̇ti֑⁠y ţȧ֝rĕşǐyʻé֗⁠niy lĕma֣ʻan ţi̇ẕĕdáֽ̇q׃"],[40,9,"וְ⁠אִם־זְר֖וֹעַ כָּ⁠אֵ֥ל ׀ לָ֑⁠ךְ וּ֝⁠בְ⁠ק֗וֹל כָּמֹ֥⁠הוּ תַרְעֵֽם׃","wĕ⁠ʼim-zĕr֖wòʻa ká̇⁠ʼé֥l ׀ lá֑⁠kĕ ẇ֝⁠bĕ⁠q֗wòl ká̇mò֥⁠hẇ ţarĕʻéֽm׃"],[40,10,"עֲדֵ֥ה נָ֣א גָֽא֣וֹן וָ⁠גֹ֑בַהּ וְ⁠ה֖וֹד וְ⁠הָדָ֣ר תִּלְבָּֽשׁ׃","ʻàdé֥h ná֣ʼ gáֽʼ֣wòn wá⁠gò֑baḣ wĕ⁠h֖wòd wĕ⁠hádá֣r ţi̇lĕbáֽ̇ş̌׃"],[40,11,"הָ֭פֵץ עֶבְר֣וֹת אַפֶּ֑⁠ךָ וּ⁠רְאֵ֥ה כָל־גֵּ֝אֶ֗ה וְ⁠הַשְׁפִּילֵֽ⁠הוּ׃","há֭péẕ ʻebĕr֣wòţ ʼapė֑⁠ká ẇ⁠rĕʼé֥h kál-gé̇֝ʼe֗h wĕ⁠haşĕ̌pi̇yléֽ⁠hẇ׃"],[40,12,"רְאֵ֣ה כָל־גֵּ֭אֶה הַכְנִיעֵ֑⁠הוּ וַ⁠הֲדֹ֖ךְ רְשָׁעִ֣ים תַּחְתָּֽ⁠ם׃","rĕʼé֣h kál-gé֭̇ʼeh hakĕniyʻé֑⁠hẇ wa⁠hàdò֖kĕ rĕşá̌ʻi֣ym ţȧẖĕţáֽ̇⁠m׃"],[40,13,"טָמְנֵ֣⁠ם בֶּ⁠עָפָ֣ר יָ֑חַד פְּ֝נֵי⁠הֶ֗ם חֲבֹ֣שׁ בַּ⁠טָּמֽוּן׃","támĕné֣⁠m bė⁠ʻápá֣r yá֑ẖad pĕ̇֝néy⁠he֗m ẖàbò֣ş̌ bȧ⁠tá̇mֽẇn׃"],[40,14,"וְ⁠גַם־אֲנִ֥י אוֹדֶ֑⁠ךָּ כִּֽי־תוֹשִׁ֖עַ לְ⁠ךָ֣ יְמִינֶֽ⁠ךָ׃","wĕ⁠gam-ʼàni֥y ʼwòde֑⁠ká̇ kiֽ̇y-ţwòşǐ֖ʻa lĕ⁠ká֣ yĕmiyneֽ⁠ká׃"],[40,15,"הִנֵּה־נָ֣א בְ֭הֵמוֹת אֲשֶׁר־עָשִׂ֣יתִי עִמָּ֑⁠ךְ חָ֝צִ֗יר כַּ⁠בָּקָ֥ר יֹאכֵֽל׃","hiné̇h-ná֣ʼ bĕ֭hémwòţ ʼàşěr-ʻáşî֣yţiy ʻimá֑̇⁠kĕ ẖá֝ẕi֗yr kȧ⁠bá̇qá֥r yòʼkéֽl׃"],[40,16,"הִנֵּה־נָ֣א כֹח֣⁠וֹ בְ⁠מָתְנָ֑י⁠ו וְ֝⁠אֹנ֗⁠וֹ בִּ⁠שְׁרִירֵ֥י בִטְנֽ⁠וֹ׃","hiné̇h-ná֣ʼ kòẖ֣⁠wò bĕ⁠máţĕná֑y⁠w wĕ֝⁠ʼòn֗⁠wò bi̇⁠şĕ̌riyré֥y bitĕnֽ⁠wò׃"],[40,17,"יַחְפֹּ֣ץ זְנָב֣⁠וֹ כְמוֹ־אָ֑רֶז גִּידֵ֖י פחד⁠ו יְשֹׂרָֽגוּ׃","yaẖĕpò֣̇ẕ zĕnáb֣⁠wò kĕmwò-ʼá֑rez gi̇ydé֖y pẖd⁠w yĕşò̂ráֽgẇ׃"],[40,18,"עֲ֭צָמָי⁠ו אֲפִיקֵ֣י נְחוּשָׁ֑ה גְּ֝רָמָ֗י⁠ו כִּ⁠מְטִ֥יל בַּרְזֶֽל׃","ʻà֭ẕámáy⁠w ʼàpiyqé֣y nĕẖẇşá֑̌h gĕ̇֝rámá֗y⁠w ki̇⁠mĕti֥yl bȧrĕzeֽl׃"],[40,19,"ה֭וּא רֵאשִׁ֣ית דַּרְכֵי־אֵ֑ל הָ֝⁠עֹשׂ⁠וֹ יַגֵּ֥שׁ חַרְבּֽ⁠וֹ׃","h֭ẇʼ réʼşǐ֣yţ dȧrĕkéy-ʼé֑l há֝⁠ʻòş̂⁠wò yagé֥̇ş̌ ẖarĕḃֽ⁠wò׃"],[40,20,"כִּֽי־ב֭וּל הָרִ֣ים יִשְׂאוּ־ל֑⁠וֹ וְֽ⁠כָל־חַיַּ֥ת הַ֝⁠שָּׂדֶ֗ה יְשַֽׂחֲקוּ־שָֽׁם׃","kiֽ̇y-b֭ẇl hári֣ym yişĕ̂ʼẇ-l֑⁠wò wĕֽ⁠kál-ẖayȧ֥ţ ha֝⁠şá̇̂de֗h yĕşâֽẖàqẇ-şáֽ̌m׃"],[40,21,"תַּֽחַת־צֶאֱלִ֥ים יִשְׁכָּ֑ב בְּ⁠סֵ֖תֶר קָנֶ֣ה וּ⁠בִצָּֽה׃","ţȧֽẖaţ-ẕeʼèli֥ym yişĕ̌ká֑̇b bĕ̇⁠sé֖ţer qáne֣h ẇ⁠biẕáֽ̇h׃"],[40,22,"יְסֻכֻּ֣⁠הוּ צֶאֱלִ֣ים צִֽלֲל֑⁠וֹ יְ֝סֻבּ֗וּ⁠הוּ עַרְבֵי־נָֽחַל׃","yĕsuku֣̇⁠hẇ ẕeʼèli֣ym ẕiֽlàl֑⁠wò yĕ֝suḃ֗ẇ⁠hẇ ʻarĕbéy-náֽẖal׃"],[40,23,"הֵ֤ן יַעֲשֹׁ֣ק נָ֭הָר לֹ֣א יַחְפּ֑וֹז יִבְטַ֓ח ׀ כִּֽי־יָגִ֖יחַ יַרְדֵּ֣ן אֶל־פִּֽי⁠הוּ׃","hé֤n yaʻàşò֣̌q ná֭hár lò֣ʼ yaẖĕṗ֑wòz yibĕta֓ẖ ׀ kiֽ̇y-yági֖yẖa yarĕdé֣̇n ʼel-piֽ̇y⁠hẇ׃"],[40,24,"בְּ⁠עֵינָ֥י⁠ו יִקָּחֶ֑⁠נּוּ בְּ֝⁠מֽוֹקְשִׁ֗ים יִנְקָב־אָֽף׃","bĕ̇⁠ʻéyná֥y⁠w yiqá̇ẖe֑⁠ṅẇ bĕ̇֝⁠mֽwòqĕşǐ֗ym yinĕqáb-ʼáֽp׃"],[41,1,"תִּמְשֹׁ֣ךְ לִוְיָתָ֣ן בְּ⁠חַכָּ֑ה וּ֝⁠בְ⁠חֶ֗בֶל תַּשְׁקִ֥יעַ לְשֹׁנֽ⁠וֹ׃","ţi̇mĕşò֣̌kĕ liwĕyáţá֣n bĕ̇⁠ẖaká֑̇h ẇ֝⁠bĕ⁠ẖe֗bel ţȧşĕ̌qi֥yʻa lĕşò̌nֽ⁠wò׃"],[41,2,"הֲ⁠תָשִׂ֣ים אַגְמ֣וֹן בְּ⁠אַפּ֑⁠וֹ וּ֝⁠בְ⁠ח֗וֹחַ תִּקּ֥וֹב לֶֽחֱי⁠וֹ׃","hà⁠ţáşî֣ym ʼagĕm֣wòn bĕ̇⁠ʼaṗ֑⁠wò ẇ֝⁠bĕ⁠ẖ֗wòẖa ţi̇q֥̇wòb leֽẖèy⁠wò׃"],[41,3,"הֲ⁠יַרְבֶּ֣ה אֵ֭לֶי⁠ךָ תַּחֲנוּנִ֑ים אִם־יְדַבֵּ֖ר אֵלֶ֣י⁠ךָ רַכּֽוֹת׃","hà⁠yarĕbė֣h ʼé֭ley⁠ká ţȧẖànẇni֑ym ʼim-yĕdabé֖̇r ʼéle֣y⁠ká rakֽ̇wòţ׃"],[41,4,"הֲ⁠יִכְרֹ֣ת בְּרִ֣ית עִמָּ֑⁠ךְ תִּ֝קָּחֶ֗⁠נּוּ לְ⁠עֶ֣בֶד עוֹלָֽם׃","hà⁠yikĕrò֣ţ bĕ̇ri֣yţ ʻimá֑̇⁠kĕ ţi̇֝qá̇ẖe֗⁠ṅẇ lĕ⁠ʻe֣bed ʻwòláֽm׃"],[41,5,"הַֽ⁠תְשַׂחֶק־בּ֭⁠וֹ כַּ⁠צִּפּ֑וֹר וְ֝⁠תִקְשְׁרֶ֗⁠נּוּ לְ⁠נַעֲרוֹתֶֽי⁠ךָ׃","hֽa⁠ţĕşâẖeq-ḃ֭⁠wò kȧ⁠ẕi̇ṗ֑wòr wĕ֝⁠ţiqĕşĕ̌re֗⁠ṅẇ lĕ⁠naʻàrwòţeֽy⁠ká׃"],[41,6,"יִכְר֣וּ עָ֭לָי⁠ו חַבָּרִ֑ים יֶ֝חֱצ֗וּ⁠הוּ בֵּ֣ין כְּֽנַעֲנִֽים׃","yikĕr֣ẇ ʻá֭láy⁠w ẖabá̇ri֑ym ye֝ẖèẕ֗ẇ⁠hẇ bé֣̇yn kĕֽ̇naʻàniֽym׃"],[41,7,"הַֽ⁠תְמַלֵּ֣א בְ⁠שֻׂכּ֣וֹת עוֹר֑⁠וֹ וּ⁠בְ⁠צִלְצַ֖ל דָּגִ֣ים רֹאשֽׁ⁠וֹ׃","haֽ⁠ţĕmalé֣̇ʼ bĕ⁠şûk֣̇wòţ ʻwòr֑⁠wò ẇ⁠bĕ⁠ẕilĕẕa֖l dá̇gi֣ym ròʼşֽ̌⁠wò׃"],[41,8,"שִׂים־עָלָ֥י⁠ו כַּפֶּ֑⁠ךָ זְכֹ֥ר מִ֝לְחָמָ֗ה אַל־תּוֹסַֽף׃","şîym-ʻálá֥y⁠w kȧpė֑⁠ká zĕkò֥r mi֝lĕẖámá֗h ʼal-ţ̇wòsaֽp׃"],[41,9,"הֵן־תֹּחַלְתּ֥⁠וֹ נִכְזָ֑בָה הֲ⁠גַ֖ם אֶל־מַרְאָ֣י⁠ו יֻטָֽל׃","hén-ţò̇ẖalĕţ֥̇⁠wò nikĕzá֑báh hà⁠ga֖m ʼel-marĕʼá֣y⁠w yutáֽl׃"],[41,10,"לֹֽא־אַ֭כְזָר כִּ֣י יְעוּרֶ֑⁠נּוּ וּ⁠מִ֥י ה֝֗וּא לְ⁠פָנַ֥⁠י יִתְיַצָּֽב׃","lòֽʼ-ʼa֭kĕzár ki֣̇y yĕʻẇre֑⁠ṅẇ ẇ⁠mi֥y h֝֗ẇʼ lĕ⁠pána֥⁠y yiţĕyaẕáֽ̇b׃"],[41,11,"מִ֣י הִ֭קְדִּימַ⁠נִי וַ⁠אֲשַׁלֵּ֑ם תַּ֖חַת כָּל־הַ⁠שָּׁמַ֣יִם לִ⁠י־הֽוּא׃","mi֣y hi֭qĕdi̇yma⁠niy wa⁠ʼàşǎlé֑̇m ţȧ֖ẖaţ ká̇l-ha⁠şá̇̌ma֣yim li⁠y-hֽẇʼ׃"],[41,12,"לא־אַחֲרִ֥ישׁ בַּדָּ֑י⁠ו וּ⁠דְבַר־גְּ֝בוּר֗וֹת וְ⁠חִ֣ין עֶרְכּֽ⁠וֹ׃","lʼ-ʼaẖàri֥yş̌ bȧdá֑̇y⁠w ẇ⁠dĕbar-gĕ̇֝bẇr֗wòţ wĕ⁠ẖi֣yn ʻerĕkֽ̇⁠wò׃"],[41,13,"מִֽי־גִ֭לָּה פְּנֵ֣י לְבוּשׁ֑⁠וֹ בְּ⁠כֶ֥פֶל רִ֝סְנ֗⁠וֹ מִ֣י יָבֽוֹא׃","miֽy-gi֭lá̇h pĕ̇né֣y lĕbẇş֑̌⁠wò bĕ̇⁠ke֥pel ri֝sĕn֗⁠wò mi֣y yábֽwòʼ׃"],[41,14,"דַּלְתֵ֣י פָ֭נָי⁠ו מִ֣י פִתֵּ֑חַ סְבִיב֖וֹת שִׁנָּ֣י⁠ו אֵימָֽה׃","dȧlĕţé֣y pá֭náy⁠w mi֣y piţé֑̇ẖa sĕbiyb֖wòţ şǐná֣̇y⁠w ʼéymáֽh׃"],[41,15,"גַּ֭אֲוָה אֲפִיקֵ֣י מָֽגִנִּ֑ים סָ֝ג֗וּר חוֹתָ֥ם צָֽר׃","gȧ֭ʼàwáh ʼàpiyqé֣y máֽgini֑̇ym sá֝g֗ẇr ẖwòţá֥m ẕáֽr׃"],[41,16,"אֶחָ֣ד בְּ⁠אֶחָ֣ד יִגַּ֑שׁוּ וְ֝⁠ר֗וּחַ לֹא־יָב֥וֹא בֵֽינֵי⁠הֶֽם׃","ʼeẖá֣d bĕ̇⁠ʼeẖá֣d yigȧ֑ş̌ẇ wĕ֝⁠r֗ẇẖa lòʼ-yáb֥wòʼ béֽynéy⁠heֽm׃"],[41,17,"אִישׁ־בְּ⁠אָחִ֥י⁠הוּ יְדֻבָּ֑קוּ יִ֝תְלַכְּד֗וּ וְ⁠לֹ֣א יִתְפָּרָֽדוּ׃","ʼiyş̌-bĕ̇⁠ʼáẖi֥y⁠hẇ yĕdubá֑̇qẇ yi֝ţĕlakĕ̇d֗ẇ wĕ⁠lò֣ʼ yiţĕpá̇ráֽdẇ׃"],[41,18,"עֲֽ֭טִישֹׁתָי⁠ו תָּ֣הֶל א֑וֹר וְ֝⁠עֵינָ֗י⁠ו כְּ⁠עַפְעַפֵּי־שָֽׁחַר׃","ʻàֽ֭tiyşò̌ţáy⁠w ţá֣̇hel ʼ֑wòr wĕ֝⁠ʻéyná֗y⁠w kĕ̇⁠ʻapĕʻapé̇y-şáֽ̌ẖar׃"],[41,19,"מִ֭⁠פִּי⁠ו לַפִּידִ֣ים יַהֲלֹ֑כוּ כִּיד֥וֹדֵי אֵ֝֗שׁ יִתְמַלָּֽטוּ׃","mi֭⁠pi̇y⁠w lapi̇ydi֣ym yahàlò֑kẇ ki̇yd֥wòdéy ʼé֝֗ş̌ yiţĕmaláֽ̇tẇ׃"],[41,20,"מִ֭⁠נְּחִירָי⁠ו יֵצֵ֣א עָשָׁ֑ן כְּ⁠ד֖וּד נָפ֣וּחַ וְ⁠אַגְמֹֽן׃","mi֭⁠nĕ̇ẖiyráy⁠w yéẕé֣ʼ ʻáşá֑̌n kĕ̇⁠d֖ẇd náp֣ẇẖa wĕ⁠ʼagĕmòֽn׃"],[41,21,"נַ֭פְשׁ⁠וֹ גֶּחָלִ֣ים תְּלַהֵ֑ט וְ֝⁠לַ֗הַב מִ⁠פִּ֥י⁠ו יֵצֵֽא׃","na֭pĕş̌⁠wò gėẖáli֣ym ţĕ̇lahé֑t wĕ֝⁠la֗hab mi⁠pi֥̇y⁠w yéẕéֽʼ׃"],[41,22,"בְּֽ֭⁠צַוָּאר⁠וֹ יָלִ֣ין עֹ֑ז וּ֝⁠לְ⁠פָנָ֗י⁠ו תָּד֥וּץ דְּאָבָֽה׃","bĕֽ֭̇⁠ẕawá̇ʼr⁠wò yáli֣yn ʻò֑z ẇ֝⁠lĕ⁠páná֗y⁠w ţá̇d֥ẇẕ dĕ̇ʼábáֽh׃"],[41,23,"מַפְּלֵ֣י בְשָׂר֣⁠וֹ דָבֵ֑קוּ יָצ֥וּק עָ֝לָ֗י⁠ו בַּל־יִמּֽוֹט׃","mapĕ̇lé֣y bĕşá̂r֣⁠wò dábé֑qẇ yáẕ֥ẇq ʻá֝lá֗y⁠w bȧl-yiṁֽwòt׃"],[41,24,"לִ֭בּ⁠וֹ יָצ֣וּק כְּמוֹ־אָ֑בֶן וְ֝⁠יָצ֗וּק כְּ⁠פֶ֣לַח תַּחְתִּֽית׃","li֭ḃ⁠wò yáẕ֣ẇq kĕ̇mwò-ʼá֑ben wĕ֝⁠yáẕ֗ẇq kĕ̇⁠pe֣laẖ ţȧẖĕţiֽ̇yţ׃"],[41,25,"מִ֭⁠שֵּׂת⁠וֹ יָג֣וּרוּ אֵלִ֑ים מִ֝⁠שְּׁבָרִ֗ים יִתְחַטָּֽאוּ׃","mi֭⁠şé̇̂ţ⁠wò yág֣ẇrẇ ʼéli֑ym mi֝⁠şĕ̇̌bári֗ym yiţĕẖatáֽ̇ʼẇ׃"],[41,26,"מַשִּׂיגֵ֣⁠הוּ חֶ֭רֶב בְּלִ֣י תָק֑וּם חֲנִ֖ית מַסָּ֣ע וְ⁠שִׁרְיָֽה׃","maşi̇̂ygé֣⁠hẇ ẖe֭reb bĕ̇li֣y ţáq֑ẇm ẖàni֖yţ masá֣̇ʻ wĕ⁠şǐrĕyáֽh׃"],[41,27,"יַחְשֹׁ֣ב לְ⁠תֶ֣בֶן בַּרְזֶ֑ל לְ⁠עֵ֖ץ רִקָּב֣וֹן נְחוּשָֽׁה׃","yaẖĕşò֣̌b lĕ⁠ţe֣ben bȧrĕze֑l lĕ⁠ʻé֖ẕ riqá̇b֣wòn nĕẖẇşáֽ̌h׃"],[41,28,"לֹֽא־יַבְרִיחֶ֥⁠נּוּ בֶן־קָ֑שֶׁת לְ֝⁠קַ֗שׁ נֶהְפְּכוּ־ל֥⁠וֹ אַבְנֵי־קָֽלַע׃","lòֽʼ-yabĕriyẖe֥⁠ṅẇ ben-qá֑şěţ lĕ֝⁠qa֗ş̌ nehĕpĕ̇kẇ-l֥⁠wò ʼabĕnéy-qáֽlaʻ׃"],[41,29,"כְּ֭⁠קַשׁ נֶחְשְׁב֣וּ תוֹתָ֑ח וְ֝⁠יִשְׂחַ֗ק לְ⁠רַ֣עַשׁ כִּידֽוֹן׃","kĕ֭̇⁠qaş̌ neẖĕşĕ̌b֣ẇ ţwòţá֑ẖ wĕ֝⁠yişĕ̂ẖa֗q lĕ⁠ra֣ʻaş̌ ki̇ydֽwòn׃"],[41,30,"תַּ֭חְתָּי⁠ו חַדּ֣וּדֵי חָ֑רֶשׂ יִרְפַּ֖ד חָר֣וּץ עֲלֵי־טִֽיט׃","ţȧ֭ẖĕţá̇y⁠w ẖaḋ֣ẇdéy ẖá֑reş̂ yirĕpȧ֖d ẖár֣ẇẕ ʻàléy-tiֽyt׃"],[41,31,"יַרְתִּ֣יחַ כַּ⁠סִּ֣יר מְצוּלָ֑ה יָ֝֗ם יָשִׂ֥ים כַּ⁠מֶּרְקָחָֽה׃","yarĕţi֣̇yẖa kȧ⁠si֣̇yr mĕẕẇlá֑h yá֝֗m yáşî֥ym kȧ⁠mėrĕqáẖáֽh׃"],[41,32,"אַ֭חֲרָי⁠ו יָאִ֣יר נָתִ֑יב יַחְשֹׁ֖ב תְּה֣וֹם לְ⁠שֵׂיבָֽה׃","ʼa֭ẖàráy⁠w yáʼi֣yr náţi֑yb yaẖĕşò֖̌b ţĕ̇h֣wòm lĕ⁠şé̂ybáֽh׃"],[41,33,"אֵֽין־עַל־עָפָ֥ר מָשְׁל֑⁠וֹ הֶ֝⁠עָשׂ֗וּ לִ⁠בְלִי־חָֽת׃","ʼéֽyn-ʻal-ʻápá֥r máşĕ̌l֑⁠wò he֝⁠ʻáş̂֗ẇ li⁠bĕliy-ẖáֽţ׃"],[41,34,"אֵֽת־כָּל־גָּבֹ֥הַּ יִרְאֶ֑ה ה֝֗וּא מֶ֣לֶךְ עַל־כָּל־בְּנֵי־שָֽׁחַץ׃ס","ʼéֽţ-ká̇l-gá̇bò֥hȧ yirĕʼe֑h h֝֗ẇʼ me֣lekĕ ʻal-ká̇l-bĕ̇néy-şáֽ̌ẖaẕ׃s"],[42,1,"וַ⁠יַּ֖עַן אִיּ֥וֹב אֶת־יְהוָ֗ה וַ⁠יֹּאמַֽר׃","wa⁠yȧ֖ʻan ʼiẏ֥wòb ʼeţ-yĕhwá֗h wa⁠yò̇ʼmaֽr׃"],[42,2,"ידעת כִּי־כֹ֣ל תּוּכָ֑ל וְ⁠לֹא־יִבָּצֵ֖ר מִמְּ⁠ךָ֣ מְזִמָּֽה׃","ydʻţ ki̇y-kò֣l ţ̇ẇká֑l wĕ⁠lòʼ-yibá̇ẕé֖r mimĕ̇⁠ká֣ mĕzimáֽ̇h׃"],[42,3,"מִ֤י זֶ֨ה ׀ מַעְלִ֥ים עֵצָ֗ה בְּֽלִ֫י דָ֥עַת לָ⁠כֵ֣ן הִ֭גַּדְתִּי וְ⁠לֹ֣א אָבִ֑ין נִפְלָא֥וֹת מִ֝מֶּ֗⁠נִּי וְ⁠לֹ֣א אֵדָֽע׃","mi֤y ze֨h ׀ maʻĕli֥ym ʻéẕá֗h bĕֽ̇li֫y dá֥ʻaţ lá⁠ké֣n hi֭gȧdĕţi̇y wĕ⁠lò֣ʼ ʼábi֑yn nipĕláʼ֥wòţ mi֝mė֗⁠ni̇y wĕ⁠lò֣ʼ ʼédáֽʻ׃"],[42,4,"שְֽׁמַֽע־נָ֭א וְ⁠אָנֹכִ֣י אֲדַבֵּ֑ר אֶ֝שְׁאָלְ⁠ךָ֗ וְ⁠הוֹדִיעֵֽ⁠נִי׃","şĕֽ̌maֽʻ-ná֭ʼ wĕ⁠ʼánòki֣y ʼàdabé֑̇r ʼe֝şĕ̌ʼálĕ⁠ká֗ wĕ⁠hwòdiyʻéֽ⁠niy׃"],[42,5,"לְ⁠שֵֽׁמַע־אֹ֥זֶן שְׁמַעְתִּ֑י⁠ךָ וְ֝⁠עַתָּ֗ה עֵינִ֥⁠י רָאָֽתְ⁠ךָ׃","lĕ⁠şéֽ̌maʻ-ʼò֥zen şĕ̌maʻĕţi֑̇y⁠ká wĕ֝⁠ʻaţá̇֗h ʻéyni֥⁠y ráʼáֽţĕ⁠ká׃"],[42,6,"עַל־כֵּ֭ן אֶמְאַ֣ס וְ⁠נִחַ֑מְתִּי עַל־עָפָ֥ר וָ⁠אֵֽפֶר׃פ","ʻal-ké֭̇n ʼemĕʼa֣s wĕ⁠niẖa֑mĕţi̇y ʻal-ʻápá֥r wá⁠ʼéֽper׃p"],[42,7,"וַ⁠יְהִ֗י אַחַ֨ר דִּבֶּ֧ר יְהוָ֛ה אֶת־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה אֶל־אִיּ֑וֹב וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־אֱלִיפַ֣ז הַ⁠תֵּֽימָנִ֗י חָרָ֨ה אַפִּ֤⁠י בְ⁠ךָ֙ וּ⁠בִ⁠שְׁנֵ֣י רֵעֶ֔י⁠ךָ כִּ֠י לֹ֣א דִבַּרְתֶּ֥ם אֵלַ֛⁠י נְכוֹנָ֖ה כְּ⁠עַבְדִּ֥⁠י אִיּֽוֹב׃","wa⁠yĕhi֗y ʼaẖa֨r di̇bė֧r yĕhwá֛h ʼeţ-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh ʼel-ʼiẏ֑wòb wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-ʼèliypa֣z ha⁠ţéֽ̇ymáni֗y ẖárá֨h ʼapi֤̇⁠y bĕ⁠ká֙ ẇ⁠bi⁠şĕ̌né֣y réʻe֔y⁠ká ki̇֠y lò֣ʼ dibȧrĕţė֥m ʼéla֛⁠y nĕkwòná֖h kĕ̇⁠ʻabĕdi֥̇⁠y ʼiẏֽwòb׃"],[42,8,"וְ⁠עַתָּ֡ה קְחֽוּ־לָ⁠כֶ֣ם שִׁבְעָֽה־פָרִים֩ וְ⁠שִׁבְעָ֨ה אֵילִ֜ים וּ⁠לְכ֣וּ ׀ אֶל־עַבְדִּ֣⁠י אִיּ֗וֹב וְ⁠הַעֲלִיתֶ֤ם עוֹלָה֙ בַּֽעַדְ⁠כֶ֔ם וְ⁠אִיּ֣וֹב עַבְדִּ֔⁠י יִתְפַּלֵּ֖ל עֲלֵי⁠כֶ֑ם כִּ֧י אִם־פָּנָ֣י⁠ו אֶשָּׂ֗א לְ⁠בִלְתִּ֞י עֲשׂ֤וֹת עִמָּ⁠כֶם֙ נְבָלָ֔ה כִּ֠י לֹ֣א דִבַּרְתֶּ֥ם אֵלַ֛⁠י נְכוֹנָ֖ה כְּ⁠עַבְדִּ֥⁠י אִיּֽוֹב׃","wĕ⁠ʻaţá̇֡h qĕẖֽẇ-lá⁠ke֣m şǐbĕʻáֽh-páriym֩ wĕ⁠şǐbĕʻá֨h ʼéyli֜ym ẇ⁠lĕk֣ẇ ׀ ʼel-ʻabĕdi֣̇⁠y ʼiẏ֗wòb wĕ⁠haʻàliyţe֤m ʻwòláh֙ ḃֽaʻadĕ⁠ke֔m wĕ⁠ʼiẏ֣wòb ʻabĕdi̇֔⁠y yiţĕpȧlé֖̇l ʻàléy⁠ke֑m ki֧̇y ʼim-pá̇ná֣y⁠w ʼeşá̇̂֗ʼ lĕ⁠bilĕţi̇֞y ʻàş֤̂wòţ ʻimá̇⁠kem֙ nĕbálá֔h ki̇֠y lò֣ʼ dibȧrĕţė֥m ʼéla֛⁠y nĕkwòná֖h kĕ̇⁠ʻabĕdi֥̇⁠y ʼiẏֽwòb׃"],[42,9,"וַ⁠יֵּלְכוּ֩ אֱלִיפַ֨ז הַ⁠תֵּֽימָנִ֜י וּ⁠בִלְדַּ֣ד הַ⁠שּׁוּחִ֗י צֹפַר֙ הַ⁠נַּ֣עֲמָתִ֔י וַֽ⁠יַּעֲשׂ֔וּ כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר אֲלֵי⁠הֶ֖ם יְהוָ֑ה וַ⁠יִּשָּׂ֥א יְהוָ֖ה אֶת־פְּנֵ֥י אִיּֽוֹב׃","wa⁠yé̇lĕkẇ֩ ʼèliypa֨z ha⁠ţéֽ̇ymáni֜y ẇ⁠bilĕdȧ֣d ha⁠ş̇̌ẇẖi֗y ẕòpar֙ ha⁠nȧ֣ʻàmáţi֔y waֽ⁠yȧʻàş̂֔ẇ kȧ⁠ʼàşě֛r di̇bė֥r ʼàléy⁠he֖m yĕhwá֑h wa⁠yi̇şá֥̇̂ʼ yĕhwá֖h ʼeţ-pĕ̇né֥y ʼiẏֽwòb׃"],[42,10,"וַֽ⁠יהוָ֗ה שָׁ֚ב אֶת־שבית אִיּ֔וֹב בְּ⁠הִֽתְפַּֽלְל֖⁠וֹ בְּעַ֣ד רֵעֵ֑⁠הוּ וַ֧⁠יֹּסֶף יְהוָ֛ה אֶת־כָּל־אֲשֶׁ֥ר לְ⁠אִיּ֖וֹב לְ⁠מִשְׁנֶֽה׃","waֽ⁠yhwá֗h şá֚̌b ʼeţ-şbyţ ʼiẏ֔wòb bĕ̇⁠hiֽţĕpȧֽlĕl֖⁠wò bĕ̇ʻa֣d réʻé֑⁠hẇ wa֧⁠yò̇sep yĕhwá֛h ʼeţ-ká̇l-ʼàşě֥r lĕ⁠ʼiẏ֖wòb lĕ⁠mişĕ̌neֽh׃"],[42,11,"וַ⁠יָּבֹ֣אוּ אֵ֠לָי⁠ו כָּל־אֶחָ֨י⁠ו וְ⁠כָל־אחיתי⁠ו וְ⁠כָל־יֹדְעָ֣י⁠ו לְ⁠פָנִ֗ים וַ⁠יֹּאכְל֨וּ עִמּ֣⁠וֹ לֶחֶם֮ בְּ⁠בֵית⁠וֹ֒ וַ⁠יָּנֻ֤דוּ ל⁠וֹ֙ וַ⁠יְנַחֲמ֣וּ אֹת֔⁠וֹ עַ֚ל כָּל־הָ֣⁠רָעָ֔ה אֲשֶׁר־הֵבִ֥יא יְהוָ֖ה עָלָ֑י⁠ו וַ⁠יִּתְּנוּ־ל֗⁠וֹ אִ֚ישׁ קְשִׂיטָ֣ה אֶחָ֔ת וְ⁠אִ֕ישׁ נֶ֥זֶם זָהָ֖ב אֶחָֽד׃ס","wa⁠yá̇bò֣ʼẇ ʼé֠láy⁠w ká̇l-ʼeẖá֨y⁠w wĕ⁠kál-ʼẖyţy⁠w wĕ⁠kál-yòdĕʻá֣y⁠w lĕ⁠páni֗ym wa⁠yò̇ʼkĕl֨ẇ ʻiṁ֣⁠wò leẖem֮ bĕ̇⁠béyţ⁠wò֒ wa⁠yá̇nu֤dẇ l⁠wò֙ wa⁠yĕnaẖàm֣ẇ ʼòţ֔⁠wò ʻa֚l ká̇l-há֣⁠ráʻá֔h ʼàşěr-hébi֥yʼ yĕhwá֖h ʻálá֑y⁠w wa⁠yi̇ţĕ̇nẇ-l֗⁠wò ʼi֚yş̌ qĕşîytá֣h ʼeẖá֔ţ wĕ⁠ʼi֕yş̌ ne֥zem záhá֖b ʼeẖáֽd׃s"],[42,12,"וַֽ⁠יהוָ֗ה בֵּרַ֛ךְ אֶת־אַחֲרִ֥ית אִיּ֖וֹב מֵ⁠רֵאשִׁת֑⁠וֹ וַֽ⁠יְהִי־ל֡⁠וֹ אַרְבָּעָה֩ עָשָׂ֨ר אֶ֜לֶף צֹ֗אן וְ⁠שֵׁ֤שֶׁת אֲלָפִים֙ גְּמַלִּ֔ים וְ⁠אֶֽלֶף־צֶ֥מֶד בָּקָ֖ר וְ⁠אֶ֥לֶף אֲתוֹנֽוֹת׃","waֽ⁠yhwá֗h bé̇ra֛kĕ ʼeţ-ʼaẖàri֥yţ ʼiẏ֖wòb mé⁠réʼşǐţ֑⁠wò waֽ⁠yĕhiy-l֡⁠wò ʼarĕbá̇ʻáh֩ ʻáşá̂֨r ʼe֜lep ẕò֗ʼn wĕ⁠şé֤̌şěţ ʼàlápiym֙ gĕ̇mali̇֔ym wĕ⁠ʼeֽlep-ẕe֥med bá̇qá֖r wĕ⁠ʼe֥lep ʼàţwònֽwòţ׃"],[42,13,"וַֽ⁠יְהִי־ל֛⁠וֹ שִׁבְעָ֥נָה בָנִ֖ים וְ⁠שָׁל֥וֹשׁ בָּנֽוֹת׃","waֽ⁠yĕhiy-l֛⁠wò şǐbĕʻá֥náh báni֖ym wĕ⁠şá̌l֥wòş̌ bá̇nֽwòţ׃"],[42,14,"וַ⁠יִּקְרָ֤א שֵׁם־הָֽ⁠אַחַת֙ יְמִימָ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖ית קְצִיעָ֑ה וְ⁠שֵׁ֥ם הַ⁠שְּׁלִישִׁ֖ית קֶ֥רֶן הַפּֽוּךְ׃","wa⁠yi̇qĕrá֤ʼ şé̌m-háֽ⁠ʼaẖaţ֙ yĕmiymá֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖yţ qĕẕiyʻá֑h wĕ⁠şé֥̌m ha⁠şĕ̇̌liyşǐ֖yţ qe֥ren haṗֽẇkĕ׃"],[42,15,"וְ⁠לֹ֨א נִמְצָ֜א נָשִׁ֥ים יָפ֛וֹת כִּ⁠בְנ֥וֹת אִיּ֖וֹב בְּ⁠כָל־הָ⁠אָ֑רֶץ וַ⁠יִּתֵּ֨ן לָ⁠הֶ֧ם אֲבִי⁠הֶ֛ם נַחֲלָ֖ה בְּ⁠ת֥וֹךְ אֲחֵי⁠הֶֽם׃ס","wĕ⁠lò֨ʼ nimĕẕá֜ʼ náşǐ֥ym yáp֛wòţ ki̇⁠bĕn֥wòţ ʼiẏ֖wòb bĕ̇⁠kál-há⁠ʼá֑reẕ wa⁠yi̇ţé̇֨n lá⁠he֧m ʼàbiy⁠he֛m naẖàlá֖h bĕ̇⁠ţ֥wòkĕ ʼàẖéy⁠heֽm׃s"],[42,16,"וַ⁠יְחִ֤י אִיּוֹב֙ אַֽחֲרֵי־זֹ֔את מֵאָ֥ה וְ⁠אַרְבָּעִ֖ים שָׁנָ֑ה ו⁠ירא אֶת־בָּנָי⁠ו֙ וְ⁠אֶת־בְּנֵ֣י בָנָ֔י⁠ו אַרְבָּעָ֖ה דֹּרֽוֹת׃","wa⁠yĕẖi֤y ʼiẏwòb֙ ʼaֽẖàréy-zò֔ʼţ méʼá֥h wĕ⁠ʼarĕbá̇ʻi֖ym şá̌ná֑h w⁠yrʼ ʼeţ-bá̇náy⁠w֙ wĕ⁠ʼeţ-bĕ̇né֣y báná֔y⁠w ʼarĕbá̇ʻá֖h dò̇rֽwòţ׃"],[42,17,"וַ⁠יָּ֣מָת אִיּ֔וֹב זָקֵ֖ן וּ⁠שְׂבַ֥ע יָמִֽים׃","wa⁠yá֣̇máţ ʼiẏ֔wòb záqé֖n ẇ⁠şĕ̂ba֥ʻ yámiֽym׃"]]}};